INSERT INTO learning_card_texts ("cardId", lang, title, body, tutor, audio) VALUES
  (E'marking-1.1', E'en', E'Marking 1.1', E'Separates traffic flows moving in opposite directions and marks the boundaries of traffic lanes on dangerous sections; marks the boundaries of the carriageway where entry is prohibited; marks the boundaries of vehicle parking places and the edges of the carriageway on roads that, by traffic conditions, are not classed as motorways. Crossing line 1.1 is prohibited. Crossing line 1.1 that marks the edge of the carriageway and lies on the driver''s right is allowed in order to stop the vehicle at the side of the road.', E'Solid line: separates opposite traffic flows and marks lane edges in dangerous places; it also marks carriageway edges where entry is banned, the edges of parking places, and the edges of the carriageway (except on motorways). Crossing line 1.1 is banned. Exception: you may cross a 1.1 line on your right that marks the edge of the carriageway to stop on the roadside.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/en/card_a962dd066a.webm'),
  (E'marking-1.1', E'ka', E'მონიშვნა 1.1', E'ყოფს საპირისპირო მიმართულებით მოძრავ სატრანსპორტო ნაკადებს და სახიფათო მონაკვეთზე აღნიშნავს მოძრაობის ზოლების საზღვრებს; აღნიშნავს სავალი ნაწილის საზღვრებს, რომლებზედაც შესვლა აკრძალულია; აღნიშნავს ტრანსპორტის დგომის ადგილის საზღვრებს და იმ გზის სავალი ნაწილის ნაპირებს, რომლებიც მოძრაობის პირობებით არ განეკუთვნება ავტომაგისტრალს. 1.1 ხაზის გადაკვეთა აკრძალულია. დასაშვებია სავალი ნაწილის ნაპირის აღმნიშვნელი და მძღოლის მარჯვენა მხარეს განლაგებული 1.1 ხაზის გადაკვეთა ტრანსპორტის გზის ნაპირზე გასაჩერებლად.', E'უწყვეტი ხაზი: ყოფს საპირისპირო მიმართულების ნაკადებს და სახიფათო ადგილებში ზოლების საზღვრებს აღნიშნავს; ასევე აღნიშნავს სავალი ნაწილის იმ საზღვრებს, სადაც შესვლა აკრძალულია, დგომის ადგილის საზღვრებს და სავალი ნაწილის ნაპირებს (ავტომაგისტრალის გარდა). 1.1 ხაზის გადაკვეთა აკრძალულია. გამონაკლისი: ნაპირის აღმნიშვნელი, შენგან მარჯვნივ მდებარე 1.1 ხაზი შეგიძლია გადაკვეთო, რომ გზის ნაპირზე გაჩერდე.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ka/card_f632e401e4.webm'),
  (E'marking-1.1', E'ru', E'Разметка 1.1', E'Разделяет транспортные потоки противоположных направлений и обозначает границы полос движения в опасных местах; обозначает границы проезжей части, на которые въезд запрещён; обозначает границы стояночных мест транспортных средств и края проезжей части дорог, не относящихся по условиям движения к автомагистралям. Пересекать линию 1.1 запрещается. Допускается пересекать линию 1.1, обозначающую край проезжей части и расположенную справа от водителя, для остановки транспортного средства на обочине.', E'Сплошная линия: разделяет потоки противоположных направлений и обозначает границы полос в опасных местах; также обозначает границы проезжей части, на которые въезд запрещён, границы мест стоянки и края проезжей части (кроме автомагистралей). Пересекать линию 1.1 запрещено. Исключение: линию 1.1 справа от вас, обозначающую край проезжей части, можно пересечь, чтобы остановиться на обочине.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ru/card_4119d11a65.webm'),
  (E'marking-1.10', E'en', E'Marking 1.10', E'Marks a place where parking is prohibited; it is used on its own or in combination with sign 3.28; it is painted along the edge of the carriageway or on top of the kerb.', E'Marks a place where parking is banned. It is used on its own or with sign 3.28, along the edge of the carriageway or on top of the kerb.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/en/card_e65b28d1c5.webm'),
  (E'marking-1.10', E'ka', E'მონიშვნა 1.10', E'აღნიშნავს ადგილს, სადაც აკრძალულია დგომა; გამოიყენება დამოუკიდებლად ან 3.28 ნიშანთან შეერთებით; იხაზება სავალი ნაწილის ნაპირთან ან ბორდიურზე ზემოდან.', E'აღნიშნავს ადგილს, სადაც დგომა აკრძალულია. გამოიყენება ცალკე ან 3.28 ნიშანთან ერთად; იხაზება სავალი ნაწილის ნაპირთან ან ბორდიურის თავზე.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ka/card_682de11568.webm'),
  (E'marking-1.10', E'ru', E'Разметка 1.10', E'Обозначает места, где запрещена стоянка; применяется самостоятельно или в сочетании со знаком 3.28; наносится у края проезжей части или по верху бордюра.', E'Обозначает места, где стоянка запрещена. Применяется самостоятельно или вместе со знаком 3.28; наносится у края проезжей части или по верху бордюра.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ru/card_e02697af39.webm'),
  (E'marking-1.11', E'en', E'Marking 1.11', E'Separates traffic flows moving in opposite or the same directions on a section of road where changing lanes is allowed from one lane only; marks turning places, exits from and entrances to parking areas, etc., where movement is allowed in one direction only. Crossing line 1.11 is allowed from the broken-line side, and also from the solid-line side, but only when completing overtaking or passing around.', E'A solid and a broken line together: separates flows where changing lanes is allowed from one side only, or marks turning places and entries to and exits from parking areas. You may cross it from the broken-line side; from the solid-line side, only to finish overtaking or passing an obstacle.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/en/card_f539b22f4d.webm'),
  (E'marking-1.11', E'ka', E'მონიშვნა 1.11', E'ყოფს საპირისპირო ან იმავე მიმართულებით მოძრავ სატრანსპორტო ნაკადებს გზის მონაკვეთზე, სადაც გადაჯგუფება ნებადართულია მხოლოდ ერთი ზოლიდან; აღნიშნავს მობრუნების ადგილს, სადგომი მოედნიდან გამოსასვლელსა და შესასვლე­ლს და ა. შ., სადაც მოძრაობა ნებადართულია მხოლოდ ერთ მხარეს.1.11 ხაზის გადაკვეთა ნებადართულია წყვეტილი ხაზის მხრიდან, ასევე უწყვეტი ხაზის მხრიდან, მაგრამ მხოლოდ გასწრების ან შემოვლის დამთავრებისას.', E'უწყვეტი და წყვეტილი ხაზი ერთად: ყოფს ნაკადებს იქ, სადაც გადაჯგუფება მხოლოდ ერთი მხრიდან შეიძლება, ან აღნიშნავს მობრუნების ადგილს, სადგომიდან გასასვლელს და შესასვლელს. წყვეტილი ხაზის მხრიდან მისი გადაკვეთა შეიძლება, უწყვეტის მხრიდან კი — მხოლოდ გასწრების ან შემოვლის დასასრულებლად.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ka/card_39193df922.webm'),
  (E'marking-1.11', E'ru', E'Разметка 1.11', E'Разделяет транспортные потоки противоположных или попутных направлений на участке дороги, где перестроение разрешено только из одной полосы; обозначает места для разворота, выезда со стоянки и въезда на неё и т. п., где движение разрешено только в одну сторону. Пересекать линию 1.11 разрешается со стороны прерывистой линии, а также со стороны сплошной линии, но только при завершении обгона или объезда.', E'Сплошная и прерывистая линии вместе: разделяют потоки там, где перестроение разрешено только с одной стороны, или обозначают места разворота, въезда на стоянку и выезда с неё. Со стороны прерывистой линии её пересекать можно, со стороны сплошной — только чтобы завершить обгон или объезд.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ru/card_ebabfc1fab.webm'),
  (E'marking-1.12', E'en', E'Marking 1.12', E'The "stop line" shows the place where the driver must stop when sign 2.5 is present, or at a prohibiting signal of a traffic light or traffic controller.', E'Stop line: shows where to stop when sign 2.4 stands there, or at a red traffic light or a traffic controller''s stop signal.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/en/card_cb06c9f7b7.webm'),
  (E'marking-1.12', E'ka', E'მონიშვნა 1.12', E'„სდექ ხაზი” აჩვენებს ადგილს, სადაც მძღოლი უნდა გაჩერდეს 2.5 ნიშნის არსებობისას, ან შუქნიშნის და მარეგულირებლის ამკრძალავ სიგნალზე.', E'„სდექ“ ხაზი: აჩვენებს, სად უნდა გაჩერდე, როცა 2.4 ნიშანი დგას, ან შუქნიშნის ან მარეგულირებლის ამკრძალავ სიგნალზე.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ka/card_2be43f7ee8.webm'),
  (E'marking-1.12', E'ru', E'Разметка 1.12', E'«Стоп-линия» указывает место, где водитель должен остановиться при наличии знака 2.5 или при запрещающем сигнале светофора и регулировщика.', E'Стоп-линия: показывает, где остановиться при знаке 2.4 или при запрещающем сигнале светофора или регулировщика.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ru/card_dbfc75b9bc.webm'),
  (E'marking-1.13', E'en', E'Marking 1.13', E'Shows the place where the driver must, if necessary, stop and give way to vehicles moving on the intersecting road.', E'Shows where to stop, if needed, to give way to traffic on the crossing road.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/en/card_63125403fe.webm'),
  (E'marking-1.13', E'ka', E'მონიშვნა 1.13', E'აჩვენებს ადგილს, სადაც მძღოლი აუცილებლობის შემთხვევაში უნდა გაჩერდეს და გზა დაუთმოს გადამკვეთ გზაზე მოძრავ სატრანსპორტო საშუალებას.', E'აჩვენებს, სად უნდა გაჩერდე საჭიროების შემთხვევაში, რომ გადამკვეთ გზაზე მოძრავს გზა დაუთმო.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ka/card_bafd70d023.webm'),
  (E'marking-1.13', E'ru', E'Разметка 1.13', E'Указывает место, где водитель при необходимости должен остановиться и уступить дорогу транспортным средствам, движущимся по пересекаемой дороге.', E'Показывает, где при необходимости остановиться, чтобы уступить дорогу тем, кто едет по пересекаемой дороге.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ru/card_accd5c7604.webm'),
  (E'marking-1.14.1', E'en', E'Marking 1.14.1', E'The "zebra" marks an uncontrolled pedestrian crossing;', E'“Zebra”: marks an unregulated pedestrian crossing.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/en/card_5eb502e0d6.webm'),
  (E'marking-1.14.1', E'ka', E'მონიშვნა 1.14.1', E'„ზებრა” აღნიშნავს ქვეითთა მოუწესრიგებელ გადასასვლელს;', E'„ზებრა“: აღნიშნავს ქვეითთა არარეგულირებულ გადასასვლელს.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ka/card_5ff0fafb94.webm'),
  (E'marking-1.14.1', E'ru', E'Разметка 1.14.1', E'«Зебра» обозначает нерегулируемый пешеходный переход;', E'«Зебра»: обозначает нерегулируемый пешеходный переход.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ru/card_0cb5486f42.webm'),
  (E'marking-1.14.2', E'en', E'Marking 1.14.2', E'The "zebra" marks an uncontrolled pedestrian crossing; the arrows of marking 1.14.2 show the direction of pedestrian movement.', E'“Zebra”: marks an unregulated pedestrian crossing. The arrows show the direction pedestrians walk.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/en/card_8a762c66d3.webm'),
  (E'marking-1.14.2', E'ka', E'მონიშვნა 1.14.2', E'„ზებრა” აღნიშნავს ქვეითთა მოუწესრიგებელ გადასასვლელს; 1.14.2 მონიშვნის ისარი უჩვენებს ქვეითთა მოძრაო­ბის მიმართულებას.', E'„ზებრა“: აღნიშნავს ქვეითთა არარეგულირებულ გადასასვლელს. ისარი ქვეითთა მოძრაობის მიმართულებას აჩვენებს.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ka/card_5ff0fafb94.webm'),
  (E'marking-1.14.2', E'ru', E'Разметка 1.14.2', E'«Зебра» обозначает нерегулируемый пешеходный переход; стрелы разметки 1.14.2 указывают направление движения пешеходов.', E'«Зебра»: обозначает нерегулируемый пешеходный переход. Стрелки показывают направление движения пешеходов.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ru/card_eac9d74392.webm'),
  (E'marking-1.14.3', E'en', E'Marking 1.14.3', E'Marks a pedestrian crossing where traffic is controlled by a traffic light.', E'Marks a pedestrian crossing controlled by traffic lights.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/en/card_fe9aa14bdf.webm'),
  (E'marking-1.14.3', E'ka', E'მონიშვნა 1.14.3', E'აღნიშნავს ქვეითთა გადასასვლელს, სადაც მოძრაობა წესრიგდება შუქნიშნით.', E'აღნიშნავს ქვეითთა გადასასვლელს, სადაც მოძრაობას შუქნიშანი არეგულირებს.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ka/card_2b9e72cfb7.webm'),
  (E'marking-1.14.3', E'ru', E'Разметка 1.14.3', E'Обозначает пешеходный переход, где движение регулируется светофором.', E'Обозначает пешеходный переход, на котором движение регулирует светофор.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ru/card_a03fe7fc70.webm'),
  (E'marking-1.15', E'en', E'Marking 1.15', E'Marks the place where a cycle track crosses the carriageway.', E'Marks the place where a cycle path crosses the carriageway.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/en/card_41e96aad31.webm'),
  (E'marking-1.15', E'ka', E'მონიშვნა 1.15', E'აღნიშნავს ადგილს, სადაც საველოსიპედო ბილიკი კვეთსგზის სავალ ნაწილს.', E'აღნიშნავს ადგილს, სადაც ველობილიკი სავალ ნაწილს კვეთს.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ka/card_9d6250ecbd.webm'),
  (E'marking-1.15', E'ru', E'Разметка 1.15', E'Обозначает место, где велосипедная дорожка пересекает проезжую часть.', E'Обозначает место, где велосипедная дорожка пересекает проезжую часть.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ru/card_6376e10cc9.webm'),
  (E'marking-1.16.1–1.16.3', E'en', E'Marking 1.16.1–1.16.3', E'Marks guide islands at places where traffic flows split or merge.', E'Marks guiding islands where traffic flows split or merge.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/en/card_64816da89d.webm'),
  (E'marking-1.16.1–1.16.3', E'ka', E'მონიშვნა 1.16.1–1.16.3', E'აღნიშნავს მიმმართველ კუნძულებს სატრანსპორტო ნაკადების გაყოფის ან შეერთების ადგილზე.', E'აღნიშნავს მიმმართველ კუნძულებს იქ, სადაც ნაკადები იყოფა ან ერთდება.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ka/card_87b71f6109.webm'),
  (E'marking-1.16.1–1.16.3', E'ru', E'Разметка 1.16.1–1.16.3', E'Обозначает направляющие островки в местах разделения или слияния транспортных потоков.', E'Обозначает направляющие островки в местах разделения или слияния транспортных потоков.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ru/card_14753e2c76.webm'),
  (E'marking-1.17', E'en', E'Marking 1.17', E'Marks stops of route vehicles and taxi ranks.', E'Marks route vehicle stops and taxi ranks.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/en/card_570422ac9b.webm'),
  (E'marking-1.17', E'ka', E'მონიშვნა 1.17', E'აღნიშნავს სამარშრუტო სატრანსპორტო საშუალების გაჩერებას და ტაქსის სადგომს.', E'აღნიშნავს სამარშრუტო ტრანსპორტის გაჩერებას და ტაქსის სადგომს.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ka/card_5bc194756e.webm'),
  (E'marking-1.17', E'ru', E'Разметка 1.17', E'Обозначает остановки маршрутных транспортных средств и стоянки такси.', E'Обозначает остановки маршрутных транспортных средств и стоянки такси.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ru/card_c03c026d00.webm'),
  (E'marking-1.18', E'en', E'Marking 1.18', E'Marks the permitted directions of movement in the lanes at an intersection; it is used on its own or in combination with signs 5.8.1, 5.8.2; marking with a dead-end symbol indicates that turning onto the nearest carriageway is prohibited; marking that allows a left turn from the far-left lane also allows a U-turn from that lane.', E'Lane arrows: show which directions you may take at the intersection from this lane. Used on their own or with signs 5.15.1 and 5.15.2. A dead-end symbol means turning onto the nearest carriageway is banned; if you may turn left from the leftmost lane, you may also make a U-turn from it.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/en/card_6e8e13753c.webm'),
  (E'marking-1.18', E'ka', E'მონიშვნა 1.18', E'აღნიშნავს გზაჯვარედინის ზოლებზე მოძრაობის ნებადართულ მიმართულებებს; გამოიყენება დამოუკიდებლად ან 5.8.1, 5.8.2 ნიშნებთან შეერთებით; მონიშვნა ჩიხის გამოსახულებით მიუთითებს, რომ მოხვევა უახლოეს სავალ ნაწილზე აკრძალულია; უკიდურესი მარცხენა ზოლიდან მარცხნივ მოხვევის ნებადამრთველი მონიშვნა, ამავე დროს, ამ ზოლიდან მობრუნების ნებას იძლევა.', E'ისრები ზოლებზე: გიჩვენებს, რა მიმართულებით შეიძლება მოძრაობა გზაჯვარედინზე ამ ზოლიდან. გამოიყენება ცალკე ან 5.15.1 და 5.15.2 ნიშნებთან ერთად. ჩიხის გამოსახულება ნიშნავს, რომ უახლოეს სავალ ნაწილზე მოხვევა აკრძალულია; თუ უკიდურესი მარცხენა ზოლიდან მარცხნივ მოხვევა შეიძლება, ამ ზოლიდან მობრუნებაც შეიძლება.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ka/card_c4c5431cfd.webm'),
  (E'marking-1.18', E'ru', E'Разметка 1.18', E'Указывает разрешённые на перекрёстке направления движения по полосам; применяется самостоятельно или в сочетании со знаками 5.8.1, 5.8.2; разметка с изображением тупика указывает, что поворот на ближайшую проезжую часть запрещён; разметка, разрешающая поворот налево из крайней левой полосы, разрешает и разворот из этой полосы.', E'Стрелки на полосах: показывают, в каких направлениях на перекрёстке разрешено движение из этой полосы. Применяются самостоятельно или со знаками 5.15.1 и 5.15.2. Изображение тупика означает, что поворот на ближайшую проезжую часть запрещён; если из крайней левой полосы разрешён поворот налево, из неё разрешён и разворот.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ru/card_1e078f8041.webm'),
  (E'marking-1.19', E'en', E'Marking 1.19', E'Warns of approaching a narrowing of the carriageway (a section where the number of traffic lanes in the given direction decreases) or marking 1.1 or 1.11 that separates traffic flows moving in opposite directions. In the first case, marking 1.19 may be used in combination with signs 1.18.1–1.18.3.', E'Warns that the carriageway narrows ahead (fewer lanes in your direction), or that you are approaching marking 1.1 or 1.11 separating opposite flows. When the road narrows, it may be used with signs 1.21.1–1.21.3.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/en/card_3588383677.webm'),
  (E'marking-1.19', E'ka', E'მონიშვნა 1.19', E'აფრთხილებს სავალი ნაწილის შევიწროებასთან (მონაკვეთთან, სადაც მცირდება მოცემული მიმართულებით მოძრაობის ზოლების რაოდენობა) ან საპირისპირო მიმართულებით მოძრავ სატრანსპორტო ნაკადების გამყოფ 1.1 ან 1.11 მონიშვნასთან მიახლოების შესახებ. 1.19 მონიშვნა პირველ შემთხვევაში შეიძლება გამოყენებულ იქნეს 1.18.1–1.18.3 ნიშნებთან შეერთებით.', E'აფრთხილებს, რომ წინ სავალი ნაწილი ვიწროვდება (შენი მიმართულებით ზოლები მცირდება), ან რომ უახლოვდები 1.1 ან 1.11 მონიშვნას, რომელიც საპირისპირო ნაკადებს ყოფს. შევიწროებისას ის შეიძლება 1.21.1–1.21.3 ნიშნებთან ერთად გამოიყენებოდეს.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ka/card_4be875490e.webm'),
  (E'marking-1.19', E'ru', E'Разметка 1.19', E'Предупреждает о приближении к сужению проезжей части (участку, где уменьшается число полос движения в данном направлении) или к разметке 1.1 или 1.11, разделяющей транспортные потоки противоположных направлений. В первом случае разметка 1.19 может применяться в сочетании со знаками 1.18.1–1.18.3.', E'Предупреждает о сужении проезжей части впереди (в вашем направлении становится меньше полос) или о приближении к разметке 1.1 или 1.11, разделяющей встречные потоки. При сужении может применяться вместе со знаками 1.21.1–1.21.3.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ru/card_057d7c7d85.webm'),
  (E'marking-1.2', E'en', E'Marking 1.2', E'A wide solid line marks the edges of the carriageway on a motorway. Crossing line 1.2 is allowed in order to stop the vehicle at the side of the road.', E'Wide solid line: marks the edge of the carriageway on a motorway. You may cross it to stop on the roadside.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/en/card_db939c509f.webm'),
  (E'marking-1.2', E'ka', E'მონიშვნა 1.2', E'მთლიანი ფართო ხაზი აღნიშნავს ავტომაგისტრალზე სავალი ნაწილის ნაპირებს. 1.2 ხაზის გადაკვეთა დასაშვებია სატრანსპორტო საშუალების გზის ნაპირზე გასაჩერებლად.', E'უწყვეტი ფართო ხაზი: ავტომაგისტრალზე სავალი ნაწილის ნაპირს აღნიშნავს. მისი გადაკვეთა შეიძლება, რომ გზის ნაპირზე გაჩერდე.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ka/card_0ded675ae3.webm'),
  (E'marking-1.2', E'ru', E'Разметка 1.2', E'Сплошная широкая линия обозначает края проезжей части на автомагистрали. Пересекать линию 1.2 допускается для остановки транспортного средства на обочине.', E'Широкая сплошная линия: обозначает край проезжей части на автомагистрали. Пересекать её можно, чтобы остановиться на обочине.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ru/card_ce8a682657.webm'),
  (E'marking-1.20', E'en', E'Marking 1.20', E'Warns of approaching marking 1.13.', E'Warns that you are approaching marking 1.13.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/en/card_3efe36c5c0.webm'),
  (E'marking-1.20', E'ka', E'მონიშვნა 1.20', E'აფრთხილებს 1.13 მონიშვნასთან მიახლოების შესახებ.', E'აფრთხილებს, რომ უახლოვდები 1.13 მონიშვნას.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ka/card_fbee4022e7.webm'),
  (E'marking-1.20', E'ru', E'Разметка 1.20', E'Предупреждает о приближении к разметке 1.13.', E'Предупреждает о приближении к разметке 1.13.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ru/card_652716e2b2.webm'),
  (E'marking-1.21', E'en', E'Marking 1.21', E'The inscription "STOP" warns of approaching marking 1.12 when it is used in combination with sign 2.5.', E'The word “STOP”: warns that you are approaching marking 1.12 when it is used with sign 2.4.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/en/card_55f12913ab.webm'),
  (E'marking-1.21', E'ka', E'მონიშვნა 1.21', E'წარწერა „სდექ” აფრთხილებს 1.12 მონიშვნასთან მიახლოების შესახებ, თუ ის გამოიყენება 2.5 ნიშანთან შეერთებით.', E'წარწერა „სდექ“: აფრთხილებს, რომ უახლოვდები 1.12 მონიშვნას, როცა ის 2.4 ნიშანთან ერთად გამოიყენება.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ka/card_0909fdbc9e.webm'),
  (E'marking-1.21', E'ru', E'Разметка 1.21', E'Надпись «СТОП» предупреждает о приближении к разметке 1.12, если она применяется в сочетании со знаком 2.5.', E'Надпись «СТОП»: предупреждает о приближении к разметке 1.12, когда она применяется вместе со знаком 2.4.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ru/card_e2bd64c4dc.webm'),
  (E'marking-1.22', E'en', E'Marking 1.22', E'Shows the road (route) number.', E'Shows the road (route) number.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/en/card_ce07a1d031.webm'),
  (E'marking-1.22', E'ka', E'მონიშვნა 1.22', E'აჩვენებს გზის (მარშრუტის) ნომერს.', E'გიჩვენებს გზის (მარშრუტის) ნომერს.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ka/card_cd13ab9f5b.webm'),
  (E'marking-1.22', E'ru', E'Разметка 1.22', E'Указывает номер дороги (маршрута).', E'Показывает номер дороги (маршрута).', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ru/card_41c9bc514c.webm'),
  (E'marking-1.23', E'en', E'Marking 1.23', E'Marks a special lane intended for the movement of route vehicles.', E'Marks a lane meant for route vehicles.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/en/card_8fd5fe1877.webm'),
  (E'marking-1.23', E'ka', E'მონიშვნა 1.23', E'აღნიშნავს სპეციალურ ზოლს, რომელიც განკუთვნილია სამარშრუტო სატრანსპორტო საშუალების მოძრაობისათვის.', E'აღნიშნავს ზოლს, რომელიც სამარშრუტო ტრანსპორტის მოძრაობისთვისაა განკუთვნილი.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ka/card_df4c7116c4.webm'),
  (E'marking-1.23', E'ru', E'Разметка 1.23', E'Обозначает специальную полосу, предназначенную для движения маршрутных транспортных средств.', E'Обозначает полосу, предназначенную для движения маршрутных транспортных средств.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ru/card_10152c5d15.webm'),
  (E'marking-1.3', E'en', E'Marking 1.3', E'Separates traffic flows moving in opposite directions on roads with four or more traffic lanes. Crossing line 1.3 is prohibited.', E'Double solid line: separates opposite traffic flows on a road with four or more lanes. Crossing line 1.3 is banned.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/en/card_b9e83daae3.webm'),
  (E'marking-1.3', E'ka', E'მონიშვნა 1.3', E'ყოფს საპირისპირო მიმართულებით მოძრავ სატრანსპორტო ნაკადებს გზაზე, რომელსაც მოძრაობის ოთხი და მეტი ზოლი აქვს.1.3 ხაზის გადაკვეთა აკრძალულია.', E'ორმაგი უწყვეტი ხაზი: ყოფს საპირისპირო მიმართულების ნაკადებს გზაზე, სადაც ოთხი ან მეტი ზოლია. 1.3 ხაზის გადაკვეთა აკრძალულია.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ka/card_903095288e.webm'),
  (E'marking-1.3', E'ru', E'Разметка 1.3', E'Разделяет транспортные потоки противоположных направлений на дорогах, имеющих четыре полосы движения и более. Пересекать линию 1.3 запрещается.', E'Двойная сплошная линия: разделяет потоки противоположных направлений на дороге с четырьмя и более полосами. Пересекать линию 1.3 запрещено.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ru/card_5700fb092e.webm'),
  (E'marking-1.4', E'en', E'Marking 1.4', E'Marks a place where stopping is prohibited; it is used on its own or in combination with sign 3.27; it is painted along the edge of the carriageway or on top of the kerb.', E'Marks a place where stopping is banned. It is used on its own or with sign 3.27, along the edge of the carriageway or on top of the kerb.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/en/card_5b4bf330e3.webm'),
  (E'marking-1.4', E'ka', E'მონიშვნა 1.4', E'აღნიშნავს ადგილს, სადაც აკრძალულია გაჩერება; გამოი­ყენება დამოუკიდებლად ან 3.27 ნიშანთან შეერთებით; იხაზება სავალი ნაწილის ნაპირთან ან ბორდიურზე ზემოდან.', E'აღნიშნავს ადგილს, სადაც გაჩერება აკრძალულია. გამოიყენება ცალკე ან 3.27 ნიშანთან ერთად; იხაზება სავალი ნაწილის ნაპირთან ან ბორდიურის თავზე.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ka/card_421861da0c.webm'),
  (E'marking-1.4', E'ru', E'Разметка 1.4', E'Обозначает места, где запрещена остановка; применяется самостоятельно или в сочетании со знаком 3.27; наносится у края проезжей части или по верху бордюра.', E'Обозначает места, где остановка запрещена. Применяется самостоятельно или вместе со знаком 3.27; наносится у края проезжей части или по верху бордюра.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ru/card_8da4d283a3.webm'),
  (E'marking-1.5', E'en', E'Marking 1.5', E'Separates traffic flows moving in opposite directions on roads with two or three traffic lanes; marks the boundaries of traffic lanes when there are two or more lanes intended for traffic in one direction. Crossing line 1.5 is allowed from either side.', E'Broken line: separates opposite traffic flows on a two- or three-lane road, and marks lane edges when there are two or more lanes in one direction. You may cross it from either side.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/en/card_59a96378f8.webm'),
  (E'marking-1.5', E'ka', E'მონიშვნა 1.5', E'ყოფს საპირისპირო მიმართულებით მოძრავ სატრანსპორტო ნაკადებს გზაზე, რომელსაც მოძრაობის ორი ან სამი ზოლი აქვს; აღნიშნავს მოძრაობის ზოლების საზღვრებს ერთი მიმართულებით მოძრაობისათვის განკუთვნილი ორი და მეტიზოლის არსებობისას. 1.5 ხაზის გადაკვეთა ნებადართულია ნებისმიერი მხრიდან.', E'წყვეტილი ხაზი: ყოფს საპირისპირო მიმართულების ნაკადებს ორ- ან სამზოლიან გზაზე, ასევე აღნიშნავს ზოლების საზღვრებს, როცა ერთი მიმართულებით ორი ან მეტი ზოლია. მის გადაკვეთა ნებისმიერი მხრიდან შეიძლება.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ka/card_bcb1b26ddb.webm'),
  (E'marking-1.5', E'ru', E'Разметка 1.5', E'Разделяет транспортные потоки противоположных направлений на дорогах, имеющих две или три полосы движения; обозначает границы полос движения при наличии двух и более полос, предназначенных для движения в одном направлении. Пересекать линию 1.5 разрешается с любой стороны.', E'Прерывистая линия: разделяет потоки противоположных направлений на дороге с двумя или тремя полосами, а также обозначает границы полос, когда в одном направлении две полосы и более. Пересекать её можно с любой стороны.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ru/card_37d848b45c.webm'),
  (E'marking-1.6', E'en', E'Marking 1.6', E'Approach line (a broken line whose dashes are three times longer than the gaps between them) warns of approaching marking 1.1 or 1.11 that separates traffic flows moving in opposite or the same directions. Crossing line 1.6 is allowed from either side.', E'Approach line: a broken line whose dashes are three times longer than the gaps. It warns that you are approaching marking 1.1 or 1.11 that separates traffic flows. You may cross it from either side.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/en/card_7542274e29.webm'),
  (E'marking-1.6', E'ka', E'მონიშვნა 1.6', E'მიახლოების ხაზი – (წყვეტილი ხაზი, რომლის შტრიხების სიგრძე სამჯერ აღემატება მათ შორის არსებულ შუალედებს) აფრთხილებს საპირისპირო ან თანმხვედრი მიმართულებით მოძრავი სატრანს­პორტო ნაკადების გამყოფ 1.1 ან 1.11 მონიშვნასთან მიახლოების შესახებ. 1.6 ხაზის გადაკვეთა ნებადართულია ნებისმიერი მხრიდან.', E'მიახლოების ხაზი: წყვეტილი ხაზი, რომლის შტრიხები შუალედებზე სამჯერ გრძელია. აფრთხილებს, რომ უახლოვდები 1.1 ან 1.11 მონიშვნას, რომელიც ნაკადებს ყოფს. მის გადაკვეთა ნებისმიერი მხრიდან შეიძლება.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ka/card_ee02fdf318.webm'),
  (E'marking-1.6', E'ru', E'Разметка 1.6', E'Линия приближения – (прерывистая линия, у которой длина штрихов в три раза превышает промежутки между ними) предупреждает о приближении к разметке 1.1 или 1.11, разделяющей транспортные потоки противоположных или попутных направлений. Пересекать линию 1.6 разрешается с любой стороны.', E'Линия приближения: прерывистая линия, штрихи которой втрое длиннее промежутков. Предупреждает, что вы приближаетесь к разметке 1.1 или 1.11, разделяющей потоки. Пересекать её можно с любой стороны.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ru/card_f6b01c8b86.webm'),
  (E'marking-1.7', E'en', E'Marking 1.7', E'A broken line with short dashes and gaps of the same length marks traffic lanes within an intersection. Crossing line 1.7 is allowed from either side.', E'Broken line with short dashes and equal gaps: marks traffic lanes within an intersection. You may cross it from either side.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/en/card_c3f4d56e76.webm'),
  (E'marking-1.7', E'ka', E'მონიშვნა 1.7', E'წყვეტილი ხაზი მოკლე შტრიხებითა და იმავე ზომის შუალედებით აღნიშნავს მოძრაობის ზოლებს გზაჯვარედინის ფარგლებში. 1.7 ხაზის გადაკვეთა ნებადართულია ნებისმიერი მხრიდან.', E'წყვეტილი ხაზი მოკლე შტრიხებით და იმავე ზომის შუალედებით: გზაჯვარედინზე მოძრაობის ზოლებს აღნიშნავს. მის გადაკვეთა ნებისმიერი მხრიდან შეიძლება.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ka/card_93d52ab19b.webm'),
  (E'marking-1.7', E'ru', E'Разметка 1.7', E'Прерывистая линия с короткими штрихами и равными им промежутками обозначает полосы движения в пределах перекрёстка. Пересекать линию 1.7 разрешается с любой стороны.', E'Прерывистая линия с короткими штрихами и равными им промежутками: обозначает полосы движения в пределах перекрёстка. Пересекать её можно с любой стороны.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ru/card_2c84d76537.webm'),
  (E'marking-1.8', E'en', E'Marking 1.8', E'Wide broken line: marks the boundary between acceleration or deceleration lanes and the main lane of the carriageway (at intersections, at grade-separated junctions, at bus stop areas, etc.). Crossing line 1.8 is allowed from either side.', E'Wide broken line: marks the border between an acceleration or braking lane and the main lane (at intersections, at grade-separated junctions, at bus stops and so on). You may cross it from either side.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/en/card_a17201d4aa.webm'),
  (E'marking-1.8', E'ka', E'მონიშვნა 1.8', E'განიერი წყვეტილი ხაზი - აღნიშნავს საზღვრებს გაქანების ან დამუხრუჭების ზოლებსა და სავალი ნაწილის ძირითად ზოლსშორის (გზაჯვარედინზე, სხვადასხვა დონეზე გზებისგადაკვეთაზე, ავტობუსის გაჩერების ზონაში და სხვა). 1.8 ხაზის გადაკვეთა ნებადართულია ნებისმიერი მხრიდან.', E'განიერი წყვეტილი ხაზი: გაქანების ან დამუხრუჭების ზოლსა და ძირითად ზოლს შორის საზღვარს აღნიშნავს (გზაჯვარედინზე, სხვადასხვა დონის გზების გადაკვეთაზე, ავტობუსის გაჩერებასთან და ა. შ.). მის გადაკვეთა ნებისმიერი მხრიდან შეიძლება.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ka/card_48fde92ec4.webm'),
  (E'marking-1.8', E'ru', E'Разметка 1.8', E'Широкая прерывистая линия – обозначает границу между полосами разгона или торможения и основной полосой проезжей части (на перекрёстках, пересечениях дорог в разных уровнях, в зоне автобусных остановок и т. д.). Пересекать линию 1.8 разрешается с любой стороны.', E'Широкая прерывистая линия: обозначает границу между полосой разгона или торможения и основной полосой (на перекрёстках, пересечениях дорог в разных уровнях, у автобусных остановок и т. д.). Пересекать её можно с любой стороны.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ru/card_358536e062.webm'),
  (E'marking-1.9', E'en', E'Marking 1.9', E'Marks the boundaries of traffic lanes with reversible traffic control; separates traffic flows moving in opposite directions (when the reversible traffic lights are switched off) on roads with reversible traffic control.', E'Marks the edges of reversible lanes. When the reversible traffic lights are off, it separates opposite traffic flows.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/en/card_88facb5738.webm'),
  (E'marking-1.9', E'ka', E'მონიშვნა 1.9', E'აღნიშნავს რევერსულად მოწესრიგებული მოძრაობის ზოლების საზღვრებს, ყოფს საპირისპირო მიმართულებით მოძრავ სატრანსპორტო ნაკადებს (როდესაც გამორთულია რევერსული შუქნიშნები) გზებზე, რომლებიც რევერსულად წესრიგდება.', E'აღნიშნავს რევერსული მოძრაობის ზოლების საზღვრებს. როცა რევერსული შუქნიშნები გამორთულია, ის საპირისპირო მიმართულების ნაკადებს ყოფს.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ka/card_f1b768ba8a.webm'),
  (E'marking-1.9', E'ru', E'Разметка 1.9', E'Обозначает границы полос движения, на которых осуществляется реверсивное регулирование; разделяет транспортные потоки противоположных направлений (при выключенных реверсивных светофорах) на дорогах, где осуществляется реверсивное регулирование.', E'Обозначает границы полос реверсивного движения. Когда реверсивные светофоры выключены, она разделяет потоки противоположных направлений.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ru/card_7dba109a47.webm'),
  (E'rule-1-accident', E'ka', E'საგზაო-სატრანსპორტო შემთხვევის შემდეგ', E'შემთხვევის მონაწილე მძღოლმა მანქანა დაუყოვნებლივ უნდა გააჩეროს, ადგილიდან არ დაძრას და საავარიო შუქსიგნალიზაცია ჩართოს. მან ადგილზე მოძრაობის უსაფრთხოება უნდა უზრუნველყოს, არაფერი შეცვალოს და არ გაანადგუროს ნაკვალევი, რომელიც პასუხისმგებლობის დადგენას გამოადგება. თვითმხილველების გვარებიც უნდა ჩაიწეროს.', NULL, NULL),
  (E'rule-1-axle-load', E'ka', E'ღერძზე დატვირთვა', E'ღერძზე დატვირთვა ფაქტობრივი მასის ის ნაწილია, რომელიც ღერძზე დაწოლით გზას ტვირთავს. მისი განსაზღვრისას განივ ჭრილში ერთ ხაზზე განლაგებული, კონსტრუქციულად განცალკევებული ღერძები ერთ მთლიან ღერძად ითვლება.', NULL, NULL),
  (E'rule-1-b-trailer', E'ka', E'„B“ და „BE“ მისაბმელით', E'„B“ კატეგორიით შეგიძლია მართო ავტომობილი მისაბმელით, რომლის ნებადართული მაქსიმალური მასა 750 კგ-ს არ აღემატება. უფრო მძიმე მისაბმელიც შეიძლება, თუ ის ავტომობილის დაუტვირთავ მასაზე მძიმე არ არის, ხოლო შემადგენლობის საერთო ნებადართული მაქსიმალური მასა 3 500 კგ-ს არ აღემატება. „BE“ კატეგორია საჭიროა, როცა 750 კგ-ზე მძიმე მისაბმელი ავტომობილის დაუტვირთავ მასას აღემატება ან შემადგენლობის საერთო მასა 3 500 კგ-ზე მეტია.', NULL, NULL),
  (E'rule-1-category-b', E'ka', E'რას მართავ „B“ კატეგორიით', E'„B“ კატეგორიით შეგიძლია მართო ავტომობილი, რომლის ნებადართული მაქსიმალური მასა 3 500 კგ-ს არ აღემატება, ხოლო დასასხდომი ადგილები, მძღოლისას გარდა, 8-ს. ამ კატეგორიით „B1“ ქვეკატეგორიის მართვაც შეგიძლია. ასევე თვლიანი სასოფლო-სამეურნეო ტრაქტორი, რომლის ნებადართული მაქსიმალური მასა 4 250 კგ-ს არ აღემატება, და ის მისაბმელით, თუ შემადგენლობის საერთო ნებადართული მაქსიმალური მასა 4 250 კგ-ზე მეტი არ არის.', NULL, NULL),
  (E'rule-1-category-c', E'ka', E'„C“ და „CE“ კატეგორია', E'„C“ კატეგორიით მართავ ავტომობილს, რომლის ნებადართული მაქსიმალური მასა 3 500 კგ-ს აღემატება, გარდა „D1“ ქვეკატეგორიისა და „D“ კატეგორიის სატრანსპორტო საშუალებებისა. მას მისაბმელიც შეიძლება ჰქონდეს, თუ მისაბმელის ნებადართული მაქსიმალური მასა 750 კგ-ს არ აღემატება. უფრო მძიმე მისაბმელისთვის „CE“ კატეგორია გჭირდება. „C“ კატეგორია „C1“ ქვეკატეგორიის მართვის უფლებასაც გაძლევს, „CE“ კი — „C1E“-სი.', NULL, NULL),
  (E'rule-1-category-c1', E'ka', E'„C1“ და „C1E“ ქვეკატეგორია', E'„C1“ ქვეკატეგორიით მართავ ავტომობილს, რომლის ნებადართული მაქსიმალური მასა 3 500 კგ-ს აღემატება, მაგრამ 7 500 კგ-ს არა, გარდა „D1“ ქვეკატეგორიისა და „D“ კატეგორიის სატრანსპორტო საშუალებებისა. მასზე შეიძლება გადაბმული იყოს მისაბმელი, რომლის ნებადართული მაქსიმალური მასა 750 კგ-ს არ აღემატება. „C1E“ ქვეკატეგორიით უფრო მძიმე მისაბმელსაც მართავ, თუ ის ავტომობილის დაუტვირთავ მასაზე მძიმე არ არის, ხოლო შემადგენლობის საერთო ნებადართული მაქსიმალური მასა 12 000 კგ-ს არ აღემატება.', NULL, NULL),
  (E'rule-1-combined-categories', E'ka', E'კატეგორიების შეთავსება', E'„CE“ ან „DE“ კატეგორიის, ასევე „C1E“ ან „D1E“ ქვეკატეგორიის მქონე პირს „BE“ კატეგორიის მართვის უფლებაც აქვს. თუ „CE“-სთან ერთად „D“ კატეგორიაც გაქვს, „DE“-ს მართვაც შეგიძლია. „C1E“ და „D1“ ერთად „D1E“-ს მართვის უფლებას გაძლევს, „DE“ და „C1“ კი — „C1E“-სი.', NULL, NULL),
  (E'rule-1-driver-care-pedestrians', E'ka', E'სიფრთხილე ქვეითების მიმართ', E'განსაკუთრებული სიფრთხილე გამოიჩინე ქვეითების, მათ შორის ბავშვების, ხანდაზმულებისა და შეზღუდული შესაძლებლობის მქონე პირების, ასევე ველოსიპედისტების მიმართ. თეთრი ხელჯოხით ან გამყოლ ძაღლთან ერთად მოძრავ უსინათლო ქვეითს გზა ყველა შემთხვევაში უნდა დაუთმო. ჩართული გარე სანათებით ან ღია კარით გაჩერებული სატრანსპორტო საშუალების გასწვრივ ფრთხილად იმოძრავე, რომ ქვეითებისა და ბავშვების მოულოდნელი გამოჩენით შექმნილი საფრთხე დროულად აიცილო. თუ წესები ქვეითთა ადგილებში შესვლის უფლებას გაძლევს, იქ მაქსიმალური სიფრთხილით და დაბალი სიჩქარით იმოძრავე, რომ საჭიროებისას გაჩერდე.', NULL, NULL),
  (E'rule-1-id-plates-large', E'ka', E'საცნობი ნიშნები დიდ ავტომობილებზე', E'„ავტომატარებელი“ კაბინის თავზე ჰორიზონტალურად განლაგებული სამი ნარინჯისფერი მაშუქია, ერთმანეთისგან 150–300 მმ-ით დაშორებული; ის ავტომატარებელსა და შესახსრებულ ავტობუსზე მაგრდება. „არაგაბარიტული (მსხვილგაბარიტიანი) ტვირთი“ 400×400 მმ ზომის დაფაა დიაგონალური წითელი და თეთრი შუქამრეკლი ზოლებით და წინა და უკანა მხარეს მაგრდება. „გრძელი სატრანსპორტო საშუალება“ ყვითელი მართკუთხედია წითელი არშიით. ის უკან მაგრდება, თუ სიგრძე ტვირთით ან უმისოდ 20 მეტრს აღემატება, ან შემადგენლობაში ორი ან მეტი მისაბმელია.', NULL, NULL),
  (E'rule-1-id-plates-optional', E'ka', E'საცნობი ნიშნები სურვილისამებრ', E'ზოგი საცნობი ნიშანი მძღოლის სურვილით მაგრდება. „შეზღუდული შესაძლებლობის მქონე პირი“ ყვითელი კვადრატია 8.17 ნიშნის შავი სიმბოლოთი: მას წინ და უკან ამაგრებს ასეთი სტატუსის მძღოლი ან ის, ვისაც ასეთი პირები გადაჰყავს. „ექიმი“ ლურჯი კვადრატია თეთრი წრითა და წითელი ჯვრით და იმ მანქანაზე მაგრდება, რომელსაც ექიმი მართავს.', NULL, NULL),
  (E'rule-1-id-plates-required', E'ka', E'სავალდებულო საცნობი ნიშნები', E'„კოტები“ — თეთრი სამკუთხედი წითელი არშიითა და შავი „კ“-თი, უკან, თუ კოტებიანი საბურავებია. „სასწავლო-სატრანსპორტო საშუალება“ — იგივე სამკუთხედი „ს“-ით, წინ და უკან. „სახიფათო ტვირთი“ — ნარინჯისფერი სწორკუთხედი შავი არშიით, წინ და უკან, ცისტერნაზე გვერდებზეც. „სმენადაქვეითებული მძღოლი“ — ყვითელი წრე სამი შავი წრით, წინ და უკან. „სიჩქარის შეზღუდვა“ — 3.24 ნიშნის შემცირებული ასლი, უკან მარცხნივ, როცა მანქანის მაქსიმალური სიჩქარე კანონით დადგენილზე ნაკლებია. „ავტომატარებელი“ — სამი ნარინჯისფერი ფარანი კაბინის თავზე, ავტომატარებელსა და შესახსრებულ ავტობუსზე; მოძრაობისას ირთვება, სიბნელესა და ცუდ ხილვადობაში — დგომისასაც.', NULL, NULL),
  (E'rule-1-lanes-junctions', E'ka', E'ზოლი, გზაჯვარედინი, დასახლებული პუნქტი', E'მოძრაობის ზოლი სავალი ნაწილის გრძივი ზოლია, მონიშნული თუ არა, რომელზეც ავტომობილები ერთ რიგად ეტევიან. გზაჯვარედინი გზების ერთ დონეზე კვეთა, შეერთება ან განშტოებაა; მიმდებარე ტერიტორიიდან (ეზო, ავტოსადგომი, ბენზინგასამართი სადგური, დაწესებულება) გამოსასვლელი გზაჯვარედინი არ არის. დასახლებული პუნქტი განაშენიანებული ტერიტორიაა, რომლის შესასვლელი და გამოსასვლელი ნიშნებითაა აღნიშნული: 5.23.1 და 5.23.2 „დასახლებული პუნქტის დასაწყისი“ აჩვენებს, საიდან მოქმედებს მისი წესები; 5.23.2 ისეთ განაშენიანებულ მონაკვეთზე დგას, რომელიც არცერთ დასახლებულ პუნქტში არ შედის.', NULL, NULL),
  (E'rule-1-masses', E'ka', E'დაუტვირთავი, დატვირთული და სრული მასა', E'დაუტვირთავი მასა ქარხანა-დამამზადებლის განსაზღვრული მასაა მძღოლის, მგზავრებისა და ტვირთის გარეშე, მაგრამ საწვავის სრული მარაგითა და ხელსაწყოების აუცილებელი კომპლექტით. დატვირთული მასა მოცემულ დროს ფაქტობრივი მასაა, მძღოლისა და მგზავრების ჩათვლით. სრული მასა ტვირთით, მძღოლითა და მგზავრებით შევსებული, აღჭურვილი სატრანსპორტო საშუალების მასაა, რომლის ზღვარს ქარხანა-დამამზადებელი ადგენს. ნებადართული მაქსიმალური მასა დატვირთულის მაქსიმალური მასაა, რომელსაც დასაშვებად აცხადებს იმ სახელმწიფოს კომპეტენტური ორგანო, სადაც მანქანაა დარეგისტრირებული.', NULL, NULL),
  (E'rule-1-pedestrian-duties', E'ka', E'ქვეითი გზაზე', E'თუ ხილვადობის ზონაში გადასასვლელი ან გზაჯვარედინი არ არის, ქვეითი გზას სავალი ნაწილის ღერძის პერპენდიკულარულად კვეთს იქ, სადაც გამყოფი ზოლი და ღობურა არ არის და გზა ორივე მხრიდან კარგად ჩანს. ვინც გადასვლა ვერ მოასწრო, უსაფრთხოების კუნძულზე ან ნაკადების გამყოფ ზოლზე თუ ხაზზე ჩერდება. დაუსახლებელ პუნქტში, ორმხრივ გზაზე გამყოფი ზოლისა და ტროტუარის გარეშე, ქვეითი საპირისპირო მხარის გვერდულაზე, მისი არარსებობისას კი სავალი ნაწილის მარცხენა კიდეზე, მოძრაობის საწინააღმდეგოდ მიდის. ველოსიპედის, მოპედის ან მოტოციკლის ხელით გადამყვანი და სავარძელ-ეტლით მოძრავი პირი მარჯვენა მხარეს იკავებს.', NULL, NULL),
  (E'rule-1-pedestrians-children', E'ka', E'ქვეითები და ბავშვები', E'თუ ქვეითთა ბილიკი, ტროტუარი და გზისპირი არ არის ან მათი გამოყენება შეუძლებელია, ქვეითს სავალ ნაწილზე სიარული შეუძლია, მაგრამ მის კიდესთან რაც შეიძლება ახლოს. ქვეითთა გადასასვლელზე ნუ შეხვალ, სანამ არ დარწმუნდები, რომ მასზე გაჩერება არ მოგიწევს. ტროტუარზე მოთამაშე ბავშვებთან სიჩქარე შეანელე და დამუხრუჭებისთვის მზად იყავი; თუ ბურთი სავალ ნაწილზე გადმოვარდა, ისინი შეიძლება მის ასაღებად გამოიქცნენ. საბავშვო ეტლი, სავარძელი ან დამჭერი მოწყობილობა ბავშვის სიმაღლესა და წონას უნდა შეესაბამებოდეს, ხოლო მანქანის კონსტრუქცია მისი გამოყენების საშუალებას უნდა იძლეოდეს.', NULL, NULL),
  (E'rule-1-priority', E'ka', E'უპირატესობა და გზის დათმობა', E'უპირატესობა მოძრაობის მონაწილის უფლებაა, სხვებზე ადრე იმოძრაოს დასახული მიმართულებით. გზის დათმობა ნიშნავს, რომ არ განაგრძო ან არ განაახლო მოძრაობა და არ შეასრულო მანევრი, თუ ამით უპირატესობის მქონეს აიძულებ, უეცრად შეცვალოს მიმართულება ან სიჩქარე. თუ სიბნელის, თოვლის, ტალახის ან სხვა მიზეზით ვერ არკვევ, გზას საფარი აქვს თუ არა, და პრიორიტეტის ნიშნებიც არ არის, ითვლება, რომ მეორეხარისხოვან გზაზე ხარ. გზის დათმობის განზრახვა ნათლად გამოხატე სიჩქარის შემცირებით ან გაჩერებით.', NULL, NULL),
  (E'rule-1-road-parts', E'ka', E'გზა და სავალი ნაწილი', E'გზა მოძრაობისთვის გახსნილი გზის ან ქუჩის მთელი ზედაპირია. სავალი ნაწილი ურელსო სატრანსპორტო საშუალებების მოძრაობისთვისაა; ტროტუარი, გვერდული, ველობილიკი და ქვეითთა ბილიკი მასში არ შედის. გზას შეიძლება ჰქონდეს ერთი ან რამდენიმე სავალი ნაწილი, რომლებსაც გამყოფი ზოლი ან სხვადასხვა დონე მიჯნავს. გამყოფი ზოლი კონსტრუქციულად გამოყოფილი ელემენტია და მასზე ურელსო სატრანსპორტო საშუალებები არ მოძრაობენ. ასეთ ორმხრივმოძრაობიან გზაზე საპირისპირო მოძრაობის მხარეა ის, რაც გამყოფი ზოლის მარცხნივაა.', NULL, NULL),
  (E'rule-1-temporary-signs', E'ka', E'დროებითი ნიშანი და 7.1 ნიშანი', E'თუ გადასატან სადგარზე ან საგზაო სამუშაოების ავტომობილზე დაყენებული დროებითი ნიშანი ეწინააღმდეგება იმავე მონაკვეთზე სტაციონარულად დადგმულს, დროებითის მოთხოვნები შეასრულე. 7.1 ნიშანი „მაქსიმალური სიჩქარის ზოგადი შეზღუდვები“ გაცნობებს საქართველოს გზებზე დადგენილ სიჩქარის შეზღუდვებს. ის საქართველოს ტერიტორიაზე შემოსასვლელში, საკონტროლო გამშვებ პუნქტთან იდგმება.', NULL, NULL),
  (E'rule-1-tractor-c', E'ka', E'ტრაქტორი „C“ და „C1“ კატეგორიით', E'„C1“ ქვეკატეგორიით შეგიძლია მართო თვლიანი სასოფლო-სამეურნეო ტრაქტორი, რომლის ნებადართული მაქსიმალური მასა 8 250 კგ-ს არ აღემატება, და ის მისაბმელით, თუ შემადგენლობის საერთო ნებადართული მაქსიმალური მასა 8 250 კგ-ზე მეტი არ არის. „C“ კატეგორიით იგივე ზღვარი 12 000 კგ-ია, როგორც ტრაქტორისთვის, ისე მისაბმელიანი შემადგენლობისთვის.', NULL, NULL),
  (E'rule-1-trailers', E'ka', E'მისაბმელები და ავტომატარებელი', E'მსუბუქი მისაბმელის ნებადართული მაქსიმალური მასა 750 კგ-ს არ აღემატება. ნახევარმისაბმელი ავტომობილს ისე ებმება, რომ მისი ნაწილი ავტომობილს ეყრდნობა და მასზე მოდის ნახევარმისაბმელისა და ტვირთის მასის მნიშვნელოვანი ნაწილი. ავტომატარებელი სატვირთო ავტომობილის კომბინაციაა ერთ ან რამდენიმე მისაბმელთან, რომლის ნებადართული მაქსიმალური მასა 750 კგ-ზე მეტია.', NULL, NULL),
  (E'rule-1-vehicle-types', E'ka', E'სატრანსპორტო საშუალებების სახეები', E'მსუბუქი ავტომობილის ნებადართული მაქსიმალური მასა 3500 კგ-ს არ აღემატება, დასასხდომი ადგილები კი, მძღოლისას გარდა, 8-ზე მეტი არ არის. სატვირთო ავტომობილი ტვირთის გადასაზიდია და მისი ნებადართული მაქსიმალური მასა 3 500 კგ-ს აღემატება. ნელმავალია ძრავიანი სატრანსპორტო საშუალება, რომლის კონსტრუქციული სიჩქარე 40 კმ/სთ-ს არ აღემატება, ან რომელიც ამ სიჩქარეს ვერ აჭარბებს, ან ნაკადთან დაუკავშირებელი მიზეზით ეკრძალება მისი გადაჭარბება. ავტომზიდი ავტომობილისა და თვლიანი მსუბუქი ტრაქტორის გადასაზიდი სპეციალიზებული ავტოსატრანსპორტო საშუალებაა.', NULL, NULL),
  (E'rule-1-visibility', E'ka', E'არასაკმარისი და შეზღუდული ხილვადობა', E'არასაკმარისი ხილვადობაა, როცა გვირაბში, ბნელ დროს, ნისლში, წვიმაში, თოვლში ან სხვა ბუნებრივი მოვლენისას გზა 300 მეტრზე ნაკლებ მანძილზე ჩანს. შეზღუდული ხილვადობაა, როცა მოკლე მოსახვევი, აღმართის დასასრული, გამწვანება, გზისპირა ნაგებობა ან დაბრკოლება ხედვას ისე ამცირებს, რომ ნებადართული მაქსიმალური სიჩქარით მოძრაობა შეიძლება სახიფათო იყოს. ბნელ დროს ან არასაკმარისი ხილვადობისას სიჩქარის შერჩევისას გადამწყვეტია მხედველობის პირობები. ასეთ პირობებში შეამცირე სიჩქარე და გაზარდე დისტანცია წინ მიმავალ სატრანსპორტო საშუალებამდე.', NULL, NULL),
  (E'rule-1-who-drives', E'ka', E'ვის შეუძლია მართვა', E'სატრანსპორტო საშუალების მართვა შეუძლია მხოლოდ იმას, ვისი ჯანმრთელობაც კანონით დადგენილ მოთხოვნებს შეესაბამება და ვისაც შესაბამისი კატეგორიის მართვის უფლება აქვს, რომელიც შეჩერებული, ჩამორთმეული ან შეწყვეტილი არ არის. აკრძალულია მანქანის სამართავად გადაცემა ალკოჰოლური, ნარკოტიკული ან ფსიქოტროპული სიმთვრალის მდგომარეობაში მყოფისთვის. ასევე აკრძალულია მისი გადაცემა იმისთვის, ვისაც მართვის უფლება არ აქვს ან ეს უფლება შეჩერებული, ჩამორთმეული ან გაუქმებული აქვს.', NULL, NULL),
  (E'rule-10-arrows', E'ka', E'ისრები შუქნიშანზე', E'ისრიან სიგნალს იგივე მნიშვნელობა აქვს, რაც იმავე ფერის უისროს, ოღონდ მხოლოდ ისრით ნაჩვენები მიმართულებით. მარცხნივ მოხვევის ისარი მობრუნების უფლებასაც იძლევა, თუ ნიშანი ან მონიშვნა ამას არ კრძალავს. დამატებითი სექციის გამორთული სიგნალი ნიშნავს, რომ მისი მიმართულებით მოძრაობა აკრძალულია. ძირითად მწვანეზე კონტურის ისარი გაცნობებს დამატებითი სექციის შესაძლო არსებობას და გიჩვენებს სხვა ნებადართულ მიმართულებებს. თუ შუქნიშნები თითოეული ზოლის ზემოთაა, თითოეული მხოლოდ თავის ზოლზე მოქმედებს.', NULL, NULL),
  (E'rule-10-colors', E'ka', E'შუქნიშნის ფერები', E'წითელი ან წითელი მოციმციმე სიგნალი მოძრაობას კრძალავს. წითელი და ყვითელი ერთად ასევე კრძალავს მოძრაობას და გაცნობებს, რომ მალე მწვანე აინთება. მწვანე მოძრაობის ნებას რთავს, მწვანე მოციმციმე კი იმასაც გეუბნება, რომ მისი დრო იწურება და მალე ამკრძალავი სიგნალი ჩაირთვება. ამკრძალავ სიგნალზე „სდექ“ ხაზთან ან 7.16 ნიშანთან უნდა გაჩერდე. თუ ნებადამრთველი სიგნალი დიდი ხანია ანთია, ისე იმოძრავე, რომ ნებისმიერ მომენტში უსაფრთხოდ გაჩერება შეძლო.', NULL, NULL),
  (E'rule-10-extra-section', E'ka', E'დამატებითი სექციის ისარი', E'თუ დამატებით სექციაში ისარი ძირითად წითელ ან ყვითელ სიგნალთან ერთად ანთია, მისი მიმართულებით მოძრაობა შეგიძლია. ამ დროს გზა უნდა დაუთმო სხვა მიმართულებებიდან მოძრავ სატრანსპორტო საშუალებებს. თუ მარჯვნივ მოსახვევი ზოლი ამაღლებული უსაფრთხოების კუნძულით არის გამოყოფილი და მის წინ შუქნიშანი არ არის, მარჯვნივ შუქნიშნის სიგნალებისგან დამოუკიდებლად უხვევ, ოღონდ სხვა მიმართულებებიდან მოძრავ ყველა სატრანსპორტო საშუალებას გზას უთმობ.', NULL, NULL),
  (E'rule-10-flashing-yellow-off', E'ka', E'ყვითელი მოციმციმე და გამორთული შუქნიშანი', E'ყვითელი მოციმციმე სიგნალი მოძრაობის ნებას რთავს და გაფრთხილებს არარეგულირებული გზაჯვარედინის, ქვეითთა ან ველოსიპედისტთა გადასასვლელის ან მოსალოდნელი საფრთხის შესახებ. ასეთ, ან გამორთული შუქნიშნის მქონე გზაჯვარედინზე არარეგულირებულის წესები მოქმედებს. მეორეხარისხოვანი გზიდან გზა დაუთმე მთავარ გზაზე მოძრავებს, თანაბარმნიშვნელოვანი გზების გადაკვეთაზე კი მარჯვნიდან მოახლოებულს. აქ ტრამვაის უპირატესობა აქვს ურელსო სატრანსპორტო საშუალების მიმართ, მიუხედავად მისი მიმართულებისა, ტრამვაები კი ერთმანეთის მიმართ იმავე მარჯვნიდან მოახლოების წესს იცავენ.', NULL, NULL),
  (E'rule-10-inside-junction', E'ka', E'გზაჯვარედინზე შესვლა და გასვლა', E'თუ გზაჯვარედინზე ნებადამრთველ სიგნალზე შეხვედი, დასახული მიმართულებით გასვლა შეგიძლია გასასვლელთან მდგარი შუქნიშნის ამკრძალავი სიგნალის მიუხედავად, თუ ხელს არ შეუშლი მათ, ვისთვისაც მოძრაობა გახსნილია. თუ შიგნით შუქნიშნების წინ „სდექ“ ხაზები ან 7.16 ნიშნებია, თითოეულ შუქნიშანს ცალ-ცალკე დაემორჩილე. ნუ შეხვალ გზაჯვარედინზე, თუ მის შემდეგ ხერგილია და იძულებული გახდები, შიგ გაჩერდე და განივ მოძრაობას ხელი შეუშალო. ეს წესი მწვანე სიგნალზეც მოქმედებს.', NULL, NULL),
  (E'rule-10-left-turn', E'ka', E'მარცხნივ მოხვევა მწვანეზე', E'მწვანე სიგნალზე მარცხნივ მოხვევისას ან მობრუნებისას გზა დაუთმე საპირისპირო მიმართულებიდან პირდაპირ ან მარჯვნივ მოძრავ სატრანსპორტო საშუალებებს. ამავე წესით იქცევიან ტრამვაის მძღოლებიც ერთმანეთის მიმართ. შუქნიშნის სიგნალს აქ უპირატესი ძალა აქვს პრიორიტეტის ნიშნებისა და მონიშვნის მიმართ.', NULL, NULL),
  (E'rule-10-pedestrians', E'ka', E'ქვეითები შუქნიშნიან გადასასვლელზე', E'ამკრძალავ სიგნალზე ქვეითთა გადასასვლელის ან მის წინ მდებარე განივი მონიშვნის წინ გაჩერდი. როცა მოძრაობის უფლებას მიიღებ, გადასასვლელზე შესულ ქვეითებს ხელი არ შეუშალო. თუ ისეთ გზაზე უხვევ, რომლის შესასვლელშიც გადასასვლელია, დაბალი სიჩქარით იმოძრავე და საჭიროებისას გაჩერდი, რომ ქვეითები გაატარო. ლურჯი ციმციმა და ხმოვანი სიგნალით მოახლოებულ ოპერატიული სამსახურის ავტომობილს ადგილი გაუთავისუფლე, საჭიროებისას გაჩერდი. ქვეითი, თუ მისთვის განკუთვნილი შუქნიშანია, ამ შუქნიშნის სიგნალებს ემორჩილება.', NULL, NULL),
  (E'rule-10-reversible', E'ka', E'რევერსული შუქნიშანი', E'რევერსული შუქნიშანი იმ ზოლებზე გამოიყენება, სადაც მოძრაობის მიმართულება საპირისპიროდ იცვლება. წითელი X კრძალავს, ქვემოთ მიმართული მწვანე ისარი კი ნებას რთავს მოძრაობას იმ ზოლზე, რომლის ზემოთაც ანთია. დიაგონალურად ქვემოთ დახრილი ყვითელი ან თეთრი ისარი გაცნობებს, რომ სიგნალი შეიცვლება და ისრით ნაჩვენებ ზოლზე უნდა გადახვიდე. ორივე მხრიდან 1.9 მონიშვნით აღნიშნული ზოლის ზემოთ გამორთული რევერსული შუქნიშანი ამ ზოლზე გასვლას კრძალავს. რევერსული მოძრაობის სავალ ნაწილზე მოხვევისას განაპირა მარჯვენა ზოლი დაიკავე, სხვაზე კი მხოლოდ მაშინ გადადი, როცა დარწმუნდები, რომ იქ თანმხვედრი მოძრაობაა ნებადართული.', NULL, NULL),
  (E'rule-10-signal-over-signs', E'ka', E'შუქნიშანი პრიორიტეტის ნიშნებზე ძლიერია', E'თუ შუქნიშნის სიგნალი ეწინააღმდეგება გავლის უპირატესობის განმსაზღვრელ ნიშნებს ან მონიშვნას, შუქნიშანს დაემორჩილე. მის სიგნალს მათზე უპირატესი ძალა აქვს.', NULL, NULL),
  (E'rule-10-special-lights', E'ka', E'სამარშრუტო და გადასასვლელის შუქნიშნები', E'სამარშრუტო სატრანსპორტო საშუალებების ზოლზე შეიძლება იყოს „T“-სებურად განლაგებული ოთხი მოყვითალო მრგვალი სიგნალი. მოძრაობა ნებადართულია, როცა ქვედა და ერთი ან რამდენიმე ზედა ერთად ანთია: მარცხენა მარცხნივ უშვებს, შუა პირდაპირ, მარჯვენა მარჯვნივ. თუ მხოლოდ სამი ზედაა ჩართული, მოძრაობა აკრძალულია. რკინიგზის გადასასვლელთან, გასახსნელ ხიდთან, გემის ან ბორნის მისადგომთან, სახანძრო ავტომობილის გამოსასვლელთან და იქ, სადაც გზას დაბალ სიმაღლეზე საფრენი აპარატი კვეთს, დგას ერთი ან ორი მორიგეობით მოციმციმე წითელი ან ყვითელი სიგნალის შუქნიშანი. წითელი „სდექ“ ხაზის გადაკვეთას კრძალავს, ყვითელზე კი მოძრაობა განსაკუთრებული სიფრთხილით გრძელდება.', NULL, NULL),
  (E'rule-10-trams', E'ka', E'ტრამვაი რეგულირებულ გზაჯვარედინზე', E'თუ შუქნიშანი ერთდროულად უშვებს რელსიან და ურელსო სატრანსპორტო საშუალებებს, ტრამვაის უპირატესობა აქვს, მიუხედავად მისი მოძრაობის მიმართულებისა. გამონაკლისია, როცა ის დამატებითი სექციის ისრით მოძრაობს, რომელიც ძირითად წითელ ან ყვითელ სიგნალთან ერთად ანთია: მაშინ ტრამვაის მძღოლი გზას უთმობს სხვა მიმართულებებიდან მოძრავებს.', NULL, NULL),
  (E'rule-10-yellow', E'ka', E'ყვითელი და გზაჯვარედინის დასრულება', E'თუ მწვანის შემდეგ ყვითელი აინთო და „სდექ“ ხაზთან მკვეთრი დამუხრუჭების გარეშე ვეღარ გაჩერდები, მოძრაობის გაგრძელების უფლება გაქვს. როცა შენთვის ნებადამრთველი სიგნალი აინთება, ჯერ გზა დაუთმე სატრანსპორტო საშუალებას, რომელიც გზაჯვარედინზე გადასვლას ამთავრებს, და ქვეითს, რომელმაც სავალ ნაწილზე გადასვლა ვერ დაამთავრა.', NULL, NULL),
  (E'rule-11-arms-sideways', E'ka', E'ხელები განზე ან ჩამოშვებული', E'განზე გაშვერილი ან ჩამოშვებული ხელები „სდექ“-ია ყველასთვის, ვისი მიმართულებაც ხელებით ნაჩვენებ მიმართულებას კვეთს. მარეგულირებლის მარჯვენა და მარცხენა გვერდიდან ტრამვაი მხოლოდ პირდაპირ მოძრაობს, ურელსო სატრანსპორტო საშუალება პირდაპირ და მარჯვნივ, ქვეითს კი სავალი ნაწილის გადაკვეთა შეუძლია. მოხვევის წინ დროულად დაიკავე შესაბამისი განაპირა მდებარეობა სავალ ნაწილზე.', NULL, NULL),
  (E'rule-11-crossing-paths', E'ka', E'როცა ტრაექტორიები იკვეთება', E'თუ მარეგულირებლის სიგნალი ერთდროულად უშვებს ურელსო სატრანსპორტო საშუალებებს, რომელთა გზებიც იკვეთება, იხელმძღვანელე არარეგულირებული გზაჯვარედინის წესებითა და იქ დადგმული პრიორიტეტის ნიშნებით.', NULL, NULL),
  (E'rule-11-emergency', E'ka', E'ოპერატიული ავტომობილი რეგულირებისას', E'ოპერატიული ან სპეციალური სამსახურის მძღოლს, რომელსაც ლურჯი ციმციმა სიგნალი აქვს ჩართული და სამსახურებრივ დავალებას ასრულებს, შეუძლია უსაფრთხოების დაცვით მოძრაობის წესებს გადაუხვიოს. დანარჩენი მძღოლები ამ დროსაც მარეგულირებლის ჟესტით მოძრაობენ: თუ ჟესტი შენს მიმართულებას კრძალავს, გაჩერდი.', NULL, NULL),
  (E'rule-11-means', E'ka', E'როგორ იძლევა სიგნალს მარეგულირებელი', E'მარეგულირებელი სიგნალს აძლევს ხელით, შავ-თეთრზოლიანი ხელკეტით, შუქამრეკლი წითელი დისკით, „მოძრაობა აკრძალულია“ ნიშნიანი დისკით, წითელი ან ყვითელი ალმით და წითელი სინათლის მოძრაობით; სინათლის მოძრაობა „სდექ“-ია ყველასთვის, ვისკენაც არის მიმართული. სასტვენი ყურადღების მისაპყრობი დამატებითი სიგნალია. თუ ხმამაღლამოლაპარაკე მოწყობილობით ან შენკენ მიმართული ჟესტით გაჩერებას მოგთხოვს, მითითებულ ადგილას გაჩერდი. შსს-ს უფლებამოსილი პირების გარდა, მოძრაობას თავიანთ ფარგლებში არეგულირებენ მაშველები სამაშველო სამუშაოებისას, რკინიგზის თანამშრომლები გადასასვლელზე და საბორნე გადაზიდვის ორგანიზატორები ნავსადგურში.', NULL, NULL),
  (E'rule-11-priority', E'ka', E'მარეგულირებლის სიგნალის ძალა', E'მარეგულირებლის სიგნალს უპირატესი ძალა აქვს შუქნიშნის, საგზაო ნიშნებისა და მონიშვნის, ასევე მოძრაობის წესების მოთხოვნებზე. გზაჯვარედინზე მისი რეგულირებისას ამკრძალავი და მიმთითებელი ნიშნები კვლავ მოქმედებს, თუ მარეგულირებელი კონკრეტულად არ მიგითითებს, რომ ისინი უგულებელყო.', NULL, NULL),
  (E'rule-11-raised-arm', E'ka', E'ზემოთ აწეული ხელი', E'ზემოთ აწეული ერთი ხელი ყველასთვის ნიშნავს „ყურადღება, სდექ“. გაგრძელება შეუძლია მხოლოდ მძღოლს, რომელიც მკვეთრი დამუხრუჭებისა და უსაფრთხოების დარღვევის გარეშე ვეღარ გაჩერდება, და იმას, ვინც გზაჯვარედინზე უკვე შესულია. სავალ ნაწილზე მყოფმა ქვეითმა ის უნდა გაათავისუფლოს, ხოლო თუ ვერ ახერხებს, საპირისპირო ნაკადების გამყოფ ხაზზე უნდა გაჩერდეს.', NULL, NULL),
  (E'rule-11-right-arm', E'ka', E'მარჯვენა ხელი წინ', E'წინ გაშვერილი მარჯვენა ხელი „სდექ“-ია ყველასთვის, ვინც მარეგულირებლის მარჯვენა გვერდიდან ან ზურგიდან მოძრაობს. მარცხენა გვერდიდან ურელსო სატრანსპორტო საშუალებას ყველა მიმართულებით შეუძლია მოძრაობა, მკერდის მხრიდან კი ყველას მხოლოდ მარჯვნივ. ქვეითი სავალ ნაწილს მარეგულირებლის ზურგს უკან კვეთს.', NULL, NULL),
  (E'rule-11-right-arm-trams', E'ka', E'მარჯვენა ხელი წინ: ტრამვაი და ზოლი', E'ამ ჟესტზე ტრამვაის მარეგულირებლის მარცხენა გვერდიდან მხოლოდ მარცხნივ მოძრაობა შეუძლია, მკერდის მხრიდან კი, როგორც ყველას, მხოლოდ მარჯვნივ. მარჯვენა გვერდიდან და ზურგიდან ის ჩერდება. მოხვევისა და მობრუნების წინ დროულად დაიკავე შესაბამისი განაპირა მდებარეობა თანმხვედრი მოძრაობის სავალ ნაწილზე.', NULL, NULL),
  (E'rule-11-where-stop', E'ka', E'სად უნდა გაჩერდე', E'ამკრძალავ სიგნალზე ქვეითთა გადასასვლელის ან მის წინ მდებარე განივი მონიშვნის წინ გაჩერდი. რკინიგზის გადასასვლელზე მოძრაობას მარეგულირებელი კრძალავს, როცა შენკენ მკერდით ან ზურგით დგას და თავს ზემოთ კვერთხს, წითელ ფარანს ან ალამს სწევს, ან ხელებს განზე წევს. ასეთ დროს გადასასვლელზე არავინ შედის, შლაგბაუმის მდგომარეობის მიუხედავად. გაჩერდი „სდექ“ ხაზთან, 2.4 ნიშანთან ან შუქნიშანთან; თუ ისინი არ არის, შლაგბაუმამდე არანაკლებ 5 მეტრზე, ხოლო შლაგბაუმის გარეშე უახლოეს რელსამდე არანაკლებ 10 მეტრზე.', NULL, NULL),
  (E'rule-12-blue-priority', E'ka', E'ლურჯი ციმციმა და პრიორიტეტი', E'ოპერატიული ან სპეციალური სამსახურის მძღოლს, რომელსაც ჩართული აქვს ლურჯი მოელვარე სპეციალური ციმციმა სიგნალი და სამსახურებრივ დავალებას ასრულებს, შეუძლია უსაფრთხოების დაცვით გადაუხვიოს მოძრაობის წესებს, მათ შორის ნიშნებისა და მონიშვნის მოთხოვნებს. სხვების მიმართ უპირატესობის მისაღებად ლურჯ ციმციმასთან ერთად ხმოვანი სიგნალიც უნდა ჩართოს; ლურჯს შეიძლება წითელი ციმციმაც დაემატოს. პრიორიტეტით მხოლოდ მაშინ სარგებლობს, როცა დარწმუნდება, რომ გზას უთმობენ. ლურჯი ციმციმის გარეშე ის ჩვეულებრივ წესებს ემორჩილება. სპეციალური სიგნალების დაყენება და სპეციალური შეფერილობა შინაგან საქმეთა მინისტრის დადგენილი წესით ხდება.', NULL, NULL),
  (E'rule-12-give-way', E'ka', E'გზის დათმობა სპეცტრანსპორტისთვის', E'როცა გიახლოვდება სამსახურის ავტომობილი ჩართული ლურჯი ციმციმითა და ხმოვანი სიგნალით, ან ხმამაღლამოლაპარაკე ხელსაწყოთი გაძლევს სიგნალს, სავალ ნაწილზე ადგილი უნდა გაუთავისუფლო, საჭიროების შემთხვევაში კი გაჩერდე. იგივე ეხება მის მიერ გაცილებულ ავტომობილს, რომელსაც ახლო განათების ფარები აქვს ჩართული. ადგილის დასათმობად ზოლს თუ იცვლი, გზა დაუთმე იმ ზოლში შენი მიმართულებით მოძრავ ტრანსპორტს. თუ ლურჯი ციმციმა და ხმოვანი სიგნალი ჩართული არ არის, ასეთი ვალდებულება არ გაქვს.', NULL, NULL),
  (E'rule-12-intersection-order', E'ka', E'გზაჯვარედინის გავლის რიგი', E'ლურჯი ციმციმითა და ხმოვანი სიგნალით მოძრავი სამსახურის ავტომობილი გზაჯვარედინს პირველი გადის. დანარჩენები ჩვეულებრივი რიგით მიდიან. მარცხნივ მოხვევისას ან მობრუნებისას ურელსო ტრანსპორტი გზას უთმობს საპირისპირო მიმართულებიდან პირდაპირ ან მარჯვნივ მოძრავს. არარეგულირებულ გზაჯვარედინზე, თანაბარმნიშვნელოვანი გზების გადაკვეთაზე, გზა ეთმობა მარჯვნიდან მოახლოებულს.', NULL, NULL),
  (E'rule-12-orange-yellow', E'ka', E'ნარინჯისფერი და ყვითელი ციმციმა', E'ნარინჯისფერ ან ყვითელ მოელვარე ციმციმა სიგნალს რთავს ტრანსპორტი, რომელიც გზაზე სამშენებლო, სარემონტო ან დასასუფთავებელ სამუშაოებს ასრულებს, საინკასაციო ავტომობილი, სახიფათო ტვირთის გადამზიდი, არაგაბარიტული და ზენორმატიული ტრანსპორტი. ასეთ მძღოლს შეუძლია გადაუხვიოს ნიშნებისა და მონიშვნის მოთხოვნებს, თუ მოძრაობის უსაფრთხოებას უზრუნველყოფს. ეს სიგნალი უპირატესობას არ იძლევა: ის მხოლოდ ყურადღებას იპყრობს, რომ მოსალოდნელი საშიშროება თავიდან იქნეს აცილებული.', NULL, NULL),
  (E'rule-12-stopped-blue', E'ka', E'მდგომი ავტომობილი ლურჯი ციმციმით', E'თუ უახლოვდები ავტომობილს, რომელიც ჩართული ლურჯი მოელვარე სპეციალური ციმციმა სიგნალით დგას, შეანელე სიჩქარე. ისე იმოძრავე, რომ საჭიროების შემთხვევაში დაუყოვნებლივ გაჩერება შეძლო.', NULL, NULL),
  (E'rule-13-allowed-place', E'ka', E'გაჩერება ნებადართულ ადგილას', E'იძულებით გაჩერებისას შუქსიგნალიზაციისა და ნიშნის ვალდებულება გაქვს იქ, სადაც გაჩერება აკრძალულია ან ხილვადობის გამო ვერ შეგამჩნევენ. დაუსახლებელ პუნქტში გაჩერებული ავტომობილი, შეძლებისდაგვარად, სავალი ნაწილის გარეთ უნდა იდგეს. სავალ ნაწილზე გაჩერება აკრძალულია სავალი ნაწილების გადაკვეთაზე და მისი ნაპირებიდან 5 მეტრზე ახლოს. გამონაკლისია სამმხრივი გზაჯვარედინის გვერდითი გასასვლელის მოპირდაპირე მხარე, სადაც მონიშვნის უწყვეტი ხაზი ან გამყოფი ზოლია.', NULL, NULL),
  (E'rule-13-distance', E'ka', E'რა მანძილზე დგება ნიშანი', E'„საავარიო გაჩერების ნიშანი“ და მოციმციმე წითელი ფარანი ისეთ მანძილზე დგება, რომ სხვა მძღოლები დროულად გააფრთხილოს. ეს მანძილი დასახლებულ პუნქტში არანაკლებ 15 მეტრია, დაუსახლებელში — არანაკლებ 30 მეტრი. საგზაო ნიშნით აღნიშნულ გვირაბში იძულებით გაჩერებისას იგივე მოთხოვნები მოქმედებს, რაც გაჩერებისთვის აკრძალულ ადგილებში.', NULL, NULL),
  (E'rule-13-motorway', E'ka', E'იძულებითი გაჩერება ავტომაგისტრალზე', E'ავტომაგისტრალზე, მის შესასვლელსა და გამოსასვლელზე გაჩერება და დგომა აკრძალულია, გარდა დგომისთვის სპეციალურად მონიშნული ადგილებისა. თუ იძულებით გაჩერდი, ყველა ზომა მიიღე, რომ ავტომობილი სავალი ნაწილიდან გაიყვანო. თუ ეს დაუყოვნებლივ ვერ ხერხდება, ჩართე საავარიო შუქსიგნალიზაცია და საკმარის მანძილზე დადგი ნიშანი, რომ მოახლოებული მძღოლები დროულად გააფრთხილო.', NULL, NULL),
  (E'rule-13-warning-sign', E'ka', E'საავარიო გაჩერების ნიშანი და ფარანი', E'საავარიო შუქსიგნალიზაციის ჩართვის შემდეგ, ან თუ ის არ გაქვს ან გაუმართავია, დაუყოვნებლივ დადგი „საავარიო გაჩერების ნიშანი“, არასაკმარისი ხილვადობისას კი — მოციმციმე წითელი ფარანი. ეს საჭიროა ავარიისას, იძულებით გაჩერებისას იქ, სადაც გაჩერება აკრძალულია, და იქ, სადაც ხილვადობის გამო სხვები დროულად ვერ შეგამჩნევენ. თუ არც ნიშანი გაქვს და არც ფარანი, მოახლოებული მძღოლები სხვა მსგავსი ეფექტიანი საშუალებით გააფრთხილე. ბუქსირებისას საბუქსირო ავტომობილს საავარიო შუქსიგნალიზაცია უნდა ჰქონდეს ჩართული, ხოლო მისი არქონისას ან გაუმართაობისას უკანა ნაწილზე „საავარიო გაჩერების ნიშანი“ მაგრდება.', NULL, NULL),
  (E'rule-13-when-hazard', E'ka', E'როდის ირთვება საავარიო შუქსიგნალიზაცია', E'საავარიო შუქსიგნალიზაცია სხვებს მოსალოდნელ საფრთხეზე აფრთხილებს. ის უნდა ჩართო, თუ ავარიაში მონაწილე ან მწყობრიდან გამოსული ავტომობილის გაყვანა ან ბუქსირება დაუყოვნებლივ შეუძლებელია და ეს სხვებს აბრკოლებს, ასევე იძულებით გაჩერებისას იქ, სადაც გაჩერება აკრძალულია. იძულებითი გაჩერება მოძრაობის შეწყვეტაა ტექნიკური გაუმართაობის, ტვირთის, მძღოლის ან მგზავრის მდგომარეობის ან გზაზე მოულოდნელი დაბრკოლების გამო. თუ შემხვედრის ფარები თვალს გჭრის, ზოლის შეუცვლელად შეანელე, გაჩერდი და ჩართე საავარიო შუქსიგნალიზაცია; მოძრაობას მხოლოდ მხედველობის სრულად აღდგენის შემდეგ განაგრძობ.', NULL, NULL),
  (E'rule-14-equipment', E'ka', E'სანათების ფერი და დამატებითი ფარები', E'უკუსვლის მაშუქი მხოლოდ მაშინ ირთვება, როცა უკუსვლით მოძრაობ ან ამას აპირებ. აკრძალულია წინ წითელი და უკან თეთრი სინათლეები, ასევე კონსტრუქციის შეცვლა ან დამატებითი სინათლეები, რომლებიც ამ მოთხოვნებს ეწინააღმდეგება. ერთნაირი დანიშნულებისა და ერთ მხარეს მიმართული ფარები ერთი ფერის უნდა იყოს. ფარა-პროჟექტორითა და ფარა-მაძიებლით სარგებლობა მხოლოდ დაუსახლებელ პუნქტში შეიძლება, როცა საპირისპიროდ არავინ მოძრაობს; დასახლებულ პუნქტში მათ მხოლოდ ოპერატიული და სპეციალური სამსახურები იყენებენ სამსახურებრივი მოვალეობისას.', NULL, NULL),
  (E'rule-14-fog-lights', E'ka', E'ნისლსაწინააღმდეგო ფარები', E'წინა ნისლსაწინააღმდეგო ფარები თეთრი ან ყვითელი სელექციური სინათლისაა: ავტომობილზე ორი, მოტოციკლზე ერთი. ისინი ისე დგება, რომ მათი გამნათებელი ზედაპირის არცერთი წერტილი ახლო ფარების ზედაპირის ყველაზე მაღალ წერტილზე მაღლა არ იყოს. უკანა ნისლსაწინააღმდეგო ფარები წითელია. არასაკმარისი ხილვადობისას ან ვიწრო მიხვეულ-მოხვეულ გზაზე ისინი შორ ან ახლო ფარებთან ერთად ირთვება; ბნელში, ძლიერი თოვისას, გზას უკეთ ანათებს ნისლსაწინააღმდეგო და ახლო ფარები ერთად.', NULL, NULL),
  (E'rule-14-high-to-low', E'ka', E'შორიდან ახლო შუქზე გადართვა', E'შემხვედრისთვის გვერდის აქცევისას შორი შუქი ახლოზე მისგან არანაკლებ 150 მეტრზე გადართე, ან უფრო ადრე, თუ შემხვედრი მძღოლი ფარების გადართვით გთხოვს. ახლო შუქი ირთვება დასახლებულ პუნქტში, თუ გზა საკმარისად არის განათებული, და დაუსახლებელში, თუ სავალი ნაწილი თანაბრად და საკმარისად არის განათებული. ასევე ყოველთვის, როცა სხვა მონაწილეებს ან გზის გასწვრივ სანაოსნო ან სალიანდაგო გზით მოსარგებლეებს მხედველობა შეიძლება დაებინდოთ. ბნელში აღმართის ბოლოსთან მიახლოებისას ახლო შუქზე გადართვა ნებისმიერ შემთხვევაში სავალდებულოა.', NULL, NULL),
  (E'rule-14-horn', E'ka', E'ხმოვანი და მანათობელი სიგნალი', E'ხმოვანი სიგნალი მხოლოდ ორ შემთხვევაში შეიძლება: სხვების დროული გაფრთხილებისთვის, რომ ავარია თავიდან აიცილო, და დასახლებული პუნქტის გარეთ, როცა სხვა მძღოლს გასწრების განზრახვაზე აფრთხილებ. ის საჭიროზე ხანგრძლივი არ უნდა იყოს. დასახლებულ პუნქტში გასწრების განზრახვაზე მანათობელი სიგნალით აფრთხილებ: დღე-ღამის ნათელ დროს ფარების ხანმოკლე ჩართვა-გამორთვით, ბნელ დროს კი ახლო შუქის შორზე მრავალჯერადი გადართვით. დაუსახლებელ პუნქტში მანათობელი სიგნალი ხმოვანის ნაცვლად ან მასთან ერთად გამოიყენება. ხმოვანი და მანათობელი სიგნალი სხვების მიმართ უპირატესობას არ განიჭებს.', NULL, NULL),
  (E'rule-14-lights-moving', E'ka', E'განათება მოძრაობისას', E'სიბნელეში და არასაკმარისი ხილვადობისას მოძრავ ავტომობილსა და მოპედს ჩართული უნდა ჰქონდეს ახლო ან შორი ფარები და უკანა საგაბარიტო სინათლეები; მისაბმელზე — არანაკლებ ორი უკანა, წინა კი თუ კანონით არის გათვალისწინებული. წინა საგაბარიტო სინათლეები ფარებთან ან წინა ნისლსაწინააღმდეგო ფარებთან ერთად ირთვება. დღისითაც სავალდებულოა ახლო ფარები და უკანა საგაბარიტო სინათლეები ბავშვთა ჯგუფის გადაყვანისას, მობუქსირე ავტომობილზე და სამარშრუტო ტრანსპორტზე, რომელიც თავის ზოლში ნაკადის საპირისპიროდ მოძრაობს. ნიშნით აღნიშნულ გვირაბში ფარები ყოველთვის ირთვება, განათებულია ის თუ არა.', NULL, NULL),
  (E'rule-14-parked-lights', E'ka', E'განათება გაჩერებისა და დგომისას', E'დაბინდებიდან გათენებამდე და არასაკმარისი ხილვადობისას გზაზე გაჩერებული ან მდგომი ავტომობილი და მისი მისაბმელი წინა და უკანა საგაბარიტო სინათლეებით უნდა იყოს აღნიშნული. დასახლებულ პუნქტში მათ ნაცვლად პარკირების ნათურები შეიძლება ჩართო, თუ ავტომობილი 6 მ-ზე გრძელი და 2 მ-ზე განიერი არ არის და მისაბმელი არ აქვს. უშუქოდ შეიძლება იდგე ისე განათებულ გზაზე, სადაც ავტომობილი შორიდან კარგად ჩანს, ან სავალი ნაწილისა და მკვრივსაფარიანი გვერდულების მიღმა. სქელ ნისლში, ხშირ თოვასა და ძლიერ წვიმაში საგაბარიტო სინათლეებს ახლო ან წინა ნისლის ფარები, უკან კი უკანა ნისლსაწინააღმდეგო ფარი შეიძლება დაემატოს.', NULL, NULL),
  (E'rule-14-turn-signals', E'ka', E'მოხვევის შუქ-მაჩვენებელი', E'მანევრის დაწყებამდე ყოველთვის ჩართე შესაბამისი მიმართულების მოხვევის შუქ-მაჩვენებელი; თუ ის არ გაქვს ან გაუმართავია, ხელით ანიშნე. სიგნალი დროულად, მანევრის დაწყებამდე უნდა მისცე და მისი დასრულებისთანავე შეწყვიტო; ხელით მიცემული სიგნალი შეიძლება მანევრის დაწყების წინ შეწყდეს. სიგნალმა სხვა მონაწილეები შეცდომაში არ უნდა შეიყვანოს. შუქ-მაჩვენებელი უპირატესობას არ განიჭებს და სიფრთხილის ზომების მიღებისგან არ გათავისუფლებს.', NULL, NULL),
  (E'rule-15-accel-decel-lanes', E'ka', E'გაქანებისა და დამუხრუჭების ზოლი', E'თუ გზაზე გასასვლელ ადგილას გაქანების ზოლია, მასზე უნდა იმოძრაო, ხოლო მეზობელ ზოლზე გადასვლისას გზა დაუთმო იქ მოძრავებს. თუ დამუხრუჭების ზოლია, მოხვევის წინ დროულად გადადი მასზე და სიჩქარე მხოლოდ ამის შემდეგ შეანელე.', NULL, NULL),
  (E'rule-15-adjacent-left-turn', E'ka', E'მიმდებარე ტერიტორია და მარცხნივ მოხვევა', E'მიმდებარე ტერიტორიიდან გზაზე გასვლისას გზა დაუთმე გზაზე მოძრავ ტრანსპორტს და ქვეითებს. გზიდან ასეთ ტერიტორიაზე შესვლისას გზას უთმობ ქვეითს, ველოსიპედისტს, მოპედისა და ორბორბლიანი ელექტროთვითმგორავის მძღოლს, რომელსაც გზას უჭრი. მარცხნივ მოხვევისას ან გზაჯვარედინის მიღმა მობრუნებისას ურელსო ტრანსპორტი გზას უთმობს საპირისპიროდ მოძრავებს და თანმხვედრი მიმართულებით მოძრავ ტრამვაის.', NULL, NULL),
  (E'rule-15-before-manoeuvre', E'ka', E'მანევრის დაწყების წინ', E'ნებისმიერ მანევრს იწყებ მხოლოდ მაშინ, როცა დარწმუნდები, რომ საფრთხეს არ შეუქმნი უკან, წინ და გვერდით მოძრავებს, როგორც თანმხვედრი, ისე საპირისპირო მიმართულებით. ამისთვის მათი მდებარეობა, მიმართულება და სიჩქარე გაითვალისწინე. მანევრის წინ ყოველთვის ჩართე შესაბამისი მიმართულების მოხვევის შუქ-მაჩვენებელი, ხოლო თუ ის არ გაქვს ან გაუმართავია, ხელით ანიშნე.', NULL, NULL),
  (E'rule-15-bus-lane', E'ka', E'სამარშრუტო ტრანსპორტის ზოლი', E'5.11, 5.13.1, 5.13.2 ან 5.14 ნიშნით აღნიშნულ სამარშრუტო ტრანსპორტის ზოლზე სხვა ტრანსპორტის მოძრაობა და გაჩერება აკრძალულია. თუ ეს ზოლი დანარჩენი სავალი ნაწილისგან წყვეტილი ხაზით არის გამოყოფილი, მოხვევისას მასზე უნდა გადაჯგუფდე. ასეთ ადგილებში მასზე შესვლა შეიძლება აგრეთვე გზაზე გასვლისას და მგზავრების ჩასხდომა-გადმოსხდომისას მარჯვენა კიდესთან, თუ სამარშრუტო ტრანსპორტს ხელს არ შეუშლი.', NULL, NULL),
  (E'rule-15-hand-signals', E'ka', E'ხელით მიცემული სიგნალები', E'მარცხნივ მოხვევის ან მობრუნების სიგნალია გვერდზე ჰორიზონტალურად გაშვერილი მარცხენა ხელი, ან გვერდზე გაშვერილი და იდაყვში სწორი კუთხით ზემოთ მოხრილი მარჯვენა. მარჯვნივ მოხვევისას პირიქითაა: ჰორიზონტალურად გაშვერილი მარჯვენა ხელი, ან ზემოთ მოხრილი მარცხენა. დამუხრუჭების სიგნალია ზემოთ ვერტიკალურად აწეული მარცხენა ან მარჯვენა ხელი.', NULL, NULL),
  (E'rule-15-keep-right', E'ka', E'მარჯვენა მხარე და საპირისპირო მხარე', E'საქართველოში მარჯვენა მხარეს მოძრაობენ; ორი ან სამი სავალი ნაწილის მქონე გზაზე საპირისპირო მხარის სავალ ნაწილზე გასვლა აკრძალულია. მონიშნულ სამზოლიან ორმხრივ გზაზე შენი მხარე მარჯვენა ზოლია: შუაზე მხოლოდ გასწრების, შემოვლის, მარცხნივ მოხვევის ან მობრუნებისთვის გადიხარ, საპირისპირო განაპირაზე — არასდროს. თუ შუაში სავალ ნაწილთან ერთ დონეზე ტრამვაის ლიანდაგია, მხარეებს საპირისპირო ლიანდაგებს შორის გავლებული წარმოსახვითი ხაზი ყოფს. ორმხრივი გზის ღერძზე მდგარ უსაფრთხოების კუნძულს ან ტუმბოს მხოლოდ მარჯვნიდან შემოუვლი. გვერდულაზე, ველოზოლზე, ველობილიკზე, ტროტუარსა და ქვეითთა ბილიკზე მექანიკური ტრანსპორტით მოძრაობა აკრძალულია.', NULL, NULL),
  (E'rule-15-lane-change', E'ka', E'ზოლის შეცვლა და გზის დათმობა', E'მოძრაობის მიმართულების შეუცვლელად ზოლიდან ზოლში გადასვლისას გზა დაუთმე იმ ზოლში შენი მიმართულებით მოძრავ ტრანსპორტს. თუ თანმხვედრი მიმართულებით მოძრავები ზოლს ერთდროულად იცვლიან და მათი ტრაექტორიები იკვეთება, უპირატესობა მარჯვნივ მყოფს აქვს. ზოგადად, თუ ტრაექტორიები იკვეთება და გავლის რიგი განსაზღვრული არ არის, გზა უთმობ იმას, ვინც მარჯვნიდან გიახლოვდება.', NULL, NULL),
  (E'rule-15-lane-choice', E'ka', E'მოძრაობის ზოლის არჩევა', E'დასახლებულ პუნქტში, სადაც შენი მიმართულებით მონიშვნით გამოყოფილი ორი ზოლი მაინცაა, ისარგებლე მოსახერხებელი ზოლით; სხვაზე მოხვევის, გასწრების, გაჩერების ან დგომის წესების მიხედვით გადადიხარ. სადაც სამი ან მეტი ზოლია, განაპირა მარცხენას მხოლოდ ინტენსიური მოძრაობისას იკავებ, როცა სხვები დაკავებულია, ან გასწრების, მარცხნივ მოხვევისა და მობრუნებისთვის; სატვირთო — მხოლოდ მარცხნივ მოხვევისა და მობრუნებისას. თუ ვიწრო ან ცუდი გზა ნელმავალი ან დიდგაბარიტიანი ავტომობილის უსაფრთხო გასწრების საშუალებას არ იძლევა, მისმა მძღოლმა უნდა შეანელოს და პირველივე შესაძლებლობისას უკან მომავლებს გზა დაუთმოს.', NULL, NULL),
  (E'rule-15-narrow-u-turn', E'ka', E'მობრუნება ვიწრო გზაზე', E'თუ გზაჯვარედინზე სავალი ნაწილი უკიდურესი მარცხენა მდებარეობიდან მობრუნებისთვის ვიწროა, მობრუნება გზაჯვარედინის მიღმა უნდა შეასრულო, გარდა იმ შემთხვევისა, როცა მის სიახლოვეს გზის სიგანე ამის საშუალებას არ იძლევა. გზაჯვარედინის მიღმა, თუ სიგანე არ კმარა, შეგიძლია მობრუნდე სავალი ნაწილის მარჯვენა კიდიდან ან მარჯვენა გვერდულადან და გზა დაუთმო თანმხვედრი და საპირისპირო მიმართულებით მოძრავებს. ყველა შემთხვევაში უსაფრთხოება უნდა დაიცვა და სხვებს დაბრკოლება არ შეუქმნა. ეს წესი არ მოქმედებს იქ, სადაც მობრუნება ნიშნით ან მონიშვნით არის აკრძალული; მაგალითად, 3.19 ნიშანი „მობრუნება აკრძალულია“ კრძალავს მობრუნებას სავალი ნაწილების უახლოეს გადაკვეთაზე.', NULL, NULL),
  (E'rule-15-no-u-turn', E'ka', E'სადაც მობრუნება აკრძალულია', E'მობრუნება აკრძალულია ქვეითთა გადასასვლელზე, გვირაბში, ხიდზე, გზაგამტარზე, ესტაკადაზე და მათ ქვეშ, რკინიგზის გადასასვლელზე, გასაჩერებელ პუნქტთან და იქ, სადაც ხილვადობა თუნდაც ერთი მიმართულებით 100 მეტრზე ნაკლებია. ავტომაგისტრალზე, მის შესასვლელსა და გამოსასვლელზე აკრძალულია მობრუნებაც, უკუსვლაც და ცენტრალური გამყოფი ზოლის განივ შეერთებაზე გასვლაც. გზაჯვარედინი ამ ჩამონათვალში არ არის. 1.5 მონიშვნის გადაკვეთა ნებისმიერი მხრიდან შეიძლება. ყველა ამ ადგილას უკუსვლით მოძრაობაც აკრძალულია.', NULL, NULL),
  (E'rule-15-reversing', E'ka', E'უკუსვლით მოძრაობა', E'მობრუნების ან უკუსვლის წინ დარწმუნდი, რომ მანევრს ისე შეასრულებ, რომ სხვებს საფრთხეს არ შეუქმნი და ხელს არ შეუშლი. საჭიროების შემთხვევაში მიზანშეწონილია სხვა პირის დახმარება. უკუსვლით მოძრაობა აკრძალულია გზაჯვარედინზე, ავტომაგისტრალზე და ყველგან, სადაც მობრუნებაა აკრძალული.', NULL, NULL),
  (E'rule-15-route-stop', E'ka', E'სამარშრუტო ტრანსპორტი გაჩერებასთან', E'დასახლებულ პუნქტში, როცა სამარშრუტო ტრანსპორტი გასაჩერებელი პუნქტიდან გამოდის, შეანელე და საჭიროებისას გაჩერდი, რომ მან მანევრი შეასრულოს. მისი მძღოლი ჯერ შუქ-მაჩვენებელს რთავს და მოძრაობას მხოლოდ მაშინ იწყებს, როცა დარწმუნდება, რომ გზას უთმობენ. დაუსახლებელ პუნქტში ეს უპირატესობა არ მოქმედებს და მანევრის ჩვეულებრივი წესი ვრცელდება. მონიშნულ გაჩერებაზე მდგომი სამარშრუტო ტრანსპორტის გვერდის ავლისას შეამცირე სიჩქარე და საჭიროებისას გაჩერდი, რომ მგზავრებმა უსაფრთხოდ ჩაჯდომა ან გადმოსვლა შეძლონ.', NULL, NULL),
  (E'rule-15-tram-tracks', E'ka', E'ტრამვაის ლიანდაგზე მოძრაობა', E'თანმხვედრი მიმართულების ტრამვაის ლიანდაგზე, რომელიც მარცხნივ, სავალ ნაწილთან ერთ დონეზეა, შეგიძლია იმოძრაო, თუ შენი მიმართულების ყველა ზოლი დაკავებულია, ასევე დაბრკოლების შემოვლის, გასწრების, მარცხნივ მოხვევის ან მობრუნებისას. ამ დროს ტრამვაის მოძრაობას დაბრკოლება არ უნდა შეუქმნა. საპირისპირო მიმართულების ტრამვაის ლიანდაგზე გასვლა აკრძალულია. ერთ ზოლზე მოპედებსა და უეტლო მოტოციკლებს შეუძლიათ თანმხვედრი მიმართულებით ორ რიგად იმოძრაონ.', NULL, NULL),
  (E'rule-15-turn-ban-signs', E'ka', E'მოხვევის ამკრძალავი ნიშნები', E'3.18.1 ნიშანი „მარჯვნივ მოხვევა აკრძალულია“ და 3.18.2 ნიშანი „მარცხნივ მოხვევა აკრძალულია“ მოქმედებს სავალი ნაწილების იმ გადაკვეთაზე, რომლის წინაც დგას. 3.32 ნიშანი კრძალავს მოძრაობას იმ სახიფათო ტვირთის გადამზიდით, რომელიც შესაბამისი საცნობი ნიშნით უნდა იყოს აღნიშნული. 8.11 დაფა „ნებადართული მაქსიმალური მასის შეზღუდვა“ ნიშნის მოქმედებას მხოლოდ იმ სატრანსპორტო საშუალებაზე ავრცელებს, რომლის ნებადართული მაქსიმალური მასა დაფაზე მითითებულს აღემატება.', NULL, NULL),
  (E'rule-15-turn-position', E'ka', E'მდებარეობა მოხვევის წინ', E'მარჯვნივ ან მარცხნივ მოხვევის და მობრუნების წინ დროულად დაიკავე შესაბამისი განაპირა მდებარეობა შენი მიმართულების სავალ ნაწილზე; გამონაკლისია მოხვევა წრიული მოძრაობის გზაჯვარედინიდან გასასვლელად. მარჯვნივ მოსახვევად იმოძრავე რაც შეიძლება ახლოს მარჯვენა კიდესთან და მანევრი მოკლედ შეასრულე. მარცხნივ მოსახვევად მიუახლოვდი სავალი ნაწილის ღერძს ორმხრივ გზაზე ან მარცხენა კიდეს ცალმხრივ გზაზე. სხვა ორმხრივ გზაზე გასვლისას ისე მოუხვიე, რომ გადაკვეთიდან გამოსვლისას საპირისპირო მოძრაობის მხარეს არ აღმოჩნდე. 1.1 მონიშვნის გადაკვეთა აკრძალულია.', NULL, NULL),
  (E'rule-15-wide-vehicle-turn', E'ka', E'დიდი ავტომობილის მოხვევა', E'თუ გაბარიტის ან სხვა მიზეზის გამო მოხვევას ჩვეულებრივი წესით ვერ ასრულებ, წესებიდან გადახვევა დასაშვებია, თუ უსაფრთხოება დაცულია და სხვებს დაბრკოლება არ ექმნებათ. როცა წინ მიმავალი სატვირთო ავტომობილი ვიწრო ქუჩაზე მარჯვნივ უხვევს, გაითვალისწინე: დიდი მოხვევის რადიუსის გამო ის მოსახვევის წინ შეიძლება მარცხნივ გადაიწიოს, მკვეთრად შეანელოს ან ქვეითების გასატარებლად მოხვევისას გაჩერდეს.', NULL, NULL),
  (E'rule-16-before-start', E'ka', E'გასწრების დაწყებამდე', E'დაწყებამდე დარწმუნდი, რომ უკან მომავალ არცერთ მძღოლს გასწრება არ დაუწყია და წინ მიმავალს იმავე ზოლზე გასწრების სიგნალი არ მიუცია. ასევე დარწმუნდი, რომ მანევრი არავის შეუქმნის საფრთხეს ან დაბრკოლებას, გასასვლელი ზოლი საკმარის მანძილზე თავისუფალია და ორი სატრანსპორტო საშუალების სიჩქარეთა ფარდობა საკმარისად მოკლე დროში გასწრების საშუალებას გაძლევს. ყველაზე ხშირად ავარიული სიტუაცია დისტანციის დაუცველობისა და შემხვედრი ტრანსპორტის მიმართ ყურადღების ნაკლებობის გამო იქმნება. ხმოვანი სიგნალით დასახლებული პუნქტის გარეთ შეგიძლია გააფრთხილო მძღოლი გასწრების განზრახვის შესახებ.', NULL, NULL),
  (E'rule-16-during-after', E'ka', E'გასწრების დროს და შემდეგ', E'თუ გასწრებისას წარმოიშვა დაბრკოლება ან საფრთხე, რომლის განჭვრეტაც ადრე ვერ შეძელი, გასწრება შეწყვიტე; უკან მომავლებმა ზოლში დაბრუნების საშუალება უნდა მოგცენ. როცა ხედავ, რომ უკნიდან გასწრებას გიპირებენ, შეძლებისდაგვარად მიუახლოვდი მარჯვენა კიდეს და სიჩქარე არ გაზარდო; სიჩქარის მომატებით ან სხვა მოქმედებით გასწრებისთვის ხელის შეშლა აკრძალულია. იმავე მიმართულების ორ- ან მეტზოლიან გზაზე შეგიძლია დარჩე დაკავებულ ზოლში, თუ მალე ახალი გასწრება გელის და ეს უკან უფრო სწრაფად მოძრავს არ შეუშლის ხელს.', NULL, NULL),
  (E'rule-16-intersections', E'ka', E'გასწრება გზაჯვარედინზე', E'გასწრება აკრძალულია გზაჯვარედინზე, წრიულმოძრაობიანის გარდა, და უშუალოდ მის წინ. გამონაკლისია, როცა მთავარ გზაზე მოძრაობ, რეგულირებულ გზაჯვარედინზე საპირისპირო ზოლში გაუსვლელად უსწრებ, ან მარჯვნიდან ნებადართულ გასწრებას ასრულებ. ორთვლიანი ველოსიპედის, მოპედისა და ეტლის გარეშე მოტოციკლის გასწრებაზე ეს აკრძალვა არ ვრცელდება. 1.1 ხაზის გადაკვეთა აკრძალულია, 1.5 ხაზისა კი ნებისმიერი მხრიდან შეიძლება.', NULL, NULL),
  (E'rule-16-left-side', E'ka', E'რა არის გასწრება', E'გასწრება ნიშნავს დაკავებული ზოლიდან გამოსვლით წინ, იმავე მიმართულებით მოძრავი ერთი ან რამდენიმე სატრანსპორტო საშუალების გადასწრებას. გაასწარი მარცხნიდან. მარჯვნიდან მხოლოდ მაშინ შეიძლება, როცა წინა მძღოლმა მარცხნივ მოხვევის სიგნალი მისცა და ავტომობილი ისე მიმართა, რომ სხვა გზაზე შეუხვიოს, მიმდებარე ტერიტორიაზე შევიდეს ან ამ მხარეს გაჩერდეს. სადაც 80 კმ/სთ-ზე მეტია ნებადართული, სავალი ნაწილის მარჯვენა კიდესთან რაც შეიძლება ახლოს იმოძრავე: მარცხენა ზოლს ვერ დაიკავებ, როცა მარჯვენა თავისუფალია, გარდა დაბრკოლების შემოვლის, მარცხნივ მოხვევის ან მობრუნებისა.', NULL, NULL),
  (E'rule-16-mountain-road', E'ka', E'შემხვედრის გვერდის ავლა მთის გზაზე', E'მთის გზაზე და დიდი დახრილობის გზაზე, აგრეთვე 1.14 და 1.15 ნიშნებით აღნიშნულ გზაზე, სადაც გვერდის აქცევა შეუძლებელია ან გართულებულია, დაღმართზე მოძრავი მძღოლი ჩერდება და გზას უთმობს აღმართზე მოძრავს. გამონაკლისია, როცა ასაქცევი ადგილი აღმართზე მოძრავის წინაა და მას იქ გაჩერება შეუძლია, რომ არცერთს უკუსვლა არ დასჭირდეს.', NULL, NULL),
  (E'rule-16-no-overtaking-signs', E'ka', E'გასწრების ამკრძალავი ნიშნები', E'3.20 ნიშანი „გასწრება აკრძალულია“ კრძალავს ყველა მექანიკური სატრანსპორტო საშუალების გასწრებას, გარდა 30 კმ/სთ-ზე ნაკლები სიჩქარით მოძრავისა. მისი მოქმედების ზონაში ეტლის გარეშე მოტოციკლის, მოპედისა და ველოსიპედის გასწრება შეიძლება, თუ შემხვედრ ზოლში არ გადახვალ. 3.22 ნიშანი „სატვირთო ავტომობილით გასწრება აკრძალულია“ კრძალავს 3,5 ტონაზე მეტი ნებადართული მაქსიმალური მასის სატვირთოთი გასწრებას, გარდა 30 კმ/სთ-ზე ნაკლები სიჩქარით მოძრავისა.', NULL, NULL),
  (E'rule-16-overtaking-vehicle', E'ka', E'ვინც თვითონ უსწრებს', E'აკრძალულია იმ სატრანსპორტო საშუალების გასწრება, რომელიც თვითონ ასრულებს გასწრებას ან დაბრკოლების შემოვლას. თუ წინა მძღოლმა უკვე მისცა სიგნალი, რომ გასწრებას აპირებს, დაელოდე, სანამ ის მანევრს დაასრულებს.', NULL, NULL),
  (E'rule-16-pedestrian-crossing', E'ka', E'ქვეითთა გადასასვლელთან', E'იმ სატრანსპორტო საშუალებას, რომელიც ქვეითთა გადასასვლელს უახლოვდება ან უშუალოდ მის წინ გაჩერდა, მხოლოდ საკმარისად შემცირებული სიჩქარით შეგიძლია გაუსწრო, რომ ქვეითის დანახვისას დროულად გაჩერდე. თუ გადასასვლელზე ქვეითი მოძრაობს, გასწრება აკრძალულია. არარეგულირებულ გადასასვლელთან სიჩქარე შეამცირე და, საჭიროების შემთხვევაში, გაჩერდი და ქვეითები გაატარე.', NULL, NULL),
  (E'rule-16-railway', E'ka', E'რკინიგზის გადასასვლელთან', E'გასწრება აკრძალულია რკინიგზის გადასასვლელზე და მის წინ 100 მეტრზე ახლოს. გამონაკლისია, როცა იქ მოძრაობას არეგულირებს ისეთი შუქნიშანი, როგორიც გზაჯვარედინზე გამოიყენება. 1.1 და 1.2 ნიშნები გაფრთხილებს რკინიგზის გადასასვლელთან მიახლოების შესახებ.', NULL, NULL),
  (E'rule-16-stopped-service-vehicles', E'ka', E'გაჩერებული სამსახურებრივი მანქანა', E'თუ გზაზე დგას ლურჯი ციმციმით გაჩერებული ოპერატიული, ან ნარინჯისფერი ან ყვითელი ციმციმით გაჩერებული სპეციალური ან საგზაო-საექსპლუატაციო სამსახურის მანქანა, მისი გასწრება, შემოვლა ან გვერდის ავლა შეიძლება როგორც მარჯვნიდან, ისე მარცხნიდან. იგივე ეხება ნელა მოძრავ ტექნიკური სამსახურის მანქანას და საგზაო სამუშაოების შემსრულებელს. ამ დროს გაითვალისწინე მისი განლაგება და საფრთხე, მიუხედავად იქ არსებული ნიშნებისა და მონიშვნისა.', NULL, NULL),
  (E'rule-16-three-lanes', E'ka', E'სამზოლიანი ორმხრივი გზა', E'სამზოლიან ორმხრივმოძრაობიან გზაზე არ გადახვიდე განაპირა ზოლზე, სადაც შემხვედრი ტრანსპორტი მოძრაობს. თუ შუა ზოლი ორივე მიმართულებისთვისაა, მასზე გასვლა მხოლოდ გასწრების, დაბრკოლების შემოვლის, მარცხნივ მოხვევის ან მობრუნებისთვის შეიძლება.', NULL, NULL),
  (E'rule-16-visibility', E'ka', E'შეზღუდული ხილვადობა', E'შეზღუდული ხილვადობის დროს აკრძალულია გასწრება საპირისპირო მოძრაობის ზოლზე გასვლით. ასეთ ადგილზე გაფრთხილებს, მაგალითად, 1.15 ნიშანი „ციცაბო აღმართი“ ან 1.12.1 ნიშანი „სახიფათო მოსახვევი“. თუ საპირისპირო ზოლში გასვლა საჭირო არ არის, ეს აკრძალვა არ მოქმედებს.', NULL, NULL),
  (E'rule-17-category-b', E'ka', E'B კატეგორია დასახლების გარეთ', E'დაუსახლებელ პუნქტში, აგრეთვე დასახლებული პუნქტის იმ მონაკვეთზე, სადაც ნიშნით 60 კმ/სთ-ზე მეტია დაშვებული, B კატეგორიის ავტომობილს მისაბმელის გარეშე ავტომაგისტრალზე არაუმეტეს 110 კმ/სთ სიჩქარით შეუძლია მოძრაობა, სხვა გზაზე — არაუმეტეს 90 კმ/სთ. 5.1 ნიშანი „ავტომაგისტრალი“ ავტომაგისტრალის დასაწყისს აღნიშნავს.', NULL, NULL),
  (E'rule-17-road-conditions', E'ka', E'სიჩქარე და საგზაო პირობები', E'სიჩქარის შეცვლისას გაითვალისწინე საგზაო პირობები: ადგილის რელიეფი, გზისა და ავტომობილის მდგომარეობა, მისი დატვირთვა, ამინდი, მოძრაობის ინტენსივობა და ხილვადობა. ასე საჭიროების დროს, ან ნებისმიერი დაბრკოლების წინ, რომლის განჭვრეტაც შეგიძლია, სიჩქარეს დროულად შეამცირებ, ხოლო აუცილებლობისას გაჩერდები.', NULL, NULL),
  (E'rule-17-settlement', E'ka', E'სიჩქარე დასახლებულ პუნქტში', E'დასახლებულ პუნქტში ნებადართულია არაუმეტეს 60 კმ/სთ სიჩქარით მოძრაობა, საცხოვრებელ ზონაში — არაუმეტეს 20 კმ/სთ. თუ საგზაო პირობები საშუალებას იძლევა, გზის ცალკეულ მონაკვეთზე სიჩქარე შესაბამისი საგზაო ნიშნით შეიძლება გაიზარდოს. 4.6 ნიშანი „მინიმალური სიჩქარის შეზღუდვა“ ადგენს ქვედა ზღვარს: მის ზონაში მასზე ნაკლები სიჩქარით ვერ იმოძრავებ.', NULL, NULL),
  (E'rule-17-signs-and-own-limit', E'ka', E'ნიშანი და შენი ზღვარი', E'3.24 ნიშანი „მაქსიმალური სიჩქარის შეზღუდვა“ კრძალავს მასზე მითითებულზე მეტი სიჩქარით მოძრაობას, 4.6 ნიშანი „მინიმალური სიჩქარის შეზღუდვა“ კი ქვედა ზღვარს ადგენს. ორივე მოქმედებს ნიშნიდან უახლოეს გზაჯვარედინამდე, ხოლო დასახლებულ პუნქტში გზაჯვარედინის არარსებობისას — მის ბოლომდე. 8.14 დაფა „მოძრაობის ზოლი“ აჩვენებს, რომელ ზოლზე ვრცელდება ნიშანი. თუ ნიშანი უფრო მაღალ სიჩქარეს უშვებს, შენი სატრანსპორტო საშუალებისთვის კანონით დადგენილ ზღვარს მაინც ვერ გადააჭარბებ. ვერც სატრანსპორტო საშუალების მაქსიმალურ კონსტრუქციულ სიჩქარეს გადააჭარბებ და ვერც მასზე დამაგრებულ საცნობ ნიშანზე „სიჩქარის შეზღუდვა“ მითითებულს.', NULL, NULL),
  (E'rule-17-towing-special', E'ka', E'ბუქსირი და განსაკუთრებული შემთხვევები', E'ავტომობილი, რომელიც სხვა მექანიკურ სატრანსპორტო საშუალებას ბუქსირებს, დასახლებულ და დაუსახლებელ პუნქტში არაუმეტეს 50 კმ/სთ სიჩქარით მოძრაობს. არაგაბარიტული ან ზენორმატიული სატრანსპორტო საშუალება იმ სიჩქარით მოძრაობს, რომელიც უფლებამოსილი ორგანოს შეთანხმებაშია მითითებული. ავტომაგისტრალზე, მის შესასვლელსა და გამოსასვლელზე ასეთი შეთანხმების გარეშე აკრძალულია ავტომობილი, რომლის კონსტრუქციული სიჩქარე 40 კმ/სთ-ს არ აღემატება.', NULL, NULL),
  (E'rule-17-trailer-light-vehicles', E'ka', E'მისაბმელი, მოტოციკლი, B1', E'B კატეგორიის ავტომობილს, რომელიც მსუბუქ მისაბმელს ბუქსირებს, ყველა გზაზე არაუმეტეს 80 კმ/სთ სიჩქარით შეუძლია მოძრაობა. იგივე 80 კმ/სთ მოქმედებს A კატეგორიისა და A1, B1 ქვეკატეგორიების სატრანსპორტო საშუალებებზე. BE კატეგორიის ავტომობილისთვის ზღვარი ყველა გზაზე, ავტომაგისტრალის ჩათვლით, 70 კმ/სთ-ია.', NULL, NULL),
  (E'rule-17-trucks-buses', E'ka', E'სატვირთო ავტომობილი და მიკროავტობუსი', E'C, CE, C1 და C1E კატეგორიის სატრანსპორტო საშუალებას ავტომაგისტრალზე არაუმეტეს 80 კმ/სთ სიჩქარით შეუძლია მოძრაობა, სხვა გზაზე — არაუმეტეს 70 კმ/სთ. თუ ის ძარით მგზავრებს გადაიყვანს, ზღვარი ყველა გზაზე 60 კმ/სთ-ია. D1 და D1E ქვეკატეგორიისთვის ყველა გზაზე 80 კმ/სთ მოქმედებს. 7.2 ნიშანი „რეკომენდებული სიჩქარე“ მხოლოდ გირჩევს სიჩქარეს.', NULL, NULL),
  (E'rule-18-braking-distance', E'ka', E'რა არის სამუხრუჭე მანძილი', E'სამუხრუჭე მანძილი არის მანძილი, რომელსაც სატრანსპორტო საშუალება გადის მუხრუჭების ამოქმედებიდან სრულ გაჩერებამდე. ის დამოკიდებულია სიჩქარეზე, გზის საფარის მდგომარეობასა და საბურავების ცვეთაზე. სიჩქარის გაზრდისას საბურავის გზასთან ჩაჭიდება მცირდება. რაც მეტია მასა, მით მეტი ძალა და დროა საჭირო დასამუხრუჭებლად, ამიტომ მისაბმელით, რომელსაც სამუხრუჭე სისტემა არ აქვს, მსუბუქი ავტომობილის სამუხრუჭე მანძილი იზრდება.', NULL, NULL),
  (E'rule-18-engine-braking', E'ka', E'ძრავით დამუხრუჭება დაღმართზე', E'მექანიკური გადაცემათა კოლოფით ციცაბო დაღმართზე დამუხრუჭების ეფექტური ხერხი ძრავით დამუხრუჭებაა. რაც უფრო მკვეთრია დაღმართი, მით უფრო დაბალი გადაცემა უნდა ჩართო. ხანგრძლივი დამუხრუჭება გამორთული გადაბმულობით სამუხრუჭე სისტემას ახურებს და დამუხრუჭების ეფექტურობას ამცირებს.', NULL, NULL),
  (E'rule-18-following-distance', E'ka', E'დისტანცია წამებში', E'წინ მიმავალს ისეთ დისტანციაზე მიჰყევი, რომ მისი მოულოდნელი დამუხრუჭებისას ან გაჩერებისას შეჯახება აიცილო. ნორმალურ პირობებში ამ მანძილის დასაფარად საჭირო დრო დასახლებულ პუნქტში არანაკლებ 2 წამია, დაუსახლებელში — არანაკლებ 3 წამი. მოყინულ გზაზე ეს დრო დასახლებულ პუნქტში არანაკლებ 6 წამია, დაუსახლებელში — არანაკლებ 9 წამი. გვერდითი ინტერვალის დაცვაც აუცილებელია.', NULL, NULL),
  (E'rule-18-hard-braking', E'ka', E'მკვეთრი და ექსტრემალური დამუხრუჭება', E'მკვეთრი დამუხრუჭება აკრძალულია, გარდა იმ შემთხვევისა, როცა ის საგზაო-სატრანსპორტო შემთხვევის თავიდან ასაცილებლად გჭირდება. ექსტრემალურ სიტუაციაში სამუხრუჭე მანძილს ამცირებ, თუ სატერფულს მრავალჯერ და მკვეთრად აწვები თვლების ბლოკირების ზღვარზე. ABS-ით აღჭურვილი ავტომობილი დამუხრუჭებისას უკეთ იმართება. თუ მარჯვენა თვლები არამდგრად და სველ გვერდულზე გადავიდა, ავტომობილი სავალ ნაწილზე მდორედ დააბრუნე, დამუხრუჭების გარეშე.', NULL, NULL),
  (E'rule-19-boarding', E'ka', E'ჩასხდომა-გადმოსხდომა', E'მგზავრი ჩაჯდება და გადმოვა სრული გაჩერების შემდეგ, ტროტუარის ან გვერდულის მხრიდან. თუ ეს შეუძლებელია, სავალი ნაწილის მხრიდან ან ავტომობილის უკანა მხრიდან შეიძლება, როცა ეს სხვებს საფრთხეს ან დაბრკოლებას არ უქმნის. კარის გაღება სრულ გაჩერებამდე აკრძალულია.', NULL, NULL),
  (E'rule-19-bridges-tunnels', E'ka', E'ხიდი, ესტაკადა, გვირაბი', E'ესტაკადაზე, ხიდსა და გზაგამტარზე გაჩერება აკრძალულია, თუ იქ თანმხვედრი მიმართულების ორზე მეტი ზოლი არ არის. მათ ქვეშ და გვირაბში გაჩერება მხოლოდ სპეციალურად გამოყოფილ ადგილზე შეიძლება. ნიშნით აღნიშნულ გვირაბში გაჩერდები ან დადგები მხოლოდ საავარიო სიტუაციისას ან საფრთხისას, შესაძლებლობის შემთხვევაში მონიშნულ ადგილზე. ხანგრძლივი გაჩერებისას იქ ძრავი უნდა გამორთო.', NULL, NULL),
  (E'rule-19-hazard-lights', E'ka', E'იძულებითი გაჩერება', E'საავარიო შუქსიგნალიზაცია სხვებს მოსალოდნელ საფრთხეზე აფრთხილებს. ის უნდა ჩართო, როცა იძულებით ჩერდები იქ, სადაც გაჩერება აკრძალულია. ამის შემდეგ, ან თუ შუქსიგნალიზაცია არ გაქვს ან გაუმართავია, დაუყოვნებლივ დადგი საავარიო გაჩერების ნიშანი, არასაკმარისი ხილვადობისას — მოციმციმე წითელი ფარანი. ბავშვთა ჯგუფის გადამყვანმა ავტობუსმა ყოველი გაჩერებისას საავარიო შუქსიგნალიზაცია უნდა ჩართოს.', NULL, NULL),
  (E'rule-19-how-to-park', E'ka', E'როგორ დააყენო', E'სატრანსპორტო საშუალებები ერთ რიგად, სავალი ნაწილის კიდის პარალელურად დგას, თუ ადგილი სხვაგვარ დაყენებას არ ითვალისწინებს. გვერდითი მისაბმელის გარეშე ორთვლიანები შეიძლება ორ რიგად დადგეს. სავალ ნაწილთან მოსაზღვრე ტროტუარის ნაპირზე მხოლოდ მსუბუქი ავტომობილი, მოტოციკლი, მოპედი და ველოსიპედი დგება, ისიც მაშინ, თუ ქვეითს დაბრკოლებას არ უქმნის.', NULL, NULL),
  (E'rule-19-no-stop-distances', E'ka', E'სად არის გაჩერება აკრძალული', E'ვერ გაჩერდები ქვეითთა და ველოსიპედისტთა გადასასვლელზე და მის წინ 5 მეტრზე ახლოს, ასევე სავალი ნაწილების გადაკვეთაზე და მისი ნაპირებიდან 5 მეტრზე ახლოს. გამონაკლისია სამმხრივი გზაჯვარედინის გვერდითი გასასვლელის მოპირდაპირე მხარე, სადაც მონიშვნის უწყვეტი ხაზი ან გამყოფი ზოლია. აკრძალულია გაჩერება იქ, სადაც უწყვეტ ხაზამდე 3 მეტრზე ნაკლები რჩება, სამარშრუტო ტრანსპორტის ან ტაქსის გაჩერებიდან 15 მეტრზე ახლოს, თუ მათ აბრკოლებ, ლიანდაგებთან, თუ ტრამვაის ან მატარებლის მოძრაობას აძნელებ, ნელმავალთა დამატებით ზოლზე და იქ, სადაც შუქნიშანს ან ნიშანს სხვებს უფარავ.', NULL, NULL),
  (E'rule-19-outside-settlement', E'ka', E'დასახლებული პუნქტის გარეთ', E'დაუსახლებელ პუნქტში გაჩერებისას ან დგომისას, შესაძლებლობის ფარგლებში, სავალი ნაწილის გარეთ იყავი. ხანგრძლივი დასვენებისთვის, მაგალითად ღამის გასათევად, მხოლოდ სპეციალურ სადგომზე ან გზის ფარგლებს მიღმა შეგიძლია დადგე. დგომა აკრძალულია დაუსახლებელ პუნქტში 2.1, 5.1 და 5.3 ნიშნებით აღნიშნულ სავალ ნაწილზე, დასახლებულ პუნქტში კი იქ, სადაც 80 კმ/სთ-ზე მეტია დაშვებული, გარდა სპეციალურად აღნიშნული ადგილებისა.', NULL, NULL),
  (E'rule-19-right-left-side', E'ka', E'გზის რომელ მხარეს', E'სავალ ნაწილზე გაჩერდი ან დადექი მარჯვენა მხარეს, კიდესთან რაც შეიძლება ახლოს. მარცხენა მხარეს ეს ნებადართულია, თუ ლიანდაგის გამო მარჯვნივ შეუძლებელია, დასახლებულ პუნქტში იმ გზაზე, სადაც თითო მიმართულებას ერთი ზოლი აქვს და შუაში ტრამვაის ლიანდაგი არ არის, ან ცალმხრივმოძრაობიან გზაზე. ცალმხრივ გზაზე სატვირთო ავტომობილი მარცხნივ მხოლოდ დატვირთვა-გადმოტვირთვისთვის ჩერდება. სავალი ნაწილის შუაში გაჩერება და დგომა მხოლოდ ნიშნით ან მონიშვნით განსაზღვრულ ადგილზე შეიძლება.', NULL, NULL),
  (E'rule-19-route-lane', E'ka', E'სამარშრუტო ტრანსპორტის ზოლი', E'5.11, 5.13.1, 5.13.2 და 5.14 ნიშნებით აღნიშნულ სამარშრუტო ტრანსპორტის ზოლზე სხვა სატრანსპორტო საშუალებებს მოძრაობა და გაჩერება ეკრძალებათ. თუ ზოლი წყვეტილი ხაზითაა გამოყოფილი, მასზე შესვლა შეიძლება მოხვევისას, გზაზე გასვლისას და მარჯვენა კიდესთან მგზავრთა ჩასხდომა-გადმოსხდომისას, თუ სამარშრუტო ტრანსპორტს არ აბრკოლებ.', NULL, NULL),
  (E'rule-19-signs-markings', E'ka', E'ამკრძალავი ნიშნები და მონიშვნა', E'3.27 ნიშანი „გაჩერება აკრძალულია“ კრძალავს როგორც გაჩერებას, ისე დგომას, 3.28 ნიშანი „დგომა აკრძალულია“ — მხოლოდ დგომას. ისინი მოქმედებს ნიშნიდან უახლოეს გზაჯვარედინამდე და მხოლოდ გზის იმ მხარეს, სადაც დგას; ზონა შეიძლება შემცირდეს 8.2.3 დაფიანი განმეორებითი ნიშნით. 1.4 მონიშვნა, მთლიანი ყვითელი ხაზი, გაჩერებას კრძალავს; 3.27 ნიშანთან ერთად ზონა ხაზის სიგრძით განისაზღვრება. დგომა აკრძალულია ასევე იქ, სადაც გაჩერებაა აკრძალული, რკინიგზის გადასასვლელიდან 50 მეტრზე ახლოს და ეზოდან გამოსასვლელთან.', NULL, NULL),
  (E'rule-19-stop-vs-park', E'ka', E'გაჩერება და დგომა', E'გაჩერება მოძრაობის წინასწარგანზრახული შეწყვეტაა 5 წუთამდე, ან უფრო დიდი ხნით, თუ ეს მგზავრთა ჩასხდომა-გადმოსხდომას ან დატვირთვა-გადმოტვირთვას სჭირდება. დგომა მოძრაობის გამიზნული შეწყვეტაა 5 წუთზე მეტი ხნით, როცა ამას ჩასხდომა-გადმოსხდომა ან დატვირთვა-გადმოტვირთვა არ მოითხოვს. ნაკადში, შუქნიშნის, ნიშნის ან მარეგულირებლის მოთხოვნით შეჩერება გაჩერებად არ ითვლება.', NULL, NULL),
  (E'rule-2-faults-ban', E'ka', E'როდის ეკრძალება მოძრაობა', E'მძღოლს ეკრძალება მოძრაობა, თუ გაუმართავია მუშა სამუხრუჭო სისტემა, საჭის მექანიზმი ან შემადგენლობის მისაბმელი მოწყობილობა. დღე-ღამის ბნელ დროს ჩართული უნდა იყოს ახლო ან შორი განათების ფარები და უკანა საგაბარიტო სინათლეები. თუ ერთდროულად ჩაქრა ახლო და შორი განათების ფარები ან უკანა საგაბარიტო სინათლეები, აკრძალულია მოძრაობა გზაზე, სადაც ხელოვნური განათება არ არის ან ხილვადობა არასაკმარისია. თუ მძღოლის მხარეს მინასაწმენდი არ მუშაობს, ნისლის, წვიმისა და თოვის დროს მართვა აკრძალულია.', NULL, NULL),
  (E'rule-2-parked-lights', E'ka', E'საგაბარიტო სინათლეები გაჩერებისას', E'დაბინდებიდან გათენებამდე და ნებისმიერი არასაკმარისი ხილვადობის დროს გზაზე გაჩერებულ ან მდგომ ავტომობილს წინა და უკანა საგაბარიტო სინათლეები უნდა ჰქონდეს ჩართული. ეს მის მისაბმელსაც ეხება. გარე სანათების ჩაურთველად დგომა მხოლოდ სავალი ნაწილისა და მკვრივი საფარის მქონე გვერდულების მიღმა შეიძლება.', NULL, NULL),
  (E'rule-2-regular-checks', E'ka', E'რეგულარული შემოწმება და მუხრუჭები', E'რეგულარულად შეამოწმე საჭის მართვის მექანიზმის, საბურავებისა და გარე სანათი ხელსაწყოების გამართულობა. სამუხრუჭო დისკებზე დიდი ოდენობით ჟანგი სამუხრუჭო სისტემის არათანაბარ მუშაობას იწვევს. ჰიდრავლიკური სამუხრუჭო სისტემა მუხრუჭებს უფრო სწრაფად ამოქმედებს. მოტოციკლისა და მოპედის ექსპლუატაცია აკრძალულია, თუ საბურავის პროტექტორის დარჩენილი სიმაღლე 0,8 მმ-ზე ნაკლებია.', NULL, NULL),
  (E'rule-2-wheel-tyres', E'ka', E'საჭე და საბურავები', E'საჭის თვალზე ხელები ისე უნდა გეჭიროს, რომ ავარიულ სიტუაციაში საჭე სწრაფად და მოხერხებულად მოაბრუნო ყველა მიმართულებით და საწყის მდგომარეობაში დააბრუნო. სწორი განლაგება ხელებს ნაკლებად ტვირთავს და დაღლილობას ამცირებს. საბურავებში აირის დაბალი წნევა ზრდის საწვავის ხარჯს, აძნელებს საჭით მართვას და საბურავებს ახურებს.', NULL, NULL),
  (E'rule-20-inside-intersection', E'ka', E'გზაჯვარედინზე შესვლა და მოხვევა', E'ნუ შეხვალ გზაჯვარედინზე, თუ წინ ისეთი ხერგილია, რომ იქ გაჩერება მოგიწევს და განივ მოძრაობას დააბრკოლებ, თუნდაც შუქნიშანი მოძრაობის უფლებას გაძლევდეს. 1.7 მონიშვნა, მოკლე შტრიხებიანი წყვეტილი ხაზი, გზაჯვარედინის ფარგლებში ზოლებს აღნიშნავს და მისი გადაკვეთა ნებისმიერი მხრიდან შეიძლება. თუ გაბარიტის გამო მოხვევას დადგენილი წესით ვერ ასრულებ, მისგან გადახვევა დასაშვებია, ოღონდ უსაფრთხოდ და ისე, რომ სხვებს დაბრკოლება არ შეუქმნა.', NULL, NULL),
  (E'rule-20-left-turn-equal', E'ka', E'მარცხნივ მოხვევა თანაბარ გზებზე', E'თანაბარმნიშვნელოვან გზაზე მარცხნივ მოხვევისას ან მობრუნებისას გზა უნდა დაუთმო საპირისპირო მიმართულებიდან პირდაპირ ან მარჯვნივ მოძრავს. საცხოვრებელი ზონიდან გამოსვლისას კი გადაკვეთაზე ყველა სხვა მონაწილეს უთმობ. ზონის ყველა გამოსასვლელში დგას 5.22 ნიშანი „საცხოვრებელი ზონის დასასრული“.', NULL, NULL),
  (E'rule-20-main-road', E'ka', E'მთავარი და მეორეხარისხოვანი გზა', E'არარეგულირებულ გზაჯვარედინზე მეორეხარისხოვან გზაზე მოძრავი მძღოლი უთმობს მთავარი გზიდან მოახლოებულს, მიუხედავად იმისა, საით აპირებს ის შემდეგ მოძრაობას. 2.3 ნიშანი „დაუთმე გზა“ ნიშნავს, რომ გადასაკვეთ გზაზე მოძრავს უნდა დაუთმო; ის მოქმედებს იმ გადაკვეთაზე, რომლის წინაც დგას. თუ შუქნიშანი არ მუშაობს, გზაჯვარედინს არარეგულირებულის წესებით გადიხარ.', NULL, NULL),
  (E'rule-20-main-road-left-turn', E'ka', E'მოხვევა მთავარ გზაზე', E'ჯერ მთავარი გზიდან მოახლოებულები გადიან, შემდეგ — მეორეხარისხოვანზე მყოფები. ერთი რანგის გზაზე მყოფებს შორის მარცხნივ მომხვევი ან მობრუნებული უთმობს საპირისპირო მიმართულებიდან პირდაპირ ან მარჯვნივ მოძრავს. ამიტომ მთავარ გზაზეც, მარცხნივ თუ უხვევ, შემხვედრი წინ გაატარე.', NULL, NULL),
  (E'rule-20-main-road-turns', E'ka', E'მთავარი გზა მიმართულებას იცვლის', E'თუ გზაჯვარედინზე მთავარი გზა მიმართულებას იცვლის, მასზე მოძრავები ერთმანეთს შორის თანაბარმნიშვნელოვანი გზების წესით გადიან: უთმობენ მარჯვნიდან მოახლოებულს. იმავე წესს იცავენ მეორეხარისხოვან გზაზე მყოფებიც, ოღონდ მხოლოდ მას შემდეგ, რაც მთავარ გზაზე მოძრავები გაივლიან.', NULL, NULL),
  (E'rule-20-oncoming-priority', E'ka', E'შემხვედრი მოძრაობის უპირატესობა', E'2.5 ნიშანი „შემხვედრი მოძრაობის უპირატესობა“ გიკრძალავს ვიწრო მონაკვეთზე შესვლას, თუ ეს საპირისპირო მიმართულებით მოძრაობას გაართულებს. შემხვედრს, რომელიც უკვე მონაკვეთზეა ან მოპირდაპირე მისასვლელთანაა, გზა უნდა დაუთმო. თუ შენს მხარეს დაბრკოლებაა, შეანელე და საჭიროებისას გაჩერდი, რომ შემხვედრი გაატარო.', NULL, NULL),
  (E'rule-20-pedestrians', E'ka', E'ქვეითები მოხვევისას და გადასასვლელზე', E'სხვა გზაზე შესასვლელად მოხვევისას ვალდებული ხარ, დაუთმო ამ გზის სავალ ნაწილზე შესულ ქვეითებს, მაშინაც, როცა იქ მონიშნული გადასასვლელი არ არის. არარეგულირებულ ქვეითთა გადასასვლელთან მიახლოებისას შეანელე და საჭიროებისას გაჩერდი, რომ შესული ან შემავალი ქვეითები გაატარო. თუ გადასასვლელის წინ გაჩერებული ავტომობილი ხედვას გიზღუდავს, გააგრძელე მხოლოდ მაშინ, როცა დარწმუნდები, რომ იქ ქვეითი არ არის.', NULL, NULL),
  (E'rule-20-right-hand', E'ka', E'მარჯვენა ხელის წესი', E'თანაბარმნიშვნელოვანი გზების გადაკვეთაზე გზა უნდა დაუთმო მარჯვნიდან მოახლოებულ სატრანსპორტო საშუალებას. იგივე წესი მოქმედებს, როცა მოძრაობის ტრაექტორიები იკვეთება და გავლის რიგი სხვაგვარად განსაზღვრული არ არის. პირველი გადის ის, ვისაც მარჯვნიდან არავინ უახლოვდება. თუ ორი ავტომობილი ზოლს ერთდროულად იცვლის და მათი ტრაექტორიები იკვეთება, უპირატესობა მარჯვნივ მყოფს აქვს.', NULL, NULL),
  (E'rule-20-special-vehicles', E'ka', E'სპეციალური სიგნალის მქონე ავტომობილები', E'ოპერატიული ან სპეციალური სამსახურის ავტომობილს, რომელსაც ლურჯი მოელვარე ციმციმა და ხმოვანი სიგნალი ერთად აქვს ჩართული, ადგილი უნდა გაუთავისუფლო, საჭიროებისას კი გაჩერდე; ის გზაჯვარედინს პირველი გადის. უპირატესობის მისაღებად ორივე სიგნალია საჭირო, ციმციმის გარეშე ასეთი ავტომობილი ჩვეულებრივი წესებით გადის. ნარინჯისფერი ან ყვითელი მოელვარე სიგნალი უპირატესობას არ იძლევა და მხოლოდ ყურადღების მისაპყრობად გამოიყენება.', NULL, NULL),
  (E'rule-20-tram-equal', E'ka', E'ტრამვაი თანაბარ გზებზე', E'თანაბარმნიშვნელოვანი გზების გადაკვეთაზე ტრამვაის უპირატესობა აქვს ურელსო სატრანსპორტო საშუალების მიმართ, მიუხედავად მისი მოძრაობის მიმართულებისა. ტრამვაები ერთმანეთს შორის ჩვეულებრივ წესებს იცავენ: უთმობენ მარჯვნიდან მოახლოებულს, მარცხნივ მოხვევისას კი — საპირისპიროდან პირდაპირ ან მარჯვნივ მოძრავს. გზაჯვარედინის მიღმა, სადაც ლიანდაგი სავალ ნაწილს კვეთს, უპირატესობა ისევ ტრამვაის აქვს, გარდა დეპოდან გამოსვლისა.', NULL, NULL),
  (E'rule-20-tram-main-road', E'ka', E'ტრამვაი და მთავარი გზა', E'არათანაბარმნიშვნელოვანი გზების გადაკვეთაზე ჯერ მთავარი გზიდან მოახლოებულები გადიან, მიუხედავად მათი შემდგომი მიმართულებისა. ეს ტრამვაისაც ეხება: მეორეხარისხოვან გზაზე ის მთავარზე მოძრავს უთმობს, მთავარ გზაზე ყოფნისას კი პირველი გადის.', NULL, NULL)
INSERT INTO learning_card_texts ("cardId", lang, title, body, tutor, audio) VALUES
  (E'rule-20-unclear-surface', E'ka', E'გრუნტოვანი გზა და დაფარული ნიშნები', E'გრუნტოვანი გზიდან არაგრუნტოვან გზაზე გასვლისას მასზე მოძრავს უთმობ, თუ ნიშნით სხვა რამ არ არის დადგენილი. ღორღიან ან გრუნტოვან გზაზე გზაჯვარედინის წინ მკვრივსაფარიანი უბანი მას მკვრივსაფარიან გზასთან არ ათანაბრებს. თუ სიბნელის, თოვლის ან ტალახის გამო საფარს ვერ არჩევ და პრიორიტეტის ნიშნებიც არ ჩანს, ჩათვალე, რომ მეორეხარისხოვან გზაზე ხარ.', NULL, NULL),
  (E'rule-21-banned', E'ka', E'რა არის აკრძალული გადასასვლელზე', E'გადასასვლელზე აკრძალულია შლაგბაუმის ან ნახევარშლაგბაუმის თვითნებური გახსნა. არ შეიძლება იმ სასოფლო-სამეურნეო, საგზაო-სამშენებლო და სხვა მანქანების არასატრანსპორტო მდგომარეობაში გადატანა, რომლებმაც შეიძლება გადასასვლელი დააზიანონ ან მასზე მოძრაობა შეაფერხონ. აქ ასევე აკრძალულია მობრუნება და უკუსვლით მოძრაობა. ასეთი მანევრის წინ, სადაც ის დასაშვებია, დარწმუნდი, რომ სხვებს საფრთხეს არ უქმნი. ლიანდაგის დისტანციის უფროსის ნებართვის გარეშე აკრძალულია ნელმავალი სატრანსპორტო საშუალების, რომლის სიჩქარე 8 კმ/სთ-ს არ აღემატება, და ტრაქტორის მარხილ-სათრეველას მოძრაობა.', NULL, NULL),
  (E'rule-21-definition', E'ka', E'რა არის რკინიგზის გადასასვლელი', E'რკინიგზის გადასასვლელი არის გზისა და დამოუკიდებელი ვაკისის მქონე რკინიგზის ან ტრამვაის ლიანდაგების ერთ დონეზე გადაკვეთა. მასთან მიახლოებისას და მასზე გავლისას ზომიერი სიჩქარით იმოძრავე: ლიანდაგზე მხოლოდ გადასასვლელით გადადიხარ და მატარებელს, ლოკომოტივსა თუ დრეზინას გზას უთმობ.', NULL, NULL),
  (E'rule-21-forced-stop', E'ka', E'საცობი და იძულებითი გაჩერება', E'გადასასვლელზე ნუ შეხვალ, სანამ არ დარწმუნდები, რომ მასზე გაჩერება არ მოგიწევს, მაგალითად, მის მიღმა საცობის გამო. თუ ავტომობილი მაინც იძულებით გაჩერდა, გაჩერების სიგნალია ხელის წრიული მოძრაობა: დღისით მკვეთრი ფერის ქსოვილით ან კარგად გასარჩევი საგნით, ღამით ჩირაღდნით ან ფარნით. საერთო განგაშის სიგნალია ერთი გრძელი და სამი მოკლე ხმოვანი სიგნალი.', NULL, NULL),
  (E'rule-21-overtaking', E'ka', E'გასწრება გადასასვლელთან', E'გასწრება აკრძალულია რკინიგზის გადასასვლელზე და მის წინ 100 მეტრზე ახლოს. გამონაკლისია, როცა მოძრაობას ისეთი შუქნიშანი არეგულირებს, როგორიც გზაჯვარედინებზე გამოიყენება. ასევე აკრძალულია გადასასვლელის წინ მდგომი სატრანსპორტო საშუალების შემოვლა საპირისპირო მოძრაობის ზოლზე გასვლით. 1.2 ნიშანი „რკინიგზის უშლაგბაუმო გადასასვლელი“ უშლაგბაუმო გადასასვლელთან მიახლოებას გაფრთხილებს.', NULL, NULL),
  (E'rule-21-signals', E'ka', E'გადასასვლელის შუქნიშანი', E'გადასასვლელზე შუქნიშანს ერთ სადგარზე ორი მორიგეობით მოციმციმე ან ერთი მოციმციმე წითელი ან ყვითელი სიგნალი აქვს. წითელი კრძალავს „სდექ“ ხაზის გადაკვეთას, ხოლო თუ ხაზი არ არის — შუქნიშნის იქით გასვლას; მას შეიძლება ხმოვანი სიგნალიც ახლდეს, რომელიც აკრძალვას დამატებით გამცნობს. მოციმციმე ყვითელზე მოძრაობის გაგრძელება შეიძლება, ოღონდ განსაკუთრებული სიფრთხილით. თუ სიგნალები გამორთულია, გადასასვლელზე მხოლოდ მაშინ გადიხარ, როცა ხილვადობის ფარგლებში მოახლოებული მატარებელი, ლოკომოტივი ან დრეზინა არ ჩანს.', NULL, NULL),
  (E'rule-21-traffic-controller', E'ka', E'მარეგულირებელი გადასასვლელზე', E'მარეგულირებელი გადასასვლელზე მოძრაობას კრძალავს, როცა შენკენ მკერდით ან ზურგით დგას. ამავეს ნიშნავს თავს ზემოთ აწეული კვერთხი, წითელი ფარანი ან ალამი და განზე გაწეული ხელები.', NULL, NULL),
  (E'rule-21-where-to-stop', E'ka', E'სად უნდა გაჩერდე', E'გადასასვლელზე ნუ შეხვალ, თუ შლაგბაუმი ან ნახევარშლაგბაუმი დაკეტილია, იკეტება ან იწევა, სიგნალები რასაც არ უნდა აჩვენებდეს. შუქნიშნის ან მარეგულირებლის ამკრძალავ სიგნალზეც ნუ შეხვალ, შლაგბაუმის მდგომარეობისა და მისი არსებობის მიუხედავად. გაჩერდი „სდექ“ ხაზთან, 2.4 ნიშანთან ან შუქნიშანთან; თუ ისინი არ არის — შლაგბაუმამდე არანაკლებ 5 მეტრზე. თუ არც შლაგბაუმია, უახლოეს რელსამდე არანაკლებ 10 მეტრზე გაჩერდი.', NULL, NULL),
  (E'rule-22-entering', E'ka', E'ავტომაგისტრალზე შესვლა', E'ავტომაგისტრალზე შესვლისას გზა უნდა დაუთმო მასზე მოძრავ ავტომობილებს. თუ გაქანების ზოლი არსებობს, ჯერ მასზე იმოძრავე, მეზობელ ზოლზე გადასვლისას კი იქ მოძრავებს დაუთმე.', NULL, NULL),
  (E'rule-22-exiting', E'ka', E'ავტომაგისტრალიდან გამოსვლა', E'გამოსვლისას დროულად გადადი გამოსასვლელის მიმდებარე ზოლზე და რაც შეიძლება სწრაფად შედი შენელების ზოლზე, თუ ასეთი არსებობს. მოხვევის წინ ჯერ დამუხრუჭების ზოლზე გადადი და სიჩქარე მხოლოდ ამის შემდეგ შეანელე.', NULL, NULL),
  (E'rule-22-forced-stop', E'ka', E'იძულებითი გაჩერება', E'ავტომაგისტრალზე გაჩერება და დგომა აკრძალულია, გარდა დგომისთვის სპეციალურად მონიშნული ადგილებისა. თუ შენგან დამოუკიდებელი მიზეზით გაჩერდი, ყველა ზომა მიიღე, რომ ავტომობილი სავალი ნაწილიდან გაიყვანო. თუ ეს მაშინვე შეუძლებელია, ჩართე საავარიო შუქსიგნალიზაცია და დადგი საავარიო გაჩერების ნიშანი: დასახლებულ პუნქტში არანაკლებ 15, დაუსახლებელში — არანაკლებ 30 მეტრზე. 1.2.1 მონიშვნა სავალი ნაწილის ნაპირებს აღნიშნავს; მისი გადაკვეთა მხოლოდ მარჯვენა მხარეს, გზის ნაპირზე გასაჩერებლად შეიძლება.', NULL, NULL),
  (E'rule-22-heavy-vehicles', E'ka', E'ზოლები მძიმე ავტომობილებისთვის', E'ავტომაგისტრალზე მეორე ზოლის იქით ვერ იმოძრავებს ტვირთის გადამზიდავი ავტომობილი, რომლის ნებადართული მაქსიმალური მასა 3,5 ტონას აღემატება, და მისაბმელიანი ავტომობილი, რომლის საერთო სიგრძე 7 მეტრზე მეტია. ეს აკრძალვა მგზავრთა გადასაყვან ავტომობილზე არ ვრცელდება. აქ ასევე აკრძალულია სასწავლო სვლა.', NULL, NULL),
  (E'rule-22-no-reverse', E'ka', E'მობრუნება და უკუსვლა', E'ავტომაგისტრალზე, მის შესასვლელსა და გამოსასვლელზე აკრძალულია მობრუნება და უკუსვლით მოძრაობა. ასევე არ შეიძლება ცენტრალურ გამყოფ ზოლსა და ორივე სავალი ნაწილის განივ შეერთებაზე გასვლა. ამიტომ თუ საჭირო მოსახვევს ან შეერთებას გასცდი, უკუსვლით მასთან ვეღარ დაბრუნდები.', NULL, NULL),
  (E'rule-22-who-allowed', E'ka', E'ვის ეკრძალება ავტომაგისტრალი', E'ავტომაგისტრალზე, მის შესასვლელსა და გამოსასვლელზე აკრძალულია ქვეითის, ცხოველის, ველოსიპედის, მოპედის, ორბორბლიანი ელექტროთვითმგორავის და ყველა იმ სატრანსპორტო საშუალების მოძრაობა, რომელიც ავტომობილი ან მისი მისაბმელი არ არის. არ შეიძლება იმ ავტომობილით მოძრაობაც, რომლის კონსტრუქციული სიჩქარე 40 კმ/სთ-ს არ აღემატება. 5.1 ნიშანი „ავტომაგისტრალი“ აღნიშნავს გზას, სადაც ეს წესები მოქმედებს. მძღოლს, რომელსაც ნარინჯისფერი ან ყვითელი მოელვარე სიგნალი აქვს ჩართული და გზაზე სარემონტო, სამშენებლო ან დასასუფთავებელ სამუშაოებს ასრულებს, ამ მოთხოვნებიდან გადახვევა შეუძლია, თუ უსაფრთხოებას უზრუნველყოფს.', NULL, NULL),
  (E'rule-23-leaving', E'ka', E'ზონიდან გამოსვლა', E'საცხოვრებელი ზონიდან გამოსვლისას გადაკვეთაზე ყველა სხვა მონაწილეს უთმობ. ზონის ყველა გამოსასვლელში დგას 5.22 ნიშანი „საცხოვრებელი ზონის დასასრული“. მიმდებარე ტერიტორიიდან გზაზე გასვლისას მასზე მოძრავ სატრანსპორტო საშუალებებსა და ქვეითებს უთმობ, ხოლო გზიდან გადასვლისას — იმ ქვეითებს, ველოსიპედისტებს, მოპედისა და ორბორბლიანი ელექტროთვითმგორავის მძღოლებს, რომლებსაც გზას უჭრი.', NULL, NULL),
  (E'rule-23-pedestrians', E'ka', E'ქვეითები და აკრძალვები ზონაში', E'საცხოვრებელ ზონასა და ქვეითთა ზონაში ქვეითს უპირატესობა აქვს სხვა მონაწილეების მიმართ. თუმცა ის ტრანსპორტის მოძრაობას უსაფუძვლოდ არ უნდა აფერხებდეს. ასეთ ზონაში აკრძალულია გამჭოლი მოძრაობა, სასწავლო სვლა და ჩართული ძრავით დგომა.', NULL, NULL),
  (E'rule-23-zone-speed', E'ka', E'საცხოვრებელი ზონა და სიჩქარე', E'5.21 ნიშანი „საცხოვრებელი ზონა“ ზონის ყველა შესასვლელში დგას და აღნიშნავს ტერიტორიას, სადაც საცხოვრებელი ზონის წესები მოქმედებს. აქ არაუმეტეს 20 კმ/სთ სიჩქარით მოძრაობ, მაშინ როცა დასახლებულ პუნქტში ზოგადი ზღვარი 60 კმ/სთ-ია.', NULL, NULL),
  (E'rule-24-banned', E'ka', E'როდის არის ბუქსირება აკრძალული', E'ხისტი ან მოქნილი გადაბმით არ შეიძლება იმ ავტომობილის ბუქსირება, რომლის საჭის მართვის მექანიზმი გაუმართავია; ეს აკრძალვა მხოლოდ ამ ორ ხერხს ეხება. მოქნილი გადაბმით ბუქსირება აკრძალულია მოყინულ გზაზე. აკრძალულია მოტოციკლით ბუქსირება გვერდითი მისაბმელის გარეშე, ასევე ასეთი მოტოციკლის ბუქსირება. უმოქმედო სამუხრუჭო სისტემის მქონე ავტომობილის ბუქსირება აკრძალულია, თუ მისი ფაქტობრივი მასა მობუქსირის ფაქტობრივი მასის ნახევარს აღემატება; თუ ნაკლებია, მხოლოდ ხისტი გადაბმით ან ნაწილობრივი დატვირთვით შეიძლება.', NULL, NULL),
  (E'rule-24-distance-lights', E'ka', E'მანძილი, ალმები და განათება', E'მოქნილი გადაბმით ბუქსირებისას ავტომობილებს შორის მანძილი 4–6 მეტრია, ხისტი გადაბმით — არაუმეტეს 4 მეტრისა. მოქნილ გადაბმაზე სულ მცირე ორი ალამი მაგრდება. დღე-ღამის ნებისმიერ დროს მობუქსირეს ჩართული უნდა ჰქონდეს ახლო განათების ფარები, საბუქსიროს — საავარიო შუქსიგნალიზაცია. თუ საბუქსიროს ის არ აქვს ან გაუმართავია, მის უკანა ნაწილზე საავარიო გაჩერების ნიშანი მაგრდება.', NULL, NULL),
  (E'rule-24-motorway', E'ka', E'თოკით ბუქსირი ავტომაგისტრალზე', E'თვითნაკეთი მოწყობილობით — თოკით, მავთულით ან მსგავსით — ბუქსირებული ავტომობილი ავტომაგისტრალზე ვერ შევა. თუ ავტომობილი ავტომაგისტრალზე გაფუჭდა და მას თოკით ბუქსირებენ, მაგისტრალი უახლოეს გასასვლელზე უნდა დატოვო.', NULL, NULL),
  (E'rule-24-people', E'ka', E'მძღოლი და მგზავრები ბუქსირისას', E'ხისტი ან მოქნილი გადაბმით ბუქსირებისას საბუქსირო ავტომობილს მძღოლი უნდა მართავდეს. გამონაკლისია ხისტი გადაბმა, რომლის კონსტრუქციაც საბუქსიროს მობუქსირის კვალზე ატარებს. ამ დროს აკრძალულია მგზავრების გადაყვანა საბუქსირო ავტობუსით, ტროლეიბუსით და სატვირთო ავტომობილის ძარით. ნაწილობრივი დატვირთვით ბუქსირებისას ადამიანი არ უნდა იყოს არც საბუქსირო ავტომობილში, არც მობუქსირის ძარაზე.', NULL, NULL),
  (E'rule-24-speed', E'ka', E'სიჩქარე ბუქსირისას', E'ბუქსირებისას მობუქსირე არაუმეტეს 50 კმ/სთ სიჩქარით მოძრაობს, როგორც დასახლებულ პუნქტში, ისე მის გარეთ. 4.6 ნიშანი „მინიმალური სიჩქარის შეზღუდვა“ სავალდებულოა: თუ ის 50 კმ/სთ-ზე მეტს მოითხოვს, ბუქსირით იქ ვერ იმოძრავებ. 7.2 ნიშანი „რეკომენდებული სიჩქარე“ მხოლოდ გირჩევს და მოძრაობას არ კრძალავს.', NULL, NULL),
  (E'rule-24-what-tows', E'ka', E'ვინ ვის ბუქსირებს', E'მობუქსირე ის ავტომობილია, რომელიც ბუქსირებს, საბუქსირო — ის, რომელსაც ბუქსირებენ. მექანიკურ სატრანსპორტო საშუალებას სხვა მექანიკური სატრანსპორტო საშუალების ბუქსირება მხოლოდ მისაბმელის გარეშე შეუძლია. აკრძალულია ერთდროულად ორი ან მეტი ავტომობილის ბუქსირება, ასევე ისეთი ავტომობილისა, რომელსაც ორი ან მეტი მისაბმელი აქვს.', NULL, NULL),
  (E'rule-25-motorway', E'ka', E'სასწავლო სვლა ავტომაგისტრალზე', E'სასწავლო სვლა, როცა საჭესთან მოსწავლე ზის, ავტომაგისტრალზე აკრძალულია. აკრძალვა მის შესასვლელსა და გამოსასვლელზეც მოქმედებს.', NULL, NULL),
  (E'rule-25-residential-zone', E'ka', E'სასწავლო სვლა საცხოვრებელ ზონაში', E'საცხოვრებელ ზონასა და ქვეითთა ზონად გამოცხადებულ ადგილზე სასწავლო სვლა აკრძალულია. იქ ასევე არ შეიძლება გამჭოლი მოძრაობა და ჩართული ძრავით დგომა.', NULL, NULL),
  (E'rule-26-aetr-driving-rest', E'ka', E'მართვისა და დასვენების დრო', E'AETR შეთანხმებით კვირაში მართვის ხანგრძლივობა 56 საათს არ უნდა აღემატებოდეს, ნებისმიერ ორ მომდევნო კვირაში ჯამურად კი — 90 საათს. ოთხნახევარი საათის მართვის შემდეგ, თუ დასვენების პერიოდი არ იწყება, არანაკლებ 45 წუთით შეისვენე. წინა ყოველდღიური ან ყოველკვირეული დასვენების დასრულებიდან ყოველ 24 საათში ახალი ყოველდღიური დასვენება უნდა გამოიყენო. ნორმალური ყოველდღიური დასვენება არანაკლებ 11 საათია, შემცირებული — არანაკლებ 9, მაგრამ 11 საათზე ნაკლები.', NULL, NULL),
  (E'rule-26-aetr-scope-records', E'ka', E'AETR: ვისზე ვრცელდება და ჩანაწერები', E'თუ მხარეები სხვაგვარად არ შეთანხმდნენ, AETR არ ვრცელდება საერთაშორისო გადაზიდვაზე სატვირთოთი, რომლის ნებადართული მაქსიმალური მასა მისაბმელიანად 3,5 ტონას არ აღემატება, სამგზავრო საშუალებით, რომელიც მძღოლის ჩათვლით ცხრა კაცზე მეტს ვერ იტევს, და 50 კმ-მდე სიგრძის რეგულარულ სამგზავრო ხაზზე. მართვის პერიოდში ითვლება მართვის მთელი დრო, ხელშემკვრელ თუ არახელშემკვრელ სახელმწიფოში. საკონტროლო მოწყობილობა სიჩქარეს, გავლილ მანძილს, მართვის, შესვენებისა და დასვენების დროს აფიქსირებს; მძღოლმა მიმდინარე დღისა და წინა 28 კალენდარული დღის ჩანაწერები უნდა წარადგინოს.', NULL, NULL),
  (E'rule-26-cargo-check', E'ka', E'ტვირთის შემოწმება და ჩაბარება', E'ტვირთის მიღებისას გადამზიდველი ამოწმებს მის ცალობრივ რაოდენობას, ნიშნებისა და ნომრების ზედნადებთან შესაბამისობას, ტვირთისა და შეფუთვის გარეგნულ მდგომარეობას. გამგზავნს შეუძლია მოსთხოვოს, რომ მან გადაამოწმოს წონა, სხვაგვარად მოცემული რაოდენობა ან შემცველობა; შედეგები ზედნადებში აღინიშნება. თუ ზედნადებში გადაზიდვის პირობები არ წერია, საპირისპიროს დამტკიცებამდე ივარაუდება, რომ ტვირთი და შეფუთვა გარეგნულად კარგ მდგომარეობაში იყო, რაოდენობა, აღნიშვნები და ნომრები კი ჩანაწერს ემთხვევა. თუ მიმღები ტვირთს გადამზიდველთან ერთად არ ამოწმებს და პრეტენზიას არ აყენებს, ივარაუდება, რომ ის ზედნადებში მითითებულ მდგომარეობაში ჩაიბარა.', NULL, NULL),
  (E'rule-26-cargo-placement', E'ka', E'ტვირთის განთავსება და დამაგრება', E'ტვირთი ისე უნდა მოათავსო და საჭიროებისას დაამაგრო, რომ სხვა მონაწილეებს საფრთხე არ შეუქმნას, ქონებას ზიანი არ მიაყენოს, გზაზე არ ეთრეოდეს და არ ცვიოდეს. ის არ უნდა ზღუდავდეს ხილვადობასა და ხედვის არეს, არ უნდა არღვევდეს სატრანსპორტო საშუალების მდგრადობას და ართულებდეს მართვას. არც სინათლეები, „სდექ“ სიგნალი, მოხვევის შუქ-მაჩვენებლები, შუქამრეკლები, რეგისტრაციის ნომერი, სახელმწიფოს განმასხვავებელი ნიშანი და ხელით მისაცემი სიგნალები უნდა დაიფაროს. ყველა ეს მოთხოვნა სავალდებულოა.', NULL, NULL),
  (E'rule-26-carriage-contract', E'ka', E'გადაზიდვის ხელშეკრულება', E'ვინც ტვირთის გადაზიდვასა და მგზავრთა გადაყვანას საჯაროდ სთავაზობს, ვალდებულია ხელშეკრულება დადოს, თუ უარის თქმის საფუძველი არ არსებობს. გადამზიდველის პასუხისმგებლობა ხელშეკრულებით ვერ გამოირიცხება და ვერ შეიზღუდება. თუ ერთი ხელშეკრულებით ტვირთს ერთმანეთის მიმდევარი რამდენიმე გადამზიდველი ზიდავს, თითოეული მთლიანი გადაზიდვისთვის აგებს პასუხს. წინა გადამზიდველისგან ტვირთის მიმღები ვალდებულია გადასცეს მიღების დამადასტურებელი, ვადამითითებული და ხელმოწერილი საბუთი. ბათილია შეთანხმება, რომლითაც გადამზიდველი ტვირთის დაზღვევიდან წარმოშობილ მოთხოვნებს თმობს.', NULL, NULL),
  (E'rule-26-carriage-liability', E'ka', E'ვინ აგებს პასუხს ზიანზე', E'გადამზიდველი პასუხს აგებს ზედნადებში აღნიშნული ან მისთვის გადაცემული საბუთების დაკარგვასა და არასწორ გამოყენებაზე, მაგრამ არა უმეტეს იმისა, რაც ტვირთის დაკარგვისას დაეკისრებოდა. ის თავისუფლდება პასუხისმგებლობისგან, თუ დაკარგვა, დაზიანება ან დაგვიანება უფლებამოსილი პირის ბრალით ან მითითებით, ანდა აუცილებელი გარემოებით მოხდა. დაკარგული ტვირთის ზიანი გადაცემის ადგილსა და დროს მოქმედი ფასით ითვლება. გამგზავნი აგებს პასუხს ზედნადებში არასწორი ან არასრული მონაცემებით გამოწვეულ ზიანზე და უხარისხო შეფუთვაზეც, გარდა იმისა, როცა ნაკლი აშკარა იყო ან გადამზიდველმა იცოდა და პირობა არ დაუთქვამს.', NULL, NULL),
  (E'rule-26-children-road', E'ka', E'ბავშვები გზაზე', E'თუ გზაზე ან მის სიახლოვეს ბავშვს ხედავ, ან გაჩერებულ ავტობუსს საცნობი ნიშნით „ბავშვების გადაყვანა“, განსაკუთრებული სიფრთხილე გამოიჩინე. იმოძრავე ისეთი სიჩქარით, რომ საფრთხე აიცილო და საჭიროებისას მკვეთრი დამუხრუჭების გარეშე გაჩერდე. ორმხრივ მოძრაობიან გზაზე, სადაც გამყოფი ზოლი არ არის, ბავშვთა ჯგუფი მოძრაობის მიმართულების საწინააღმდეგო მხარის გვერდულაზე გადაადგილდება.', NULL, NULL),
  (E'rule-26-children-transport', E'ka', E'ბავშვების გადაყვანა', E'ბავშვები სატრანსპორტო საშუალებით მხოლოდ დამსხდარ მდგომარეობაში, კონსტრუქციით განსაზღვრულ დასასხდომ ადგილებზე გადაჰყავთ; ფეხზე მდგომის გადაყვანა აკრძალულია. 12 წლამდე ბავშვის გადაყვანა აკრძალულია მსუბუქი ავტომობილის წინა სავარძელზე, ასევე მოპედით და მოტოციკლით.', NULL, NULL),
  (E'rule-26-dangerous-cargo', E'ka', E'სახიფათო ტვირთი', E'სახიფათო ტვირთის გადამზიდავ სატრანსპორტო საშუალებას წინა და უკანა მხარეს, ცისტერნას კი გვერდებზეც, ემაგრება საცნობი ნიშანი „სახიფათო ტვირთი“ — ნარინჯისფერი ფირფიტა შავი არშიით. ასეთი საშუალებისთვის ნებადართულ მიმართულებას ნიშნები „სახიფათო ტვირთის გადამზიდავი სატრანსპორტო საშუალებით მოძრაობის მიმართულება“ აჩვენებს: 4.9.1 ნიშანი — პირდაპირ, 4.9.2 ნიშანი — მარჯვნივ, 4.9.3 ნიშანი — მარცხნივ.', NULL, NULL),
  (E'rule-26-delivery-limitation', E'ka', E'ვადის გადაცილება და ხანდაზმულობა', E'მიტანა დაგვიანებულია, თუ ტვირთი შეთანხმებულ ვადაში არ მივიდა, ვადის გარეშე კი — წინდახედული გადამზიდველისთვის ჩვეულებრივ საჭირო დროში. უფლებამოსილ პირს შეუძლია ტვირთი დაკარგულად ჩათვალოს შეთანხმებული ვადიდან 30 დღის, ვადის არარსებობისას კი მიღებიდან 60 დღის შემდეგ. გადაზიდვიდან გამომდინარე მოთხოვნების ხანდაზმულობა ერთი წელია, განზრახვისა და უხეში გაუფრთხილებლობისას — სამი. ვადა ნაწილობრივი დაკარგვის, დაზიანების ან დაგვიანებისას ტვირთის გამოგზავნის დღიდან ითვლება, მთლიანი დაკარგვისას — შეთანხმებული ვადის გასვლიდან 30-ე, ვადის გარეშე კი მიღებიდან 60-ე დღიდან.', NULL, NULL),
  (E'rule-26-hazardous-shipment', E'ka', E'საფრთხეშემცველი ტვირთის გაგზავნა', E'საფრთხეშემცველი ტვირთის გამგზავნი ვალდებულია გადამზიდველს ზუსტი ინფორმაცია მიაწოდოს, გააფრთხილოს და საჭიროებისას ტვირთი დააზღვიოს. თუ ეს ზედნადებში არ წერია, გამგზავნმა და მიმღებმა სხვა საშუალებით უნდა დაამტკიცონ, რომ გადამზიდველმა ტვირთის სახეობა და საფრთხე ზუსტად იცოდა. თუ ინფორმაციის მიუწოდებლობის გამო გადამზიდველმა საფრთხის შესახებ არაფერი იცოდა, მას შეუძლია ტვირთი ნებისმიერ დროსა და ადგილას გადმოცალოს, მოსპოს ან გააუვნებელყოს ზიანის ანაზღაურების გარეშე.', NULL, NULL),
  (E'rule-26-oversize-cargo', E'ka', E'გადმოშვერილი ტვირთის აღნიშვნა', E'თუ ტვირთი სატრანსპორტო საშუალების გაბარიტს გარეთ წინ ან უკან 1 მეტრზე მეტად, ან გვერდიდან საგაბარიტო სინათლის გარე ნაპირიდან 0,4 მეტრზე მეტად არის გადმოშვერილი, მას საცნობი ნიშნით „არაგაბარიტული (მსხვილგაბარიტიანი) ტვირთი“ აღნიშნავენ. დღე-ღამის ბნელ დროს ან არასაკმარისი ხილვადობისას დამატებით საჭიროა წინ თეთრი ფარანი ან შუქამრეკლი, უკან კი წითელი ფარანი ან შუქამრეკლი.', NULL, NULL),
  (E'rule-26-oversize-vehicle', E'ka', E'არაგაბარიტული სატრანსპორტო საშუალება', E'სატრანსპორტო საშუალება არაგაბარიტულად ითვლება, თუ სავალი ნაწილის ზედაპირიდან მისი სიმაღლე 4 მეტრს აღემატება, ავტომზიდისა და კონტეინერის გადაზიდვისას კი — 4,30 მეტრს. დღის ნათელ დროსაც ასეთ, ასევე ზენორმატიულ და სახიფათო ტვირთის გადამზიდავ ავტომობილს ჩართული უნდა ჰქონდეს ახლო განათების ფარები და უკანა საგაბარიტო სინათლეები. ხიდის, ესტაკადის, მაღალი ძაბვის გადამცემი ხაზის ქვეშ და გვირაბში გავლამდე ავტობუსისა და სატვირთო ავტომობილის მძღოლი უნდა დარწმუნდეს, რომ უსაფრთხოდ გაივლის.', NULL, NULL),
  (E'rule-26-passengers', E'ka', E'მგზავრების გადაყვანა', E'აკრძალულია მგზავრების იმდენი ან ისე გადაყვანა, რომ ეს მართვას ხელს უშლიდეს ან მძღოლს ხედვის არეს უზღუდავდეს. მგზავრს ვერ გადაიყვან ავტომობილის, ტრაქტორის ან სხვა თვითმავალი მანქანის სალონისა თუ კაბინის გარეთ; გამონაკლისია ფურგონძარიანი ან ბორტის პლატფორმის მქონე სატვირთო ავტომობილის ძარა. აკრძალულია გადაყვანა სატვირთო ავტომობილის მისაბმელით, მისაბმელ-აგარაკით, სატვირთო მოტოციკლის ძარით და მოტოციკლის დასასხდომი ადგილების გარეთ. მგზავრებს ვერც მაშინ გადაიყვან, როცა სატრანსპორტო საშუალების ფაქტობრივი მასა ნებადართულ მაქსიმალურ მასას აღემატება.', NULL, NULL),
  (E'rule-26-truck-bed-setup', E'ka', E'მგზავრები სატვირთოს ძარაზე', E'მგზავრებისთვის მოწყობილ ძარაზე დასაჯდომი ადგილები იატაკიდან 0,3–0,5 მ-ზე და ბორტის ზედა კიდიდან არანაკლებ 0,3 მ-ზეა, უკანა და გვერდითი ბორტების გასწვრივ კი მყარი საზურგეებით. ბავშვთა ჯგუფისთვის ბორტები იატაკიდან არანაკლებ 0,8 მ სიმაღლისაა და ჯგუფს ორი სრულწლოვანი მაინც ახლავს. მგზავრები ადგილების რაოდენობას არ აღემატებიან და მხოლოდ სხედან: დგომა, ბორტზე ჯდომა და ტვირთის დადება აკრძალულია. გზის წინ ჩაუტარე ინსტრუქტაჟი და დაიძარი მხოლოდ მაშინ, როცა უსაფრთხოება უზრუნველყოფილია. მოუწყობელი ძარით მხოლოდ ტვირთის თანმხლები მგზავრობს, თუ ბორტის დონეზე დაბლა დასაჯდომი ადგილი აქვს.', NULL, NULL),
  (E'rule-26-truck-bed-who', E'ka', E'ვინ გადაიყვანს მგზავრებს ძარით', E'სატვირთო ავტომობილის მოწყობილი ძარით არაუმეტეს 8 მგზავრის, მძღოლის გარდა, გადაყვანა შეუძლია „C“ კატეგორიის მქონე პირს ამ კატეგორიის მართვის მოწმობის მიღებიდან 1 წლის შემდეგ. 8-ზე მეტი მგზავრისთვის „C“ და „D“ კატეგორია ერთად გჭირდება, ხოლო „C“ კატეგორიის მოწმობის მიღებიდან 3 წელი უნდა იყოს გასული.', NULL, NULL),
  (E'rule-26-van-loading', E'ka', E'სატვირთოს დატვირთვა და მოცულობა', E'სატვირთო ავტომობილზე ტვირთის მოთავსებისას გაითვალისწინე სიმძიმის ცენტრის მდებარეობა, ღერძზე დატვირთვის მოთხოვნები და ის, რომ საგზაო-სატრანსპორტო შემთხვევისას ტვირთი შეიძლება გადაადგილდეს. ფურგონის სატვირთო განყოფილების მოცულობის გამოსათვლელად მისი სიგრძე გაამრავლე სიგანესა და სიმაღლეზე. ავტომობილის საერთო სიგრძე ამ გამოთვლაში არ მონაწილეობს.', NULL, NULL),
  (E'rule-26-waybill', E'ka', E'ზედნადები', E'ზედნადები სამ ცალად დგება და მას გამგზავნი და გადამზიდველი აწერენ ხელს: პირველი გამგზავნს რჩება, მეორე ტვირთს მიჰყვება, მესამე გადამზიდველს. თუ ტვირთი რამდენიმე ტრანსპორტზე ნაწილდება, სხვადასხვა სახისაა ან პარტიებადაა დაყოფილი, ორივე მხარეს შეუძლია თითო ტრანსპორტზე ან სახეობაზე ცალკე ზედნადები მოითხოვოს. მასში იწერება გაცემისა და გადაცემის დღე და ადგილი, მიტანის ადგილი, ტვირთის სახელწოდება, შეფუთვა, რაოდენობა, ნიშნები, ნომრები, წონა და ხარჯები; საჭიროებისას — გადატვირთვის აკრძალვა, გამგზავნის ხარჯები, ფასდანამატი, ღირებულება, დაზღვევის მითითებები და გადაცემული საბუთების სია.', NULL, NULL),
  (E'rule-27-age-and-riding', E'ka', E'ასაკი და მართვის წესი', E'გზაზე ველოსიპედისა და ორბორბლიანი ელექტროთვითმგორავის მართვა 14 წლიდან შეიძლება, მოპედისა — 16 წლიდან. მოპედის, მოტოციკლის, ელექტროთვითმგორავის და ველოსიპედის მძღოლი ისე უნდა მოძრაობდეს, რომ ყველა თვალი გზის ზედაპირს ეხებოდეს; ეს სამთვლიან მოპედსაც ეხება. ველოსიპედის, მოპედისა და ელექტროთვითმგორავის მძღოლს ეკრძალება მოძრაობა, თუ საჭე ერთი ხელით მაინც არ უჭირავს.', NULL, NULL),
  (E'rule-27-animals', E'ka', E'პირუტყვი და ჯოგი გზაზე', E'ღამით სავალ ნაწილზე შესაბმელი, სასაპალნე ან საჯდომი პირუტყვის ან ნახირის მეხრეს მოძრაობის მარცხენა მხრიდან უნდა ჰქონდეს წინ სულ მცირე ერთი თეთრი ან ყვითელი სელექციური სინათლე და უკან ერთი წითელი, ან ყვითელი შუქი წინაც და უკანაც. სინათლის წყაროდ შეიძლება ერთი მოწყობილობა გამოიყენოს. თუ შენ წინ სავალ ნაწილზე საქონლის ჯოგი გადადის, გაითვალისწინე, რომ მის შემდეგ ჩამორჩენილი ცალკეული ცხოველიც შეიძლება გამოვიდეს.', NULL, NULL),
  (E'rule-27-columns', E'ka', E'კოლონით მოძრაობა', E'ველოსიპედისა და მოპედის მძღოლებს კოლონით გადაადგილება შეუძლიათ. სავალ ნაწილზე კოლონა ჯგუფებად იყოფა, თითოეულში არაუმეტეს 10 ერთეულისა. გასწრების გასაადვილებლად ჯგუფებს შორის მანძილი 80–100 მეტრია.', NULL, NULL),
  (E'rule-27-overtaking-moped', E'ka', E'მოპედის გასწრება გზაჯვარედინზე', E'რეგულირებულ გზაჯვარედინზე ავტომობილით მოპედის გასწრება აკრძალული არ არის, თუ საპირისპირო მოძრაობის ზოლზე არ გადიხარ. იგივე წესი ეტლიან მოტოციკლსაც ეხება.', NULL, NULL),
  (E'rule-27-where-to-ride', E'ka', E'სად მოძრაობს ველოსიპედი და მოპედი', E'ველოსიპედით ტროტუარზე მხოლოდ მაშინ შეიძლება, თუ ველოზოლი, ველობილიკი და გვერდულა არ არის, სავალ ნაწილზე მოძრაობა გართულებულია და ქვეითებს არ აფერხებ; მოპედით ტროტუარზე მოძრაობა აკრძალულია. ქვეითს ველობილიკზე სიარული შეუძლია, თუ ქვეითთა ბილიკი, ტროტუარი და გზისპირი არ არის და ველოსიპედებს ხელს არ უშლის. ველოსიპედსა და მოპედს ეკრძალება მარცხნივ მოხვევა და მობრუნება ტრამვაის ლიანდაგიან გზაზე და იქ, სადაც ერთი მიმართულებით ერთზე მეტი ზოლია. სადაც ველოზოლი ან ველობილიკია, მათ მიღმა ვერ იმოძრავებენ; სავალ ნაწილზე — მხოლოდ განაპირა მარჯვენა ზოლზე, ერთ რიგად.', NULL, NULL),
  (E'rule-27-yield-to-cyclists', E'ka', E'ველოსიპედისტი და გზის დათმობა', E'მიმდებარე ტერიტორიიდან გზაზე გასვლისას გზა დაუთმე გზაზე მოძრავ სატრანსპორტო საშუალებებსა და ქვეითებს, ხოლო გზიდან გადასვლისას — ქვეითს, ველოსიპედისტს, მოპედისა და ორბორბლიანი ელექტროთვითმგორავის მძღოლებს, რომლებსაც გზას უჭრი. გზაჯვარედინის მიღმა, გზასთან ველობილიკის არარეგულირებულ გადაკვეთაზე, ველოსიპედისა და მოპედის მძღოლები გზას უთმობენ ამ გზაზე მოძრავ სატრანსპორტო საშუალებებს. სავალი ნაწილის, ველობილიკის ან ველოსიპედის ზოლის მხარეს კარი მგზავრთა ჩასხდომა-გადმოსხდომისთვის საჭირო დროზე მეტხანს ღია არ უნდა იყოს.', NULL, NULL),
  (E'rule-29-assessment', E'ka', E'დაშავებულის მდგომარეობის შეფასება', E'დაშავებულის მდგომარეობა სწრაფად შეაფასე: ჯერ შეამოწმე ცნობიერება, შემდეგ გაუხსენი სასუნთქი გზები, გააკონტროლე სუნთქვა და ბოლოს შეამოწმე პულსაცია საძილე არტერიაზე. ავტომობილის კაბინიდან გადმოყვანა მიზანშეწონილია, როცა დაშავებულს გონება აქვს დაკარგული და არ აღენიშნება სუნთქვა და პულსაცია საძილე არტერიაზე. უგონო მდგომარეობაში მყოფს სამკურნალო პრეპარატს არ აძლევენ.', NULL, NULL),
  (E'rule-29-bleeding', E'ka', E'სისხლდენის სახეები', E'არტერიული სისხლდენისას ღია-ალისფერი სისხლი ჭრილობიდან პულსირებული ნაკადით გამოედინება. ის სიცოცხლისთვის საშიშია: საშიში რაოდენობის სისხლი შეიძლება 10–15 წუთის შემდეგ დაიკარგოს. ვენური სისხლდენისას მუქი-ალუბლისფერი სისხლი სუსტი ნაკადით მოდის; ჭრილობაზე მჭიდრო სახვევი დაადე, ხოლო როცა მისი ქვედა ფენა გაიჟღინთება, არ მოაცილო და ახალი დაუმატე. ცხვირიდან სისხლდენისას დაშავებული ნახევრადმჯდომარედ დასვი, თავი მკერდისკენ დაახრევინე და ცხვირზე ცივი საფენი დაადე.', NULL, NULL),
  (E'rule-29-breathing-cpr', E'ka', E'ხელოვნური სუნთქვა და გულის მასაჟი', E'თუ დაშავებულს არც სუნთქვა აქვს და არც პულსაცია საძილე არტერიაზე, უტარდება ხელოვნური სუნთქვაც და გულის არაპირდაპირი მასაჟიც: ორი ჩაბერვა და 30 მასაჟი, ჯამში წუთში 100 მასაჟი. თუ არ სუნთქავს, მაგრამ პულსი აქვს, საჭიროა მხოლოდ ხელოვნური სუნთქვა — ერთი ჩასუნთქვა ყოველ 6 წამში, სანამ სპონტანური სუნთქვა არ აღუდგება. პულსი ამ დროს ყოველ 2 წუთში ერთხელ შეამოწმე. სასუნთქ გზებში უცხო სხეულის მოსაცილებლად ჯერ ზურგზე რამდენჯერმე ხელისგული დაარტყი. თუ არ უშველა, დადექი დაშავებულის უკან, ქვედა ნეკნის დონეზე მუცელთან ხელები მუშტად გადააჭდე და მუშტებით მკვეთრად დააწექი შიგნით და ზემოთ.', NULL, NULL),
  (E'rule-29-duty-to-help', E'ka', E'დახმარების ვალდებულება', E'საგზაო-სატრანსპორტო შემთხვევის მონაწილე მძღოლი ვალდებულია დაშავებულს პირველადი სამედიცინო დახმარება აღმოუჩინოს და სასწრაფო სამედიცინო დახმარება გამოიძახოს. გადაუდებელი აუცილებლობისას დაშავებული უახლოეს სამკურნალო დაწესებულებაში გზად მიმავალი სხვა სატრანსპორტო საშუალებით უნდა გაგზავნოს, ხოლო თუ ეს შეუძლებელია, თავად წაიყვანოს. გამონაკლისია შემთხვევა, როცა არსებობს საფუძვლიანი ეჭვი, რომ გადაყვანა დაშავებულს ზიანს მიაყენებს.', NULL, NULL),
  (E'rule-29-fractures', E'ka', E'მოტეხილობა და სახვევი', E'წვივის ძვლების მოტეხილობისას არტაშანი ორივე მხრიდან, ტერფიდან შუა ბარძაყამდე იდება. არტაშნის მასალა თუ არ გაქვს, დაზიანებული ფეხი ჯანმრთელს ბინტით დაუმაგრე და მათ შორის რბილი ქსოვილი ჩადე; მოტეხილი ხელი კი იდაყვში მოხრილი კისერზე ჩამოკიდე და ბინტით ტანზე მიუმაგრე. მენჯისა და ბარძაყის მოტეხილობისას დაშავებული ზურგზე დააწვინე, მუხლებქვეშ მჭიდროდ დახვეული საფენი ან ტანსაცმელი ამოუდე და ტკივილგამაყუჩებელი მიეცი. წვივ-ტერფის სახსრის დაზიანებისას რვიანისებური სახვევი გამოიყენება. თუ ერთი ხელია დაზიანებული, პიჯაკი ან პერანგი ჯერ ჯანსაღ ხელზე გახადე, მერე — დაზიანებულზე.', NULL, NULL),
  (E'rule-29-head-shock-fainting', E'ka', E'გულის წასვლა, შოკი, თავის ტრავმა', E'გულწასული დაშავებული ზურგზე დააწვინე, ფეხები წამოუწიე, ნიშადურის სპირტი ასუნთქე და საფეთქლები ადეკოლონით ან სხვა სპირტის შემცველი სითხით დაუზილე. ტრავმული შოკის დროს საჭიროებისას სისხლდენა შეაჩერე, სათბურები დააფარე, ხოლო თუ მუცლის ღრუს შიდა ორგანოების დაზიანებას არ ეჭვობ, თბილი სასმელი დაალევინე. თავის ქალისა და ტვინის დაზიანების გამო გონებადაკარგული, ასევე ტვინის შერყევის მქონე დაშავებული გვერდზე დააწვინე და ასე გადაიყვანე. თავის თმიან ადგილზე ტრავმისას კისერზე იმპროვიზირებული ნახვევი დაადე, ჭრილობაზე — სტერილური ბინტით დამწოლი ნახვევი, დაშავებული გვერდზე მუხლებში მოხრილი ფეხებით დააწვინე და თავზე ყინული ან ცივი საფენი მიადე.', NULL, NULL),
  (E'rule-29-spine', E'ka', E'კისრისა და ხერხემლის ტრავმა', E'კისრის ხერხემლის მალების ტრავმისას კისრისა და ზურგის არეში ტკივილია, რომელიც ხელით შეხებისას მატულობს. ასეთი დაზიანებისას ან მისი ეჭვის დროს არ შეიძლება თავისა და კისრის მოძრაობა, ჭრილობაზე შეხება, ძვლის ნამსხვრევების ჩასწორება და უცხო სხეულების მოცილება. დაშავებული ზურგზე, სწორ და მაგარ ზედაპირზე დააწვინე, კისრისა და წელის არეში ბალიში ამოუდე და ასევე, ზურგზე მწოლიარე, გადაიყვანე; მისი დაჯდომა ან ფეხზე დგომა აკრძალულია. თუ სიცოცხლეს საფრთხე ემუქრება და მარტო ხარ, დასვი, დადექი ზურგს უკან, მკლავები მხრებქვეშ შეუცურე, ქვედა ყბა და კისერი დაუფიქსირე და უკან გადაათრიე.', NULL, NULL),
  (E'rule-29-tourniquet', E'ka', E'ლახტის დადება', E'არტერიული სისხლდენის შემაჩერებელი ლახტი კიდურზე ჭრილობის ადგილის ზემოთ იდება, უმჯობესია იქ, სადაც მხოლოდ ერთი ძვალია — მხარზე ან ბარძაყზე. წვივის დაზიანებისას მას ბარძაყზე ადებენ, იდაყვის ქვემოთ ხელის დაზიანებისას — იდაყვის ზემოთ, მხართან. პირდაპირ კანზე არ იდება: ქვეშ ბამბა, ნაჭერი ან ტანსაცმელი უნდა მოთავსდეს. დადების ზუსტი დრო აუცილებლად უნდა აღინიშნოს.', NULL, NULL),
  (E'rule-29-transport-position', E'ka', E'როგორ გადავიყვანოთ დაშავებული', E'მუცლის არის ჭრილობისას დაშავებული ზურგზე დაწოლილი, მუხლებში მოხრილი ფეხებით გადაიყვანე. გულმკერდის გამჭოლი ჭრილობისას — ჯანმრთელ გვერდზე დაწოლილი ან ნახევრადმჯდომარე. ნეკნებისა და მკერდის ძვლის მოტეხილობისას — მჯდომარე ან ნახევრადმჯდომარე, ლავიწის მოტეხილობისას კი — მჯდომარე.', NULL, NULL),
  (E'rule-29-wounds-burns', E'ka', E'ჭრილობა, თვალი, დამწვრობა', E'კანისა და კუნთის ჭრილობისას იოდის ხსნარით დაამუშავე ჭრილობის ნაპირები და მიმდებარე კანი, მერე დაადე ბაქტერიციდული საფენი, ასეთის არქონისას — სუფთა. თვალის ჭრილობისას დაშავებული ზურგზე დააწვინე, თავი წინ წამოუწიე და დაზიანებულ თვალზე სუფთა საფენი დაადე. მე-2 ხარისხის დამწვრობისას ბუშტებს ნუ გაუხსნი და ტანსაცმლის ნარჩენებს ნუ მოაცილებ; დაადე სტერილური საფენი ბინტით შეხვევის გარეშე, მიადე ყინული ან ცივი საფენი, მიეცი ტკივილგამაყუჩებელი, თუ მასზე ალერგია არ აქვს, და დაალევინე წყალი. გოგირდის მჟავით დაზიანებული კანი წყლის უხვი რაოდენობით გადარეცხე.', NULL, NULL),
  (E'rule-30-alcohol-drugs', E'ka', E'თრობა და წამლები საჭესთან', E'აკრძალულია მართვა ალკოჰოლური, ნარკოტიკული ან ფსიქოტროპული სიმთვრალის მდგომარეობაში. აკრძალვა მოქმედებს მაშინაც, როცა ნარკოტიკული ან ფსიქოტროპული საშუალება ექიმის დანიშნულებით, სამედიცინო მიზნით მიიღე. საჭეს ვერ შეუჯდები ისეთი სამკურნალო პრეპარატის ზემოქმედებისასაც, რომელიც რეაქციასა და ყურადღებას აქვეითებს. ალკოჰოლი რეაქციის დროს ზრდის.', NULL, NULL),
  (E'rule-30-belt-phone-child', E'ka', E'ღვედი, ტელეფონი, ბავშვი', E'მართვისას უსაფრთხოების ღვედი უნდა გეკეთოს; ვალდებულება არ გაქვს მხოლოდ მაშინ, თუ სატრანსპორტო საშუალების კონსტრუქცია ღვედებს არ ითვალისწინებს. მოერიდე ყველა მოქმედებას, რომელიც მართვას არ უკავშირდება. მობილური ტელეფონით სარგებლობა დასაშვებია მხოლოდ ყურსასმენით ან ხმამაღალი საუბრის ფუნქციით, როცა ორივე ხელი სამართავად თავისუფალი გაქვს. გაჩერებულ ავტომობილში 6 წლამდე ბავშვის უმეთვალყურეოდ დატოვება აკრძალულია.', NULL, NULL),
  (E'rule-30-calm', E'ka', E'სიმშვიდე საჭესთან', E'მძღოლის ემოციური მდგომარეობა მოძრაობის უსაფრთხოებაზე გავლენას ახდენს. მართე მშვიდად: ნუ გამოიჩენ აგრესიულობას და ნუ ეცდები, თავი გზაზე უპირატესად წარმოაჩინო. თუ სხვა მძღოლი აგრესიულად და გამომწვევად იქცევა, შეინარჩუნე სიმშვიდე და აკონტროლე შენი სატრანსპორტო საშუალება.', NULL, NULL),
  (E'rule-30-curves', E'ka', E'მოსახვევი და მდგრადობა', E'მოსახვევში სიჩქარის გაზრდისას ცენტრიდანული ძალა იზრდება. მუხრუჭის მკვეთრმა გამოყენებამ ან მაღალი სიჩქარით შესვლამ, განსაკუთრებით სველ გზაზე, შეიძლება მართვაზე კონტროლი დაგაკარგვინოს. რაც უფრო დაბლაა სიმძიმის ცენტრი, მით უფრო მდგრადია ავტომობილი გადაყირავების წინააღმდეგ; ტვირთიანისა ის ყოველთვის უფრო მაღლაა, ვიდრე უტვირთოსი. მოხვევისას წინა და უკანა თვლების რადიუსების სხვაობას დინამიკური დერეფანი ეწოდება: სატვირთოსა და ავტობუსს მოსახვევში მნიშვნელოვნად ფართო ზოლი სჭირდება.', NULL, NULL),
  (E'rule-30-distance-flow', E'ka', E'დისტანცია, ინტერვალი, ნაკადი', E'მჭიდრო ნაკადში ავარიული სიტუაციის ალბათობა ნაკლებია, თუ შენი სიჩქარე ნაკადის სიჩქარის ტოლია. განსაკუთრებული საფუძვლის გარეშე მეტისმეტად დაბალი სიჩქარით სხვების გადაადგილებას ნუ გაართულებ. საფრთხე იზრდება, თუ დისტანციას ან გვერდით ინტერვალს არ იცავ, ან მანევრს ისე იწყებ, რომ მის უსაფრთხოებაში არ რწმუნდები. გვერდითი ინტერვალი გაზარდე მაღალი სიჩქარით მომავალ ან გრძელ შემხვედრთან გვერდის აქცევისას, ასევე სველ, მოლიპულ ან უსწორმასწორო გზაზე.', NULL, NULL),
  (E'rule-30-driver-state', E'ka', E'რა მოქმედებს მძღოლზე', E'მძღოლის მოქმედებაზე გავლენას ახდენს დაღლილობა, უძილობა, სამკურნალო პრეპარატები და ალკოჰოლი; მართვის უნარს აუარესებს ნარკოტიკული და ფსიქოტროპული თრობაც. გადაღლილ მძღოლს ყურადღება უქვეითდება, რეაქციის დრო კი იზრდება. რეაქციის დრო არის დრო საფრთხის აღმოჩენიდან მის ასაცილებლად საჭირო ზომების მიღებამდე. თუ მართვისას დაღლილობას გრძნობ, გაჩერდი და დაისვენე, შეძლებისდაგვარად კი საჭესთან სხვა მძღოლი დასვი.', NULL, NULL),
  (E'rule-30-fault-signs', E'ka', E'გაუმართაობის ნიშნები', E'დამუხრუჭებისას ლითონის ხმა და დამახასიათებელი ჭრიალი სამუხრუჭე ხუნდების გაცვეთაზე მიუთითებს. მაყუჩიდან მძლავრი მუქი კვამლი ძრავის კვების სისტემის გაუმართაობის ან არასწორი რეგულირების ნიშანია, რაც საწვავის ხარჯს მკვეთრად ზრდის. პნევმატურ სამუხრუჭე სისტემაში რესივერი შეკუმშული ჰაერის რეზერვს ქმნის.', NULL, NULL),
  (E'rule-30-faults-no-driving', E'ka', E'როდის აკრძალულია მოძრაობა', E'მგზავრობის დაწყებამდე შეამოწმე და გზაში შეინარჩუნე სატრანსპორტო საშუალების ტექნიკური გამართულობა. მოძრაობა აკრძალულია, თუ გაუმართავია მუშა სამუხრუჭო სისტემა, საჭის მექანიზმი ან შემადგენლობის მისაბმელი მოწყობილობა. დღე-ღამის ბნელ დროს გაუნათებელ გზაზე ან არასაკმარისი ხილვადობისას ვერ იმოძრავებ, თუ ერთდროულად ჩამქრალია ახლო და შორი განათების ფარები ან უკანა საგაბარიტო სინათლეები. ნისლში, წვიმასა და თოვაში მართვა აკრძალულია, თუ მძღოლის მხარეს მინასაწმენდი არ მუშაობს.', NULL, NULL),
  (E'rule-30-handing-over', E'ka', E'ვის არ გადასცე საჭე', E'აკრძალულია სატრანსპორტო საშუალების სამართავად გადაცემა პირისთვის, რომელიც ალკოჰოლური, ნარკოტიკული ან ფსიქოტროპული სიმთვრალის მდგომარეობაშია. მნიშვნელობა არ აქვს, ეს საშუალება მან ექიმის დანიშნულებით მიიღო თუ არა. არც იმას გადასცემ მართვას, ვინც რეაქციისა და ყურადღების დამაქვეითებელი სამკურნალო პრეპარატის ზემოქმედების ქვეშაა.', NULL, NULL),
  (E'rule-30-ice-snow', E'ka', E'ყინული, ლიპი და ღრმა თოვლი', E'მოყინულ მონაკვეთზე შეძლებისდაგვარად მოერიდე დამუხრუჭებას, სიჩქარის ცვლილებასა და მიმართულების მკვეთრ შეცვლას. გზა ყველაზე ხშირად ხიდზე, გზაგამტარსა და ესტაკადაზე იყინება. თუ სწორ გზაზე მოულოდნელად მოკლე მოლიპულ მონაკვეთზე მოხვდი, გააგრძელე მოძრაობა იმავე ტრაექტორიით, სიჩქარის შეუცვლელად. უკანა წამყვანღერძიანი ავტომობილით ყინულზე მოერიდე გადაბმულობის ქუროს სატერფულის მკვეთრ აშვებას და აქსელერატორის მკვეთრ დაჭერას. ღრმა თოვლით დაფარულ გრუნტოვან გზაზე იმოძრავე წინასწარ შერჩეული დაბალი გადაცემით და სიჩქარით, გაჩერებებისა და მკვეთრი მობრუნების გარეშე.', NULL, NULL),
  (E'rule-30-night', E'ka', E'ღამე და ცუდი განათება', E'ნათელი მონაკვეთიდან ბნელზე გასვლისას თვალი სიბნელეს ნელა ეჩვევა, ამიტომ წინ არსებული დაბრკოლებები ძნელი შესამჩნევია. ცუდად ან არათანაბრად განათებულ გზაზე მოძრაობის მონაწილეები ერთმანეთს ძნელად ამჩნევენ. სიბნელეში ორიენტირი მხოლოდ ფარების შუქია, ამიტომ შემხვედრის სიჩქარე რეალურზე ნაკლები გეჩვენება. სიჩქარე ისე შეარჩიე, რომ გასაჩერებელი მანძილი მხედველობის არეზე ნაკლები იყოს. შემხვედრის ფარებმა თვალი რომ ნაკლებად მოგჭრას, მზერა სავალი ნაწილის მარჯვენა ნაპირისკენ მიმართე.', NULL, NULL),
  (E'rule-30-pedestrians', E'ka', E'ქვეითები და ბავშვები', E'შუქნიშანთან მდგარი ბავშვები შეიძლება სავალ ნაწილზე გადმოვიდნენ მწვანე სიგნალის ყვითლით შეცვლისთანავე ან მათთვის ნებადამრთველი სიგნალის ჩართვამდეც; ჯგუფში ხელის კვრით რომელიმე შეიძლება სავალ ნაწილზე აღმოჩნდეს. წვიმიან ამინდში ქვეითების მიმართ განსაკუთრებით ყურადღებით იყავი, რადგან მათი შესაძლო სიჩქარის გამო საფრთხე შეიძლება შეიქმნას. თუ გზის შესასვლელთან, სადაც უხვევ, ქვეითთა გადასასვლელია, მოუხვიე მხოლოდ დაბალი სიჩქარით, საჭიროებისას გაჩერდი და გაატარე გადასასვლელზე შესული ან შემავალი ქვეითები. მოხუცი ქვეითი სავალ ნაწილზე სხვებზე ნელა მოძრაობს, შეიძლება ნახევარი გზიდან უკან მობრუნდეს ან წონასწორობა დაკარგოს და წაიქცეს.', NULL, NULL),
  (E'rule-30-perception', E'ka', E'როგორ ცდება თვალი', E'დიდხანს მაღალი სიჩქარით მოძრაობა აქვეითებს კონცენტრაციასა და სიჩქარის შეგრძნებას: სწორ გზაზე საკუთარ სიჩქარეს რეალურზე ნაკლებად აღიქვამ. საპირისპირო ზოლზე გასწრებისას ავარიის ერთ-ერთი მთავარი მიზეზი ისაა, რომ მძღოლი შემხვედრის სიჩქარეს რეალურზე ნაკლებად აფასებს. სიჩქარის ზრდასთან ერთად მხედველობის არე ვიწროვდება, ნისლში კი საგნებამდე მანძილი რეალურზე მეტი გეჩვენება. შიდა უკუხედვის სარკე შენს სიმაღლეზე დაარეგულირე; ამობურცულ სარკეში საგნები უფრო შორს ჩანს და მას „მკვდარი უბნები“ აქვს.', NULL, NULL),
  (E'rule-30-rain', E'ka', E'წვიმა და თოვა', E'წვიმასა და თოვაში დამუხრუჭებისთვის საჭირო დრო და მანძილი იზრდება, ნალექი კი ხილვადობას აუარესებს. ამიტომ შეამცირე სიჩქარე და გაზარდე დისტანცია წინ მიმავლამდე. მოცურების საშიშროება განსაკუთრებით მაღალია წვიმის დასაწყისში, როცა გზის ზედაპირი ტალახიანდება; ასეთ დროს სიჩქარე მდორე დამუხრუჭებით შეამცირე. წყლის გუბეებში მართვა და დამუხრუჭება რთულდება და მოცურების ალბათობა დიდია, განსაკუთრებით გაცვეთილი საბურავებით ან მაღალი სიჩქარით.', NULL, NULL),
  (E'rule-30-road-train', E'ka', E'ავტომატარებელი და ავტოცისტერნა', E'მისაბმელის დიდი ინერციის გამო ავტომატარებელს მოცურების, დაკეცვისა და გადაყირავების დიდი საშიშროება აქვს; მას იწვევს გადამეტებული სიჩქარე, საჭის მკვეთრი მობრუნება და მკვეთრი დამუხრუჭება, განსაკუთრებით მოლიპულ აღმართზე. მოსახვევები მდორედ და ნელა გაიარე. დიდი მასის გამო სამუხრუჭე მანძილი მეტია — წინ მიმავალთან მსუბუქ ავტომობილზე მეტი დისტანცია დაიცავი. ავტომატარებლისა და შესახსრებული ავტობუსის დინამიკური დერეფანი ერთეულისაზე 10–40%-ით მეტია, ამიტომ გასწრებისას გვერდითი ინტერვალი 2 მ-ზე ნაკლები არ უნდა იყოს. ავტოცისტერნა მით მდგრადია, რაც დაბლაა სიმძიმის ცენტრი: ელიფსური პროფილი მრგვალზე მდგრადია, სავსე კი — ნახევრად სავსეზე, სადაც სითხე ირხევა.', NULL, NULL),
  (E'rule-30-skids-braking', E'ka', E'მოცურება და დამუხრუჭება', E'თუ მოცურება დამუხრუჭებამ გამოიწვია, შეწყვიტე დამუხრუჭება. მოლიპულ გზაზე საჭის მკვეთრი მობრუნებით გამოწვეული მოცურებისას სწრაფად, მაგრამ მდორედ მოაბრუნე საჭე მოცურების მხარეს, შემდეგ კი გაასწორე ტრაექტორია. მოსახვევში უკანა ხიდის მოცურებისას წინა წამყვანღერძიან ავტომობილში ოდნავ მოუმატე საწვავის მიწოდებას და საჭით გაასწორე მიმართულება, უკანა წამყვანღერძიანში კი ოდნავ შეამცირე მიწოდება და საჭე მოცურების მხარეს მოაბრუნე. მუხრუჭების ბლოკირების საწინააღმდეგო სისტემის არმქონე ავტომობილში სატერფულს პულსირებულად დააჭირე, რომ თვლები არ დაიბლოკოს. წყლის დაბრკოლების შემდეგ სველი ხუნდები მოძრაობისას გააშრე სატერფულზე მრავალჯერადი ხანმოკლე დაჭერით.', NULL, NULL),
  (E'rule-30-smooth-start', E'ka', E'დაძვრა და მდორე მართვა', E'აღმართზე დაძვრისას სადგომი მუხრუჭის ბერკეტი მოძრაობის დაწყებასთან ერთდროულად დაუშვი. მექანიკური გადაცემათა კოლოფით პირველ გადაცემაზე ხანგრძლივი გაქანებისას ძრავი მაღალ ბრუნებზე მუშაობს და საწვავის ხარჯი იზრდება. ყველაზე ნაკლებ საწვავს მდორე აჩქარება და მდორე შენელება ხარჯავს.', NULL, NULL),
  (E'rule-31-agreed-scheme', E'ka', E'შემთხვევის სქემა შეთანხმებით', E'თუ შემთხვევის შედეგად არავინ დაშავებულა, მძღოლებს შეთანხმებით შეუძლიათ წინასწარ შეადგინონ შემთხვევის სქემა და მოაწერონ ხელი. ამის შემდეგ ფაქტის გასაფორმებლად ისინი საპატრულო პოლიციის უახლოეს დანაყოფში მიდიან. ეს გზა მხოლოდ მაშინ მოქმედებს, როცა დაშავებული არ არის.', NULL, NULL),
  (E'rule-31-driver-duties', E'ka', E'მძღოლის მოვალეობა შემთხვევის შემდეგ', E'საგზაო-სატრანსპორტო შემთხვევის მონაწილე მძღოლი ვალდებულია დარწმუნდეს, რომ არავინ დაშავებულა ან დაღუპულა. მომხდარის შესახებ მან დაუყოვნებლივ უნდა აცნობოს შინაგან საქმეთა სამინისტროს სისტემაში შემავალ შესაბამის სამსახურს. სასწრაფო სამედიცინო დახმარების გამოძახებისას დისპეჩერს უთხარი ზუსტი ადგილი — ქუჩა, სახლის ნომერი და უახლოესი ორიენტირი, დაშავებულთა რაოდენობა, მათი სქესი და მიახლოებითი ასაკი, აქვთ თუ არა სასიცოცხლო ნიშნები და არის თუ არა ძლიერი სისხლდენა.', NULL, NULL),
  (E'rule-31-stay-or-leave', E'ka', E'როდის შეიძლება ადგილის დატოვება', E'შემთხვევის შემდეგ მძღოლი ადგილზე რჩება და უფლებამოსილი პირის მისვლას ელოდება. ადგილის დატოვება მხოლოდ მაშინ შეიძლება, თუ გადაუდებლად აუცილებელია, რომ თავად მივიდეს სამკურნალო დაწესებულებაში ან იქ დაშავებული გადაიყვანოს. ასეთ დროს სამკურნალო დაწესებულებაში უნდა განაცხადოს ვინაობა, წარადგინოს პირადობის დამადასტურებელი დოკუმენტი და სატრანსპორტო საშუალების სარეგისტრაციო დოკუმენტები, ხოლო თუ ეს შეუძლებელი არ არის, შემთხვევის ადგილზე დაბრუნდეს.', NULL, NULL),
  (E'rule-32-cold-engine', E'ka', E'ცივი ძრავი და მოკლე მანძილი', E'ცივი ძრავით დაძვრის შემდეგ მცირე ხანს დაბალ ბრუნებზე იმოძრავე, სანამ ძრავი გათბება. მოკლე მანძილზე ცივი ძრავით მოძრაობა მეტ საწვავს მოიხმარს, ამიტომ გარემოს დასაცავად ასეთ მგზავრობას მოერიდე. რამდენიმე ადგილას მისასვლელად მარშრუტები ერთში გააერთიანე.', NULL, NULL),
  (E'rule-32-engine-exhaust', E'ka', E'გამართული ძრავი და გამონაბოლქვი', E'გამონაბოლქვის შესამცირებლად და საწვავის დასაზოგად ძრავი გამართული უნდა იყოს. დროულად გამოცვალე ძრავის ჰაერის ფილტრი; დაბალი სიბლანტის ძრავის ზეთი საწვავის მოხმარებას ამცირებს. გამოსაბოლქვი სისტემის გაუმართაობა მავნე ნივთიერებების რაოდენობას ზრდის, კატალიზატორი კი შეიძლება დაზიანდეს, თუ ავტომობილს ბუქსირებით ქოქავ. შავი გამონაბოლქვი ბენზინის გაზრდილ ხარჯზე მიუთითებს. თუ მუქი კვამლი შეგამჩნიეს, დაუყოვნებლივ გაჩერდი, შეამოწმე ავტომობილი და გაუმართაობა აღმოფხვერი.', NULL, NULL),
  (E'rule-32-fewer-cars', E'ka', E'ნაკლები ავტომობილი გზაზე', E'საწვავს დაზოგავ და გამონაბოლქვს შეამცირებ, თუ შესაძლებლობისას საზოგადოებრივ ტრანსპორტს ან ველოსიპედს აირჩევ, ან ფეხით გაივლი. გარემოზე ზემოქმედებას ისიც ამცირებს, როცა ერთ ავტომობილს სხვებთან ერთად იზიარებ და ერთად მგზავრობთ.', NULL, NULL),
  (E'rule-32-idling', E'ka', E'ძრავის გათიშვა დგომისას', E'ჩართული ძრავით დგომა საწვავს უაზროდ წვავს და მავნე გამონაბოლქვს ზრდის. ძრავი გათიშე, როცა საცობში დიდხანს გიწევს დგომა, რკინიგზის გადასასვლელის დაკეტილ შლაგბაუმთან ელოდები ან ავტომობილს ტვირთავ და განტვირთავ. შუქნიშნის ნებადამრთველი სიგნალის მოლოდინში აქსელერატორზე პერიოდული დაჭერა საწვავის უმიზნო ხარჯვა და გარემოს დაბინძურებაა.', NULL, NULL),
  (E'rule-32-load-air', E'ka', E'ტვირთი, ჰაერის წინაღობა, კონდიციონერი', E'სახურავზე დამაგრებული არააუცილებელი ტვირთი, საბარგული თუ თხილამურების სამაგრი ჰაერის წინაღობას ზრდის, ამიტომ მოხსენი. ბარგი სახურავზე კი არა, საბარგულში მოათავსე. საწვავის დანახარჯს ამცირებს შესაბამისი აეროდინამიკური მოწყობილობა. მოხმარებას ზრდის მგზავრებისა და ტვირთის მატება, მნიშვნელოვნად კი ჰაერის გაგრილების სისტემა.', NULL, NULL),
  (E'rule-32-low-rpm', E'ka', E'დაბალი ბრუნები და გადაცემები', E'ძრავის ბრუნვის დაბალი სიჩქარით მოძრაობა საწვავს ზოგავს, მაღალი ბრუნები კი ხარჯსაც და მავნე ნივთიერებების გამოყოფასაც ზრდის. მაღალ გადაცემაზე რაც შეიძლება ადრე გადართე, დაბალზე კი რაც შეიძლება გვიან. თანაბარი სიჩქარით მოძრაობისას ხარჯს ამცირებს კრუიზკონტროლი, რომელიც სიჩქარეს თავად არეგულირებს. დაღმართზე აქსელერატორი ბოლომდე აუშვი და ისეთი გადაცემა აირჩიე, რომ მუხრუჭის სატერფულზე ძლიერად დაჭერა არ მოგიწიოს.', NULL, NULL),
  (E'rule-32-noise', E'ka', E'ხმაურის შემცირება', E'ხმაური მცირდება, როცა ძრავის დაბალი ბრუნვის სიჩქარით მართავ. მას ზრდის მაყუჩის გაუმართაობა და საწვავის არასრული წვით წარმოქმნილი აირების მაყუჩში მოხვედრა. დასახლებულ პუნქტში სიჩქარე გზის საფარის მდგომარეობის მიხედვით შეარჩიე. ხმოვანი სიგნალი მისალმებისთვის ნუ გამოიყენე: ეს ზედმეტი, ასაცილებელი ხმაურია.', NULL, NULL),
  (E'rule-32-oil-fuel-washing', E'ka', E'ზეთი, საწვავი და რეცხვა', E'აგრეგატიდან გამოჟონილი ზეთი გარემოს აბინძურებს. გამოყენებული ზეთები, საცხებ-საპოხი სითხეები და აკუმულატორები გადამამუშავებელ ცენტრებში ჩააბარე. საწვავის ჩასხმა შეწყვიტე, როგორც კი ავზის გავსებისას პისტოლეტი ავტომატურად გაითიშება. ავტომობილი ავტოსამრეცხაოში გარეცხე. ნიადაგში მოხვედრილი საავტომობილო ზეთი ნიადაგსა და გრუნტის წყლებს ხანგრძლივად აბინძურებს.', NULL, NULL),
  (E'rule-32-plan-ahead', E'ka', E'მოძრაობის წინასწარ დაგეგმვა', E'ხშირი დამუხრუჭება და აჩქარება საწვავის მოხმარებას ზრდის, ამიტომაა ქალაქში პიკის საათში ხარჯი მეტი. მოძრაობა წინასწარ დაგეგმე, რომ მოულოდნელ დამუხრუჭებასა და აჩქარებას აარიდო თავი. წითელზე გადასული შუქნიშნისკენ ინერციით იმოძრავე და დროულად დაამუხრუჭე. სწრაფი მოძრაობისას საბურავებისა და სამუხრუჭე ხუნდების ცვეთა მატულობს.', NULL, NULL),
  (E'rule-32-tyres', E'ka', E'საბურავები და წნევა', E'საბურავებში ჰაერის წნევა ინსტრუქციით განსაზღვრულ, რეკომენდებულ დონეზე შეინარჩუნე. დაბალი წნევა საწვავის მოხმარებას ზრდის, სწორი კი ხარჯსაც, გამონაბოლქვსაც და საბურავების ცვეთასაც ამცირებს. გარემოს დაცვას ხელს უწყობს დაბალი გორვის წინაღობის მქონე საბურავები. ზაფხულში ზამთრის საბურავებით მოძრაობა მათ ცვეთას ზრდის.', NULL, NULL),
  (E'sign-1.1', E'en', E'Level crossing with barrier', E'Warns of an approaching level crossing with a barrier. Outside built-up areas the sign is placed 150−300 metres before the start of the hazardous section, in built-up areas – 50–100 metres before it. Outside built-up areas the sign is repeated at a distance of at least 50 metres from the start of the hazardous section.', E'A level crossing with a barrier is ahead. In a built-up area the sign stands 50–100 metres before the hazard, outside one 150–300 metres before it. Outside built-up areas the sign is repeated at least 50 metres before the hazard.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/en/card_6bab6a630e.webm'),
  (E'sign-1.1', E'ka', E'რკინიგზის შლაგბაუმიანი გადასასვლელი', E'იძლევა გაფრთხილებას რკინიგზის შლაგბაუმიან გადასასვლელთან მიახლოების თაობაზე. ნიშანი დაუსახლებელ პუნქტში იდგმება სახიფათო მონაკვეთის დასაწყისამდე 150−300 მეტრ მანძილზე, დასახლებულ პუნქტში – 50–100 მეტრ მანძილზე. ნიშანი მეორდება დაუსახლებელ პუნქტში, სახიფათო მონაკვეთის დასაწყისიდან არანაკლებ 50 მეტრ მანძილზე.', E'წინ რკინიგზის გადასასვლელია შლაგბაუმით. დასახლებულ პუნქტში ნიშანი სახიფათო მონაკვეთამდე 50–100 მეტრით ადრე დგას, მის გარეთ კი — 150–300 მეტრით ადრე. დასახლებული პუნქტის გარეთ ნიშანი მეორდება, სახიფათო მონაკვეთამდე სულ მცირე 50 მეტრით ადრე.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ka/card_391f8e72b9.webm'),
  (E'sign-1.1', E'ru', E'Железнодорожный переезд со шлагбаумом', E'Предупреждает о приближении к железнодорожному переезду со шлагбаумом. Вне населённых пунктов знак устанавливается на расстоянии 150−300 метров до начала опасного участка, в населённых пунктах – на расстоянии 50–100 метров. Вне населённых пунктов знак повторяется на расстоянии не менее 50 метров от начала опасного участка.', E'Впереди железнодорожный переезд со шлагбаумом. В населённом пункте знак стоит за 50–100 метров до опасного участка, вне его — за 150–300 метров. Вне населённого пункта знак повторяется не менее чем за 50 метров до опасного участка.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ru/card_d78cc2f1ee.webm'),
  (E'sign-1.10', E'en', E'Opening bridge', E'Warns of an approaching opening bridge or ferry crossing. Outside built-up areas the sign is placed 150−300 metres before the start of the hazardous section, in built-up areas – 50–100 metres before it. Outside built-up areas the sign is repeated at a distance of at least 50 metres from the start of the hazardous section.', E'A drawbridge or a ferry crossing is ahead. In a built-up area the sign stands 50–100 metres before the hazard, outside one 150–300 metres before it. Outside built-up areas the sign is repeated at least 50 metres before the hazard.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/en/card_69d24e5654.webm'),
  (E'sign-1.10', E'ka', E'გასახსნელი ხიდი', E'იძლევა გაფრთხილებას გასახსნელ ხიდთან ან საბორნე გადასასვლელთან მიახლოების თაობაზე. ნიშანი დაუსახლებელ პუნქტში იდგმება სახიფათო მონაკვეთის დასაწყისამდე 150−300 მეტრ მანძილზე, დასახლებულ პუნქტში – 50–100 მეტრ მანძილზე. ნიშანი მეორდება დაუსახლებელ პუნქტში, სახიფათო მონაკვეთის დასაწყისიდან არანაკლებ 50 მეტრ მანძილზე.', E'წინ გასახსნელი ხიდი ან საბორნე გადასასვლელია. დასახლებულ პუნქტში ნიშანი სახიფათო მონაკვეთამდე 50–100 მეტრით ადრე დგას, მის გარეთ კი — 150–300 მეტრით ადრე. დასახლებული პუნქტის გარეთ ნიშანი მეორდება, სახიფათო მონაკვეთამდე სულ მცირე 50 მეტრით ადრე.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ka/card_5c03f27082.webm'),
  (E'sign-1.10', E'ru', E'Разводной мост', E'Предупреждает о приближении к разводному мосту или паромной переправе. Вне населённых пунктов знак устанавливается на расстоянии 150−300 метров до начала опасного участка, в населённых пунктах – на расстоянии 50–100 метров. Вне населённых пунктов знак повторяется на расстоянии не менее 50 метров от начала опасного участка.', E'Впереди разводной мост или паромная переправа. В населённом пункте знак стоит за 50–100 метров до опасного участка, вне его — за 150–300 метров. Вне населённого пункта знак повторяется не менее чем за 50 метров до опасного участка.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ru/card_b22209410c.webm'),
  (E'sign-1.11', E'en', E'Quayside or river bank', E'Exit onto an embankment or the shore of a reservoir. Outside built-up areas the sign is placed 150−300 metres before the start of the hazardous section, in built-up areas – 50–100 metres before it. Outside built-up areas the sign is repeated at a distance of at least 50 metres from the start of the hazardous section.', E'The road ahead runs along an embankment or the shore of a reservoir. In a built-up area the sign stands 50–100 metres before the hazard, outside one 150–300 metres before it. Outside built-up areas the sign is repeated at least 50 metres before the hazard.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/en/card_59e73ff24e.webm'),
  (E'sign-1.11', E'ka', E'სანაპიროზე გასასვლელი', E'სანაპიროზე ან წყალსაცავის ნაპირზე გასასვლელი. ნიშანი დაუსახლებელ პუნქტში იდგმება სახიფათო მონაკვეთის დასაწყისამდე 150−300 მეტრ მანძილზე, დასახლებულ პუნქტში – 50–100 მეტრ მანძილზე. ნიშანი მეორდება დაუსახლებელ პუნქტში, სახიფათო მონაკვეთის დასაწყისიდან არანაკლებ 50 მეტრ მანძილზე.', E'წინ გზა სანაპიროზე ან წყალსაცავის ნაპირზე გადის. დასახლებულ პუნქტში ნიშანი სახიფათო მონაკვეთამდე 50–100 მეტრით ადრე დგას, მის გარეთ კი — 150–300 მეტრით ადრე. დასახლებული პუნქტის გარეთ ნიშანი მეორდება, სახიფათო მონაკვეთამდე სულ მცირე 50 მეტრით ადრე.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ka/card_2f33cd93ac.webm'),
  (E'sign-1.11', E'ru', E'Выезд на набережную', E'Выезд на набережную или берег водоёма. Вне населённых пунктов знак устанавливается на расстоянии 150−300 метров до начала опасного участка, в населённых пунктах – на расстоянии 50–100 метров. Вне населённых пунктов знак повторяется на расстоянии не менее 50 метров от начала опасного участка.', E'Впереди дорога проходит по набережной или берегу водоёма. В населённом пункте знак стоит за 50–100 метров до опасного участка, вне его — за 150–300 метров. Вне населённого пункта знак повторяется не менее чем за 50 метров до опасного участка.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ru/card_74bf58d42f.webm'),
  (E'sign-1.12.1', E'en', E'Dangerous bend', E'A dangerous bend to the right of small radius or with limited visibility. Outside built-up areas the sign is placed 150−300 metres before the start of the hazardous section, in built-up areas – 50–100 metres before it.', E'A dangerous bend to the right is ahead — sharp or with limited visibility. In a built-up area the sign stands 50–100 metres before the hazard, outside one 150–300 metres before it.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/en/card_12cf20bbf9.webm'),
  (E'sign-1.12.1', E'ka', E'სახიფათო მოსახვევი', E'მცირერადიუსიანი ან შეზღუდული ხილვადობის მქონე გზის სახიფათო მოსახვევი მარჯვნივ. ნიშანი დაუსახლებელ პუნქტში იდგმება სახიფათო მონაკვეთის დასაწყისამდე 150−300 მეტრ მანძილზე, დასახლებულ პუნქტში – 50–100 მეტრ მანძილზე.', E'წინ მარჯვნივ სახიფათო მოსახვევია — მკვეთრი ან შეზღუდული ხილვადობით. დასახლებულ პუნქტში ნიშანი სახიფათო მონაკვეთამდე 50–100 მეტრით ადრე დგას, მის გარეთ კი — 150–300 მეტრით ადრე.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ka/card_07070a934e.webm'),
  (E'sign-1.12.1', E'ru', E'Опасный поворот', E'Опасный поворот дороги направо с малым радиусом или с ограниченной видимостью. Вне населённых пунктов знак устанавливается на расстоянии 150−300 метров до начала опасного участка, в населённых пунктах – на расстоянии 50–100 метров.', E'Впереди опасный поворот направо — крутой или с ограниченной видимостью. В населённом пункте знак стоит за 50–100 метров до опасного участка, вне его — за 150–300 метров.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ru/card_265e2c6974.webm'),
  (E'sign-1.12.2', E'en', E'Dangerous bend', E'A dangerous bend to the left of small radius or with limited visibility. Outside built-up areas the sign is placed 150−300 metres before the start of the hazardous section, in built-up areas – 50–100 metres before it.', E'A dangerous bend to the left is ahead — sharp or with limited visibility. In a built-up area the sign stands 50–100 metres before the hazard, outside one 150–300 metres before it.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/en/card_b0637da011.webm'),
  (E'sign-1.12.2', E'ka', E'სახიფათო მოსახვევი', E'მცირერადიუსიანი ან შეზღუდული ხილვადობის მქონე გზის სახიფათო მოსახვევი მარცხნივ. ნიშანი დაუსახლებელ პუნქტში იდგმება სახიფათო მონაკვეთის დასაწყისამდე 150−300 მეტრ მანძილზე, დასახლებულ პუნქტში – 50–100 მეტრ მანძილზე.', E'წინ მარცხნივ სახიფათო მოსახვევია — მკვეთრი ან შეზღუდული ხილვადობით. დასახლებულ პუნქტში ნიშანი სახიფათო მონაკვეთამდე 50–100 მეტრით ადრე დგას, მის გარეთ კი — 150–300 მეტრით ადრე.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ka/card_28cd83dbd3.webm'),
  (E'sign-1.12.2', E'ru', E'Опасный поворот', E'Опасный поворот дороги налево с малым радиусом или с ограниченной видимостью. Вне населённых пунктов знак устанавливается на расстоянии 150−300 метров до начала опасного участка, в населённых пунктах – на расстоянии 50–100 метров.', E'Впереди опасный поворот налево — крутой или с ограниченной видимостью. В населённом пункте знак стоит за 50–100 метров до опасного участка, вне его — за 150–300 метров.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ru/card_9c6d04c79c.webm'),
  (E'sign-1.13.1', E'en', E'Dangerous bends', E'A section of road with dangerous bends: the first bend to the right. Outside built-up areas the sign is placed 150−300 metres before the start of the hazardous section, in built-up areas – 50–100 metres before it.', E'Several dangerous bends are ahead, the first one to the right. In a built-up area the sign stands 50–100 metres before the hazard, outside one 150–300 metres before it.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/en/card_600355ed5b.webm'),
  (E'sign-1.13.1', E'ka', E'სახიფათო მოსახვევები', E'გზის მონაკვეთი სახიფათო მოსახვევებით: პირველი მოსახვევით მარჯვნივ. ნიშანი დაუსახლებელ პუნქტში იდგმება სახიფათო მონაკვეთის დასაწყისამდე 150−300 მეტრ მანძილზე, დასახლებულ პუნქტში – 50–100 მეტრ მანძილზე.', E'წინ რამდენიმე სახიფათო მოსახვევია, პირველი — მარჯვნივ. დასახლებულ პუნქტში ნიშანი სახიფათო მონაკვეთამდე 50–100 მეტრით ადრე დგას, მის გარეთ კი — 150–300 მეტრით ადრე.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ka/card_695815fa10.webm'),
  (E'sign-1.13.1', E'ru', E'Опасные повороты', E'Участок дороги с опасными поворотами: с первым поворотом направо. Вне населённых пунктов знак устанавливается на расстоянии 150−300 метров до начала опасного участка, в населённых пунктах – на расстоянии 50–100 метров.', E'Впереди несколько опасных поворотов, первый — направо. В населённом пункте знак стоит за 50–100 метров до опасного участка, вне его — за 150–300 метров.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ru/card_580029d019.webm'),
  (E'sign-1.13.2', E'en', E'Dangerous bends', E'A section of road with dangerous bends: the first bend to the left. Outside built-up areas the sign is placed 150−300 metres before the start of the hazardous section, in built-up areas – 50–100 metres before it.', E'Several dangerous bends are ahead, the first one to the left. In a built-up area the sign stands 50–100 metres before the hazard, outside one 150–300 metres before it.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/en/card_6aa3f85723.webm'),
  (E'sign-1.13.2', E'ka', E'სახიფათო მოსახვევები', E'გზის მონაკვეთი სახიფათო მოსახვევებით: პირველი მოსახვევით მარცხნივ. ნიშანი დაუსახლებელ პუნქტში იდგმება სახიფათო მონაკვეთის დასაწყისამდე 150−300 მეტრ მანძილზე, დასახლებულ პუნქტში – 50–100 მეტრ მანძილზე.', E'წინ რამდენიმე სახიფათო მოსახვევია, პირველი — მარცხნივ. დასახლებულ პუნქტში ნიშანი სახიფათო მონაკვეთამდე 50–100 მეტრით ადრე დგას, მის გარეთ კი — 150–300 მეტრით ადრე.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ka/card_f20e61e10c.webm'),
  (E'sign-1.13.2', E'ru', E'Опасные повороты', E'Участок дороги с опасными поворотами: с первым поворотом налево. Вне населённых пунктов знак устанавливается на расстоянии 150−300 метров до начала опасного участка, в населённых пунктах – на расстоянии 50–100 метров.', E'Впереди несколько опасных поворотов, первый — налево. В населённом пункте знак стоит за 50–100 метров до опасного участка, вне его — за 150–300 метров.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ru/card_fd0517720c.webm'),
  (E'sign-1.14', E'en', E'Steep descent', E'Warns of an approaching section of road with a steep descent. Outside built-up areas the sign is placed 150−300 metres before the start of the hazardous section, in built-up areas – 50–100 metres before it. If an ascent and a descent (or a descent and an ascent) follow each other, signs 1.14 and 1.15 may be placed without plate 8.1.1, respectively, immediately before the ascent and the descent;', E'A steep descent is ahead. In a built-up area the sign stands 50–100 metres before the hazard, outside one 150–300 metres before it. If a descent and a climb follow each other, signs 1.14 and 1.15 may stand right before them, without plate 8.1.1.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/en/card_de21ebfb1f.webm'),
  (E'sign-1.14', E'ka', E'ციცაბო დაღმართი', E'იძლევა გაფრთხილებას ციცაბოდაღმართიან გზის მონაკვეთთან მიახლოების თაობაზე. ნიშანი დაუსახლებელ პუნქტში იდგმება სახიფათო მონაკვეთის დასაწყისამდე 150−300 მეტრ მანძილზე, დასახლებულ პუნქტში – 50–100 მეტრ მანძილზე. თუ აღმართი და დაღმართი (ან დაღმართი და აღმართი) ერთმანეთს მიჰყვება, 8.1.1 დაფის გარეშე 1.14 და 1.15 ნიშნები შეიძლება დაიდგას შესაბამისად, უშუალოდ აღმართის და დაღმართის წინ;', E'წინ ციცაბო დაღმართია. დასახლებულ პუნქტში ნიშანი სახიფათო მონაკვეთამდე 50–100 მეტრით ადრე დგას, მის გარეთ კი — 150–300 მეტრით ადრე. თუ აღმართი და დაღმართი ერთმანეთს მოსდევს, 1.14 და 1.15 ნიშნები შეიძლება უშუალოდ დაღმართისა და აღმართის წინ დადგეს, 8.1.1 დაფის გარეშე.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ka/card_7cfa053bda.webm'),
  (E'sign-1.14', E'ru', E'Крутой спуск', E'Предупреждает о приближении к участку дороги с крутым спуском. Вне населённых пунктов знак устанавливается на расстоянии 150−300 метров до начала опасного участка, в населённых пунктах – на расстоянии 50–100 метров. Если подъём и спуск (или спуск и подъём) следуют друг за другом, знаки 1.14 и 1.15 могут устанавливаться без таблички 8.1.1 соответственно непосредственно перед подъёмом и спуском;', E'Впереди крутой спуск. В населённом пункте знак стоит за 50–100 метров до опасного участка, вне его — за 150–300 метров. Если спуск и подъём следуют друг за другом, знаки 1.14 и 1.15 могут стоять непосредственно перед ними, без таблички 8.1.1.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ru/card_4c61036089.webm'),
  (E'sign-1.15', E'en', E'Steep ascent', E'Warns of an approaching section of road with a steep ascent. Outside built-up areas the sign is placed 150−300 metres before the start of the hazardous section, in built-up areas – 50–100 metres before it. If an ascent and a descent (or a descent and an ascent) follow each other, signs 1.14 and 1.15 may be placed without plate 8.1.1, respectively, immediately before the ascent and the descent;', E'A steep climb is ahead. In a built-up area the sign stands 50–100 metres before the hazard, outside one 150–300 metres before it. If a descent and a climb follow each other, signs 1.14 and 1.15 may stand right before them, without plate 8.1.1.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/en/card_60c5a2bcc6.webm'),
  (E'sign-1.15', E'ka', E'ციცაბო აღმართი', E'იძლევა გაფრთხილებას ციცაბოაღმართიან გზის მონაკვეთთან მიახლოების თაობაზე. ნიშანი დაუსახლებელ პუნქტში იდგმება სახიფათო მონაკვეთის დასაწყისამდე 150−300 მეტრ მანძილზე, დასახლებულ პუნქტში – 50–100 მეტრ მანძილზე. თუ აღმართი და დაღმართი (ან დაღმართი და აღმართი) ერთმანეთს მიჰყვება, 8.1.1 დაფის გარეშე 1.14 და 1.15 ნიშნები შეიძლება დაიდგას შესაბამისად, უშუალოდ აღმართის და დაღმართის წინ;', E'წინ ციცაბო აღმართია. დასახლებულ პუნქტში ნიშანი სახიფათო მონაკვეთამდე 50–100 მეტრით ადრე დგას, მის გარეთ კი — 150–300 მეტრით ადრე. თუ აღმართი და დაღმართი ერთმანეთს მოსდევს, 1.14 და 1.15 ნიშნები შეიძლება უშუალოდ დაღმართისა და აღმართის წინ დადგეს, 8.1.1 დაფის გარეშე.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ka/card_5de7d0717d.webm'),
  (E'sign-1.15', E'ru', E'Крутой подъём', E'Предупреждает о приближении к участку дороги с крутым подъёмом. Вне населённых пунктов знак устанавливается на расстоянии 150−300 метров до начала опасного участка, в населённых пунктах – на расстоянии 50–100 метров. Если подъём и спуск (или спуск и подъём) следуют друг за другом, знаки 1.14 и 1.15 могут устанавливаться без таблички 8.1.1 соответственно непосредственно перед подъёмом и спуском;', E'Впереди крутой подъём. В населённом пункте знак стоит за 50–100 метров до опасного участка, вне его — за 150–300 метров. Если спуск и подъём следуют друг за другом, знаки 1.14 и 1.15 могут стоять непосредственно перед ними, без таблички 8.1.1.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ru/card_af6d3060cf.webm'),
  (E'sign-1.16', E'en', E'Slippery road', E'A slippery section of road on which the coefficient of tyre adhesion to the road surface is less than 0.4. Outside built-up areas the sign is placed 150−300 metres before the start of the hazardous section, in built-up areas – 50–100 metres before it.', E'The road ahead is slippery: tyres grip the road poorly (the grip coefficient is below 0.4). In a built-up area the sign stands 50–100 metres before the hazard, outside one 150–300 metres before it.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/en/card_71cf145a87.webm'),
  (E'sign-1.16', E'ka', E'მოლიპული გზა', E'გზის მოლიპული მონაკვეთი, რომელზედაც საბურავის გზის საფართან ჩაჭიდების კოეფიციენტი 0,4-ზე ნაკლებია. ნიშანი დაუსახლებელ პუნქტში იდგმება სახიფათო მონაკვეთის დასაწყისამდე 150−300 მეტრ მანძილზე, დასახლებულ პუნქტში – 50–100 მეტრ მანძილზე.', E'წინ მოლიპული გზაა: საბურავი გზას ცუდად ეჭიდება (ჩაჭიდების კოეფიციენტი 0,4-ზე ნაკლებია). დასახლებულ პუნქტში ნიშანი სახიფათო მონაკვეთამდე 50–100 მეტრით ადრე დგას, მის გარეთ კი — 150–300 მეტრით ადრე.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ka/card_eac872e625.webm'),
  (E'sign-1.16', E'ru', E'Скользкая дорога', E'Скользкий участок дороги, на котором коэффициент сцепления шин с дорожным покрытием меньше 0,4. Вне населённых пунктов знак устанавливается на расстоянии 150−300 метров до начала опасного участка, в населённых пунктах – на расстоянии 50–100 метров.', E'Впереди скользкая дорога: шины плохо сцепляются с покрытием (коэффициент сцепления меньше 0,4). В населённом пункте знак стоит за 50–100 метров до опасного участка, вне его — за 150–300 метров.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ru/card_5dd654f63c.webm'),
  (E'sign-1.17', E'en', E'Uneven road', E'A section of road whose carriageway is damaged: waves, potholes, uneven joints with a bridge, etc. Outside built-up areas the sign is placed 150−300 metres before the start of the hazardous section, in built-up areas – 50–100 metres before it.', E'The road surface ahead is damaged: waves, potholes or an uneven joint at a bridge. In a built-up area the sign stands 50–100 metres before the hazard, outside one 150–300 metres before it.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/en/card_a799af3777.webm'),
  (E'sign-1.17', E'ka', E'უსწორმასწორო გზა', E'გზის მონაკვეთი, რომლის სავალი ნაწილი დაზიანებულია ტალღოვანი, ღრანტეებიანი, ხიდთან უსწორმასწორო შეუღლებებით და ა. შ.. ნიშანი დაუსახლებელ პუნქტში იდგმება სახიფათო მონაკვეთის დასაწყისამდე 150−300 მეტრ მანძილზე, დასახლებულ პუნქტში – 50–100 მეტრ მანძილზე.', E'წინ სავალი ნაწილი დაზიანებულია: ტალღები, ორმოები ან ხიდთან უსწორმასწორო შეერთება. დასახლებულ პუნქტში ნიშანი სახიფათო მონაკვეთამდე 50–100 მეტრით ადრე დგას, მის გარეთ კი — 150–300 მეტრით ადრე.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ka/card_d5b5ae890c.webm'),
  (E'sign-1.17', E'ru', E'Неровная дорога', E'Участок дороги, проезжая часть которого имеет повреждения: волнистость, выбоины, неровные сопряжения с мостом и т. д. Вне населённых пунктов знак устанавливается на расстоянии 150−300 метров до начала опасного участка, в населённых пунктах – на расстоянии 50–100 метров.', E'Впереди неровная дорога: волны, выбоины или неровное сопряжение с мостом. В населённом пункте знак стоит за 50–100 метров до опасного участка, вне его — за 150–300 метров.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ru/card_6dba1cc99d.webm'),
  (E'sign-1.18', E'en', E'Speed bump', E'A section of road with an artificial bump installed to force vehicles to reduce speed. Outside built-up areas the sign is placed 150−300 metres before the start of the hazardous section, in built-up areas – 50–100 metres before it.', E'An artificial bump, built to make traffic slow down, is ahead. In a built-up area the sign stands 50–100 metres before the hazard, outside one 150–300 metres before it.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/en/card_5854c06a0e.webm'),
  (E'sign-1.18', E'ka', E'ხელოვნური უსწორმასწორობა', E'გზის მონაკვეთი, რომელზედაც მოწყობილია ხელოვნური უსწორმასწორობა სიჩქარის იძულებით შემცირებისათვის. ნიშანი დაუსახლებელ პუნქტში იდგმება სახიფათო მონაკვეთის დასაწყისამდე 150−300 მეტრ მანძილზე, დასახლებულ პუნქტში – 50–100 მეტრ მანძილზე.', E'წინ ხელოვნური უსწორმასწორობაა, რომელიც სიჩქარის შესამცირებლად არის მოწყობილი. დასახლებულ პუნქტში ნიშანი სახიფათო მონაკვეთამდე 50–100 მეტრით ადრე დგას, მის გარეთ კი — 150–300 მეტრით ადრე.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ka/card_fcb5636a6e.webm'),
  (E'sign-1.18', E'ru', E'Искусственная неровность', E'Участок дороги, на котором устроена искусственная неровность для принудительного снижения скорости. Вне населённых пунктов знак устанавливается на расстоянии 150−300 метров до начала опасного участка, в населённых пунктах – на расстоянии 50–100 метров.', E'Впереди искусственная неровность, устроенная для снижения скорости. В населённом пункте знак стоит за 50–100 метров до опасного участка, вне его — за 150–300 метров.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ru/card_c6347c2d7c.webm'),
  (E'sign-1.19', E'en', E'Loose chippings', E'A section of road where crushed stone, gravel, etc. may be thrown up from vehicle wheels. Outside built-up areas the sign is placed 150−300 metres before the start of the hazardous section, in built-up areas – 50–100 metres before it.', E'On the road section ahead, gravel or crushed stone may fly out from under wheels. In a built-up area the sign stands 50–100 metres before the hazard, outside one 150–300 metres before it.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/en/card_52df8d352c.webm'),
  (E'sign-1.19', E'ka', E'ქვის ასხლეტა', E'გზის მონაკვეთი, რომელზედაც შესაძლებელია სატრანსპორტო საშუალების თვლებიდან ღორღის, ხრეშის ასხლეტა და ა. შ.. ნიშანი დაუსახლებელ პუნქტში იდგმება სახიფათო მონაკვეთის დასაწყისამდე 150−300 მეტრ მანძილზე, დასახლებულ პუნქტში – 50–100 მეტრ მანძილზე.', E'წინ გზის მონაკვეთია, სადაც მანქანის თვლებიდან შეიძლება ღორღი ან ხრეში ასხლტეს. დასახლებულ პუნქტში ნიშანი სახიფათო მონაკვეთამდე 50–100 მეტრით ადრე დგას, მის გარეთ კი — 150–300 მეტრით ადრე.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ka/card_6a616a051e.webm'),
  (E'sign-1.19', E'ru', E'Выброс гравия', E'Участок дороги, на котором возможен выброс щебня, гравия и т. д. из-под колёс транспортных средств. Вне населённых пунктов знак устанавливается на расстоянии 150−300 метров до начала опасного участка, в населённых пунктах – на расстоянии 50–100 метров.', E'Впереди участок дороги, где из-под колёс может вылетать гравий или щебень. В населённом пункте знак стоит за 50–100 метров до опасного участка, вне его — за 150–300 метров.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ru/card_1e6626d4ec.webm'),
  (E'sign-1.2', E'en', E'Level crossing without barrier', E'Warns of an approaching level crossing without a barrier. Outside built-up areas the sign is placed 150−300 metres before the start of the hazardous section, in built-up areas – 50–100 metres before it. Outside built-up areas the sign is repeated at a distance of at least 50 metres from the start of the hazardous section.', E'A level crossing without a barrier is ahead. In a built-up area the sign stands 50–100 metres before the hazard, outside one 150–300 metres before it. Outside built-up areas the sign is repeated at least 50 metres before the hazard.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/en/card_706232c206.webm'),
  (E'sign-1.2', E'ka', E'რკინიგზის უშლაგბაუმო გადასასვლელი', E'იძლევა გაფრთხილებას რკინიგზის უშლაგბაუმო გადასასვლელთან მიახლოების თაობაზე. ნიშანი დაუსახლებელ პუნქტში იდგმება სახიფათო მონაკვეთის დასაწყისამდე 150−300 მეტრ მანძილზე, დასახლებულ პუნქტში – 50–100 მეტრ მანძილზე. ნიშანი მეორდება დაუსახლებელ პუნქტში, სახიფათო მონაკვეთის დასაწყისიდან არანაკლებ 50 მეტრ მანძილზე.', E'წინ რკინიგზის გადასასვლელია შლაგბაუმის გარეშე. დასახლებულ პუნქტში ნიშანი სახიფათო მონაკვეთამდე 50–100 მეტრით ადრე დგას, მის გარეთ კი — 150–300 მეტრით ადრე. დასახლებული პუნქტის გარეთ ნიშანი მეორდება, სახიფათო მონაკვეთამდე სულ მცირე 50 მეტრით ადრე.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ka/card_2c552d0c4a.webm'),
  (E'sign-1.2', E'ru', E'Железнодорожный переезд без шлагбаума', E'Предупреждает о приближении к железнодорожному переезду без шлагбаума. Вне населённых пунктов знак устанавливается на расстоянии 150−300 метров до начала опасного участка, в населённых пунктах – на расстоянии 50–100 метров. Вне населённых пунктов знак повторяется на расстоянии не менее 50 метров от начала опасного участка.', E'Впереди железнодорожный переезд без шлагбаума. В населённом пункте знак стоит за 50–100 метров до опасного участка, вне его — за 150–300 метров. Вне населённого пункта знак повторяется не менее чем за 50 метров до опасного участка.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ru/card_b98d250cc6.webm'),
  (E'sign-1.20', E'en', E'Dangerous verge', E'A section of road where the condition of the verge does not meet the applicable standards. Outside built-up areas the sign is placed 150−300 metres before the start of the hazardous section, in built-up areas – 50–100 metres before it.', E'A dangerous roadside is ahead: its condition does not meet the standards. In a built-up area the sign stands 50–100 metres before the hazard, outside one 150–300 metres before it.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/en/card_ab96329eb0.webm'),
  (E'sign-1.20', E'ka', E'სახიფათო გზისპირი', E'გზის მონაკვეთი, რომლის გზისპირის მდგომარეობა არ შეესაბამება არსებულ სტანდარტებს. ნიშანი დაუსახლებელ პუნქტში იდგმება სახიფათო მონაკვეთის დასაწყისამდე 150−300 მეტრ მანძილზე, დასახლებულ პუნქტში – 50–100 მეტრ მანძილზე.', E'წინ გზისპირი სახიფათოა: მისი მდგომარეობა სტანდარტებს არ შეესაბამება. დასახლებულ პუნქტში ნიშანი სახიფათო მონაკვეთამდე 50–100 მეტრით ადრე დგას, მის გარეთ კი — 150–300 მეტრით ადრე.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ka/card_29517fbf60.webm'),
  (E'sign-1.20', E'ru', E'Опасная обочина', E'Участок дороги, состояние обочины которого не соответствует действующим стандартам. Вне населённых пунктов знак устанавливается на расстоянии 150−300 метров до начала опасного участка, в населённых пунктах – на расстоянии 50–100 метров.', E'Впереди опасная обочина: её состояние не соответствует стандартам. В населённом пункте знак стоит за 50–100 метров до опасного участка, вне его — за 150–300 метров.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ru/card_dece9005cc.webm'),
  (E'sign-1.21.1', E'en', E'Road narrows', E'A section of road where the width of the carriageway narrows on both sides. Outside built-up areas the sign is placed 150−300 metres before the start of the hazardous section, in built-up areas – 50–100 metres before it.', E'The carriageway narrows on both sides ahead. In a built-up area the sign stands 50–100 metres before the hazard, outside one 150–300 metres before it.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/en/card_bfb648ef22.webm'),
  (E'sign-1.21.1', E'ka', E'გზის შევიწროება', E'გზის მონაკვეთი, რომლის სავალი ნაწილის სიგანე ვიწროვდება ორივე მხრიდან. ნიშანი დაუსახლებელ პუნქტში იდგმება სახიფათო მონაკვეთის დასაწყისამდე 150−300 მეტრ მანძილზე, დასახლებულ პუნქტში – 50–100 მეტრ მანძილზე.', E'წინ სავალი ნაწილი ორივე მხრიდან ვიწროვდება. დასახლებულ პუნქტში ნიშანი სახიფათო მონაკვეთამდე 50–100 მეტრით ადრე დგას, მის გარეთ კი — 150–300 მეტრით ადრე.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ka/card_d76a5c4513.webm'),
  (E'sign-1.21.1', E'ru', E'Сужение дороги', E'Участок дороги, ширина проезжей части которого сужается с обеих сторон. Вне населённых пунктов знак устанавливается на расстоянии 150−300 метров до начала опасного участка, в населённых пунктах – на расстоянии 50–100 метров.', E'Впереди сужение проезжей части с обеих сторон. В населённом пункте знак стоит за 50–100 метров до опасного участка, вне его — за 150–300 метров.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ru/card_b212970ad5.webm'),
  (E'sign-1.21.2', E'en', E'Road narrows', E'A section of road where the width of the carriageway narrows on the right. Outside built-up areas the sign is placed 150−300 metres before the start of the hazardous section, in built-up areas – 50–100 metres before it.', E'The carriageway narrows on the right ahead. In a built-up area the sign stands 50–100 metres before the hazard, outside one 150–300 metres before it.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/en/card_d3769c17bd.webm'),
  (E'sign-1.21.2', E'ka', E'გზის შევიწროება', E'გზის მონაკვეთი, რომლის სავალი ნაწილის სიგანე ვიწროვდება მარჯვნიდან. ნიშანი დაუსახლებელ პუნქტში იდგმება სახიფათო მონაკვეთის დასაწყისამდე 150−300 მეტრ მანძილზე, დასახლებულ პუნქტში – 50–100 მეტრ მანძილზე.', E'წინ სავალი ნაწილი მარჯვნიდან ვიწროვდება. დასახლებულ პუნქტში ნიშანი სახიფათო მონაკვეთამდე 50–100 მეტრით ადრე დგას, მის გარეთ კი — 150–300 მეტრით ადრე.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ka/card_20fb1d4a55.webm'),
  (E'sign-1.21.2', E'ru', E'Сужение дороги', E'Участок дороги, ширина проезжей части которого сужается справа. Вне населённых пунктов знак устанавливается на расстоянии 150−300 метров до начала опасного участка, в населённых пунктах – на расстоянии 50–100 метров.', E'Впереди сужение проезжей части справа. В населённом пункте знак стоит за 50–100 метров до опасного участка, вне его — за 150–300 метров.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ru/card_d6c457fdf4.webm'),
  (E'sign-1.21.3', E'en', E'Road narrows', E'A section of road where the width of the carriageway narrows 1.21.3 − on the left. Outside built-up areas the sign is placed 150−300 metres before the start of the hazardous section, in built-up areas – 50–100 metres before it.', E'The carriageway narrows on the left ahead. In a built-up area the sign stands 50–100 metres before the hazard, outside one 150–300 metres before it.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/en/card_01377449a7.webm'),
  (E'sign-1.21.3', E'ka', E'გზის შევიწროება', E'გზის მონაკვეთი, რომლის სავალი ნაწილის სიგანე ვიწროვდება 1.21.3 − მარცხნიდან. ნიშანი დაუსახლებელ პუნქტში იდგმება სახიფათო მონაკვეთის დასაწყისამდე 150−300 მეტრ მანძილზე, დასახლებულ პუნქტში – 50–100 მეტრ მანძილზე.', E'წინ სავალი ნაწილი მარცხნიდან ვიწროვდება. დასახლებულ პუნქტში ნიშანი სახიფათო მონაკვეთამდე 50–100 მეტრით ადრე დგას, მის გარეთ კი — 150–300 მეტრით ადრე.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ka/card_577f922cd3.webm'),
  (E'sign-1.21.3', E'ru', E'Сужение дороги', E'Участок дороги, ширина проезжей части которого сужается 1.21.3 − слева. Вне населённых пунктов знак устанавливается на расстоянии 150−300 метров до начала опасного участка, в населённых пунктах – на расстоянии 50–100 метров.', E'Впереди сужение проезжей части слева. В населённом пункте знак стоит за 50–100 метров до опасного участка, вне его — за 150–300 метров.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ru/card_5d0bce0104.webm'),
  (E'sign-1.22', E'en', E'Two-way traffic', E'The start of a section of road (carriageway) with two-way traffic, preceded by a section with one-way traffic. Outside built-up areas the sign is placed 150−300 metres before the start of the hazardous section, in built-up areas – 50–100 metres before it.', E'Two-way traffic begins ahead, after a one-way section. In a built-up area the sign stands 50–100 metres before the hazard, outside one 150–300 metres before it.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/en/card_aebebc77e7.webm'),
  (E'sign-1.22', E'ka', E'ორმხრივი მოძრაობა', E'გზის (სავალი ნაწილის) ორმხრივმოძრაობიანი მონაკვეთის დასაწყისი, რომელსაც წინ უსწრებდა უბანი ცალმხრივი მოძრაობით. ნიშანი დაუსახლებელ პუნქტში იდგმება სახიფათო მონაკვეთის დასაწყისამდე 150−300 მეტრ მანძილზე, დასახლებულ პუნქტში – 50–100 მეტრ მანძილზე.', E'წინ ორმხრივი მოძრაობა იწყება, მანამდე კი მოძრაობა ცალმხრივი იყო. დასახლებულ პუნქტში ნიშანი სახიფათო მონაკვეთამდე 50–100 მეტრით ადრე დგას, მის გარეთ კი — 150–300 მეტრით ადრე.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ka/card_c835a11fde.webm'),
  (E'sign-1.22', E'ru', E'Двустороннее движение', E'Начало участка дороги (проезжей части) с двусторонним движением, которому предшествовал участок с односторонним движением. Вне населённых пунктов знак устанавливается на расстоянии 150−300 метров до начала опасного участка, в населённых пунктах – на расстоянии 50–100 метров.', E'Впереди начинается двустороннее движение, а до этого движение было односторонним. В населённом пункте знак стоит за 50–100 метров до опасного участка, вне его — за 150–300 метров.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ru/card_216c9a505e.webm'),
  (E'sign-1.23', E'en', E'Pedestrian crossing', E'Warns of an approaching pedestrian crossing marked with signs 5.19.1 and 5.19.2 and/or markings 1.14.1–1.14.3. Outside built-up areas the sign is placed 150−300 metres before the start of the hazardous section, in built-up areas – 50–100 metres before it. Outside built-up areas the sign is repeated at a distance of at least 50 metres from the start of the hazardous section.', E'A pedestrian crossing marked with signs 5.19.1 and 5.19.2 and/or markings 1.14.1–1.14.3 is ahead. In a built-up area the sign stands 50–100 metres before the hazard, outside one 150–300 metres before it. Outside built-up areas the sign is repeated at least 50 metres before the hazard.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/en/card_3669badc81.webm'),
  (E'sign-1.23', E'ka', E'ქვეითთა გადასასვლელი', E'იძლევა გაფრთხილებას 5.19.1 და 5.19.2 ნიშნებით ან/და 1.14.1–1.14.3 მონიშვნებით აღნიშნულ ქვეითთა გადასასვლელთან მიახლოების თაობაზე. ნიშანი დაუსახლებელ პუნქტში იდგმება სახიფათო მონაკვეთის დასაწყისამდე 150−300 მეტრ მანძილზე, დასახლებულ პუნქტში – 50–100 მეტრ მანძილზე. ნიშანი მეორდება დაუსახლებელ პუნქტში, სახიფათო მონაკვეთის დასაწყისიდან არანაკლებ 50 მეტრ მანძილზე.', E'წინ ქვეითთა გადასასვლელია, რომელიც 5.19.1 და 5.19.2 ნიშნებით ან/და 1.14.1–1.14.3 მონიშვნით არის აღნიშნული. დასახლებულ პუნქტში ნიშანი სახიფათო მონაკვეთამდე 50–100 მეტრით ადრე დგას, მის გარეთ კი — 150–300 მეტრით ადრე. დასახლებული პუნქტის გარეთ ნიშანი მეორდება, სახიფათო მონაკვეთამდე სულ მცირე 50 მეტრით ადრე.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ka/card_4370c19c5c.webm'),
  (E'sign-1.23', E'ru', E'Пешеходный переход', E'Предупреждает о приближении к пешеходному переходу, обозначенному знаками 5.19.1 и 5.19.2 и/или разметкой 1.14.1–1.14.3. Вне населённых пунктов знак устанавливается на расстоянии 150−300 метров до начала опасного участка, в населённых пунктах – на расстоянии 50–100 метров. Вне населённых пунктов знак повторяется на расстоянии не менее 50 метров от начала опасного участка.', E'Впереди пешеходный переход, обозначенный знаками 5.19.1 и 5.19.2 и/или разметкой 1.14.1–1.14.3. В населённом пункте знак стоит за 50–100 метров до опасного участка, вне его — за 150–300 метров. Вне населённого пункта знак повторяется не менее чем за 50 метров до опасного участка.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ru/card_2f4e695e08.webm'),
  (E'sign-1.24', E'en', E'Children', E'Warns of a children''s facility next to the section of road, from which children are likely to appear on the carriageway. Outside built-up areas the sign is placed 150−300 metres before the start of the hazardous section, in built-up areas – 50–100 metres before it. In built-up and non-built-up areas the sign is repeated at a distance of at least 50 metres from the start of the hazardous section.', E'A children''s facility is nearby, so children may appear on the road. In a built-up area the sign stands 50–100 metres before the hazard, outside one 150–300 metres before it. The sign is repeated both in and outside built-up areas, at least 50 metres before the hazard.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/en/card_5fc252687c.webm'),
  (E'sign-1.24', E'ka', E'ბავშვები', E'იძლევა გაფრთხილებას გზის მონაკვეთთან საბავშვო დაწესებულების არსებობისთაობაზე, საიდანაც დიდია ბავშვების სავალ ნაწილზე გამოჩენის ალბათობა. ნიშანი დაუსახლებელ პუნქტში იდგმება სახიფათო მონაკვეთის დასაწყისამდე 150−300 მეტრ მანძილზე, დასახლებულ პუნქტში – 50–100 მეტრ მანძილზე. ნიშანი მეორდება დასახლებულ და დაუსახლებელ პუნქტებში, სახიფათო მონაკვეთის დასაწყისიდან არანაკლებ 50 მეტრ მანძილზე.', E'ახლოს საბავშვო დაწესებულებაა, ამიტომ სავალ ნაწილზე შეიძლება ბავშვები გამოჩნდნენ. დასახლებულ პუნქტში ნიშანი სახიფათო მონაკვეთამდე 50–100 მეტრით ადრე დგას, მის გარეთ კი — 150–300 მეტრით ადრე. ნიშანი მეორდება დასახლებულ პუნქტშიც და მის გარეთაც, სახიფათო მონაკვეთამდე სულ მცირე 50 მეტრით ადრე.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ka/card_3f3cebd6e4.webm'),
  (E'sign-1.24', E'ru', E'Дети', E'Предупреждает о наличии у участка дороги детского учреждения, из которого велика вероятность появления детей на проезжей части. Вне населённых пунктов знак устанавливается на расстоянии 150−300 метров до начала опасного участка, в населённых пунктах – на расстоянии 50–100 метров. В населённых пунктах и вне населённых пунктов знак повторяется на расстоянии не менее 50 метров от начала опасного участка.', E'Рядом детское учреждение, поэтому на проезжей части могут появиться дети. В населённом пункте знак стоит за 50–100 метров до опасного участка, вне его — за 150–300 метров. Знак повторяется и в населённом пункте, и вне его, не менее чем за 50 метров до опасного участка.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ru/card_527e029a4d.webm'),
  (E'sign-1.25', E'en', E'Cycle path crossing', E'Warns of an approaching place where a cycle path marked with sign 4.4 crosses the carriageway. Outside built-up areas the sign is placed 150−300 metres before the start of the hazardous section, in built-up areas – 50–100 metres before it.', E'A cycle path marked with sign 4.4 crosses the road ahead. In a built-up area the sign stands 50–100 metres before the hazard, outside one 150–300 metres before it.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/en/card_d25a85c337.webm'),
  (E'sign-1.25', E'ka', E'ველობილიკის გადაკვეთა', E'იძლევა გაფრთხილებას 4.4 ნიშნით აღნიშნული ველობილიკის სავალი ნაწილის გადაკვეთის ადგილთან მიახლოების თაობაზე. ნიშანი დაუსახლებელ პუნქტში იდგმება სახიფათო მონაკვეთის დასაწყისამდე 150−300 მეტრ მანძილზე, დასახლებულ პუნქტში – 50–100 მეტრ მანძილზე.', E'წინ გზას ველობილიკი კვეთს, რომელიც 4.4 ნიშნით არის აღნიშნული. დასახლებულ პუნქტში ნიშანი სახიფათო მონაკვეთამდე 50–100 მეტრით ადრე დგას, მის გარეთ კი — 150–300 მეტრით ადრე.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ka/card_212268bcd2.webm'),
  (E'sign-1.25', E'ru', E'Пересечение с велосипедной дорожкой', E'Предупреждает о приближении к месту пересечения проезжей части велосипедной дорожкой, обозначенной знаком 4.4. Вне населённых пунктов знак устанавливается на расстоянии 150−300 метров до начала опасного участка, в населённых пунктах – на расстоянии 50–100 метров.', E'Впереди дорогу пересекает велосипедная дорожка, обозначенная знаком 4.4. В населённом пункте знак стоит за 50–100 метров до опасного участка, вне его — за 150–300 метров.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ru/card_b8cac0abdc.webm'),
  (E'sign-1.26', E'en', E'Road works', E'A section of road where works are being carried out. Outside built-up areas the sign is placed 150−300 metres before the start of the hazardous section, in built-up areas – 50–100 metres before it. In built-up and non-built-up areas the sign is repeated at a distance of at least 50 metres from the start of the hazardous section. When short-term works are carried out on the carriageway, the sign is placed 10−15 metres from the place of the works, without plate 8.1.1.', E'Road works are going on ahead. In a built-up area the sign stands 50–100 metres before the hazard, outside one 150–300 metres before it. The sign is repeated both in and outside built-up areas, at least 50 metres before the hazard. For short-term works the sign stands 10–15 metres before the work site, without plate 8.1.1.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/en/card_84bc666982.webm'),
  (E'sign-1.26', E'ka', E'საგზაო სამუშაოები', E'გზის მონაკვეთი, რომლის ფარგლებშიც სამუშაოები მიმდინარეობს. ნიშანი დაუსახლებელ პუნქტში იდგმება სახიფათო მონაკვეთის დასაწყისამდე 150−300 მეტრ მანძილზე, დასახლებულ პუნქტში – 50–100 მეტრ მანძილზე. ნიშანი მეორდება დასახლებულ და დაუსახლებელ პუნქტებში, სახიფათო მონაკვეთის დასაწყისიდან არანაკლებ 50 მეტრ მანძილზე. ნიშანი სავალ ნაწილზე ხანმოკლე სამუშაოს ჩატარებისას იდგმება სამუშაოს ჩატარების ადგილიდან 10−15 მეტრ მანძილზე, 8.1.1 დაფის გარეშე.', E'წინ საგზაო სამუშაოები მიმდინარეობს. დასახლებულ პუნქტში ნიშანი სახიფათო მონაკვეთამდე 50–100 მეტრით ადრე დგას, მის გარეთ კი — 150–300 მეტრით ადრე. ნიშანი მეორდება დასახლებულ პუნქტშიც და მის გარეთაც, სახიფათო მონაკვეთამდე სულ მცირე 50 მეტრით ადრე. ხანმოკლე სამუშაოს დროს ნიშანი სამუშაო ადგილამდე 10–15 მეტრით ადრე დგას, 8.1.1 დაფის გარეშე.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ka/card_a5576e72fe.webm'),
  (E'sign-1.26', E'ru', E'Дорожные работы', E'Участок дороги, в пределах которого ведутся работы. Вне населённых пунктов знак устанавливается на расстоянии 150−300 метров до начала опасного участка, в населённых пунктах – на расстоянии 50–100 метров. В населённых пунктах и вне населённых пунктов знак повторяется на расстоянии не менее 50 метров от начала опасного участка. При проведении кратковременных работ на проезжей части знак устанавливается на расстоянии 10−15 метров от места проведения работ, без таблички 8.1.1.', E'Впереди ведутся дорожные работы. В населённом пункте знак стоит за 50–100 метров до опасного участка, вне его — за 150–300 метров. Знак повторяется и в населённом пункте, и вне его, не менее чем за 50 метров до опасного участка. При краткосрочных работах знак стоит за 10–15 метров до места работ, без таблички 8.1.1.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ru/card_c27d8dad62.webm'),
  (E'sign-1.27', E'en', E'Cattle', E'A section of road passing a livestock (cattle) shelter, a farm and/or a place where livestock (cattle) is regularly driven across, where animals may appear on the carriageway. Outside built-up areas the sign is placed 150−300 metres before the start of the hazardous section, in built-up areas – 50–100 metres before it.', E'The road ahead passes a farm or a livestock crossing, so animals may appear on the road. In a built-up area the sign stands 50–100 metres before the hazard, outside one 150–300 metres before it.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/en/card_f4c8b7bec8.webm'),
  (E'sign-1.27', E'ka', E'პირუტყვის გადარეკვა', E'გზის მონაკვეთი, რომელიც გადის პირუტყვის (საქონლის) სადგომთან, ფერმასთან ან/და პირუტყვის (საქონლის) მუდმივი გადარეკვის ადგილთან, სადაც მოსალოდნელია მისი სავალ ნაწილზე გამოჩენა. ნიშანი დაუსახლებელ პუნქტში იდგმება სახიფათო მონაკვეთის დასაწყისამდე 150−300 მეტრ მანძილზე, დასახლებულ პუნქტში – 50–100 მეტრ მანძილზე.', E'წინ გზა ფერმასთან ან პირუტყვის გადასარეკ ადგილთან გადის, ამიტომ სავალ ნაწილზე შეიძლება პირუტყვი გამოჩნდეს. დასახლებულ პუნქტში ნიშანი სახიფათო მონაკვეთამდე 50–100 მეტრით ადრე დგას, მის გარეთ კი — 150–300 მეტრით ადრე.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ka/card_2c8830b572.webm'),
  (E'sign-1.27', E'ru', E'Перегон скота', E'Участок дороги, проходящий мимо стоянки скота, фермы и/или места постоянного перегона скота, где возможно его появление на проезжей части. Вне населённых пунктов знак устанавливается на расстоянии 150−300 метров до начала опасного участка, в населённых пунктах – на расстоянии 50–100 метров.', E'Впереди дорога проходит рядом с фермой или местом перегона скота, поэтому на проезжей части может появиться скот. В населённом пункте знак стоит за 50–100 метров до опасного участка, вне его — за 150–300 метров.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ru/card_43a2cbad9a.webm'),
  (E'sign-1.28', E'en', E'Wild animals', E'A section of road passing a nature reserve, a hunting ground or a forest, or another area where wild animals may appear. Outside built-up areas the sign is placed 150−300 metres before the start of the hazardous section, in built-up areas – 50–100 metres before it.', E'The road ahead passes a nature reserve, hunting ground or forest where wild animals may appear. In a built-up area the sign stands 50–100 metres before the hazard, outside one 150–300 metres before it.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/en/card_5681d8cc25.webm'),
  (E'sign-1.28', E'ka', E'გარეული ცხოველები', E'ნაკრძალთან, სანადირო მეურნეობასთან, ტყის მასივთან გამავალი გზის მონაკვეთიან სხვა უბანი, სადაც მოსალოდნელია გარეული ცხოველების გამოჩენა. ნიშანი დაუსახლებელ პუნქტში იდგმება სახიფათო მონაკვეთის დასაწყისამდე 150−300 მეტრ მანძილზე, დასახლებულ პუნქტში – 50–100 მეტრ მანძილზე.', E'წინ გზა ნაკრძალთან, სანადირო მეურნეობასთან ან ტყესთან გადის, სადაც შეიძლება გარეული ცხოველები გამოჩნდნენ. დასახლებულ პუნქტში ნიშანი სახიფათო მონაკვეთამდე 50–100 მეტრით ადრე დგას, მის გარეთ კი — 150–300 მეტრით ადრე.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ka/card_1178bf2a40.webm'),
  (E'sign-1.28', E'ru', E'Дикие животные', E'Участок дороги, проходящий мимо заповедника, охотничьего хозяйства, лесного массива, или иной участок, где возможно появление диких животных. Вне населённых пунктов знак устанавливается на расстоянии 150−300 метров до начала опасного участка, в населённых пунктах – на расстоянии 50–100 метров.', E'Впереди дорога проходит рядом с заповедником, охотничьим хозяйством или лесом, где могут появиться дикие животные. В населённом пункте знак стоит за 50–100 метров до опасного участка, вне его — за 150–300 метров.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ru/card_12dcda58c6.webm'),
  (E'sign-1.29', E'en', E'Falling rocks', E'A section of road whose carriageway is not protected against avalanches, landslides or falling rocks. Outside built-up areas the sign is placed 150−300 metres before the start of the hazardous section, in built-up areas – 50–100 metres before it.', E'The road section ahead is not protected from avalanches, landslides or falling rocks. In a built-up area the sign stands 50–100 metres before the hazard, outside one 150–300 metres before it.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/en/card_60b07e9085.webm'),
  (E'sign-1.29', E'ka', E'ქვის ცვენა', E'გზის მონაკვეთი, რომლის სავალი ნაწილი არ არის დაცული ზვავისაგან, მეწყრისაგან ანქვის ცვენისაგან. ნიშანი დაუსახლებელ პუნქტში იდგმება სახიფათო მონაკვეთის დასაწყისამდე 150−300 მეტრ მანძილზე, დასახლებულ პუნქტში – 50–100 მეტრ მანძილზე.', E'წინ გზის მონაკვეთი დაცული არ არის ზვავისგან, მეწყრისგან ან ქვის ცვენისგან. დასახლებულ პუნქტში ნიშანი სახიფათო მონაკვეთამდე 50–100 მეტრით ადრე დგას, მის გარეთ კი — 150–300 მეტრით ადრე.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ka/card_7c6c8b22c9.webm'),
  (E'sign-1.29', E'ru', E'Падение камней', E'Участок дороги, проезжая часть которого не защищена от лавин, оползней или падения камней. Вне населённых пунктов знак устанавливается на расстоянии 150−300 метров до начала опасного участка, в населённых пунктах – на расстоянии 50–100 метров.', E'Впереди участок дороги, не защищённый от лавин, оползней или камнепада. В населённом пункте знак стоит за 50–100 метров до опасного участка, вне его — за 150–300 метров.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ru/card_81ad5b0a29.webm'),
  (E'sign-1.3.1', E'en', E'Single-track railway', E'Warns of an approaching level crossing without a barrier on a single-track railway. Placed immediately before the level crossing.', E'A single-track level crossing without a barrier is ahead. The sign stands right before the crossing.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/en/card_ec2903120c.webm'),
  (E'sign-1.3.1', E'ka', E'ერთლიანდაგიანი რკინიგზა', E'იძლევა გაფრთხილებას ერთლიანდაგიანი რკინიგზის უშლაგბაუმო გადასასვლელთან მიახლოების თაობაზე. იდგმება უშუალოდ რკინიგზის გადასასვლელის წინ.', E'წინ ერთლიანდაგიანი რკინიგზის გადასასვლელია შლაგბაუმის გარეშე. ნიშანი უშუალოდ გადასასვლელის წინ დგას.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ka/card_11634c042f.webm'),
  (E'sign-1.3.1', E'ru', E'Однопутная железная дорога', E'Предупреждает о приближении к железнодорожному переезду без шлагбаума через однопутную железную дорогу. Устанавливается непосредственно перед железнодорожным переездом.', E'Впереди однопутный железнодорожный переезд без шлагбаума. Знак стоит непосредственно перед переездом.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ru/card_47ac196ed0.webm'),
  (E'sign-1.3.2', E'en', E'Multi-track railway', E'Warns of an approaching level crossing without a barrier on a railway with two or more tracks. Placed immediately before the level crossing.', E'A level crossing without a barrier, with two or more tracks, is ahead. The sign stands right before the crossing.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/en/card_119a16ae21.webm'),
  (E'sign-1.3.2', E'ka', E'მრავალლიანდაგიანი რკინიგზა', E'იძლევა გაფრთხილებას ორი ან ორზე მეტი ლიანდაგის მქონე რკინიგზის უშლაგბაუმო გადასასვლელთან მიახლოების თაობაზე. იდგმება უშუალოდ რკინიგზის გადასასვლელის წინ.', E'წინ რკინიგზის გადასასვლელია შლაგბაუმის გარეშე, სადაც ორი ან მეტი ლიანდაგია. ნიშანი უშუალოდ გადასასვლელის წინ დგას.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ka/card_b3417ae544.webm'),
  (E'sign-1.3.2', E'ru', E'Многопутная железная дорога', E'Предупреждает о приближении к железнодорожному переезду без шлагбаума через железную дорогу с двумя и более путями. Устанавливается непосредственно перед железнодорожным переездом.', E'Впереди железнодорожный переезд без шлагбаума с двумя и более путями. Знак стоит непосредственно перед переездом.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ru/card_03662e375a.webm'),
  (E'sign-1.30', E'en', E'Side wind', E'A section of road where a strong side wind may occur. Outside built-up areas the sign is placed 150−300 metres before the start of the hazardous section, in built-up areas – 50–100 metres before it.', E'A strong side wind may blow on the road section ahead. In a built-up area the sign stands 50–100 metres before the hazard, outside one 150–300 metres before it.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/en/card_0e9583da67.webm'),
  (E'sign-1.30', E'ka', E'გვერდითი ქარი', E'გზის მონაკვეთი, რომელზედაც შეიძლება ძლიერი გვერდითი ქარი ამოვარდეს. ნიშანი დაუსახლებელ პუნქტში იდგმება სახიფათო მონაკვეთის დასაწყისამდე 150−300 მეტრ მანძილზე, დასახლებულ პუნქტში – 50–100 მეტრ მანძილზე.', E'წინ გზის მონაკვეთზე შეიძლება ძლიერი გვერდითი ქარი ამოვარდეს. დასახლებულ პუნქტში ნიშანი სახიფათო მონაკვეთამდე 50–100 მეტრით ადრე დგას, მის გარეთ კი — 150–300 მეტრით ადრე.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ka/card_4e4ee28d39.webm'),
  (E'sign-1.30', E'ru', E'Боковой ветер', E'Участок дороги, на котором возможен сильный боковой ветер. Вне населённых пунктов знак устанавливается на расстоянии 150−300 метров до начала опасного участка, в населённых пунктах – на расстоянии 50–100 метров.', E'Впереди на участке дороги возможен сильный боковой ветер. В населённом пункте знак стоит за 50–100 метров до опасного участка, вне его — за 150–300 метров.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ru/card_936f04e6f2.webm'),
  (E'sign-1.31', E'en', E'Low-flying aircraft', E'A section of road near an aerodrome over which aeroplanes or helicopters fly at low altitude. Outside built-up areas the sign is placed 150−300 metres before the start of the hazardous section, in built-up areas – 50–100 metres before it.', E'The road ahead passes close to an airfield, where planes or helicopters fly low. In a built-up area the sign stands 50–100 metres before the hazard, outside one 150–300 metres before it.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/en/card_470b9cfea9.webm'),
  (E'sign-1.31', E'ka', E'დაბლამფრენი თვითმფრინავი', E'აეროდრომთან ახლოს გამავალი გზის მონაკვეთი, რომელზედაც თვითმფრინავები ან ვერტმფრენები დაბალ სიმაღლეზე დაფრინავენ. ნიშანი დაუსახლებელ პუნქტში იდგმება სახიფათო მონაკვეთის დასაწყისამდე 150−300 მეტრ მანძილზე, დასახლებულ პუნქტში – 50–100 მეტრ მანძილზე.', E'წინ გზა აეროდრომთან ახლოს გადის, სადაც თვითმფრინავები ან ვერტმფრენები დაბალ სიმაღლეზე დაფრინავენ. დასახლებულ პუნქტში ნიშანი სახიფათო მონაკვეთამდე 50–100 მეტრით ადრე დგას, მის გარეთ კი — 150–300 მეტრით ადრე.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ka/card_38a7ea6c3a.webm'),
  (E'sign-1.31', E'ru', E'Низколетящие самолёты', E'Участок дороги, проходящий вблизи аэродрома, над которым самолёты или вертолёты летают на малой высоте. Вне населённых пунктов знак устанавливается на расстоянии 150−300 метров до начала опасного участка, в населённых пунктах – на расстоянии 50–100 метров.', E'Впереди дорога проходит рядом с аэродромом, где самолёты или вертолёты летят на малой высоте. В населённом пункте знак стоит за 50–100 метров до опасного участка, вне его — за 150–300 метров.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ru/card_e5e07f352f.webm'),
  (E'sign-1.32', E'en', E'Tunnel', E'A tunnel without artificial lighting, or whose entrance portal is visible for less than 150 metres due to the terrain. Outside built-up areas the sign is placed 150−300 metres before the start of the hazardous section, in built-up areas – 50–100 metres before it.', E'A tunnel is ahead that is not lit, or whose entrance, because of the terrain, can be seen from less than 150 metres. In a built-up area the sign stands 50–100 metres before the hazard, outside one 150–300 metres before it.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/en/card_b39b5d2b12.webm'),
  (E'sign-1.32', E'ka', E'გვირაბი', E'გვირაბი, რომელშიც არ არსებობს ხელოვნური განათება ან რომლის შესასვლელი პორტალის ხილვადობა ადგილის რელიეფის გამო 150 მეტრზე ნაკლებია. ნიშანი დაუსახლებელ პუნქტში იდგმება სახიფათო მონაკვეთის დასაწყისამდე 150−300 მეტრ მანძილზე, დასახლებულ პუნქტში – 50–100 მეტრ მანძილზე.', E'წინ გვირაბია, რომელიც არ არის განათებული, ან რომლის შესასვლელიც რელიეფის გამო 150 მეტრზე ნაკლები მანძილიდან ჩანს. დასახლებულ პუნქტში ნიშანი სახიფათო მონაკვეთამდე 50–100 მეტრით ადრე დგას, მის გარეთ კი — 150–300 მეტრით ადრე.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ka/card_4795a693a3.webm'),
  (E'sign-1.32', E'ru', E'Тоннель', E'Тоннель, в котором отсутствует искусственное освещение или видимость въездного портала которого из-за рельефа местности составляет менее 150 метров. Вне населённых пунктов знак устанавливается на расстоянии 150−300 метров до начала опасного участка, в населённых пунктах – на расстоянии 50–100 метров.', E'Впереди тоннель без освещения или тоннель, въезд в который из-за рельефа виден менее чем за 150 метров. В населённом пункте знак стоит за 50–100 метров до опасного участка, вне его — за 150–300 метров.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ru/card_67c549ab4c.webm'),
  (E'sign-1.33', E'en', E'Road blocked', E'A section of road that is temporarily blocked. Outside built-up areas the sign is placed 150−300 metres before the start of the hazardous section, in built-up areas – 50–100 metres before it.', E'The road section ahead is temporarily blocked. In a built-up area the sign stands 50–100 metres before the hazard, outside one 150–300 metres before it.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/en/card_e9d4ebbe82.webm'),
  (E'sign-1.33', E'ka', E'ხერგილი', E'გზის მონაკვეთი, რომელიც დროებით ჩახერგილია. ნიშანი დაუსახლებელ პუნქტში იდგმება სახიფათო მონაკვეთის დასაწყისამდე 150−300 მეტრ მანძილზე, დასახლებულ პუნქტში – 50–100 მეტრ მანძილზე.', E'წინ გზის მონაკვეთი დროებით ჩახერგილია. დასახლებულ პუნქტში ნიშანი სახიფათო მონაკვეთამდე 50–100 მეტრით ადრე დგას, მის გარეთ კი — 150–300 მეტრით ადრე.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ka/card_0686304d53.webm'),
  (E'sign-1.33', E'ru', E'Затор', E'Участок дороги, который временно перекрыт. Вне населённых пунктов знак устанавливается на расстоянии 150−300 метров до начала опасного участка, в населённых пунктах – на расстоянии 50–100 метров.', E'Впереди участок дороги временно перекрыт. В населённом пункте знак стоит за 50–100 метров до опасного участка, вне его — за 150–300 метров.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ru/card_7988a93e80.webm'),
  (E'sign-1.34', E'en', E'Other dangers', E'A section of road where a danger may arise that is not covered by other warning signs. Outside built-up areas the sign is placed 150−300 metres before the start of the hazardous section, in built-up areas – 50–100 metres before it.', E'Warns of a danger that no other warning sign covers. In a built-up area the sign stands 50–100 metres before the hazard, outside one 150–300 metres before it.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/en/card_895564c0bc.webm'),
  (E'sign-1.34', E'ka', E'სხვა საფრთხეები', E'გზის მონაკვეთი, რომელზედაც შეიძლება წარმოიშვას ისეთი საფრთხე, რომელიც არ არის განსაზღვრული სხვა მაფრთხილებელი ნიშნებით. ნიშანი დაუსახლებელ პუნქტში იდგმება სახიფათო მონაკვეთის დასაწყისამდე 150−300 მეტრ მანძილზე, დასახლებულ პუნქტში – 50–100 მეტრ მანძილზე.', E'აფრთხილებს ისეთ საფრთხეზე, რომელსაც სხვა მაფრთხილებელი ნიშანი არ აღნიშნავს. დასახლებულ პუნქტში ნიშანი სახიფათო მონაკვეთამდე 50–100 მეტრით ადრე დგას, მის გარეთ კი — 150–300 მეტრით ადრე.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ka/card_da530d75b6.webm'),
  (E'sign-1.34', E'ru', E'Прочие опасности', E'Участок дороги, на котором может возникнуть опасность, не предусмотренная другими предупреждающими знаками. Вне населённых пунктов знак устанавливается на расстоянии 150−300 метров до начала опасного участка, в населённых пунктах – на расстоянии 50–100 метров.', E'Предупреждает об опасности, для которой нет другого предупреждающего знака. В населённом пункте знак стоит за 50–100 метров до опасного участка, вне его — за 150–300 метров.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ru/card_e557515316.webm'),
  (E'sign-1.35.1–1.35.6', E'en', E'Direction of bend', E'Indicates the direction of travel on a small-radius curve of the road with limited visibility (1.35.1−1.35.3 − to the right, 1.35.4−1.35.6 − to the left) or the corresponding direction for bypassing a road works site.', E'Shows which way a sharp bend with limited visibility turns: 1.35.1–1.35.3 to the right, 1.35.4–1.35.6 to the left. They also show the way around road works.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/en/card_1429632926.webm'),
  (E'sign-1.35.1–1.35.6', E'ka', E'მოხვევის მიმართულება', E'მიუთითებს შეზღუდული ხილვადობის მქონე მცირე რადიუსიან გზის მრუდეზე მოძრაობის მიმართულებას (1.35.1−1.35.3 − მარჯვნივ, 1.35.4−1.35.6 − მარცხნივ) ან საგზაო სამუშაოების მიმდინარეობის ადგილის შემოვლის შესაბამის მიმართულებას.', E'გიჩვენებს, რომელ მხარეს უხვევს მკვეთრი მოსახვევი შეზღუდული ხილვადობით: 1.35.1–1.35.3 — მარჯვნივ, 1.35.4–1.35.6 — მარცხნივ. ასევე გამოიყენება საგზაო სამუშაოების შემოსავლელი მიმართულების საჩვენებლად.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ka/card_92f2c1e684.webm'),
  (E'sign-1.35.1–1.35.6', E'ru', E'Направление поворота', E'Указывает направление движения на закруглении дороги малого радиуса с ограниченной видимостью (1.35.1−1.35.3 − направо, 1.35.4−1.35.6 − налево) или соответствующее направление объезда места проведения дорожных работ.', E'Показывают, куда поворачивает крутой поворот с ограниченной видимостью: 1.35.1–1.35.3 — направо, 1.35.4–1.35.6 — налево. Также показывают направление объезда дорожных работ.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ru/card_dc6a8ba216.webm'),
  (E'sign-1.36.1–1.36.2', E'en', E'Direction of bend', E'Indicates the direction of travel at a “T”-junction or a road fork (to the right and to the left) or the corresponding direction for bypassing a road works site.', E'Shows the direction of travel at a T-junction or a fork in the road — to the right and to the left. It also shows the way around road works.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/en/card_f61859a42f.webm'),
  (E'sign-1.36.1–1.36.2', E'ka', E'მოხვევის მიმართულება', E'მიუთითებს „T“-სებურ გზაჯვარედინზე ან გზების განშტოებაზე მოძრაობის მიმართულებას (მარჯვნივ და მარცხნივ)ან საგზაო სამუშაოების მიმდინარეობის ადგილის შემოვლის შესაბამის მიმართულებას.', E'გიჩვენებს მოძრაობის მიმართულებას „T“-სებურ გზაჯვარედინზე ან გზის განშტოებაზე — მარჯვნივ და მარცხნივ. ასევე გამოიყენება საგზაო სამუშაოების შემოსავლელი მიმართულების საჩვენებლად.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ka/card_4d5ae36202.webm'),
  (E'sign-1.36.1–1.36.2', E'ru', E'Направление поворота', E'Указывает направление движения на Т-образном перекрёстке или разветвлении дорог (направо и налево) или соответствующее направление объезда места проведения дорожных работ.', E'Показывает направление движения на Т-образном перекрёстке или развилке — направо и налево. Также показывает направление объезда дорожных работ.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ru/card_d4cba36436.webm'),
  (E'sign-1.4.1–1.4.6', E'en', E'Approaching a level crossing', E'Additionally warns the driver outside built-up areas of an approaching level crossing.\nSigns 1.4.1−1.4.3 are placed on the right-hand side of the road, and signs 1.4.4−1.4.6 − on the left-hand side of the road. Signs 1.4.1 and 1.4.4 are placed, in the direction of travel, together with the main and the repeated sign 1.1 or 1.2, signs 1.4.3 and 1.4.6 − in the direction of travel, together with the repeated sign 1.1 or 1.2, and signs 1.4.2 and 1.4.5 − on their own, at an equal distance between the main and the repeated sign 1.1 or 1.2.', E'Outside built-up areas these signs give an extra warning that you are approaching a level crossing. Signs 1.4.1–1.4.3 stand on the right side of the road, 1.4.4–1.4.6 on the left. Signs 1.4.1 and 1.4.4 stand with the first sign 1.1 or 1.2, 1.4.3 and 1.4.6 with the repeated sign 1.1 or 1.2, and 1.4.2 and 1.4.5 on their own, halfway between them.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/en/card_d1fd4c8be9.webm'),
  (E'sign-1.4.1–1.4.6', E'ka', E'რკინიგზის გადასასვლელთან მიახლოება', E'დამატებით აფრთხილებს მძღოლს დაუსახლებელ პუნქტში რკინიგზის გადასასვლელთან მიახლოების თაობაზე.\n1.4.1−1.4.3 ნიშნები იდგმება გზის მარჯვენა მხარეს, ხოლო 1.4.4−1.4.6 ნიშნები − გზის მარცხენა მხარეს. 1.4.1 და 1.4.4 ნიშნები იდგმება მოძრაობის მიმართულებით ძირითად და განმეორებით 1.1 ან 1.2 ნიშანთან ერთად, 1.4.3 და 1.4.6 ნიშნები − მოძრაობის მიმართულებით განმეორებით 1.1 ან 1.2 ნიშანთან ერთად, ხოლო 1.4.2 და 1.4.5 ნიშნები − დამოუკიდებლად, თანაბარ დაშორებაზე ძირითად და განმეორებით 1.1 ან 1.2 ნიშანს შორის.', E'დასახლებული პუნქტის გარეთ დამატებით აფრთხილებს, რომ რკინიგზის გადასასვლელს უახლოვდები. 1.4.1–1.4.3 ნიშნები გზის მარჯვენა მხარეს დგას, 1.4.4–1.4.6 კი — მარცხენა მხარეს. 1.4.1 და 1.4.4 ნიშნები პირველ 1.1 ან 1.2 ნიშანთან დგას, 1.4.3 და 1.4.6 — განმეორებით 1.1 ან 1.2 ნიშანთან, 1.4.2 და 1.4.5 კი — ცალკე, მათ შუა, თანაბარ მანძილზე.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ka/card_8bb7bb77f9.webm'),
  (E'sign-1.4.1–1.4.6', E'ru', E'Приближение к железнодорожному переезду', E'Дополнительно предупреждает водителя вне населённого пункта о приближении к железнодорожному переезду.\nЗнаки 1.4.1−1.4.3 устанавливаются на правой стороне дороги, а знаки 1.4.4−1.4.6 − на левой стороне дороги. Знаки 1.4.1 и 1.4.4 устанавливаются по направлению движения вместе с основным и повторным знаком 1.1 или 1.2, знаки 1.4.3 и 1.4.6 − по направлению движения вместе с повторным знаком 1.1 или 1.2, а знаки 1.4.2 и 1.4.5 − самостоятельно, на равном расстоянии между основным и повторным знаком 1.1 или 1.2.', E'Вне населённого пункта эти знаки дополнительно предупреждают, что вы приближаетесь к железнодорожному переезду. Знаки 1.4.1–1.4.3 стоят на правой стороне дороги, 1.4.4–1.4.6 — на левой. Знаки 1.4.1 и 1.4.4 стоят вместе с первым знаком 1.1 или 1.2, 1.4.3 и 1.4.6 — с повторным знаком 1.1 или 1.2, а 1.4.2 и 1.4.5 — отдельно, посередине между ними.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ru/card_de8ced1b1b.webm'),
  (E'sign-1.5', E'en', E'Tram line crossing', E'Warns of a tram line crossing the road. Outside built-up areas the sign is placed 150−300 metres before the start of the hazardous section, in built-up areas – 50–100 metres before it.', E'A tram line crosses the road ahead. In a built-up area the sign stands 50–100 metres before the hazard, outside one 150–300 metres before it.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/en/card_9c38481bf5.webm'),
  (E'sign-1.5', E'ka', E'ტრამვაის ხაზის გადაკვეთა', E'იძლევა გაფრთხილებას ტრამვაის ხაზის გზასთან გადაკვეთის თაობაზე. ნიშანი დაუსახლებელ პუნქტში იდგმება სახიფათო მონაკვეთის დასაწყისამდე 150−300 მეტრ მანძილზე, დასახლებულ პუნქტში – 50–100 მეტრ მანძილზე.', E'წინ გზას ტრამვაის ხაზი კვეთს. დასახლებულ პუნქტში ნიშანი სახიფათო მონაკვეთამდე 50–100 მეტრით ადრე დგას, მის გარეთ კი — 150–300 მეტრით ადრე.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ka/card_214ab8dd42.webm'),
  (E'sign-1.5', E'ru', E'Пересечение с трамвайной линией', E'Предупреждает о пересечении дороги с трамвайной линией. Вне населённых пунктов знак устанавливается на расстоянии 150−300 метров до начала опасного участка, в населённых пунктах – на расстоянии 50–100 метров.', E'Впереди дорогу пересекает трамвайная линия. В населённом пункте знак стоит за 50–100 метров до опасного участка, вне его — за 150–300 метров.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ru/card_7e2b2c598d.webm')
INSERT INTO learning_card_texts ("cardId", lang, title, body, tutor, audio) VALUES
  (E'sign-1.6', E'en', E'Crossroads of roads of equal importance', E'An intersection of roads of equal importance. Outside built-up areas the sign is placed 150−300 metres before the start of the hazardous section, in built-up areas – 50–100 metres before it.', E'An intersection of equal roads is ahead. In a built-up area the sign stands 50–100 metres before the hazard, outside one 150–300 metres before it.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/en/card_f77645d20b.webm'),
  (E'sign-1.6', E'ka', E'თანაბარმნიშვნელოვანი გზების გადაკვეთა', E'გზაჯვარედინი თანაბარმნიშვნელოვანი გზების გადაკვეთით. ნიშანი დაუსახლებელ პუნქტში იდგმება სახიფათო მონაკვეთის დასაწყისამდე 150−300 მეტრ მანძილზე, დასახლებულ პუნქტში – 50–100 მეტრ მანძილზე.', E'წინ გზაჯვარედინია, სადაც ერთმანეთს თანაბარმნიშვნელოვანი გზები კვეთს. დასახლებულ პუნქტში ნიშანი სახიფათო მონაკვეთამდე 50–100 მეტრით ადრე დგას, მის გარეთ კი — 150–300 მეტრით ადრე.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ka/card_d875e38aa2.webm'),
  (E'sign-1.6', E'ru', E'Пересечение равнозначных дорог', E'Перекрёсток с пересечением равнозначных дорог. Вне населённых пунктов знак устанавливается на расстоянии 150−300 метров до начала опасного участка, в населённых пунктах – на расстоянии 50–100 метров.', E'Впереди перекрёсток равнозначных дорог. В населённом пункте знак стоит за 50–100 метров до опасного участка, вне его — за 150–300 метров.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ru/card_341616e774.webm'),
  (E'sign-1.7.1', E'en', E'Crossroads with a minor road', E'An intersection with a road on which drivers must give way. The sign is placed before the start of the hazardous section outside built-up areas at a distance of 150−300 metres, in built-up areas – 50–100 metres. Outside built-up areas the sign is placed 150−300 metres before the start of the hazardous section, in built-up areas – 50–100 metres before it.', E'An intersection with a minor road is ahead: drivers on that road must give way to you. In a built-up area the sign stands 50–100 metres before the hazard, outside one 150–300 metres before it.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/en/card_a7cd591098.webm'),
  (E'sign-1.7.1', E'ka', E'მეორეხარისხოვან გზასთან გადაკვეთა', E'ისეთ გზასთან გადაკვეთა, რომელზე მოძრავ მძღოლსაც აქვს გზის დათმობის ვალდებულება. ნიშანი სახიფათო მონაკვეთის დასაწყისამდე იდგმება დაუსახლებელ პუნქტში 150−300 მეტრ მანძილზე, დასახლებულ პუნქტში – 50–100 მეტრ მანძილზე. ნიშანი დაუსახლებელ პუნქტში იდგმება სახიფათო მონაკვეთის დასაწყისამდე 150−300 მეტრ მანძილზე, დასახლებულ პუნქტში – 50–100 მეტრ მანძილზე.', E'წინ გზაჯვარედინია მეორეხარისხოვან გზასთან: იმ გზაზე მოძრავმა მძღოლებმა გზა უნდა დაგითმონ. დასახლებულ პუნქტში ნიშანი სახიფათო მონაკვეთამდე 50–100 მეტრით ადრე დგას, მის გარეთ კი — 150–300 მეტრით ადრე.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ka/card_036a81156b.webm'),
  (E'sign-1.7.1', E'ru', E'Пересечение со второстепенной дорогой', E'Пересечение с дорогой, водитель на которой обязан уступить дорогу. Знак устанавливается до начала опасного участка вне населённых пунктов на расстоянии 150−300 метров, в населённых пунктах – на расстоянии 50–100 метров. Вне населённых пунктов знак устанавливается на расстоянии 150−300 метров до начала опасного участка, в населённых пунктах – на расстоянии 50–100 метров.', E'Впереди пересечение со второстепенной дорогой: водители на ней обязаны уступить вам дорогу. В населённом пункте знак стоит за 50–100 метров до опасного участка, вне его — за 150–300 метров.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ru/card_53592b65d5.webm'),
  (E'sign-1.7.2–1.7.7', E'en', E'Junction with a minor road', E'A junction with a road on which drivers must give way (junction from the right – 1.7.2, 1.7.4 and 1.7.6, junction from the left – 1.7.3, 1.7.5 and 1.7.7). The sign is placed before the start of the hazardous section outside built-up areas at a distance of 150−300 metres, in built-up areas – 50–100 metres. Outside built-up areas the sign is placed 150−300 metres before the start of the hazardous section, in built-up areas – 50–100 metres before it.', E'A minor road joins your road ahead: drivers on it must give way to you. Signs 1.7.2, 1.7.4 and 1.7.6 show a junction on the right, 1.7.3, 1.7.5 and 1.7.7 on the left. In a built-up area the sign stands 50–100 metres before the hazard, outside one 150–300 metres before it.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/en/card_9cda6676be.webm'),
  (E'sign-1.7.2–1.7.7', E'ka', E'მეორეხარისხოვანი გზის შეერთება', E'ისეთ გზასთან შეერთება, რომელზე მოძრავ მძღოლსაც აქვს გზის დათმობის ვალდებულება (შეერთება მარჯვნიდან – 1.7.2, 1.7.4 და 1.7.6, შეერთება მარცხნიდან – 1.7.3, 1.7.5 და 1.7.7). ნიშანი სახიფათო მონაკვეთის დასაწყისამდე იდგმება დაუსახლებელ პუნქტში 150−300 მეტრ მანძილზე, დასახლებულ პუნქტში – 50–100 მეტრ მანძილზე. ნიშანი დაუსახლებელ პუნქტში იდგმება სახიფათო მონაკვეთის დასაწყისამდე 150−300 მეტრ მანძილზე, დასახლებულ პუნქტში – 50–100 მეტრ მანძილზე.', E'წინ შენს გზას მეორეხარისხოვანი გზა უერთდება: მასზე მოძრავმა მძღოლებმა გზა უნდა დაგითმონ. 1.7.2, 1.7.4 და 1.7.6 ნიშნები შეერთებას მარჯვნიდან აღნიშნავს, 1.7.3, 1.7.5 და 1.7.7 კი — მარცხნიდან. დასახლებულ პუნქტში ნიშანი სახიფათო მონაკვეთამდე 50–100 მეტრით ადრე დგას, მის გარეთ კი — 150–300 მეტრით ადრე.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ka/card_e69c615632.webm'),
  (E'sign-1.7.2–1.7.7', E'ru', E'Примыкание второстепенной дороги', E'Примыкание дороги, водитель на которой обязан уступить дорогу (примыкание справа – 1.7.2, 1.7.4 и 1.7.6, примыкание слева – 1.7.3, 1.7.5 и 1.7.7). Знак устанавливается до начала опасного участка вне населённых пунктов на расстоянии 150−300 метров, в населённых пунктах – на расстоянии 50–100 метров. Вне населённых пунктов знак устанавливается на расстоянии 150−300 метров до начала опасного участка, в населённых пунктах – на расстоянии 50–100 метров.', E'Впереди к вашей дороге примыкает второстепенная: водители на ней обязаны уступить вам дорогу. Знаки 1.7.2, 1.7.4 и 1.7.6 обозначают примыкание справа, 1.7.3, 1.7.5 и 1.7.7 — слева. В населённом пункте знак стоит за 50–100 метров до опасного участка, вне его — за 150–300 метров.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ru/card_6943791cea.webm'),
  (E'sign-1.8', E'en', E'Roundabout', E'Warns of an approaching roundabout intersection marked with sign 4.3. Outside built-up areas the sign is placed 150−300 metres before the start of the hazardous section, in built-up areas – 50–100 metres before it.', E'A roundabout marked with sign 4.3 is ahead. In a built-up area the sign stands 50–100 metres before the hazard, outside one 150–300 metres before it.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/en/card_12a7035b0d.webm'),
  (E'sign-1.8', E'ka', E'წრიული მოძრაობის გადაკვეთა', E'იძლევა გაფრთხილებას 4.3 ნიშნით აღნიშნულ წრიულმოძრაობიან გზაჯვარედინთან მიახლოების თაობაზე. ნიშანი დაუსახლებელ პუნქტში იდგმება სახიფათო მონაკვეთის დასაწყისამდე 150−300 მეტრ მანძილზე, დასახლებულ პუნქტში – 50–100 მეტრ მანძილზე.', E'წინ წრიული მოძრაობის გზაჯვარედინია, რომელიც 4.3 ნიშნით არის აღნიშნული. დასახლებულ პუნქტში ნიშანი სახიფათო მონაკვეთამდე 50–100 მეტრით ადრე დგას, მის გარეთ კი — 150–300 მეტრით ადრე.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ka/card_3585825600.webm'),
  (E'sign-1.8', E'ru', E'Пересечение с круговым движением', E'Предупреждает о приближении к перекрёстку с круговым движением, обозначенному знаком 4.3. Вне населённых пунктов знак устанавливается на расстоянии 150−300 метров до начала опасного участка, в населённых пунктах – на расстоянии 50–100 метров.', E'Впереди перекрёсток с круговым движением, обозначенный знаком 4.3. В населённом пункте знак стоит за 50–100 метров до опасного участка, вне его — за 150–300 метров.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ru/card_be25240339.webm'),
  (E'sign-1.9', E'en', E'Traffic signals', E'An intersection, pedestrian crossing or section of road (other than a level crossing) where traffic is controlled by traffic lights. Outside built-up areas the sign is placed 150−300 metres before the start of the hazardous section, in built-up areas – 50–100 metres before it.', E'An intersection, pedestrian crossing or road section with traffic lights is ahead. This sign is not used before level crossings. In a built-up area the sign stands 50–100 metres before the hazard, outside one 150–300 metres before it.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/en/card_37f36cd279.webm'),
  (E'sign-1.9', E'ka', E'შუქნიშნით რეგულირება', E'გზაჯვარედინი, ქვეითთა გადასასვლელი ან გზის მონაკვეთი (გარდა რკინიგზის გადასასვლელისა), რომელზე მოძრაობაც შუქნიშნით რეგულირდება. ნიშანი დაუსახლებელ პუნქტში იდგმება სახიფათო მონაკვეთის დასაწყისამდე 150−300 მეტრ მანძილზე, დასახლებულ პუნქტში – 50–100 მეტრ მანძილზე.', E'წინ გზაჯვარედინი, ქვეითთა გადასასვლელი ან გზის მონაკვეთია, სადაც მოძრაობას შუქნიშანი არეგულირებს. რკინიგზის გადასასვლელთან ეს ნიშანი არ დგას. დასახლებულ პუნქტში ნიშანი სახიფათო მონაკვეთამდე 50–100 მეტრით ადრე დგას, მის გარეთ კი — 150–300 მეტრით ადრე.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ka/card_9923aeaf2e.webm'),
  (E'sign-1.9', E'ru', E'Светофорное регулирование', E'Перекрёсток, пешеходный переход или участок дороги (кроме железнодорожного переезда), движение на котором регулируется светофором. Вне населённых пунктов знак устанавливается на расстоянии 150−300 метров до начала опасного участка, в населённых пунктах – на расстоянии 50–100 метров.', E'Впереди перекрёсток, пешеходный переход или участок дороги, где движение регулирует светофор. Перед железнодорожными переездами этот знак не ставят. В населённом пункте знак стоит за 50–100 метров до опасного участка, вне его — за 150–300 метров.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ru/card_57dd3fe15e.webm'),
  (E'sign-2.1', E'en', E'Priority road', E'A road on which drivers have priority when passing through uncontrolled intersections. The sign is placed at the start of the road and repeated immediately before each intersection. Sign 2.1 with plate 8.13 is placed in built-up areas before the intersection at which the priority road changes direction, outside built-up areas − in advance, 150−300 metres before the intersection, and before the intersection.', E'Main road: you have priority at unregulated intersections. The sign stands at the start of the road and is repeated before every intersection. With plate 8.13 it shows that the main road changes direction at the intersection: in a built-up area it stands before the intersection, outside one 150–300 metres before it and again before the intersection.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/en/card_abe3013d4b.webm'),
  (E'sign-2.1', E'ka', E'მთავარი გზა', E'გზა, რომელზე მოძრავ მძღოლსაც ენიჭება არარეგულირებული გზაჯვარედინის გავლის უპირატესობა. ნიშანი იდგმება გზის დასაწყისში და მეორდება უშუალოდ ყოველი გზაჯვარედინის წინ. 2.1 ნიშანი 8.13 დაფით დასახლებულ პუნქტში იდგმება გზაჯვარედინის წინ, რომელზედაც მთავარი გზა იცვლის მიმართულებას, დაუსახლებელ პუნქტში − წინასწარ გზაჯვარედინამდე 150−300 მეტრ მანძილზე და გზაჯვარედინის წინ.', E'მთავარი გზაა: არარეგულირებულ გზაჯვარედინზე გავლის უპირატესობა შენ გაქვს. ნიშანი გზის დასაწყისში დგას და მეორდება ყოველი გზაჯვარედინის წინ. 8.13 დაფით ის აჩვენებს, რომ გზაჯვარედინზე მთავარი გზა მიმართულებას იცვლის: დასახლებულ პუნქტში დგას გზაჯვარედინის წინ, მის გარეთ კი — გზაჯვარედინამდე 150–300 მეტრით ადრე და გზაჯვარედინის წინ.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ka/card_06413551d1.webm'),
  (E'sign-2.1', E'ru', E'Главная дорога', E'Дорога, водителю на которой предоставлено преимущество проезда нерегулируемых перекрёстков. Знак устанавливается в начале дороги и повторяется непосредственно перед каждым перекрёстком. Знак 2.1 с табличкой 8.13 в населённом пункте устанавливается перед перекрёстком, на котором главная дорога меняет направление, вне населённого пункта − предварительно на расстоянии 150−300 метров до перекрёстка и перед перекрёстком.', E'Главная дорога: на нерегулируемых перекрёстках преимущество у вас. Знак стоит в начале дороги и повторяется перед каждым перекрёстком. С табличкой 8.13 он показывает, что главная дорога на перекрёстке меняет направление: в населённом пункте он стоит перед перекрёстком, вне его — за 150–300 метров до перекрёстка и перед самим перекрёстком.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ru/card_24d4fb88d2.webm'),
  (E'sign-2.2', E'en', E'End of priority road', E'The end of the section of road from which it loses the status of a priority road. If the priority road ends before a crossing with a road that has priority at that intersection, sign 2.2 is placed outside built-up areas in advance together with sign 2.4, in built-up areas − 25 metres from the intersection and/or together with sign 2.3 or 2.4. The sign may also be placed at another distance indicated on plate 8.1.1.', E'The main road ends here: from this point the road is no longer a main road. If the main road ends before an intersection, in a built-up area the sign stands 25 metres before the intersection and/or together with sign 2.3 or 2.4, outside one in advance, together with sign 2.4. The sign may also stand at the distance shown on plate 8.1.1.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/en/card_217a5f6f17.webm'),
  (E'sign-2.2', E'ka', E'მთავარი გზის დასასრული', E'გზის იმ მონაკვეთის ბოლო, საიდანაც იგი კარგავს მთავარი გზის სტატუსს. თუ მთავარი გზა იმ გზის გადაკვეთის წინ მთავრდება, რომელზედაც დაწესებულია მოცემული გზაჯვარედინის გავლის უპირატესობა, 2.2 ნიშანს დაუსახლებელ პუნქტში დგამენ წინასწარ 2.4 ნიშანთან ერთად, დასახლებულ პუნქტში − გზაჯვარედინიდან 25 მეტრ მანძილზე ან/და 2.3 ან 2.4 ნიშანთან ერთად. ნიშანი შეიძლება დაიდგას სხვა, 8.1.1 დაფაზე მითითებულ მანძილზედაც.', E'აქ მთავარი გზა მთავრდება: ამ ადგილიდან გზას მთავარი გზის სტატუსი აღარ აქვს. თუ მთავარი გზა გზაჯვარედინის წინ მთავრდება, დასახლებულ პუნქტში ნიშანი გზაჯვარედინამდე 25 მეტრით ადრე დგას ან/და 2.3 ან 2.4 ნიშანთან ერთად, მის გარეთ კი — წინასწარ, 2.4 ნიშანთან ერთად. ნიშანი შეიძლება დადგეს 8.1.1 დაფაზე მითითებულ მანძილზეც.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ka/card_afa920a939.webm'),
  (E'sign-2.2', E'ru', E'Конец главной дороги', E'Конец участка дороги, с которого она утрачивает статус главной дороги. Если главная дорога заканчивается перед пересечением с дорогой, которой предоставлено преимущество проезда данного перекрёстка, знак 2.2 вне населённого пункта устанавливают предварительно вместе со знаком 2.4, в населённом пункте − на расстоянии 25 метров от перекрёстка и/или вместе со знаком 2.3 или 2.4. Знак может устанавливаться и на другом расстоянии, указанном на табличке 8.1.1.', E'Здесь главная дорога заканчивается: с этого места дорога больше не главная. Если главная дорога заканчивается перед перекрёстком, в населённом пункте знак стоит за 25 метров до перекрёстка и/или вместе со знаком 2.3 или 2.4, вне его — заранее, вместе со знаком 2.4. Знак может стоять и на расстоянии, указанном на табличке 8.1.1.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ru/card_c08db2e80e.webm'),
  (E'sign-2.3', E'en', E'Give way', E'The driver travelling on the road where this sign is placed must give way to drivers travelling on the intersecting road, and, where plate 8.13 is present, to drivers travelling on the main road. Outside built-up areas, sign 2.3 is placed in advance, 150−300 metres before the intersection, with plate 8.1.1 if sign 2.3 is placed before the intersection, or with plate 8.1.2 if sign 2.4 is placed before the intersection. The sign applies to the intersection of carriageways in front of which the relevant sign is placed.', E'Give way: at the intersection you must give way to traffic on the crossing road, or, with plate 8.13, to traffic on the main road. Outside built-up areas the sign also stands in advance, 150–300 metres before the intersection: with plate 8.1.1 if sign 2.3 stands before the intersection, or with plate 8.1.2 if sign 2.4 stands there. The sign applies at the intersection it stands before.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/en/card_df64605fc1.webm'),
  (E'sign-2.3', E'ka', E'დაუთმე გზა', E'გზა, რომელზე მოძრავი მძღოლიც ვალდებულია გზა დაუთმოს გადა­სა­კვეთ გზაზე მოძრავ მძღოლს, ხოლო 8.13 დაფის არსებობისას – მთავარ გზაზე მოძრავ მძღოლს. 2.3 ნიშანი დაუსახლებელ პუნქტში იდგმება წინასწარ გზაჯვარედინამდე 150−300 მეტრ მანძილზე 8.1.1 დაფით, თუ გზაჯვარედინის წინ დადგმულია 2.3 ნიშანი, ან 8.1.2 დაფით, თუ გზაჯვარედინის წინ დადგმულია 2.4 ნიშანი. ნიშნის მოქმედება ვრცელდება სავალი ნაწილების იმ გადაკვეთაზე, რომლის წინაც დადგმულია სათანადო ნიშანი.', E'დაუთმე გზა: გზაჯვარედინზე გზა უნდა დაუთმო გადამკვეთ გზაზე მოძრავს, 8.13 დაფის არსებობისას კი — მთავარ გზაზე მოძრავს. დასახლებული პუნქტის გარეთ ნიშანი წინასწარაც დგას, გზაჯვარედინამდე 150–300 მეტრით ადრე: 8.1.1 დაფით, თუ გზაჯვარედინის წინ 2.3 ნიშანია, ან 8.1.2 დაფით, თუ იქ 2.4 ნიშანია. ნიშანი მოქმედებს იმ გზაჯვარედინზე, რომლის წინაც დგას.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ka/card_291765ce46.webm'),
  (E'sign-2.3', E'ru', E'Уступите дорогу', E'Водитель, движущийся по дороге, на которой установлен знак, обязан уступить дорогу водителю, движущемуся по пересекаемой дороге, а при наличии таблички 8.13 — водителю, движущемуся по главной дороге. Вне населённых пунктов знак 2.3 устанавливается предварительно на расстоянии 150−300 метров до перекрёстка с табличкой 8.1.1, если перед перекрёстком установлен знак 2.3, или с табличкой 8.1.2, если перед перекрёстком установлен знак 2.4. Действие знака распространяется на пересечение проезжих частей, перед которым установлен соответствующий знак.', E'Уступите дорогу: на перекрёстке вы должны уступить дорогу тем, кто едет по пересекаемой дороге, а при табличке 8.13 — тем, кто едет по главной. Вне населённого пункта знак стоит и заранее, за 150–300 метров до перекрёстка: с табличкой 8.1.1, если перед перекрёстком стоит знак 2.3, или с табличкой 8.1.2, если там стоит знак 2.4. Знак действует на перекрёстке, перед которым установлен.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ru/card_0e1655da73.webm'),
  (E'sign-2.4', E'en', E'Stop (no proceeding without stopping)', E'Prohibits the driver from proceeding without stopping before the “STOP” line, or, if there is none, before the edge of the intersecting carriageway. The driver must give way to drivers travelling on the intersecting road, and, where plate 8.13 is present, to drivers travelling on the main road. The sign is placed where visibility of vehicles travelling on the intersecting road is not ensured. It may also be placed before a level crossing or a quarantine checkpoint (in this case the driver must stop before the “STOP” line, or, if there is none, before the sign). The sign applies to the intersection of carriageways in front of which the relevant sign is placed', E'Driving on without stopping is banned: stop at the stop line, or, if there is none, at the edge of the carriageway you are crossing. Then give way to traffic on the crossing road, or, with plate 8.13, to traffic on the main road. The sign stands where the crossing road is hard to see, and may also stand at a level crossing or a quarantine post: then you stop at the stop line, or, if there is none, at the sign.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/en/card_dc52a624de.webm'),
  (E'sign-2.4', E'ka', E'მოძრაობა გაუჩერებლად აკრძალულია', E'უკრძალავს მძღოლს მოძრაობის გაგრძელებას „სდექ“ ხაზის წინ გაუჩერებლად, ხოლო თუ იგი არ არის – გადასაკვეთი სავალი ნაწილის ნაპირთან. მძღოლი ვალდებულია გზა დაუთმოს გადასაკვეთ გზაზე მოძრავ მძღოლს, ხოლო 8.13 დაფის არსებობისას – მთავარ გზაზე მოძრავ მძღოლს. ნიშანი იდგმება, თუ არ არის უზრუნველყოფილი გადამკვეთ გზაზე მოძრავ სატრანსპორტო საშუალებათა ხილვადობა. ის აგრეთვე შეიძლება დაიდგას რკინიგზის გადასასვლელის ან საკარანტინო საგუშაგოს წინ (ამ შემთხვევაში მძღოლი ვალდებულია გაჩერდეს „სდექ“ ხაზის წინ, ხოლო თუ იგი არ არის – ნიშნის წინ). ნიშნის მოქმედება ვრცელდება სავალი ნაწილების იმ გადაკვეთაზე, რომლის წინაც დადგმულია სათანადო ნიშანი', E'გაუჩერებლად გავლა აკრძალულია: უნდა გაჩერდე „სდექ“ ხაზთან, ხაზი თუ არ არის — გადასაკვეთი სავალი ნაწილის ნაპირთან. შემდეგ გზა უნდა დაუთმო გადამკვეთ გზაზე მოძრავს, 8.13 დაფის არსებობისას კი — მთავარ გზაზე მოძრავს. ნიშანი დგას იქ, სადაც გადამკვეთი გზა კარგად არ ჩანს, ასევე შეიძლება იდგეს რკინიგზის გადასასვლელთან ან საკარანტინო საგუშაგოსთან: მაშინ ჩერდები „სდექ“ ხაზთან, ხაზი თუ არ არის — ნიშანთან.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ka/card_345a437fea.webm'),
  (E'sign-2.4', E'ru', E'Движение без остановки запрещено', E'Запрещает водителю продолжать движение без остановки перед линией «Стоп», а если её нет — перед краем пересекаемой проезжей части. Водитель обязан уступить дорогу водителю, движущемуся по пересекаемой дороге, а при наличии таблички 8.13 — водителю, движущемуся по главной дороге. Знак устанавливается, если не обеспечена видимость транспортных средств, движущихся по пересекаемой дороге. Он также может быть установлен перед железнодорожным переездом или карантинным постом (в этом случае водитель обязан остановиться перед линией «Стоп», а если её нет — перед знаком). Действие знака распространяется на пересечение проезжих частей, перед которым установлен соответствующий знак', E'Движение без остановки запрещено: остановитесь у стоп-линии, а если её нет — у края пересекаемой проезжей части. Затем уступите дорогу тем, кто едет по пересекаемой дороге, а при табличке 8.13 — тем, кто едет по главной. Знак ставят там, где пересекаемую дорогу плохо видно; он может стоять и у железнодорожного переезда или карантинного поста: тогда вы останавливаетесь у стоп-линии, а если её нет — у знака.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ru/card_effe39e1a6.webm'),
  (E'sign-2.5', E'en', E'Priority to oncoming traffic', E'Prohibits the driver from entering a narrow section of road if this would obstruct traffic in the opposite direction. The driver must give way to an oncoming vehicle that is at the opposite approach or on the narrow section of road. The sign is placed immediately before the narrow section of road or in advance, with plate 8.1.1.', E'On the narrow section oncoming traffic has priority: you may not enter it if you would get in the way of oncoming traffic. Give way to an oncoming vehicle that is on the narrow section or at its far end. The sign stands right before the narrow section, or in advance with plate 8.1.1.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/en/card_86261ea56d.webm'),
  (E'sign-2.5', E'ka', E'შემხვედრი მოძრაობის უპირატესობა', E'უკრძალავს მძღოლს გზის ვიწრო მონაკვეთზე შესვლას, თუ ეს აძნელებს საპირისპირო მიმართულებით მოძრაობას. მძღოლი ვალდებულია გზა დაუთმოს შემხვედრ სატრან­სპორტო საშუალებას, რომელიც მოპირდაპირე მისასვლელთან ან გზის ვიწრო მონაკვეთზე იმყოფება. ნიშანი იდგმება უშუალოდ გზის ვიწრო უბნის წინ ან წინასწარ, 8.1.1 დაფით.', E'ვიწრო მონაკვეთზე უპირატესობა შემხვედრს აქვს: იქ ვერ შეხვალ, თუ საპირისპიროდ მოძრავს ხელს შეუშლი. გზა უნდა დაუთმო შემხვედრ სატრანსპორტო საშუალებას, რომელიც ვიწრო მონაკვეთზე ან მის მოპირდაპირე მისასვლელთან არის. ნიშანი უშუალოდ ვიწრო უბნის წინ დგას, ან წინასწარ — 8.1.1 დაფით.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ka/card_70ac5a1458.webm'),
  (E'sign-2.5', E'ru', E'Преимущество встречного движения', E'Запрещает водителю въезд на узкий участок дороги, если это затрудняет движение во встречном направлении. Водитель обязан уступить дорогу встречному транспортному средству, находящемуся на противоположном подъезде или на узком участке дороги. Знак устанавливается непосредственно перед узким участком дороги или предварительно с табличкой 8.1.1.', E'На узком участке преимущество у встречного движения: въезжать на него нельзя, если вы помешаете встречным. Уступите дорогу встречному транспортному средству, которое находится на узком участке или у противоположного въезда на него. Знак стоит непосредственно перед узким участком или заранее — с табличкой 8.1.1.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ru/card_e2fc406dfc.webm'),
  (E'sign-2.6', E'en', E'Priority over oncoming traffic', E'Gives the driver priority over vehicles travelling in the opposite direction when driving on a narrow section of road. The sign is placed immediately before the narrow section of road.', E'On the narrow section you have priority: oncoming vehicles must give way to you. The sign stands right before the narrow section.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/en/card_0f449f130d.webm'),
  (E'sign-2.6', E'ka', E'უპირატესობა შემხვედრ მოძრაობასთან', E'ანიჭებს მძღოლს უპირატესობას გზის ვიწრო მონაკვეთზე მოძრაობისას საპირისპირო მიმართულებით მოძრავ სატრანსპორტო საშუალებასთან შედარებით. ნიშანი იდგმება უშუალოდ გზის ვიწრო უბნის წინ.', E'ვიწრო მონაკვეთზე უპირატესობა შენ გაქვს: შემხვედრმა სატრანსპორტო საშუალებამ გზა უნდა დაგითმოს. ნიშანი უშუალოდ ვიწრო უბნის წინ დგას.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ka/card_5051016772.webm'),
  (E'sign-2.6', E'ru', E'Преимущество перед встречным движением', E'Предоставляет водителю преимущество перед транспортными средствами, движущимися во встречном направлении, при движении по узкому участку дороги. Знак устанавливается непосредственно перед узким участком дороги.', E'На узком участке преимущество у вас: встречные транспортные средства должны уступить вам дорогу. Знак стоит непосредственно перед узким участком.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ru/card_8bbc993987.webm'),
  (E'sign-3.1', E'en', E'No entry', E'Prohibits all vehicles from entering in the given direction. The sign does not apply to route vehicles.', E'No entry in this direction for all vehicles. The sign does not apply to route vehicles.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/en/card_fbf8c4ddd4.webm'),
  (E'sign-3.1', E'ka', E'შესვლა აკრძალულია', E'კრძალავს ყველა სახის სატრან­სპორტო საშუალებით შესვლას მოცემული მიმართულებით. ნიშნის მოქმედება არ ვრცელდება სამარშრუტო სატრანსპორტო საშუალებაზე.', E'ამ მიმართულებით შესვლა აკრძალულია ყველა სატრანსპორტო საშუალებისთვის. სამარშრუტო ტრანსპორტზე ნიშანი არ ვრცელდება.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ka/card_5bc8cef9ec.webm'),
  (E'sign-3.1', E'ru', E'Въезд запрещён', E'Запрещает въезд всех транспортных средств в данном направлении. Действие знака не распространяется на маршрутные транспортные средства.', E'Въезд в этом направлении запрещён всем транспортным средствам. Знак не распространяется на маршрутные транспортные средства.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ru/card_4f891ff313.webm'),
  (E'sign-3.10', E'en', E'No pedestrians', E'Prohibits pedestrian traffic. The sign is placed where pedestrian traffic is not permitted for reasons of their safety. The sign applies only to the side of the road on which it is placed.', E'No pedestrians: the sign stands where walking is dangerous for them. It applies only to the side of the road where it stands.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/en/card_08ad964ce5.webm'),
  (E'sign-3.10', E'ka', E'ქვეითთა მოძრაობა აკრძალულია', E'კრძალავს ქვეითთა მოძრაობას. ნიშანი იდგმება იმ ადგილას, სადაც ქვეითთა მოძრაობა დაუშვებელია, მათი უსაფრთხოებიდან გამომდინარე. ნიშნის მოქმედება ვრცელდება მხოლოდ გზის იმ მხარეს, რომელზედაც იგია დადგმული.', E'ქვეითთა მოძრაობა აკრძალულია: ნიშანი დგას იქ, სადაც ფეხით სიარული მათთვის სახიფათოა. ნიშანი მოქმედებს მხოლოდ გზის იმ მხარეს, სადაც დგას.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ka/card_c31a37ccf2.webm'),
  (E'sign-3.10', E'ru', E'Движение пешеходов запрещено', E'Запрещает движение пешеходов. Знак устанавливается в местах, где движение пешеходов недопустимо исходя из их безопасности. Действие знака распространяется только на ту сторону дороги, на которой он установлен.', E'Движение пешеходов запрещено: знак ставят там, где ходить пешком для них опасно. Он действует только на той стороне дороги, где установлен.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ru/card_9c58dcdf10.webm'),
  (E'sign-3.11', E'en', E'Weight limit', E'Prohibits the movement of vehicles and combinations of vehicles whose total actual mass exceeds that shown on the sign.', E'A vehicle or combination whose actual total mass is more than shown on the sign may not go on.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/en/card_1e45d6b8fe.webm'),
  (E'sign-3.11', E'ka', E'მასის შეზღუდვა', E'კრძალავს იმ სატრანსპორტო საშუალებითდა სატრანსპორტო საშუალებათა შემადგენლობით მოძრაობას, რომელთა საერთო ფაქტობრივი მასა აღემატება ნიშანზე აღნიშნულს.', E'აკრძალულია სატრანსპორტო საშუალებით ან შემადგენლობით მოძრაობა, თუ მისი საერთო ფაქტობრივი მასა ნიშანზე მითითებულს აღემატება.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ka/card_49c7936b3c.webm'),
  (E'sign-3.11', E'ru', E'Ограничение массы', E'Запрещает движение транспортных средств и составов транспортных средств, общая фактическая масса которых больше указанной на знаке.', E'Движение транспортного средства или состава запрещено, если его фактическая общая масса больше указанной на знаке.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ru/card_4fff456760.webm'),
  (E'sign-3.12', E'en', E'Axle weight limit', E'Prohibits the movement of vehicles whose actual load on any axle exceeds that shown on the sign.', E'A vehicle may not go on if the actual load on any of its axles is more than shown on the sign.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/en/card_9899f69c02.webm'),
  (E'sign-3.12', E'ka', E'ღერძზე დატვირთვის შეზღუდვა', E'კრძალავს იმ სატრანსპორტო საშუალებით მოძრაობას, რომლის ფაქტობრივი დატვირთვა რომელიმე ღერძზე აღემატება ნიშანზე აღნიშნულს.', E'აკრძალულია სატრანსპორტო საშუალებით მოძრაობა, თუ რომელიმე ღერძზე მისი ფაქტობრივი დატვირთვა ნიშანზე მითითებულს აღემატება.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ka/card_6b7e8734ed.webm'),
  (E'sign-3.12', E'ru', E'Ограничение нагрузки на ось', E'Запрещает движение транспортных средств, фактическая нагрузка которых на какую-либо ось больше указанной на знаке.', E'Движение транспортного средства запрещено, если фактическая нагрузка на любую его ось больше указанной на знаке.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ru/card_e2d994bc5c.webm'),
  (E'sign-3.13', E'en', E'Height limit', E'Prohibits the movement of vehicles whose overall height (laden or unladen) exceeds that shown on the sign.', E'A vehicle may not go on if its height, with or without load, is more than shown on the sign.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/en/card_2a081367ff.webm'),
  (E'sign-3.13', E'ka', E'სიმაღლის შეზღუდვა', E'კრძალავს იმ სატრანსპორტო საშუალებით მოძრაობას, რომლის გაბარიტული სიმაღლე (ტვირთიანად ან უტვირთოდ) აღემატება ნიშანზე აღნიშნულს.', E'აკრძალულია სატრანსპორტო საშუალებით მოძრაობა, თუ მისი სიმაღლე, ტვირთიანად ან უტვირთოდ, ნიშანზე მითითებულს აღემატება.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ka/card_2c8952a032.webm'),
  (E'sign-3.13', E'ru', E'Ограничение высоты', E'Запрещает движение транспортных средств, габаритная высота которых (с грузом или без груза) больше указанной на знаке.', E'Движение транспортного средства запрещено, если его высота с грузом или без груза больше указанной на знаке.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ru/card_a246d9de56.webm'),
  (E'sign-3.14', E'en', E'Width limit', E'Prohibits the movement of vehicles whose overall width (laden or unladen) exceeds that shown on the sign.', E'A vehicle may not go on if its width, with or without load, is more than shown on the sign.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/en/card_ff4026a756.webm'),
  (E'sign-3.14', E'ka', E'სიგანის შეზღუდვა', E'კრძალავს იმ სატრანსპორტო საშუა­ლებით მოძრაობას, რომლის გაბარიტული სიგანე (ტვირთიანად ან უტვირთოდ) აღემატება ნიშანზე აღნიშნულს.', E'აკრძალულია სატრანსპორტო საშუალებით მოძრაობა, თუ მისი სიგანე, ტვირთიანად ან უტვირთოდ, ნიშანზე მითითებულს აღემატება.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ka/card_c4cf1e9e9c.webm'),
  (E'sign-3.14', E'ru', E'Ограничение ширины', E'Запрещает движение транспортных средств, габаритная ширина которых (с грузом или без груза) больше указанной на знаке.', E'Движение транспортного средства запрещено, если его ширина с грузом или без груза больше указанной на знаке.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ru/card_eacc963279.webm'),
  (E'sign-3.15', E'en', E'Length limit', E'Prohibits the movement of vehicles and combinations of vehicles whose overall length (laden or unladen) exceeds that shown on the sign.', E'A vehicle or combination may not go on if its length, with or without load, is more than shown on the sign.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/en/card_1da587b154.webm'),
  (E'sign-3.15', E'ka', E'სიგრძის შეზღუდვა', E'კრძალავს იმ სატრანსპორტო საშუალებითდა სატრანსპორტო საშუალებათა შემადგენლობით მოძრა­ობას, რომელთა გაბარიტული სიგრძე (ტვირთიანად ან უტვირთოდ) აღემატება ნიშანზე აღნიშნულს.', E'აკრძალულია სატრანსპორტო საშუალებით ან შემადგენლობით მოძრაობა, თუ მისი სიგრძე, ტვირთიანად ან უტვირთოდ, ნიშანზე მითითებულს აღემატება.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ka/card_a929d338ef.webm'),
  (E'sign-3.15', E'ru', E'Ограничение длины', E'Запрещает движение транспортных средств и составов транспортных средств, габаритная длина которых (с грузом или без груза) больше указанной на знаке.', E'Движение транспортного средства или состава запрещено, если его длина с грузом или без груза больше указанной на знаке.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ru/card_f4167c9a33.webm'),
  (E'sign-3.16', E'en', E'Minimum distance', E'Prohibits vehicles from travelling at a distance shorter than that shown on the sign. The sign applies from the place where the relevant sign is placed to the nearest intersection after it, and in a built-up area where there is no intersection, to the end of the built-up area. The sign also applies at exits from adjacent areas and at intersections (junctions) with field, forest and other secondary roads in front of which no corresponding sign is placed.', E'You may not drive closer to the vehicle in front than the distance shown on the sign. The sign applies from where it stands to the nearest intersection; in a built-up area with no intersection, to the end of the built-up area. Exits from adjacent areas and junctions with field, forest or other minor roads do not end it.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/en/card_0f4db22a32.webm'),
  (E'sign-3.16', E'ka', E'მინიმალური დისტანციის შეზღუდვა', E'კრძალავს სატრანსპორტო საშუალებებით მოძრაობას ნიშანზე აღნიშნულ მანძილზე ნაკლები დისტანციით. ნიშნის მოქმედება ვრცელდება სათანადო ნიშნის შემდეგ, ნიშნის დადგმის ადგილიდან უახლოეს გზაჯვარედინამდე, ხოლო დასახლებულ პუნქტში გზაჯვარედინის არარსებობისას – დასახლებული პუნქტის ბოლომდე. ნიშნის მოქმედება ვრცელდება აგრეთვე მიმდებარე ტერიტორიის გამოსას¬ვლე¬ლთან, საველე, სატყეო და სხვა მეორეხარისხოვანი გზების გადაკვეთასთან (შეერთებასთან), რომელთა წინ არ დგას სათანადო ნიშანი.', E'აკრძალულია წინა სატრანსპორტო საშუალებასთან ნიშანზე მითითებულზე ნაკლები დისტანციით მოძრაობა. ნიშანი მოქმედებს დადგმის ადგილიდან უახლოეს გზაჯვარედინამდე, დასახლებულ პუნქტში კი, თუ გზაჯვარედინი არ არის, — დასახლებული პუნქტის ბოლომდე. მიმდებარე ტერიტორიიდან გამოსასვლელთან და მინდვრის, ტყის ან სხვა მეორეხარისხოვანი გზის შეერთებასთან ნიშნის მოქმედება არ წყდება.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ka/card_f218064424.webm'),
  (E'sign-3.16', E'ru', E'Ограничение минимальной дистанции', E'Запрещает движение транспортных средств с дистанцией меньше указанной на знаке. Действие знака распространяется от места установки соответствующего знака до ближайшего перекрёстка за ним, а в населённом пункте при отсутствии перекрёстка — до конца населённого пункта. Действие знака распространяется также на выезды с прилегающих территорий и на пересечения (примыкания) с полевыми, лесными и другими второстепенными дорогами, перед которыми не установлен соответствующий знак.', E'Запрещено двигаться с дистанцией до впереди идущего транспортного средства меньше указанной на знаке. Знак действует от места установки до ближайшего перекрёстка, а в населённом пункте, если перекрёстка нет, — до конца населённого пункта. Выезды с прилегающей территории и примыкания полевых, лесных и других второстепенных дорог его действие не прерывают.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ru/card_6b85036e8a.webm'),
  (E'sign-3.17.1', E'en', E'Customs', E'Prohibits passing a customs checkpoint (the customs control zone located at the customs border of Georgia) without stopping.', E'At a customs checkpoint on Georgia''s customs border, driving on without stopping is banned.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/en/card_ce0b52bc67.webm'),
  (E'sign-3.17.1', E'ka', E'საბაჟო გამშვები პუნქტი', E'კრძალავს საბაჟო გამშვებ პუნქტთან (საქართველოს საბაჟო საზღვართან მდებარე საბაჟო კონტროლის ზონა) გაუჩერებლად გავლას.', E'საბაჟო გამშვებ პუნქტთან, საქართველოს საბაჟო საზღვართან, გაუჩერებლად გავლა აკრძალულია.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ka/card_b41ea9c6b2.webm'),
  (E'sign-3.17.1', E'ru', E'Таможня', E'Запрещает проезд без остановки через таможенный пункт пропуска (зону таможенного контроля, расположенную на таможенной границе Грузии).', E'У таможенного пункта пропуска на таможенной границе Грузии проезд без остановки запрещён.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ru/card_a1c81c1b40.webm'),
  (E'sign-3.17.2', E'en', E'Danger', E'Prohibits further movement of all vehicles because of a road traffic accident or other danger.', E'Because of a road accident or another danger, all vehicles are banned from going further.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/en/card_25b0d1cc05.webm'),
  (E'sign-3.17.2', E'ka', E'საფრთხე', E'კრძალავს ყველა სახის სატრანსპორტო საშუალებით შემდგომ მოძრაობას საგზაო-სატრანსპორტო შემთხვევის ან სხვა საფრთხის გამო.', E'საგზაო-სატრანსპორტო შემთხვევის ან სხვა საფრთხის გამო შემდგომი მოძრაობა აკრძალულია ყველა სატრანსპორტო საშუალებისთვის.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ka/card_54c27de795.webm'),
  (E'sign-3.17.2', E'ru', E'Опасность', E'Запрещает дальнейшее движение всех транспортных средств в связи с дорожно-транспортным происшествием или иной опасностью.', E'Из-за дорожно-транспортного происшествия или другой опасности дальнейшее движение всех транспортных средств запрещено.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ru/card_2b56090c7b.webm'),
  (E'sign-3.17.3', E'en', E'Control', E'Prohibits passing a checkpoint (a police or quarantine post, an entrance to a border or closed zone, an exit onto a toll road, etc.) without stopping.', E'Driving past the checkpoint without stopping is banned: for example, a police or quarantine post, the entry to a border or closed zone, or the exit to a toll road.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/en/card_d931627882.webm'),
  (E'sign-3.17.3', E'ka', E'კონტროლი', E'კრძალავს საკონტროლო პუნქტთან (პოლიციის ან საკარანტინო საგუშაგოსთან, სასაზღვრო ან დახურულ ზონაში შესასვლელთან, ფასიან გზაზე გასასვლელთან და ა.შ.) გაუჩერებლად გავლას.', E'საკონტროლო პუნქტთან გაუჩერებლად გავლა აკრძალულია: მაგალითად, პოლიციის ან საკარანტინო საგუშაგოსთან, სასაზღვრო ან დახურულ ზონაში შესასვლელთან, ფასიან გზაზე გასასვლელთან.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ka/card_2dc94378b0.webm'),
  (E'sign-3.17.3', E'ru', E'Контроль', E'Запрещает проезд без остановки через контрольный пункт (пост полиции или карантинный пост, въезд в пограничную или закрытую зону, выезд на платную дорогу и т. п.).', E'Проезд без остановки у контрольного пункта запрещён: например, у поста полиции или карантинного поста, на въезде в пограничную или закрытую зону, на выезде на платную дорогу.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ru/card_548bf6fd00.webm'),
  (E'sign-3.18.1', E'en', E'No right turn', E'Prohibits turning right at the nearest intersection of carriageways. The sign does not apply to route vehicles. The sign applies to the intersection of carriageways in front of which the sign is placed.', E'Turning right at the nearest intersection is banned. The sign applies at the intersection it stands before. The sign does not apply to route vehicles.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/en/card_82a19c0613.webm'),
  (E'sign-3.18.1', E'ka', E'მარჯვნივ მოხვევა აკრძალულია', E'კრძალავს სავალი ნაწილების უახლოეს გადაკვეთაზე მარჯვნივ მოხვევას. ნიშნის მოქმედება არ ვრცელდება სამარშრუტო სატრანსპორტო საშუალებაზე. ნიშნის მოქმედება ვრცელდება სავალი ნაწილების იმ გადაკვეთაზე, რომლის წინაც დადგმულია ნიშანი.', E'უახლოეს გზაჯვარედინზე მარჯვნივ მოხვევა აკრძალულია. ნიშანი მოქმედებს იმ გზაჯვარედინზე, რომლის წინაც დგას. სამარშრუტო ტრანსპორტზე ნიშანი არ ვრცელდება.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ka/card_b117c91798.webm'),
  (E'sign-3.18.1', E'ru', E'Поворот направо запрещён', E'Запрещает поворот направо на ближайшем пересечении проезжих частей. Действие знака не распространяется на маршрутные транспортные средства. Действие знака распространяется на пересечение проезжих частей, перед которым установлен знак.', E'Поворот направо на ближайшем перекрёстке запрещён. Знак действует на перекрёстке, перед которым установлен. Знак не распространяется на маршрутные транспортные средства.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ru/card_8e7fb22735.webm'),
  (E'sign-3.18.2', E'en', E'No left turn', E'Prohibits turning left at the nearest intersection of carriageways. The sign does not apply to route vehicles. The sign applies to the intersection of carriageways in front of which the sign is placed.', E'Turning left at the nearest intersection is banned. The sign applies at the intersection it stands before. The sign does not apply to route vehicles.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/en/card_f2144a5ff9.webm'),
  (E'sign-3.18.2', E'ka', E'მარცხნივ მოხვევა აკრძალულია', E'კრძალავს სავალი ნაწილების უახლოეს გადაკვეთაზე მარცხნივ მოხვევას. ნიშნის მოქმედება არ ვრცელდება სამარშრუტო სატრანსპორტო საშუალებაზე. ნიშნის მოქმედება ვრცელდება სავალი ნაწილების იმ გადაკვეთაზე, რომლის წინაც დადგმულია ნიშანი.', E'უახლოეს გზაჯვარედინზე მარცხნივ მოხვევა აკრძალულია. ნიშანი მოქმედებს იმ გზაჯვარედინზე, რომლის წინაც დგას. სამარშრუტო ტრანსპორტზე ნიშანი არ ვრცელდება.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ka/card_ee2128d51a.webm'),
  (E'sign-3.18.2', E'ru', E'Поворот налево запрещён', E'Запрещает поворот налево на ближайшем пересечении проезжих частей. Действие знака не распространяется на маршрутные транспортные средства. Действие знака распространяется на пересечение проезжих частей, перед которым установлен знак.', E'Поворот налево на ближайшем перекрёстке запрещён. Знак действует на перекрёстке, перед которым установлен. Знак не распространяется на маршрутные транспортные средства.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ru/card_b2c754229b.webm'),
  (E'sign-3.19', E'en', E'No U-turns', E'Prohibits U-turns at the nearest intersection of carriageways. The sign does not apply to route vehicles.', E'U-turns at the nearest intersection are banned. The sign does not apply to route vehicles.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/en/card_90a5ea6c04.webm'),
  (E'sign-3.19', E'ka', E'მობრუნება აკრძალულია', E'სავალი ნაწილების უახლოეს გადაკვეთაზე მობრუნებას. ნიშნის მოქმედება არ ვრცელდება სამარშრუტო სატრანსპორტო საშუალებაზე.', E'უახლოეს გზაჯვარედინზე მობრუნება აკრძალულია. სამარშრუტო ტრანსპორტზე ნიშანი არ ვრცელდება.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ka/card_f174bc3e50.webm'),
  (E'sign-3.19', E'ru', E'Разворот запрещён', E'Запрещает разворот на ближайшем пересечении проезжих частей. Действие знака не распространяется на маршрутные транспортные средства.', E'Разворот на ближайшем перекрёстке запрещён. Знак не распространяется на маршрутные транспортные средства.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ru/card_28b9e28656.webm'),
  (E'sign-3.2', E'en', E'No vehicles', E'Prohibits the movement of all vehicles. The sign indicates that traffic is prohibited in both directions. The sign does not apply to route vehicles. The sign does not apply to vehicles serving an enterprise located in the designated zone, or serving or belonging to a person who lives or works in that zone. In this case, the vehicle enters the designated zone and leaves it at the intersection nearest to its destination. The sign does not apply to a vehicle driven by a person with the status of a significantly or severely expressed disability, or to a vehicle carrying such persons.', E'Traffic is banned for all vehicles, in both directions. The sign does not apply to route vehicles. The sign does not apply to vehicles serving a business in the zone, or serving or owned by people who live or work there: such vehicles enter and leave the zone at the intersection nearest to their destination. Nor does it apply to a vehicle driven by, or carrying, a person with a significant or severe disability.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/en/card_34618d6f5c.webm'),
  (E'sign-3.2', E'ka', E'მოძრაობა აკრძალულია', E'კრძალავს ყველა სახის სატრან­სპორტო საშუალებით მოძრაობას. ნიშანი მიუთითებს, რომ მოძრაობა ორივე მიმართულებით აკრძალულია. ნიშნის მოქმედება არ ვრცელდება სამარშრუტო სატრანსპორტო საშუალებაზე. ნიშნის მოქმედება არ ვრცელდება სატრანსპორტო საშუალებაზე, რომელიც ემსახურება აღნიშნულ ზონაში მდებარე საწარმოს, ანდა ემსახურება ან ეკუთვნის ამავე ზონაში მცხოვრებ ან მომუშავე პირს. ამ შემთხვევაში სატრანსპორტო საშუალება შედის აღნიშნულ ზონაში და გამოდის იქიდან დანიშნულების ადგილისაკენ უახლოეს გზაჯვარედინზე. ნიშნის მოქმედება არ ვრცელდება იმ სატრანსპორტო საშუალებაზე, რომელსაც მნიშვნელოვნად გამოხატული ან მკვეთრად გამოხატული შეზღუდული შესაძლებლობის სტატუსის მქონე პირი მართავს, ან იმ სატრანსპორტო საშუალებაზე, რომელსაც აღნიშნული პირები გადაჰყავს.', E'მოძრაობა აკრძალულია ყველა სატრანსპორტო საშუალებისთვის, ორივე მიმართულებით. სამარშრუტო ტრანსპორტზე ნიშანი არ ვრცელდება. ნიშანი არ ეხება სატრანსპორტო საშუალებას, რომელიც ზონაში მდებარე საწარმოს ემსახურება, ან ზონაში მცხოვრებ თუ მომუშავე ადამიანს ემსახურება ან ეკუთვნის: ასეთი სატრანსპორტო საშუალება ზონაში დანიშნულების ადგილთან უახლოესი გზაჯვარედინიდან შედის და გამოდის. ნიშანი არც იმ სატრანსპორტო საშუალებას ეხება, რომელსაც მნიშვნელოვნად ან მკვეთრად გამოხატული შეზღუდული შესაძლებლობის სტატუსის მქონე პირი მართავს ან გადაჰყავს.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ka/card_12c6539ee1.webm'),
  (E'sign-3.2', E'ru', E'Движение запрещено', E'Запрещает движение всех транспортных средств. Знак указывает, что движение запрещено в обоих направлениях. Действие знака не распространяется на маршрутные транспортные средства. Действие знака не распространяется на транспортные средства, обслуживающие предприятие, расположенное в обозначенной зоне, а также обслуживающие лицо, проживающее или работающее в этой зоне, или принадлежащие такому лицу. В этом случае транспортное средство въезжает в обозначенную зону и выезжает из неё на ближайшем к месту назначения перекрёстке. Действие знака не распространяется на транспортное средство, которым управляет лицо со статусом значительно выраженного или резко выраженного ограничения возможностей, или на транспортное средство, перевозящее таких лиц.', E'Движение запрещено всем транспортным средствам в обоих направлениях. Знак не распространяется на маршрутные транспортные средства. Знак не распространяется на транспортные средства, которые обслуживают предприятие в зоне, обслуживают людей, живущих или работающих в зоне, или принадлежат им: такие транспортные средства въезжают в зону и выезжают из неё на перекрёстке, ближайшем к месту назначения. Знак также не распространяется на транспортное средство, которым управляет или в котором перевозится лицо со значительно или резко выраженным ограничением возможностей.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ru/card_d7ea5306c4.webm'),
  (E'sign-3.20', E'en', E'No overtaking', E'Prohibits overtaking all motor vehicles (except vehicles travelling at less than 30 km/h). Overtaking a motorcycle without a sidecar, a moped or a bicycle is permitted without crossing into the oncoming traffic lane. The sign applies from the place where the relevant sign is placed to the nearest intersection after it, and in a built-up area where there is no intersection, to the end of the built-up area. The sign also applies at exits from adjacent areas and at intersections (junctions) with field, forest and other secondary roads in front of which no corresponding sign is placed.', E'Overtaking any motor vehicle is banned, except one going slower than 30 km/h. You may overtake a motorcycle without a sidecar, a moped or a bicycle if you do not move into the oncoming lane. The sign applies from where it stands to the nearest intersection; in a built-up area with no intersection, to the end of the built-up area. Exits from adjacent areas and junctions with field, forest or other minor roads do not end it.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/en/card_269882a6a8.webm'),
  (E'sign-3.20', E'ka', E'გასწრება აკრძალულია', E'კრძალავს ყველა სახის მექანიკური სატრან­სპორ­ტო საშუალების გასწრებას (გარდა 30 კმ/სთ-ზე ნაკლები სიჩქარით მოძრავი ტრანსპორტისა). ნებადართულია გასწრება უეტლო მოტოციკლის, მოპედისა და ველოსიპედის შემხვედრი მოძრაობის ზოლში გადაუსვლელად. ნიშნის მოქმედება ვრცელდება სათანადო ნიშნის შემდეგ, ნიშნის დადგმის ადგილიდან უახლოეს გზაჯვარედინამდე, ხოლო დასახლებულ პუნქტში გზაჯვარედინის არარსებობისას – დასახლებული პუნქტის ბოლომდე. ნიშნის მოქმედება ვრცელდება აგრეთვე მიმდებარე ტერიტორიის გამოსას¬ვლე¬ლთან, საველე, სატყეო და სხვა მეორეხარისხოვანი გზების გადაკვეთასთან (შეერთებასთან), რომელთა წინ არ დგას სათანადო ნიშანი.', E'აკრძალულია ყველა მექანიკური სატრანსპორტო საშუალების გასწრება, გარდა 30 კმ/სთ-ზე ნელა მოძრავისა. უეტლო მოტოციკლის, მოპედის და ველოსიპედის გასწრება შეიძლება, თუ შემხვედრ ზოლში არ გადახვალ. ნიშანი მოქმედებს დადგმის ადგილიდან უახლოეს გზაჯვარედინამდე, დასახლებულ პუნქტში კი, თუ გზაჯვარედინი არ არის, — დასახლებული პუნქტის ბოლომდე. მიმდებარე ტერიტორიიდან გამოსასვლელთან და მინდვრის, ტყის ან სხვა მეორეხარისხოვანი გზის შეერთებასთან ნიშნის მოქმედება არ წყდება.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ka/card_8221ed5605.webm'),
  (E'sign-3.20', E'ru', E'Обгон запрещён', E'Запрещает обгон всех механических транспортных средств (кроме транспортных средств, движущихся со скоростью менее 30 км/ч). Разрешается обгон мотоцикла без коляски, мопеда и велосипеда без выезда на полосу встречного движения. Действие знака распространяется от места установки соответствующего знака до ближайшего перекрёстка за ним, а в населённом пункте при отсутствии перекрёстка — до конца населённого пункта. Действие знака распространяется также на выезды с прилегающих территорий и на пересечения (примыкания) с полевыми, лесными и другими второстепенными дорогами, перед которыми не установлен соответствующий знак.', E'Обгон всех механических транспортных средств запрещён, кроме движущихся медленнее 30 км/ч. Обгонять мотоцикл без коляски, мопед и велосипед можно, если вы не выезжаете на встречную полосу. Знак действует от места установки до ближайшего перекрёстка, а в населённом пункте, если перекрёстка нет, — до конца населённого пункта. Выезды с прилегающей территории и примыкания полевых, лесных и других второстепенных дорог его действие не прерывают.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ru/card_5d838540df.webm'),
  (E'sign-3.21', E'en', E'End of no overtaking', E'End of the zone of road sign 3.20 (No overtaking).', E'This is the end of sign 3.20 (“No overtaking”).', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/en/card_429be77019.webm'),
  (E'sign-3.21', E'ka', E'გასწრების აკრძალვის დასასრული', E'3.20 საგზაო ნიშნის ( გასწრება აკრძალულია ) მოქმედების ზონის დასასრული.', E'აქ მთავრდება 3.20 ნიშნის („გასწრება აკრძალულია“) მოქმედება.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ka/card_9c16c61c3e.webm'),
  (E'sign-3.21', E'ru', E'Конец зоны запрещения обгона', E'Конец зоны действия дорожного знака 3.20 («Обгон запрещён»).', E'Здесь заканчивается действие знака 3.20 («Обгон запрещён»).', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ru/card_3c6b081cb7.webm'),
  (E'sign-3.22', E'en', E'No overtaking by goods vehicles', E'Prohibits goods vehicles with a maximum permitted mass of more than 3.5 tonnes from overtaking other vehicles (except vehicles travelling at less than 30 km/h), and also prohibits tractors from overtaking other vehicles (except animal-drawn vehicles and bicycles). The sign applies from the place where the relevant sign is placed to the nearest intersection after it, and in a built-up area where there is no intersection, to the end of the built-up area. The sign also applies at exits from adjacent areas and at intersections (junctions) with field, forest and other secondary roads in front of which no corresponding sign is placed.', E'Lorries with a maximum permitted mass over 3.5 tonnes may not overtake, except vehicles going slower than 30 km/h. Tractors may not overtake either, except horse-drawn vehicles and bicycles. The sign applies from where it stands to the nearest intersection; in a built-up area with no intersection, to the end of the built-up area. Exits from adjacent areas and junctions with field, forest or other minor roads do not end it.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/en/card_e224088f15.webm'),
  (E'sign-3.22', E'ka', E'სატვირთო ავტომობილით გასწრება აკრძალულია', E'კრძალავს 3,5 ტონაზე მეტი ნებადართული მაქსიმალური მასის მქონე სატვირთო ავტომობილით სხვა სატრანსპორტო საშუალების გასწრებას (გარდა 30 კმ/სთ-ზე ნაკლები სიჩქარით მოძრავი ტრანსპორტისა), აგრეთვე ტრაქტორით სხვა სატრანსპორტო საშუალების გასწრებას (გარდა საჭაპანო ტრანსპორტისა და ველოსიპედისა). ნიშნის მოქმედება ვრცელდება სათანადო ნიშნის შემდეგ, ნიშნის დადგმის ადგილიდან უახლოეს გზაჯვარედინამდე, ხოლო დასახლებულ პუნქტში გზაჯვარედინის არარსებობისას – დასახლებული პუნქტის ბოლომდე. ნიშნის მოქმედება ვრცელდება აგრეთვე მიმდებარე ტერიტორიის გამოსას¬ვლე¬ლთან, საველე, სატყეო და სხვა მეორეხარისხოვანი გზების გადაკვეთასთან (შეერთებასთან), რომელთა წინ არ დგას სათანადო ნიშანი.', E'3,5 ტონაზე მეტი ნებადართული მაქსიმალური მასის სატვირთო ავტომობილს გასწრება ეკრძალება, გარდა 30 კმ/სთ-ზე ნელა მოძრავი ტრანსპორტისა. ტრაქტორსაც ეკრძალება გასწრება, გარდა საჭაპანო ტრანსპორტისა და ველოსიპედისა. ნიშანი მოქმედებს დადგმის ადგილიდან უახლოეს გზაჯვარედინამდე, დასახლებულ პუნქტში კი, თუ გზაჯვარედინი არ არის, — დასახლებული პუნქტის ბოლომდე. მიმდებარე ტერიტორიიდან გამოსასვლელთან და მინდვრის, ტყის ან სხვა მეორეხარისხოვანი გზის შეერთებასთან ნიშნის მოქმედება არ წყდება.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ka/card_d261ba2e58.webm'),
  (E'sign-3.22', E'ru', E'Обгон грузовым автомобилям запрещён', E'Запрещает грузовым автомобилям с разрешённой максимальной массой более 3,5 тонны обгон других транспортных средств (кроме транспортных средств, движущихся со скоростью менее 30 км/ч), а также тракторам — обгон других транспортных средств (кроме гужевых повозок и велосипедов). Действие знака распространяется от места установки соответствующего знака до ближайшего перекрёстка за ним, а в населённом пункте при отсутствии перекрёстка — до конца населённого пункта. Действие знака распространяется также на выезды с прилегающих территорий и на пересечения (примыкания) с полевыми, лесными и другими второстепенными дорогами, перед которыми не установлен соответствующий знак.', E'Грузовым автомобилям с разрешённой максимальной массой более 3,5 тонны обгон запрещён, кроме транспорта, движущегося медленнее 30 км/ч. Тракторам обгон тоже запрещён, кроме гужевых повозок и велосипедов. Знак действует от места установки до ближайшего перекрёстка, а в населённом пункте, если перекрёстка нет, — до конца населённого пункта. Выезды с прилегающей территории и примыкания полевых, лесных и других второстепенных дорог его действие не прерывают.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ru/card_8384ca6aad.webm'),
  (E'sign-3.23', E'en', E'End of no overtaking by goods vehicles', E'End of the zone of road sign 3.22 (No overtaking by goods vehicles).', E'This is the end of sign 3.22 (“No overtaking for lorries”).', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/en/card_2e87d0743d.webm'),
  (E'sign-3.23', E'ka', E'სატვირთო ავტომობილით გასწრების აკრძალვის დასასრული', E'3.22 საგზაო ნიშნის ( სატვირთო ავტომობილით გასწრება აკრძალულია ) მოქმედების ზონის დასასრული.', E'აქ მთავრდება 3.22 ნიშნის („სატვირთო ავტომობილით გასწრება აკრძალულია“) მოქმედება.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ka/card_d468584c23.webm'),
  (E'sign-3.23', E'ru', E'Конец зоны запрещения обгона грузовым автомобилям', E'Конец зоны действия дорожного знака 3.22 («Обгон грузовым автомобилям запрещён»).', E'Здесь заканчивается действие знака 3.22 («Обгон грузовым автомобилям запрещён»).', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ru/card_b9eef6bf38.webm'),
  (E'sign-3.24', E'en', E'Maximum speed limit', E'Prohibits driving at a speed (km/h) higher than that shown on the sign. The sign applies from the place where the relevant sign is placed to the nearest intersection after it, and in a built-up area where there is no intersection, to the end of the built-up area. The sign also applies at exits from adjacent areas and at intersections (junctions) with field, forest and other secondary roads in front of which no corresponding sign is placed. Sign 3.24 placed before a built-up area designated by signs 5.23.1 and 5.23.2 applies, respectively, up to the signs 5.23.1 and 5.23.2 that mark the built-up area.', E'Driving faster than the speed on the sign (km/h) is banned. The sign applies from where it stands to the nearest intersection; in a built-up area with no intersection, to the end of the built-up area. Exits from adjacent areas and junctions with field, forest or other minor roads do not end it. If the sign stands before a built-up area, it applies up to sign 5.23.1 or 5.23.2 marking the built-up area.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/en/card_f3f708c2f9.webm'),
  (E'sign-3.24', E'ka', E'მაქსიმალური სიჩქარის შეზღუდვა', E'კრძალავს მოძრაობას ნიშანზე აღნიშნულზე მეტი სიჩქარით(კმ/სთ). ნიშნის მოქმედება ვრცელდება სათანადო ნიშნის შემდეგ, ნიშნის დადგმის ადგილიდან უახლოეს გზაჯვარედინამდე, ხოლო დასახლებულ პუნქტში გზაჯვარედინის არარსებობისას – დასახლებული პუნქტის ბოლომდე. ნიშნის მოქმედება ვრცელდება აგრეთვე მიმდებარე ტერიტორიის გამოსას¬ვლე¬ლთან, საველე, სატყეო და სხვა მეორეხარისხოვანი გზების გადაკვეთასთან (შეერთებასთან), რომელთა წინ არ დგას სათანადო ნიშანი. 5.23.1 და 5.23.2 ნიშნებით აღნიშნული დასახლებული პუნქტის წინ დადგმული 3.24 ნიშნის მოქმედება ვრცელდება შესაბამისად დასახლებული პუნქტის აღმნიშვნელ 5.23.1 და 5.23.2 ნიშნებამდე.', E'აკრძალულია ნიშანზე მითითებულზე მეტი სიჩქარით (კმ/სთ) მოძრაობა. ნიშანი მოქმედებს დადგმის ადგილიდან უახლოეს გზაჯვარედინამდე, დასახლებულ პუნქტში კი, თუ გზაჯვარედინი არ არის, — დასახლებული პუნქტის ბოლომდე. მიმდებარე ტერიტორიიდან გამოსასვლელთან და მინდვრის, ტყის ან სხვა მეორეხარისხოვანი გზის შეერთებასთან ნიშნის მოქმედება არ წყდება. თუ ნიშანი დასახლებული პუნქტის წინ დგას, ის მოქმედებს 5.23.1 ან 5.23.2 ნიშნამდე, რომელიც დასახლებულ პუნქტს აღნიშნავს.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ka/card_bb8065f988.webm'),
  (E'sign-3.24', E'ru', E'Ограничение максимальной скорости', E'Запрещает движение со скоростью (км/ч), превышающей указанную на знаке. Действие знака распространяется от места установки соответствующего знака до ближайшего перекрёстка за ним, а в населённом пункте при отсутствии перекрёстка — до конца населённого пункта. Действие знака распространяется также на выезды с прилегающих территорий и на пересечения (примыкания) с полевыми, лесными и другими второстепенными дорогами, перед которыми не установлен соответствующий знак. Действие знака 3.24, установленного перед населённым пунктом, обозначенным знаками 5.23.1 и 5.23.2, распространяется соответственно до знаков 5.23.1 и 5.23.2, обозначающих населённый пункт.', E'Запрещено двигаться со скоростью больше указанной на знаке (км/ч). Знак действует от места установки до ближайшего перекрёстка, а в населённом пункте, если перекрёстка нет, — до конца населённого пункта. Выезды с прилегающей территории и примыкания полевых, лесных и других второстепенных дорог его действие не прерывают. Если знак стоит перед населённым пунктом, он действует до знака 5.23.1 или 5.23.2, обозначающего населённый пункт.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ru/card_2b74581f2d.webm'),
  (E'sign-3.25', E'en', E'End of maximum speed limit', E'End of the zone of sign 3.24 (Maximum speed limit).', E'This is the end of sign 3.24 (“Maximum speed limit”).', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/en/card_e9bbf91b0c.webm'),
  (E'sign-3.25', E'ka', E'მაქსიმალური სიჩქარის შეზღუდვის დასასრული', E'3.24 ნიშნის ( მაქსიმალური სიჩქარის შეზღუდვა ) მოქმედების ზონის დასასრული.', E'აქ მთავრდება 3.24 ნიშნის („მაქსიმალური სიჩქარის შეზღუდვა“) მოქმედება.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ka/card_1f73fa55d9.webm'),
  (E'sign-3.25', E'ru', E'Конец зоны ограничения максимальной скорости', E'Конец зоны действия знака 3.24 («Ограничение максимальной скорости»).', E'Здесь заканчивается действие знака 3.24 («Ограничение максимальной скорости»).', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ru/card_fa939e2a3a.webm'),
  (E'sign-3.26', E'en', E'Use of horn prohibited', E'Prohibits the use of the horn, except when the signal is used to prevent a road traffic accident. The sign applies from the place where the relevant sign is placed to the nearest intersection after it, and in a built-up area where there is no intersection, to the end of the built-up area. The sign also applies at exits from adjacent areas and at intersections (junctions) with field, forest and other secondary roads in front of which no corresponding sign is placed.', E'Sounding the horn is banned, except when you need it to prevent a road accident. The sign applies from where it stands to the nearest intersection; in a built-up area with no intersection, to the end of the built-up area. Exits from adjacent areas and junctions with field, forest or other minor roads do not end it.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/en/card_38365bf0dd.webm'),
  (E'sign-3.26', E'ka', E'ხმოვანი სიგნალის მიცემა აკრძალულია', E'კრძალავს ხმოვანი სიგნალით სარგებლობას, გარდა იმ შემთხვევისა, როცა სიგნალი გამოიყენება საგზაო-სატრანსპორტო შემთხვევის თავიდან ასაცილებლად. ნიშნის მოქმედება ვრცელდება სათანადო ნიშნის შემდეგ, ნიშნის დადგმის ადგილიდან უახლოეს გზაჯვარედინამდე, ხოლო დასახლებულ პუნქტში გზაჯვარედინის არარსებობისას – დასახლებული პუნქტის ბოლომდე. ნიშნის მოქმედება ვრცელდება აგრეთვე მიმდებარე ტერიტორიის გამოსას¬ვლე¬ლთან, საველე, სატყეო და სხვა მეორეხარისხოვანი გზების გადაკვეთასთან (შეერთებასთან), რომელთა წინ არ დგას სათანადო ნიშანი.', E'ხმოვანი სიგნალის მიცემა აკრძალულია, გარდა იმ შემთხვევისა, როცა ის საგზაო-სატრანსპორტო შემთხვევის თავიდან ასაცილებლად გჭირდება. ნიშანი მოქმედებს დადგმის ადგილიდან უახლოეს გზაჯვარედინამდე, დასახლებულ პუნქტში კი, თუ გზაჯვარედინი არ არის, — დასახლებული პუნქტის ბოლომდე. მიმდებარე ტერიტორიიდან გამოსასვლელთან და მინდვრის, ტყის ან სხვა მეორეხარისხოვანი გზის შეერთებასთან ნიშნის მოქმედება არ წყდება.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ka/card_92a6455e10.webm'),
  (E'sign-3.26', E'ru', E'Подача звукового сигнала запрещена', E'Запрещает пользоваться звуковым сигналом, кроме случаев, когда сигнал подаётся для предотвращения дорожно-транспортного происшествия. Действие знака распространяется от места установки соответствующего знака до ближайшего перекрёстка за ним, а в населённом пункте при отсутствии перекрёстка — до конца населённого пункта. Действие знака распространяется также на выезды с прилегающих территорий и на пересечения (примыкания) с полевыми, лесными и другими второстепенными дорогами, перед которыми не установлен соответствующий знак.', E'Подавать звуковой сигнал запрещено, кроме случаев, когда он нужен, чтобы предотвратить дорожно-транспортное происшествие. Знак действует от места установки до ближайшего перекрёстка, а в населённом пункте, если перекрёстка нет, — до конца населённого пункта. Выезды с прилегающей территории и примыкания полевых, лесных и других второстепенных дорог его действие не прерывают.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ru/card_ce77bac827.webm'),
  (E'sign-3.27', E'en', E'No stopping', E'Prohibits both stopping and parking of vehicles. The sign does not apply to route vehicles. The sign applies from the place where the relevant sign is placed to the nearest intersection after it, and in a built-up area where there is no intersection, to the end of the built-up area. The sign also applies at exits from adjacent areas and at intersections (junctions) with field, forest and other secondary roads in front of which no corresponding sign is placed. The sign applies only to the side of the road on which it is placed.', E'Both stopping and parking are banned. The sign does not apply to route vehicles. The sign applies from where it stands to the nearest intersection; in a built-up area with no intersection, to the end of the built-up area. Exits from adjacent areas and junctions with field, forest or other minor roads do not end it. The sign applies only to the side of the road where it stands.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/en/card_61c103b971.webm'),
  (E'sign-3.27', E'ka', E'გაჩერება აკრძალულია', E'კრძალავს სატრანსპორტო საშუალების როგორც გაჩერებას, ისე დგომას. ნიშნის მოქმედება არ ვრცელდება სამარშრუტო სატრანსპორტო საშუალებაზე. ნიშნის მოქმედება ვრცელდება სათანადო ნიშნის შემდეგ, ნიშნის დადგმის ადგილიდან უახლოეს გზაჯვარედინამდე, ხოლო დასახლებულ პუნქტში გზაჯვარედინის არარსებობისას – დასახლებული პუნქტის ბოლომდე. ნიშნის მოქმედება ვრცელდება აგრეთვე მიმდებარე ტერიტორიის გამოსას¬ვლე¬ლთან, საველე, სატყეო და სხვა მეორეხარისხოვანი გზების გადაკვეთასთან (შეერთებასთან), რომელთა წინ არ დგას სათანადო ნიშანი. ნიშნის მოქმედება ვრცელდება მხოლოდ გზის იმ მხარეს, რომელზედაც იგია დადგმული.', E'აკრძალულია როგორც გაჩერება, ისე დგომა. სამარშრუტო ტრანსპორტზე ნიშანი არ ვრცელდება. ნიშანი მოქმედებს დადგმის ადგილიდან უახლოეს გზაჯვარედინამდე, დასახლებულ პუნქტში კი, თუ გზაჯვარედინი არ არის, — დასახლებული პუნქტის ბოლომდე. მიმდებარე ტერიტორიიდან გამოსასვლელთან და მინდვრის, ტყის ან სხვა მეორეხარისხოვანი გზის შეერთებასთან ნიშნის მოქმედება არ წყდება. ნიშანი მოქმედებს მხოლოდ გზის იმ მხარეს, სადაც დგას.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ka/card_a56453fb97.webm'),
  (E'sign-3.27', E'ru', E'Остановка запрещена', E'Запрещает как остановку, так и стоянку транспортных средств. Действие знака не распространяется на маршрутные транспортные средства. Действие знака распространяется от места установки соответствующего знака до ближайшего перекрёстка за ним, а в населённом пункте при отсутствии перекрёстка — до конца населённого пункта. Действие знака распространяется также на выезды с прилегающих территорий и на пересечения (примыкания) с полевыми, лесными и другими второстепенными дорогами, перед которыми не установлен соответствующий знак. Действие знака распространяется только на ту сторону дороги, на которой он установлен.', E'Запрещены и остановка, и стоянка. Знак не распространяется на маршрутные транспортные средства. Знак действует от места установки до ближайшего перекрёстка, а в населённом пункте, если перекрёстка нет, — до конца населённого пункта. Выезды с прилегающей территории и примыкания полевых, лесных и других второстепенных дорог его действие не прерывают. Знак действует только на той стороне дороги, где установлен.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ru/card_c00818bcbe.webm'),
  (E'sign-3.28', E'en', E'No parking', E'Prohibits parking of vehicles. The sign does not apply to postal vehicles that have a white diagonal stripe on a blue background on the body, or to taxis with the taximeter switched on. The sign does not apply to a vehicle driven by a person with the status of a significantly or severely expressed disability, or to a vehicle carrying such persons. The sign applies from the place where the relevant sign is placed to the nearest intersection after it, and in a built-up area where there is no intersection, to the end of the built-up area. The sign also applies at exits from adjacent areas and at intersections (junctions) with field, forest and other secondary roads in front of which no corresponding sign is placed. The sign applies only to the side of the road on which it is placed.', E'Parking is banned. The sign does not apply to a post vehicle (a white diagonal stripe on a blue background on its body) or to a taxi with its meter on. Nor does it apply to a vehicle driven by, or carrying, a person with a significant or severe disability. The sign applies from where it stands to the nearest intersection; in a built-up area with no intersection, to the end of the built-up area. Exits from adjacent areas and junctions with field, forest or other minor roads do not end it. The sign applies only to the side of the road where it stands.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/en/card_73254ecc3d.webm'),
  (E'sign-3.28', E'ka', E'დგომა აკრძალულია', E'კრძალავს სატრანსპორტო საშუალების დგომას. ნიშნის მოქმედება არ ვრცელდება საფოსტო ავტომობილზე, რომელსაც ძარაზე აქვს თეთრი დიაგონალური ზოლი ლურჯ ფონზე, აგრეთვე ტაქსიზე, რომელსაც ჩართული აქვს ტაქსომეტრი. ნიშნის მოქმედება არ ვრცელდება იმ სატრანსპორტო საშუალებაზე, რომელსაც მნიშვნელოვნად გამოხატული ან მკვეთრად გამოხატული შეზღუდული შესაძლებლობის სტატუსის მქონე პირი მართავს, ან იმ სატრანსპორტო საშუალებაზე, რომელსაც აღნიშნული პირები გადაჰყავს. ნიშნის მოქმედება ვრცელდება სათანადო ნიშნის შემდეგ, ნიშნის დადგმის ადგილიდან უახლოეს გზაჯვარედინამდე, ხოლო დასახლებულ პუნქტში გზაჯვარედინის არარსებობისას – დასახლებული პუნქტის ბოლომდე. ნიშნის მოქმედება ვრცელდება აგრეთვე მიმდებარე ტერიტორიის გამოსას¬ვლე¬ლთან, საველე, სატყეო და სხვა მეორეხარისხოვანი გზების გადაკვეთასთან (შეერთებასთან), რომელთა წინ არ დგას სათანადო ნიშანი. ნიშნის მოქმედება ვრცელდება მხოლოდ გზის იმ მხარეს, რომელზედაც იგია დადგმული.', E'დგომა აკრძალულია. ნიშანი არ ეხება საფოსტო ავტომობილს (ძარაზე ლურჯ ფონზე თეთრი დიაგონალური ზოლით) და ტაქსის, რომელსაც ტაქსომეტრი ჩართული აქვს. ნიშანი არც იმ სატრანსპორტო საშუალებას ეხება, რომელსაც მნიშვნელოვნად ან მკვეთრად გამოხატული შეზღუდული შესაძლებლობის სტატუსის მქონე პირი მართავს ან გადაჰყავს. ნიშანი მოქმედებს დადგმის ადგილიდან უახლოეს გზაჯვარედინამდე, დასახლებულ პუნქტში კი, თუ გზაჯვარედინი არ არის, — დასახლებული პუნქტის ბოლომდე. მიმდებარე ტერიტორიიდან გამოსასვლელთან და მინდვრის, ტყის ან სხვა მეორეხარისხოვანი გზის შეერთებასთან ნიშნის მოქმედება არ წყდება. ნიშანი მოქმედებს მხოლოდ გზის იმ მხარეს, სადაც დგას.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ka/card_1977b0348b.webm'),
  (E'sign-3.28', E'ru', E'Стоянка запрещена', E'Запрещает стоянку транспортных средств. Действие знака не распространяется на почтовые автомобили, имеющие на кузове белую диагональную полосу на синем фоне, а также на такси с включённым таксометром. Действие знака не распространяется на транспортное средство, которым управляет лицо со статусом значительно выраженного или резко выраженного ограничения возможностей, или на транспортное средство, перевозящее таких лиц. Действие знака распространяется от места установки соответствующего знака до ближайшего перекрёстка за ним, а в населённом пункте при отсутствии перекрёстка — до конца населённого пункта. Действие знака распространяется также на выезды с прилегающих территорий и на пересечения (примыкания) с полевыми, лесными и другими второстепенными дорогами, перед которыми не установлен соответствующий знак. Действие знака распространяется только на ту сторону дороги, на которой он установлен.', E'Стоянка запрещена. Знак не распространяется на почтовые автомобили (белая диагональная полоса на синем фоне на кузове) и на такси с включённым таксометром. Знак также не распространяется на транспортное средство, которым управляет или в котором перевозится лицо со значительно или резко выраженным ограничением возможностей. Знак действует от места установки до ближайшего перекрёстка, а в населённом пункте, если перекрёстка нет, — до конца населённого пункта. Выезды с прилегающей территории и примыкания полевых, лесных и других второстепенных дорог его действие не прерывают. Знак действует только на той стороне дороги, где установлен.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ru/card_7cd086fdef.webm'),
  (E'sign-3.29', E'en', E'No parking on odd-numbered days', E'Prohibits parking of vehicles on odd-numbered days of the month. When signs 3.29 and 3.30 are used together, the time for moving vehicles from one side of the road to the other is from 19:00 to 21:00. During this period parking is permitted on both sides of the carriageway. The sign does not apply to postal vehicles that have a white diagonal stripe on a blue background on the body, or to taxis with the taximeter switched on. The sign does not apply to a vehicle driven by a person with the status of a significantly or severely expressed disability, or to a vehicle carrying such persons. The sign applies from the place where the relevant sign is placed to the nearest intersection after it, and in a built-up area where there is no intersection, to the end of the built-up area. The sign also applies at exits from adjacent areas and at intersections (junctions) with field, forest and other secondary roads in front of which no corresponding sign is placed. The sign applies only to the side of the road on which it is placed.', E'Parking is banned on odd days of the month. If signs 3.29 and 3.30 stand together, vehicles are moved from one side of the road to the other between 19:00 and 21:00, and during that time parking is allowed on both sides. Exceptions, reach and side are the same as for sign 3.28.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/en/card_a144181186.webm'),
  (E'sign-3.29', E'ka', E'დგომა აკრძალულია კენტ რიცხვებში', E'კრძალავს სატრანსპორტო საშუალების დგომას თვის კენტ რიცხვებში. 3.29 და 3.30 ნიშნების ერთდროულად გამოყენებისას სატრანსპორტო საშუალების გზის ერთი მხრიდან მეორეზე გადაყენების დროა 19-დან 21 საათამდე. ამ პერიოდში დგომა ნებადართულია სავალი ნაწილის ორივე მხარეს. ნიშნის მოქმედება არ ვრცელდება საფოსტო ავტომობილზე, რომელსაც ძარაზე აქვს თეთრი დიაგონალური ზოლი ლურჯ ფონზე, აგრეთვე ტაქსიზე, რომელსაც ჩართული აქვს ტაქსომეტრი. ნიშნის მოქმედება არ ვრცელდება იმ სატრანსპორტო საშუალებაზე, რომელსაც მნიშვნელოვნად გამოხატული ან მკვეთრად გამოხატული შეზღუდული შესაძლებლობის სტატუსის მქონე პირი მართავს, ან იმ სატრანსპორტო საშუალებაზე, რომელსაც აღნიშნული პირები გადაჰყავს. ნიშნის მოქმედება ვრცელდება სათანადო ნიშნის შემდეგ, ნიშნის დადგმის ადგილიდან უახლოეს გზაჯვარედინამდე, ხოლო დასახლებულ პუნქტში გზაჯვარედინის არარსებობისას – დასახლებული პუნქტის ბოლომდე. ნიშნის მოქმედება ვრცელდება აგრეთვე მიმდებარე ტერიტორიის გამოსას¬ვლე¬ლთან, საველე, სატყეო და სხვა მეორეხარისხოვანი გზების გადაკვეთასთან (შეერთებასთან), რომელთა წინ არ დგას სათანადო ნიშანი. ნიშნის მოქმედება ვრცელდება მხოლოდ გზის იმ მხარეს, რომელზედაც იგია დადგმული.', E'დგომა აკრძალულია თვის კენტ რიცხვებში. თუ 3.29 და 3.30 ნიშნები ერთად დგას, 19-დან 21 საათამდე სატრანსპორტო საშუალება გზის ერთი მხრიდან მეორეზე გადაყავთ და ამ დროს დგომა ორივე მხარეს შეიძლება. გამონაკლისები, მოქმედების ზონა და მხარე იგივეა, რაც 3.28 ნიშნისა.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ka/card_89d16bebb1.webm'),
  (E'sign-3.29', E'ru', E'Стоянка запрещена по нечётным числам месяца', E'Запрещает стоянку транспортных средств по нечётным числам месяца. При одновременном применении знаков 3.29 и 3.30 время перестановки транспортных средств с одной стороны дороги на другую — с 19 до 21 часа. В этот период стоянка разрешена по обеим сторонам проезжей части. Действие знака не распространяется на почтовые автомобили, имеющие на кузове белую диагональную полосу на синем фоне, а также на такси с включённым таксометром. Действие знака не распространяется на транспортное средство, которым управляет лицо со статусом значительно выраженного или резко выраженного ограничения возможностей, или на транспортное средство, перевозящее таких лиц. Действие знака распространяется от места установки соответствующего знака до ближайшего перекрёстка за ним, а в населённом пункте при отсутствии перекрёстка — до конца населённого пункта. Действие знака распространяется также на выезды с прилегающих территорий и на пересечения (примыкания) с полевыми, лесными и другими второстепенными дорогами, перед которыми не установлен соответствующий знак. Действие знака распространяется только на ту сторону дороги, на которой он установлен.', E'Стоянка запрещена по нечётным числам месяца. Если знаки 3.29 и 3.30 стоят вместе, с 19 до 21 часа транспортные средства переставляют с одной стороны дороги на другую, и в это время стоянка разрешена с обеих сторон. Исключения, зона действия и сторона — те же, что у знака 3.28.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ru/card_b51e3ed3ad.webm'),
  (E'sign-3.3', E'en', E'No motor vehicles', E'Prohibits the movement of all motor vehicles. The sign indicates that traffic is prohibited in both directions. The sign does not apply to route vehicles. The sign does not apply to vehicles serving an enterprise located in the designated zone, or serving or belonging to a person who lives or works in that zone. In this case, the vehicle enters the designated zone and leaves it at the intersection nearest to its destination. The sign does not apply to a vehicle driven by a person with the status of a significantly or severely expressed disability, or to a vehicle carrying such persons.', E'All motor vehicles are banned, in both directions. The sign does not apply to route vehicles. The sign does not apply to vehicles serving a business in the zone, or serving or owned by people who live or work there: such vehicles enter and leave the zone at the intersection nearest to their destination. Nor does it apply to a vehicle driven by, or carrying, a person with a significant or severe disability.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/en/card_430384a9d6.webm'),
  (E'sign-3.3', E'ka', E'მექანიკური სატრანსპორტო საშუალებით მოძრაობა აკრძალულია', E'კრძალავს ყველა სახის მექანიკური სატრანსპორტო საშუალებით მოძრაობას. ნიშანი მიუთითებს, რომ მოძრაობა ორივე მიმართულებით აკრძალულია. ნიშნის მოქმედება არ ვრცელდება სამარშრუტო სატრანსპორტო საშუალებაზე. ნიშნის მოქმედება არ ვრცელდება სატრანსპორტო საშუალებაზე, რომელიც ემსახურება აღნიშნულ ზონაში მდებარე საწარმოს, ანდა ემსახურება ან ეკუთვნის ამავე ზონაში მცხოვრებ ან მომუშავე პირს. ამ შემთხვევაში სატრანსპორტო საშუალება შედის აღნიშნულ ზონაში და გამოდის იქიდან დანიშნულების ადგილისაკენ უახლოეს გზაჯვარედინზე. ნიშნის მოქმედება არ ვრცელდება იმ სატრანსპორტო საშუალებაზე, რომელსაც მნიშვნელოვნად გამოხატული ან მკვეთრად გამოხატული შეზღუდული შესაძლებლობის სტატუსის მქონე პირი მართავს, ან იმ სატრანსპორტო საშუალებაზე, რომელსაც აღნიშნული პირები გადაჰყავს.', E'აკრძალულია ყველა მექანიკური სატრანსპორტო საშუალებით მოძრაობა, ორივე მიმართულებით. სამარშრუტო ტრანსპორტზე ნიშანი არ ვრცელდება. ნიშანი არ ეხება სატრანსპორტო საშუალებას, რომელიც ზონაში მდებარე საწარმოს ემსახურება, ან ზონაში მცხოვრებ თუ მომუშავე ადამიანს ემსახურება ან ეკუთვნის: ასეთი სატრანსპორტო საშუალება ზონაში დანიშნულების ადგილთან უახლოესი გზაჯვარედინიდან შედის და გამოდის. ნიშანი არც იმ სატრანსპორტო საშუალებას ეხება, რომელსაც მნიშვნელოვნად ან მკვეთრად გამოხატული შეზღუდული შესაძლებლობის სტატუსის მქონე პირი მართავს ან გადაჰყავს.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ka/card_24bde86f05.webm'),
  (E'sign-3.3', E'ru', E'Движение механических транспортных средств запрещено', E'Запрещает движение всех механических транспортных средств. Знак указывает, что движение запрещено в обоих направлениях. Действие знака не распространяется на маршрутные транспортные средства. Действие знака не распространяется на транспортные средства, обслуживающие предприятие, расположенное в обозначенной зоне, а также обслуживающие лицо, проживающее или работающее в этой зоне, или принадлежащие такому лицу. В этом случае транспортное средство въезжает в обозначенную зону и выезжает из неё на ближайшем к месту назначения перекрёстке. Действие знака не распространяется на транспортное средство, которым управляет лицо со статусом значительно выраженного или резко выраженного ограничения возможностей, или на транспортное средство, перевозящее таких лиц.', E'Движение всех механических транспортных средств запрещено в обоих направлениях. Знак не распространяется на маршрутные транспортные средства. Знак не распространяется на транспортные средства, которые обслуживают предприятие в зоне, обслуживают людей, живущих или работающих в зоне, или принадлежат им: такие транспортные средства въезжают в зону и выезжают из неё на перекрёстке, ближайшем к месту назначения. Знак также не распространяется на транспортное средство, которым управляет или в котором перевозится лицо со значительно или резко выраженным ограничением возможностей.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ru/card_7568410e92.webm'),
  (E'sign-3.30', E'en', E'No parking on even-numbered days', E'Prohibits parking of vehicles on even-numbered days of the month. When signs 3.29 and 3.30 are used together, the time for moving vehicles from one side of the road to the other is from 19:00 to 21:00. During this period parking is permitted on both sides of the carriageway. The sign does not apply to postal vehicles that have a white diagonal stripe on a blue background on the body, or to taxis with the taximeter switched on. The sign does not apply to a vehicle driven by a person with the status of a significantly or severely expressed disability, or to a vehicle carrying such persons. The sign applies from the place where the relevant sign is placed to the nearest intersection after it, and in a built-up area where there is no intersection, to the end of the built-up area. The sign also applies at exits from adjacent areas and at intersections (junctions) with field, forest and other secondary roads in front of which no corresponding sign is placed. The sign applies only to the side of the road on which it is placed.', E'Parking is banned on even days of the month. If signs 3.29 and 3.30 stand together, vehicles are moved from one side of the road to the other between 19:00 and 21:00, and during that time parking is allowed on both sides. Exceptions, reach and side are the same as for sign 3.28.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/en/card_e013fe6c4c.webm'),
  (E'sign-3.30', E'ka', E'დგომა აკრძალულია ლუწ რიცხვებში', E'კრძალავს სატრანსპორტო საშუალების დგომას თვის ლუწ რიცხვებში. 3.29 და 3.30 ნიშნების ერთდროულად გამოყენებისას სატრანსპორტო საშუალების გზის ერთი მხრიდან მეორეზე გადაყენების დროა 19-დან 21 საათამდე. ამ პერიოდში დგომა ნებადართულია სავალი ნაწილის ორივე მხარეს. ნიშნის მოქმედება არ ვრცელდება საფოსტო ავტომობილზე, რომელსაც ძარაზე აქვს თეთრი დიაგონალური ზოლი ლურჯ ფონზე, აგრეთვე ტაქსიზე, რომელსაც ჩართული აქვს ტაქსომეტრი. ნიშნის მოქმედება არ ვრცელდება იმ სატრანსპორტო საშუალებაზე, რომელსაც მნიშვნელოვნად გამოხატული ან მკვეთრად გამოხატული შეზღუდული შესაძლებლობის სტატუსის მქონე პირი მართავს, ან იმ სატრანსპორტო საშუალებაზე, რომელსაც აღნიშნული პირები გადაჰყავს. ნიშნის მოქმედება ვრცელდება სათანადო ნიშნის შემდეგ, ნიშნის დადგმის ადგილიდან უახლოეს გზაჯვარედინამდე, ხოლო დასახლებულ პუნქტში გზაჯვარედინის არარსებობისას – დასახლებული პუნქტის ბოლომდე. ნიშნის მოქმედება ვრცელდება აგრეთვე მიმდებარე ტერიტორიის გამოსას¬ვლე¬ლთან, საველე, სატყეო და სხვა მეორეხარისხოვანი გზების გადაკვეთასთან (შეერთებასთან), რომელთა წინ არ დგას სათანადო ნიშანი. ნიშნის მოქმედება ვრცელდება მხოლოდ გზის იმ მხარეს, რომელზედაც იგია დადგმული.', E'დგომა აკრძალულია თვის ლუწ რიცხვებში. თუ 3.29 და 3.30 ნიშნები ერთად დგას, 19-დან 21 საათამდე სატრანსპორტო საშუალება გზის ერთი მხრიდან მეორეზე გადაყავთ და ამ დროს დგომა ორივე მხარეს შეიძლება. გამონაკლისები, მოქმედების ზონა და მხარე იგივეა, რაც 3.28 ნიშნისა.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ka/card_e242924615.webm'),
  (E'sign-3.30', E'ru', E'Стоянка запрещена по чётным числам месяца', E'Запрещает стоянку транспортных средств по чётным числам месяца. При одновременном применении знаков 3.29 и 3.30 время перестановки транспортных средств с одной стороны дороги на другую — с 19 до 21 часа. В этот период стоянка разрешена по обеим сторонам проезжей части. Действие знака не распространяется на почтовые автомобили, имеющие на кузове белую диагональную полосу на синем фоне, а также на такси с включённым таксометром. Действие знака не распространяется на транспортное средство, которым управляет лицо со статусом значительно выраженного или резко выраженного ограничения возможностей, или на транспортное средство, перевозящее таких лиц. Действие знака распространяется от места установки соответствующего знака до ближайшего перекрёстка за ним, а в населённом пункте при отсутствии перекрёстка — до конца населённого пункта. Действие знака распространяется также на выезды с прилегающих территорий и на пересечения (примыкания) с полевыми, лесными и другими второстепенными дорогами, перед которыми не установлен соответствующий знак. Действие знака распространяется только на ту сторону дороги, на которой он установлен.', E'Стоянка запрещена по чётным числам месяца. Если знаки 3.29 и 3.30 стоят вместе, с 19 до 21 часа транспортные средства переставляют с одной стороны дороги на другую, и в это время стоянка разрешена с обеих сторон. Исключения, зона действия и сторона — те же, что у знака 3.28.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ru/card_bc777339ca.webm'),
  (E'sign-3.31', E'en', E'End of all restrictions', E'End of the zone of several of signs 3.16, 3.20, 3.22, 3.24, 3.26–3.30 at the same time.', E'Several signs end here at once: 3.16, 3.20, 3.22, 3.24, 3.26–3.30.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/en/card_844b44920b.webm'),
  (E'sign-3.31', E'ka', E'ყველა შეზღუდვის ზონის დასასრული', E'3.16, 3.20, 3.22, 3.24, 3.26–3.30 ნიშნებიდან ერთდროულად რამდენიმე ნიშნის მოქმე­დების ზონის დასასრული.', E'აქ ერთად მთავრდება რამდენიმე ნიშნის მოქმედება: 3.16, 3.20, 3.22, 3.24, 3.26–3.30.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ka/card_0740e3d6eb.webm'),
  (E'sign-3.31', E'ru', E'Конец зоны всех ограничений', E'Конец зоны действия одновременно нескольких знаков из следующих: 3.16, 3.20, 3.22, 3.24, 3.26–3.30.', E'Здесь одновременно заканчивается действие нескольких знаков: 3.16, 3.20, 3.22, 3.24, 3.26–3.30.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ru/card_324a932c25.webm'),
  (E'sign-3.32', E'en', E'No vehicles carrying dangerous goods', E'Prohibits the movement of vehicles carrying dangerous goods which, under the legislation of Georgia, must be marked with the corresponding identification sign. The sign indicates that traffic is prohibited in both directions.\nThe sign is placed to prevent vehicles carrying dangerous, explosive and highly flammable goods from deviating from the route designated for them, and also to prohibit such vehicles from entering a road or area where they pose a particular danger to people.', E'Vehicles carrying dangerous goods, which by law must have an identification sign, are banned. Traffic is banned in both directions. The sign keeps such vehicles on their route and out of roads or areas where they would put people in special danger.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/en/card_e57a727971.webm'),
  (E'sign-3.32', E'ka', E'სახიფათო ტვირთის გადამზიდავი სატრანსპორტო საშუალებით მოძრაობა აკრძალულია', E'კრძალავს იმ სახიფათო ტვირთის გადამზიდავი სატრანსპორტო საშუალებით მოძრაობას, რომელიც საქართველოს კანონმდებლობის თანახმად, აღნიშნული უნდა იყოს შესაბამისი საცნობი ნიშნით. ნიშანი მიუთითებს, რომ მოძრაობა ორივე მიმართულებით აკრძალულია.\nნიშანი იდგმება სახიფათო, ფეთქებადი და ადვილად აალებადი ტვირთის გადამზიდავი სატრანსპორტო საშუალებებისათვის განკუთვნილი მარშრუტიდან გადახვევის თავიდან ასაცილებლად, აგრეთვე მითითებული სატრანსპორტო საშუალებებით ისეთ გზაზე ან რაიონში შესვლის აკრძალვისათვის, სადაც ისინი განსაკუთრებულ საფრთხეს უქმნიან ადამიანებს.', E'აკრძალულია მოძრაობა სახიფათო ტვირთის გადამზიდავი სატრანსპორტო საშუალებით, რომელსაც კანონის მიხედვით საცნობი ნიშანი უნდა ჰქონდეს. მოძრაობა აკრძალულია ორივე მიმართულებით. ნიშანი დგას, რომ ასეთმა სატრანსპორტო საშუალებამ თავის მარშრუტს არ გადაუხვიოს, ან ისეთ გზაზე ან რაიონში არ შევიდეს, სადაც ადამიანებს განსაკუთრებულ საფრთხეს შეუქმნის.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ka/card_6f58e93d60.webm'),
  (E'sign-3.32', E'ru', E'Движение транспортных средств с опасными грузами запрещено', E'Запрещает движение транспортных средств, перевозящих опасные грузы, которые в соответствии с законодательством Грузии должны быть обозначены соответствующим опознавательным знаком. Знак указывает, что движение запрещено в обоих направлениях.\nЗнак устанавливается для предотвращения отклонения транспортных средств, перевозящих опасные, взрывчатые и легковоспламеняющиеся грузы, от предназначенного для них маршрута, а также для запрещения въезда указанных транспортных средств на дорогу или в район, где они создают особую опасность для людей.', E'Запрещено движение транспортных средств, перевозящих опасные грузы, которые по закону должны иметь опознавательный знак. Движение запрещено в обоих направлениях. Знак ставят, чтобы такие транспортные средства не отклонялись от маршрута и не въезжали на дороги или в районы, где создадут особую опасность для людей.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ru/card_92e2fa76a9.webm'),
  (E'sign-3.33', E'en', E'No vehicles carrying explosive and flammable goods', E'Prohibits the movement of vehicles carrying explosive and highly flammable goods of classes 1.22–2.4, 3.1, 3.2, 5.2 as defined by state standard 19433-88, which, under the legislation of Georgia, must be marked with the identification sign “Dangerous goods”. The sign indicates that traffic is prohibited in both directions.\nThe sign is placed to prevent vehicles carrying dangerous, explosive and highly flammable goods from deviating from the route designated for them, and also to prohibit such vehicles from entering a road or area where they pose a particular danger to people.', E'Vehicles carrying explosive and easily flammable goods (classes 1.22–2.4, 3.1, 3.2 and 5.2 of state standard 19433-88), which must have the “Dangerous goods” identification sign, are banned. Traffic is banned in both directions. The sign keeps such vehicles on their route and out of roads or areas where they would put people in special danger.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/en/card_9c99a6f627.webm'),
  (E'sign-3.33', E'ka', E'ფეთქებადი და ადვილად აალებადი ტვირთის გადამზიდავი სატრანსპორტო საშუალებით მოძრაობა აკრძალულია', E'კრძალავს 19433-88 სახელმწიფო სტანდარტით განსაზღვრული, 1.22–2.4, 3.1, 3.2, 5.2 კლასის ფეთქებადი და ადვილად აალებადი ტვირთის გადამზიდავი სატრანსპორტო საშუალებით მოძრაობას, რომელიც,საქართველოს კანონმდებლობის თანახმად, აღნიშნული უნდა იყოს საცნობი ნიშნით სახიფათო ტვირთი. ნიშანი მიუთითებს, რომ მოძრაობა ორივე მიმართულებით აკრძალულია.\nნიშანი იდგმება სახიფათო, ფეთქებადი და ადვილად აალებადი ტვირთის გადამზიდავი სატრანსპორტო საშუალებებისათვის განკუთვნილი მარშრუტიდან გადახვევის თავიდან ასაცილებლად, აგრეთვე მითითებული სატრანსპორტო საშუალებებით ისეთ გზაზე ან რაიონში შესვლის აკრძალვისათვის, სადაც ისინი განსაკუთრებულ საფრთხეს უქმნიან ადამიანებს.', E'აკრძალულია მოძრაობა ფეთქებადი და ადვილად აალებადი ტვირთის გადამზიდავი სატრანსპორტო საშუალებით (19433-88 სახელმწიფო სტანდარტის 1.22–2.4, 3.1, 3.2 და 5.2 კლასები), რომელსაც საცნობი ნიშანი „სახიფათო ტვირთი“ უნდა ჰქონდეს. მოძრაობა აკრძალულია ორივე მიმართულებით. ნიშანი დგას, რომ ასეთმა სატრანსპორტო საშუალებამ თავის მარშრუტს არ გადაუხვიოს, ან ისეთ გზაზე ან რაიონში არ შევიდეს, სადაც ადამიანებს განსაკუთრებულ საფრთხეს შეუქმნის.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ka/card_3816741ba4.webm'),
  (E'sign-3.33', E'ru', E'Движение транспортных средств с взрывчатыми и легковоспламеняющимися грузами запрещено', E'Запрещает движение транспортных средств, перевозящих взрывчатые и легковоспламеняющиеся грузы классов 1.22–2.4, 3.1, 3.2, 5.2, определённых государственным стандартом 19433-88, которые в соответствии с законодательством Грузии должны быть обозначены опознавательным знаком «Опасный груз». Знак указывает, что движение запрещено в обоих направлениях.\nЗнак устанавливается для предотвращения отклонения транспортных средств, перевозящих опасные, взрывчатые и легковоспламеняющиеся грузы, от предназначенного для них маршрута, а также для запрещения въезда указанных транспортных средств на дорогу или в район, где они создают особую опасность для людей.', E'Запрещено движение транспортных средств, перевозящих взрывчатые и легковоспламеняющиеся грузы (классы 1.22–2.4, 3.1, 3.2 и 5.2 государственного стандарта 19433-88), которые должны иметь опознавательный знак «Опасный груз». Движение запрещено в обоих направлениях. Знак ставят, чтобы такие транспортные средства не отклонялись от маршрута и не въезжали на дороги или в районы, где создадут особую опасность для людей.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ru/card_59c8269c23.webm'),
  (E'sign-3.4', E'en', E'No goods vehicles', E'Prohibits the movement of vehicles and combinations of vehicles whose maximum permitted mass exceeds the maximum permitted mass limit shown on the sign. The sign indicates that traffic is prohibited in both directions. The sign does not apply to vehicles serving an enterprise located in the designated zone, or serving or belonging to a person who lives or works in that zone. In this case, the vehicle enters the designated zone and leaves it at the intersection nearest to its destination.', E'A vehicle or combination whose maximum permitted mass is more than shown on the sign may not go on. Traffic is banned in both directions. The sign does not apply to vehicles serving a business in the zone, or serving or owned by people who live or work there: such vehicles enter and leave the zone at the intersection nearest to their destination.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/en/card_f53b4391c6.webm'),
  (E'sign-3.4', E'ka', E'სატვირთომოძრაობა აკრძალულია', E'კრძალავს იმ სატრანსპორტო საშუალებით და სატრანსპორტო საშუალებათა შემადგენლობით მოძრაობას, რომელთა ნებადართული მაქსიმალური მასა აღემატება ნიშანზე აღნიშნულ ნებადართული მაქსიმალური მასის ზღვარს. ნიშანი მიუთითებს, რომ მოძრაობა ორივე მიმართულებით აკრძალულია. ნიშნის მოქმედება არ ვრცელდება სატრანსპორტო საშუალებაზე, რომელიც ემსახურება აღნიშნულ ზონაში მდებარე საწარმოს, ანდა ემსახურება ან ეკუთვნის ამავე ზონაში მცხოვრებ ან მომუშავე პირს. ამ შემთხვევაში სატრანსპორტო საშუალება შედის აღნიშნულ ზონაში და გამოდის იქიდან დანიშნულების ადგილისაკენ უახლოეს გზაჯვარედინზე.', E'აკრძალულია სატრანსპორტო საშუალებით ან შემადგენლობით მოძრაობა, თუ მისი ნებადართული მაქსიმალური მასა ნიშანზე მითითებულს აღემატება. მოძრაობა აკრძალულია ორივე მიმართულებით. ნიშანი არ ეხება სატრანსპორტო საშუალებას, რომელიც ზონაში მდებარე საწარმოს ემსახურება, ან ზონაში მცხოვრებ თუ მომუშავე ადამიანს ემსახურება ან ეკუთვნის: ასეთი სატრანსპორტო საშუალება ზონაში დანიშნულების ადგილთან უახლოესი გზაჯვარედინიდან შედის და გამოდის.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ka/card_42f66ee07b.webm'),
  (E'sign-3.4', E'ru', E'Движение грузовых автомобилей запрещено', E'Запрещает движение транспортных средств и составов транспортных средств, разрешённая максимальная масса которых превышает указанный на знаке предел разрешённой максимальной массы. Знак указывает, что движение запрещено в обоих направлениях. Действие знака не распространяется на транспортные средства, обслуживающие предприятие, расположенное в обозначенной зоне, а также обслуживающие лицо, проживающее или работающее в этой зоне, или принадлежащие такому лицу. В этом случае транспортное средство въезжает в обозначенную зону и выезжает из неё на ближайшем к месту назначения перекрёстке.', E'Движение транспортного средства или состава запрещено, если его разрешённая максимальная масса больше указанной на знаке. Движение запрещено в обоих направлениях. Знак не распространяется на транспортные средства, которые обслуживают предприятие в зоне, обслуживают людей, живущих или работающих в зоне, или принадлежат им: такие транспортные средства въезжают в зону и выезжают из неё на перекрёстке, ближайшем к месту назначения.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ru/card_47d0593606.webm'),
  (E'sign-3.5', E'en', E'No motorcycles', E'Prohibits the movement of all motorcycles. The sign indicates that traffic is prohibited in both directions. The sign does not apply to vehicles serving an enterprise located in the designated zone, or serving or belonging to a person who lives or works in that zone. In this case, the vehicle enters the designated zone and leaves it at the intersection nearest to its destination.', E'Motorcycles of all kinds are banned. Traffic is banned in both directions. The sign does not apply to vehicles serving a business in the zone, or serving or owned by people who live or work there: such vehicles enter and leave the zone at the intersection nearest to their destination.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/en/card_d1169dcaa7.webm'),
  (E'sign-3.5', E'ka', E'მოტოციკლით მოძრაობა აკრძალულია', E'კრძალავს ყველა სახის მოტოციკლით მოძრაობას. ნიშანი მიუთითებს, რომ მოძრაობა ორივე მიმართულებით აკრძალულია. ნიშნის მოქმედება არ ვრცელდება სატრანსპორტო საშუალებაზე, რომელიც ემსახურება აღნიშნულ ზონაში მდებარე საწარმოს, ანდა ემსახურება ან ეკუთვნის ამავე ზონაში მცხოვრებ ან მომუშავე პირს. ამ შემთხვევაში სატრანსპორტო საშუალება შედის აღნიშნულ ზონაში და გამოდის იქიდან დანიშნულების ადგილისაკენ უახლოეს გზაჯვარედინზე.', E'აკრძალულია ყველა სახის მოტოციკლით მოძრაობა. მოძრაობა აკრძალულია ორივე მიმართულებით. ნიშანი არ ეხება სატრანსპორტო საშუალებას, რომელიც ზონაში მდებარე საწარმოს ემსახურება, ან ზონაში მცხოვრებ თუ მომუშავე ადამიანს ემსახურება ან ეკუთვნის: ასეთი სატრანსპორტო საშუალება ზონაში დანიშნულების ადგილთან უახლოესი გზაჯვარედინიდან შედის და გამოდის.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ka/card_124c79d40f.webm'),
  (E'sign-3.5', E'ru', E'Движение мотоциклов запрещено', E'Запрещает движение всех мотоциклов. Знак указывает, что движение запрещено в обоих направлениях. Действие знака не распространяется на транспортные средства, обслуживающие предприятие, расположенное в обозначенной зоне, а также обслуживающие лицо, проживающее или работающее в этой зоне, или принадлежащие такому лицу. В этом случае транспортное средство въезжает в обозначенную зону и выезжает из неё на ближайшем к месту назначения перекрёстке.', E'Движение мотоциклов всех видов запрещено. Движение запрещено в обоих направлениях. Знак не распространяется на транспортные средства, которые обслуживают предприятие в зоне, обслуживают людей, живущих или работающих в зоне, или принадлежат им: такие транспортные средства въезжают в зону и выезжают из неё на перекрёстке, ближайшем к месту назначения.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ru/card_e57f41b765.webm'),
  (E'sign-3.6', E'en', E'No tractors', E'Prohibits the movement of all tractors and self-propelled specialised machines. The sign indicates that traffic is prohibited in both directions. The sign does not apply to vehicles serving an enterprise located in the designated zone, or serving or belonging to a person who lives or works in that zone. In this case, the vehicle enters the designated zone and leaves it at the intersection nearest to its destination.', E'Tractors and self-propelled machines are banned. Traffic is banned in both directions. The sign does not apply to vehicles serving a business in the zone, or serving or owned by people who live or work there: such vehicles enter and leave the zone at the intersection nearest to their destination.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/en/card_c56f7312fe.webm'),
  (E'sign-3.6', E'ka', E'ტრაქტორით მოძრაობა აკრძალულია', E'კრძალავს ყველა სახის ტრაქტორითა და სპეციალიზებული თვითმავალი მანქანით მოძრაობას. ნიშანი მიუთითებს, რომ მოძრაობა ორივე მიმართულებით აკრძალულია. ნიშნის მოქმედება არ ვრცელდება სატრანსპორტო საშუალებაზე, რომელიც ემსახურება აღნიშნულ ზონაში მდებარე საწარმოს, ანდა ემსახურება ან ეკუთვნის ამავე ზონაში მცხოვრებ ან მომუშავე პირს. ამ შემთხვევაში სატრანსპორტო საშუალება შედის აღნიშნულ ზონაში და გამოდის იქიდან დანიშნულების ადგილისაკენ უახლოეს გზაჯვარედინზე.', E'აკრძალულია ტრაქტორით და სპეციალიზებული თვითმავალი მანქანით მოძრაობა. მოძრაობა აკრძალულია ორივე მიმართულებით. ნიშანი არ ეხება სატრანსპორტო საშუალებას, რომელიც ზონაში მდებარე საწარმოს ემსახურება, ან ზონაში მცხოვრებ თუ მომუშავე ადამიანს ემსახურება ან ეკუთვნის: ასეთი სატრანსპორტო საშუალება ზონაში დანიშნულების ადგილთან უახლოესი გზაჯვარედინიდან შედის და გამოდის.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ka/card_b8c7e6ace0.webm'),
  (E'sign-3.6', E'ru', E'Движение тракторов запрещено', E'Запрещает движение всех тракторов и специализированных самоходных машин. Знак указывает, что движение запрещено в обоих направлениях. Действие знака не распространяется на транспортные средства, обслуживающие предприятие, расположенное в обозначенной зоне, а также обслуживающие лицо, проживающее или работающее в этой зоне, или принадлежащие такому лицу. В этом случае транспортное средство въезжает в обозначенную зону и выезжает из неё на ближайшем к месту назначения перекрёстке.', E'Движение тракторов и самоходных машин запрещено. Движение запрещено в обоих направлениях. Знак не распространяется на транспортные средства, которые обслуживают предприятие в зоне, обслуживают людей, живущих или работающих в зоне, или принадлежат им: такие транспортные средства въезжают в зону и выезжают из неё на перекрёстке, ближайшем к месту назначения.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ru/card_a26bf88a7a.webm'),
  (E'sign-3.7', E'en', E'No vehicles with trailers', E'Prohibits the movement of all lorries with trailers and tractors with trailers, as well as the towing of motor vehicles. The sign indicates that traffic is prohibited in both directions. The sign does not apply to vehicles serving an enterprise located in the designated zone, or serving or belonging to a person who lives or works in that zone. In this case, the vehicle enters the designated zone and leaves it at the intersection nearest to its destination.', E'Lorries and tractors with a trailer are banned, and so is towing a motor vehicle. Traffic is banned in both directions. The sign does not apply to vehicles serving a business in the zone, or serving or owned by people who live or work there: such vehicles enter and leave the zone at the intersection nearest to their destination.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/en/card_a9dea8c7cc.webm'),
  (E'sign-3.7', E'ka', E'მისაბმელით მოძრაობა აკრძალულია', E'კრძალავს ყველა სახის მისაბმელიანი სატვირთო ავტომობილითა და მისაბმელიანი ტრაქტორით მოძრაობას, აგრეთვე მექანიკური სატრანსპორტო საშუალების ბუქსირებას. ნიშანი მიუთითებს, რომ მოძრაობა ორივე მიმართულებით აკრძალულია. ნიშნის მოქმედება არ ვრცელდება სატრანსპორტო საშუალებაზე, რომელიც ემსახურება აღნიშნულ ზონაში მდებარე საწარმოს, ანდა ემსახურება ან ეკუთვნის ამავე ზონაში მცხოვრებ ან მომუშავე პირს. ამ შემთხვევაში სატრანსპორტო საშუალება შედის აღნიშნულ ზონაში და გამოდის იქიდან დანიშნულების ადგილისაკენ უახლოეს გზაჯვარედინზე.', E'აკრძალულია მისაბმელიანი სატვირთო ავტომობილით და მისაბმელიანი ტრაქტორით მოძრაობა, ასევე მექანიკური სატრანსპორტო საშუალების ბუქსირება. მოძრაობა აკრძალულია ორივე მიმართულებით. ნიშანი არ ეხება სატრანსპორტო საშუალებას, რომელიც ზონაში მდებარე საწარმოს ემსახურება, ან ზონაში მცხოვრებ თუ მომუშავე ადამიანს ემსახურება ან ეკუთვნის: ასეთი სატრანსპორტო საშუალება ზონაში დანიშნულების ადგილთან უახლოესი გზაჯვარედინიდან შედის და გამოდის.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ka/card_819b1e64e5.webm'),
  (E'sign-3.7', E'ru', E'Движение с прицепом запрещено', E'Запрещает движение всех грузовых автомобилей с прицепом и тракторов с прицепом, а также буксировку механических транспортных средств. Знак указывает, что движение запрещено в обоих направлениях. Действие знака не распространяется на транспортные средства, обслуживающие предприятие, расположенное в обозначенной зоне, а также обслуживающие лицо, проживающее или работающее в этой зоне, или принадлежащие такому лицу. В этом случае транспортное средство въезжает в обозначенную зону и выезжает из неё на ближайшем к месту назначения перекрёстке.', E'Движение грузовых автомобилей и тракторов с прицепом запрещено, как и буксировка механических транспортных средств. Движение запрещено в обоих направлениях. Знак не распространяется на транспортные средства, которые обслуживают предприятие в зоне, обслуживают людей, живущих или работающих в зоне, или принадлежат им: такие транспортные средства въезжают в зону и выезжают из неё на перекрёстке, ближайшем к месту назначения.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ru/card_f4449382fc.webm'),
  (E'sign-3.8', E'en', E'No animal-drawn vehicles', E'Prohibits the movement of animal-drawn vehicles, pack and saddle animals, as well as the driving of livestock. The sign indicates that traffic is prohibited in both directions. The sign does not apply to vehicles serving an enterprise located in the designated zone, or serving or belonging to a person who lives or works in that zone. In this case, the vehicle enters the designated zone and leaves it at the intersection nearest to its destination.', E'Horse-drawn vehicles, pack and riding animals are banned, and so is driving livestock. Traffic is banned in both directions. The sign does not apply to vehicles serving a business in the zone, or serving or owned by people who live or work there: such vehicles enter and leave the zone at the intersection nearest to their destination.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/en/card_18769b244f.webm'),
  (E'sign-3.8', E'ka', E'საჭაპანო ტრანსპორტით მოძრაობა აკრძალულია', E'კრძა­ლავს საჭაპანო ტრანსპორტით, სასაპალნე და დასაჯდომი ცხოველებით მოძრაობას, აგრეთვე პირუტყვის გადარეკვას. ნიშანი მიუთითებს, რომ მოძრაობა ორივე მიმართულებით აკრძალულია. ნიშნის მოქმედება არ ვრცელდება სატრანსპორტო საშუალებაზე, რომელიც ემსახურება აღნიშნულ ზონაში მდებარე საწარმოს, ანდა ემსახურება ან ეკუთვნის ამავე ზონაში მცხოვრებ ან მომუშავე პირს. ამ შემთხვევაში სატრანსპორტო საშუალება შედის აღნიშნულ ზონაში და გამოდის იქიდან დანიშნულების ადგილისაკენ უახლოეს გზაჯვარედინზე.', E'აკრძალულია საჭაპანო ტრანსპორტით, საპალნე და საჯდომი ცხოველებით მოძრაობა, ასევე პირუტყვის გადარეკვა. მოძრაობა აკრძალულია ორივე მიმართულებით. ნიშანი არ ეხება სატრანსპორტო საშუალებას, რომელიც ზონაში მდებარე საწარმოს ემსახურება, ან ზონაში მცხოვრებ თუ მომუშავე ადამიანს ემსახურება ან ეკუთვნის: ასეთი სატრანსპორტო საშუალება ზონაში დანიშნულების ადგილთან უახლოესი გზაჯვარედინიდან შედის და გამოდის.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ka/card_615646968a.webm'),
  (E'sign-3.8', E'ru', E'Движение гужевых повозок запрещено', E'Запрещает движение гужевых повозок, вьючных и верховых животных, а также прогон скота. Знак указывает, что движение запрещено в обоих направлениях. Действие знака не распространяется на транспортные средства, обслуживающие предприятие, расположенное в обозначенной зоне, а также обслуживающие лицо, проживающее или работающее в этой зоне, или принадлежащие такому лицу. В этом случае транспортное средство въезжает в обозначенную зону и выезжает из неё на ближайшем к месту назначения перекрёстке.', E'Движение гужевых повозок, вьючных и верховых животных запрещено, как и прогон скота. Движение запрещено в обоих направлениях. Знак не распространяется на транспортные средства, которые обслуживают предприятие в зоне, обслуживают людей, живущих или работающих в зоне, или принадлежат им: такие транспортные средства въезжают в зону и выезжают из неё на перекрёстке, ближайшем к месту назначения.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ru/card_e9c139ef4e.webm'),
  (E'sign-3.9', E'en', E'No cycling', E'Prohibits the movement of bicycles and mopeds. The sign indicates that traffic is prohibited in both directions.', E'Bicycles and mopeds are banned. Traffic is banned in both directions.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/en/card_581300c48e.webm'),
  (E'sign-3.9', E'ka', E'ველოსიპედით მოძრაობა აკრძალულია', E'კრძალავს ველოსიპედითა და მოპედით მოძრაობას. ნიშანი მიუთითებს, რომ მოძრაობა ორივე მიმართულებით აკრძალულია.', E'აკრძალულია ველოსიპედით და მოპედით მოძრაობა. მოძრაობა აკრძალულია ორივე მიმართულებით.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ka/card_f1f6cd656e.webm'),
  (E'sign-3.9', E'ru', E'Движение на велосипедах запрещено', E'Запрещает движение велосипедов и мопедов. Знак указывает, что движение запрещено в обоих направлениях.', E'Движение велосипедов и мопедов запрещено. Движение запрещено в обоих направлениях.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ru/card_d44ddbb089.webm'),
  (E'sign-4.1.1', E'en', E'Ahead only', E'Requires the driver to proceed straight ahead only. The sign applies to the intersection of carriageways in front of which the relevant sign is placed; The sign does not apply to route vehicles. The sign placed at the beginning of a road section applies up to the nearest intersection. The sign does not prohibit turning right into courtyards and entering other adjacent areas.', E'You may only go straight on. The sign applies at the intersection it stands before and does not apply to route vehicles. If the sign stands at the start of a road section, it applies up to the nearest intersection. It does not ban turning right into a yard or another adjacent area.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/en/card_3134a01328.webm'),
  (E'sign-4.1.1', E'ka', E'მოძრაობა პირდაპირ', E'ავალდებულებს მძღოლს იმოძრაოს მხოლოდ პირდაპირ. ნიშნის მოქმედება ვრცელდება სავალი ნაწილების იმ გადაკვეთაზე, რომლის წინაც დადგმულია სათანადო ნიშანი; ნიშნის მოქმედება არ ვრცელდება სამარშრუტო სატრანსპორტო საშუალებაზე. ნიშნის მოქმედება, რომელიც გზის მონაკვეთის დასაწყისშია დადგმული, ვრცელდება უახლოეს გზაჯვარედინამდე. ნიშანი არ კრძალავს მარჯვნივ ეზოში მოხვევას და სხვა მიმდებარე ტერიტორიაზე შესვლას.', E'მოძრაობა შეიძლება მხოლოდ პირდაპირ. ნიშანი მოქმედებს იმ გზაჯვარედინზე, რომლის წინაც დგას; სამარშრუტო ტრანსპორტზე არ ვრცელდება. თუ ნიშანი გზის მონაკვეთის დასაწყისში დგას, ის უახლოეს გზაჯვარედინამდე მოქმედებს. მარჯვნივ ეზოში ან სხვა მიმდებარე ტერიტორიაზე შესვლას ნიშანი არ კრძალავს.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ka/card_fe9d2a3bba.webm'),
  (E'sign-4.1.1', E'ru', E'Движение прямо', E'Обязывает водителя двигаться только прямо. Действие знака распространяется на пересечение проезжих частей, перед которым установлен соответствующий знак; Действие знака не распространяется на маршрутные транспортные средства. Действие знака, установленного в начале участка дороги, распространяется до ближайшего перекрёстка. Знак не запрещает поворот направо во дворы и въезд на другие прилегающие территории.', E'Движение разрешено только прямо. Знак действует на перекрёстке, перед которым установлен, и не распространяется на маршрутные транспортные средства. Если знак стоит в начале участка дороги, он действует до ближайшего перекрёстка. Поворот направо во двор или на другую прилегающую территорию знак не запрещает.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ru/card_681c764909.webm'),
  (E'sign-4.1.2', E'en', E'Turn right only', E'Requires the driver to turn right only. The sign applies to the intersection of carriageways in front of which the relevant sign is placed; The sign does not apply to route vehicles.', E'You may only turn right. The sign applies at the intersection it stands before and does not apply to route vehicles.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/en/card_58856aca39.webm'),
  (E'sign-4.1.2', E'ka', E'მოძრაობა მარჯვნივ', E'ავალდებულებს მძღოლს იმოძრაოს მხოლოდ მარჯვნივ. ნიშნის მოქმედება ვრცელდება სავალი ნაწილების იმ გადაკვეთაზე, რომლის წინაც დადგმულია სათანადო ნიშანი; ნიშნის მოქმედება არ ვრცელდება სამარშრუტო სატრანსპორტო საშუალებაზე.', E'მოძრაობა შეიძლება მხოლოდ მარჯვნივ. ნიშანი მოქმედებს იმ გზაჯვარედინზე, რომლის წინაც დგას; სამარშრუტო ტრანსპორტზე არ ვრცელდება.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ka/card_abdabfc0b9.webm'),
  (E'sign-4.1.2', E'ru', E'Движение направо', E'Обязывает водителя двигаться только направо. Действие знака распространяется на пересечение проезжих частей, перед которым установлен соответствующий знак; Действие знака не распространяется на маршрутные транспортные средства.', E'Движение разрешено только направо. Знак действует на перекрёстке, перед которым установлен, и не распространяется на маршрутные транспортные средства.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/ru/card_0dbbc5174c.webm'),
  (E'sign-4.1.3', E'en', E'Turn left only', E'Requires the driver to turn left only. The sign also permits a U-turn. The sign applies to the intersection of carriageways in front of which the relevant sign is placed; The sign does not apply to route vehicles.', E'You may only turn left. U-turns are allowed too. The sign applies at the intersection it stands before and does not apply to route vehicles.', E'https://prava-ge-assets.s3.eu-north-1.amazonaws.com/audio/en/card_038e83a961.webm'),
